--
-- Name: enforce_recommendation_evaluation_result_semantics_v1(); Type: FUNCTION; Schema: phase4b_eval_40784; Owner: -
--

CREATE FUNCTION phase4b_eval_40784.enforce_recommendation_evaluation_result_semantics_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_run experiment_recommendation_evaluation_run%ROWTYPE;
BEGIN
    SELECT * INTO parent_run
    FROM experiment_recommendation_evaluation_run
    WHERE recommendation_evaluation_run_id =
          NEW.recommendation_evaluation_run_id
    FOR SHARE;
    IF NOT FOUND OR NOT recommendation_evaluation_result_semantics_valid_v1(
            NEW, parent_run) THEN
        RAISE EXCEPTION 'evaluation result semantic provenance differs from run'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_evaluation_result_run_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_evaluation_run_semantics_v1(); Type: FUNCTION; Schema: phase4b_eval_40784; Owner: -
--

CREATE FUNCTION phase4b_eval_40784.enforce_recommendation_evaluation_run_semantics_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND
       (OLD.evaluation_policy_canonical, OLD.evaluation_policy_hash,
        OLD.evaluation_version, OLD.evaluator_version,
        OLD.scoring_policy_canonical, OLD.scoring_policy_hash,
        OLD.scoring_version, OLD.evaluation_run_identity_canonical,
        OLD.evaluation_run_identity_hash, OLD.evidence_snapshot_canonical,
        OLD.evidence_snapshot_hash) IS NOT DISTINCT FROM
       (NEW.evaluation_policy_canonical, NEW.evaluation_policy_hash,
        NEW.evaluation_version, NEW.evaluator_version,
        NEW.scoring_policy_canonical, NEW.scoring_policy_hash,
        NEW.scoring_version, NEW.evaluation_run_identity_canonical,
        NEW.evaluation_run_identity_hash, NEW.evidence_snapshot_canonical,
        NEW.evidence_snapshot_hash) THEN
        RETURN NEW;
    END IF;
    IF NOT recommendation_evaluation_run_semantics_valid_v1(NEW)
       OR NEW.evaluation_run_identity_hash <>
          recommendation_semantic_tagged_fnv1a64(
              NEW.evaluation_run_identity_canonical)
       OR NEW.evidence_snapshot_hash <>
          recommendation_semantic_tagged_fnv1a64(
              NEW.evidence_snapshot_canonical) THEN
        RAISE EXCEPTION 'invalid evaluation run semantic provenance'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_evaluation_run_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_member_insert(); Type: FUNCTION; Schema: phase4b_eval_40784; Owner: -
--

CREATE FUNCTION phase4b_eval_40784.enforce_recommendation_ranking_member_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'phase4b_eval_40784', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_ranking_snapshot snapshot
    JOIN experiment_recommendation_evaluation_result evaluation
      ON evaluation.recommendation_evaluation_result_id =
         NEW.recommendation_evaluation_result_id
    JOIN experiment_recommendation recommendation
      ON recommendation.recommendation_id = evaluation.recommendation_id
    WHERE snapshot.recommendation_ranking_snapshot_id =
          NEW.recommendation_ranking_snapshot_id
      AND (
          snapshot.status = 'running'
          OR (snapshot.status = 'completed' AND EXISTS (
              SELECT 1
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
                AND existing.recommendation_evaluation_result_id =
                    NEW.recommendation_evaluation_result_id
          ))
      )
      AND evaluation.recommendation_id = NEW.recommendation_id
      AND evaluation.recommendation_semantic_hash =
          NEW.recommendation_semantic_hash
      AND evaluation.evaluation_identity_hash = NEW.evaluation_identity_hash
      AND evaluation.final_score IS NOT DISTINCT FROM NEW.final_score
      AND evaluation.disposition = NEW.disposition
      AND evaluation.recommendation_scan_id = NEW.recommendation_scan_id
      AND evaluation.source_experiment_id = NEW.source_experiment_id
      AND evaluation.source_model_id IS NOT DISTINCT FROM NEW.source_model_id
      AND evaluation.source_analysis_id IS NOT DISTINCT FROM NEW.source_analysis_id
      AND (
          (snapshot.scope_type = 'evaluation_run'
              AND evaluation.recommendation_evaluation_run_id =
                  snapshot.evaluation_run_filter)
          OR (snapshot.scope_type = 'recommendation_scan'
              AND evaluation.recommendation_scan_id =
                  snapshot.recommendation_scan_filter)
          OR (snapshot.scope_type = 'symbol'
              AND recommendation.source_symbol = snapshot.symbol_filter)
          OR (snapshot.scope_type = 'horizon'
              AND recommendation.source_prediction_horizon =
                  snapshot.horizon_filter)
          OR (snapshot.scope_type = 'family'
              AND recommendation.changed_parameter = snapshot.family_filter)
          OR (snapshot.scope_type = 'symbol_horizon'
              AND recommendation.source_symbol = snapshot.symbol_filter
              AND recommendation.source_prediction_horizon =
                  snapshot.horizon_filter)
          OR snapshot.scope_type = 'global'
      )
      AND recommendation_ranking_membership_contains(
          snapshot.source_membership_canonical,
          evaluation.evaluation_identity_canonical,
          evaluation.recommendation_evaluation_result_id)
      AND (
          EXISTS (
              SELECT 1
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
                AND existing.recommendation_evaluation_result_id =
                    NEW.recommendation_evaluation_result_id
          )
          OR (
              SELECT count(*)
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
          ) < snapshot.requested_limit
      )
      AND NEW.bucket_rank <= snapshot.requested_limit
      AND NEW.global_ordinal <= snapshot.requested_limit
      AND recommendation.source_symbol = NEW.symbol
      AND recommendation.source_prediction_horizon = NEW.horizon
      AND recommendation.changed_parameter = NEW.family
      AND recommendation.source_value_canonical = NEW.source_value_canonical
      AND recommendation.proposed_value_canonical = NEW.proposed_value_canonical
      AND NEW.tie_break_semantic_hash = NEW.recommendation_semantic_hash
      AND NEW.tie_break_evaluation_hash = NEW.evaluation_identity_hash
      AND recommendation_ranking_tie_break_matches(
          NEW.tie_break_primary,
          evaluation.disposition,
          evaluation.final_score)
      AND NEW.inclusion_reason = CASE NEW.bucket
          WHEN 'advisory_ready' THEN 'included_advisory_ready'
          ELSE 'included_for_advisory_inspection'
      END
      AND NEW.block_reason IS NOT DISTINCT FROM CASE NEW.bucket
          WHEN 'advisory_ready' THEN NULL::text
          ELSE evaluation.reason_code
      END
      AND NEW.top_positive_component IS NOT DISTINCT FROM (
          SELECT component.component_name
          FROM experiment_recommendation_evaluation_component component
          WHERE component.recommendation_evaluation_result_id =
                evaluation.recommendation_evaluation_result_id
            AND NOT component.is_penalty
          ORDER BY component.weighted_contribution DESC,
                   component.component_name ASC
          LIMIT 1
      )
      AND NEW.top_penalty_component IS NOT DISTINCT FROM (
          SELECT component.component_name
          FROM experiment_recommendation_evaluation_component component
          WHERE component.recommendation_evaluation_result_id =
                evaluation.recommendation_evaluation_result_id
            AND component.is_penalty
          ORDER BY component.weighted_contribution DESC,
                   component.component_name ASC
          LIMIT 1
      )
    FOR UPDATE OF snapshot;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'invalid or terminal recommendation ranking membership'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_member_authority_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_member_semantics_v2(); Type: FUNCTION; Schema: phase4b_eval_40784; Owner: -
--

CREATE FUNCTION phase4b_eval_40784.enforce_recommendation_ranking_member_semantics_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_ranking_snapshot snapshot
    JOIN experiment_recommendation_evaluation_result evaluation
      ON evaluation.recommendation_evaluation_result_id =
         NEW.recommendation_evaluation_result_id
    JOIN experiment_recommendation_evaluation_run run
      ON run.recommendation_evaluation_run_id =
         evaluation.recommendation_evaluation_run_id
    WHERE snapshot.recommendation_ranking_snapshot_id =
          NEW.recommendation_ranking_snapshot_id
      AND snapshot.population_semantic_state = 'verified_homogeneous'
      AND recommendation_evaluation_result_semantics_valid_v1(evaluation, run)
      AND snapshot.scoring_semantic_canonical =
          recommendation_scoring_semantic_canonical_v1(
              run.scoring_policy_canonical, run.scoring_version)
      AND snapshot.scoring_semantic_hash =
          recommendation_semantic_tagged_fnv1a64(
              snapshot.scoring_semantic_canonical)
      AND snapshot.evaluation_semantic_canonical =
          recommendation_evaluation_semantic_canonical_v1(
              run.evaluation_version, run.evaluator_version,
              run.scoring_policy_canonical, run.scoring_version)
      AND snapshot.evaluation_semantic_hash =
          recommendation_semantic_tagged_fnv1a64(
              snapshot.evaluation_semantic_canonical);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ranking member semantic identity differs from snapshot'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_member_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_snapshot_semantics_v2(); Type: FUNCTION; Schema: phase4b_eval_40784; Owner: -
--

CREATE FUNCTION phase4b_eval_40784.enforce_recommendation_ranking_snapshot_semantics_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    declared_count integer;
    resolved_count integer;
    invalid_count integer;
    scoring_count integer;
    evaluation_count integer;
    expected_identity text;
BEGIN
    IF TG_OP = 'UPDATE' AND
       (OLD.ranking_snapshot_identity_version, OLD.population_semantic_state,
        OLD.scoring_semantic_canonical, OLD.scoring_semantic_hash,
        OLD.scoring_semantic_version, OLD.evaluation_semantic_canonical,
        OLD.evaluation_semantic_hash, OLD.evaluation_semantic_version,
        OLD.distinct_scoring_semantic_count,
        OLD.distinct_evaluation_semantic_count,
        OLD.homogeneity_validation_result) IS NOT DISTINCT FROM
       (NEW.ranking_snapshot_identity_version, NEW.population_semantic_state,
        NEW.scoring_semantic_canonical, NEW.scoring_semantic_hash,
        NEW.scoring_semantic_version, NEW.evaluation_semantic_canonical,
        NEW.evaluation_semantic_hash, NEW.evaluation_semantic_version,
        NEW.distinct_scoring_semantic_count,
        NEW.distinct_evaluation_semantic_count,
        NEW.homogeneity_validation_result) THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'ranking snapshot semantic identity is immutable'
            USING ERRCODE = '55000';
    END IF;
    IF NEW.ranking_snapshot_identity_version <> 2 OR
       NEW.ranking_policy_hash <>
           recommendation_semantic_tagged_fnv1a64(NEW.ranking_policy_canonical) OR
       NEW.scope_hash <>
           recommendation_semantic_tagged_fnv1a64(NEW.scope_canonical) OR
       NEW.source_membership_hash <>
           recommendation_semantic_tagged_fnv1a64(
               NEW.source_membership_canonical) THEN
        RAISE EXCEPTION 'invalid Phase 3B ranking snapshot provenance'
            USING ERRCODE = '23514';
    END IF;
    declared_count := recommendation_ranking_membership_count_v1(
        NEW.source_membership_canonical);
    IF NEW.population_semantic_state = 'empty' THEN
        IF declared_count IS DISTINCT FROM 0 OR
           NEW.homogeneity_validation_result <> 'empty_population' THEN
            RAISE EXCEPTION 'invalid empty ranking semantic state'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.population_semantic_state = 'verified_homogeneous' THEN
        IF declared_count IS NULL OR declared_count <= 0 OR
           NEW.scoring_semantic_hash <>
               recommendation_semantic_tagged_fnv1a64(
                   NEW.scoring_semantic_canonical) OR
           NEW.evaluation_semantic_hash <>
               recommendation_semantic_tagged_fnv1a64(
                   NEW.evaluation_semantic_canonical) THEN
            RAISE EXCEPTION 'invalid homogeneous ranking semantic identity'
                USING ERRCODE = '23514';
        END IF;
        SELECT count(*)::integer,
               count(*) FILTER (WHERE NOT
                   recommendation_evaluation_result_semantics_valid_v1(
                       evaluation, run))::integer,
               count(DISTINCT recommendation_scoring_semantic_canonical_v1(
                   run.scoring_policy_canonical, run.scoring_version))::integer,
               count(DISTINCT recommendation_evaluation_semantic_canonical_v1(
                   run.evaluation_version, run.evaluator_version,
                   run.scoring_policy_canonical, run.scoring_version))::integer
          INTO resolved_count, invalid_count, scoring_count, evaluation_count
        FROM experiment_recommendation_evaluation_result evaluation
        JOIN experiment_recommendation_evaluation_run run
          ON run.recommendation_evaluation_run_id =
             evaluation.recommendation_evaluation_run_id
        WHERE recommendation_ranking_membership_contains(
            NEW.source_membership_canonical,
            evaluation.evaluation_identity_canonical,
            evaluation.recommendation_evaluation_result_id)
          AND recommendation_scoring_semantic_canonical_v1(
              run.scoring_policy_canonical, run.scoring_version) =
              NEW.scoring_semantic_canonical
          AND recommendation_evaluation_semantic_canonical_v1(
              run.evaluation_version, run.evaluator_version,
              run.scoring_policy_canonical, run.scoring_version) =
              NEW.evaluation_semantic_canonical;
        IF resolved_count <> declared_count OR invalid_count <> 0 OR
           scoring_count <> 1 OR evaluation_count <> 1 THEN
            RAISE EXCEPTION 'ranking population is not verified homogeneous'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'new ranking snapshot semantic state is not admissible'
            USING ERRCODE = '23514';
    END IF;
    expected_identity :=
        'experiment_recommendation_ranking_snapshot_identity_v2;policy=' ||
        octet_length(NEW.ranking_policy_canonical) || ':' ||
        NEW.ranking_policy_canonical || ';scope=' ||
        octet_length(NEW.scope_canonical) || ':' || NEW.scope_canonical ||
        ';limit=' || NEW.requested_limit || ';population_state=' ||
        NEW.population_semantic_state || ';scoring_semantic=' ||
        CASE WHEN NEW.population_semantic_state = 'empty' THEN 'NULL'
             ELSE octet_length(NEW.scoring_semantic_canonical) || ':' ||
                  NEW.scoring_semantic_canonical END ||
        ';evaluation_semantic=' ||
        CASE WHEN NEW.population_semantic_state = 'empty' THEN 'NULL'
             ELSE octet_length(NEW.evaluation_semantic_canonical) || ':' ||
                  NEW.evaluation_semantic_canonical END || ';membership=' ||
        octet_length(NEW.source_membership_canonical) || ':' ||
        NEW.source_membership_canonical;
    IF NEW.ranking_snapshot_identity_canonical <> expected_identity OR
       NEW.ranking_snapshot_identity_hash <>
           recommendation_semantic_tagged_fnv1a64(expected_identity) THEN
        RAISE EXCEPTION 'invalid Phase 3B ranking snapshot identity'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_snapshot_transition(); Type: FUNCTION; Schema: phase4b_eval_40784; Owner: -
--

CREATE FUNCTION phase4b_eval_40784.enforce_recommendation_ranking_snapshot_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'phase4b_eval_40784', 'pg_temp'
    AS $$
DECLARE
    persisted_member_count integer;
    persisted_advisory_ready_count integer;
    persisted_blocked_count integer;
    persisted_non_actionable_count integer;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'running' THEN
            RAISE EXCEPTION 'recommendation ranking snapshot must start running'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'recommendation_ranking_snapshot_initial_status_check';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status <> 'running' OR NEW.status NOT IN ('completed', 'failed') THEN
        RAISE EXCEPTION 'invalid recommendation ranking snapshot transition'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_snapshot_transition_check';
    END IF;

    SELECT count(*)::integer,
           count(*) FILTER (WHERE bucket = 'advisory_ready')::integer,
           count(*) FILTER (WHERE bucket = 'blocked')::integer,
           count(*) FILTER (WHERE bucket = 'non_actionable')::integer
    INTO persisted_member_count,
         persisted_advisory_ready_count,
         persisted_blocked_count,
         persisted_non_actionable_count
    FROM experiment_recommendation_ranking_member
    WHERE recommendation_ranking_snapshot_id =
          OLD.recommendation_ranking_snapshot_id;

    IF (NEW.status = 'completed' AND (
            NEW.member_count <> persisted_member_count
            OR NEW.advisory_ready_count <> persisted_advisory_ready_count
            OR NEW.blocked_count <> persisted_blocked_count
            OR NEW.non_actionable_count <> persisted_non_actionable_count))
       OR (NEW.status = 'failed' AND persisted_member_count <> 0) THEN
        RAISE EXCEPTION 'recommendation ranking snapshot counts do not match members'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_snapshot_member_count_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: recommendation_evaluation_policy_provenance_valid_v1(text, text, integer, integer, text, text, integer); Type: FUNCTION; Schema: phase4b_eval_40784; Owner: -
--

CREATE FUNCTION phase4b_eval_40784.recommendation_evaluation_policy_provenance_valid_v1(evaluation_policy_canonical text, evaluation_policy_hash text, evaluation_version integer, evaluator_version integer, scoring_policy_canonical text, scoring_policy_hash text, scoring_version integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT recommendation_scoring_policy_provenance_valid_v1(
               scoring_policy_canonical, scoring_policy_hash, scoring_version)
       AND evaluation_version = 1
       AND evaluator_version = 1
       AND evaluation_policy_canonical =
           'experiment_recommendation_evaluation_policy_v1;evaluation_version=' ||
           evaluation_version || ';evaluator_version=' || evaluator_version ||
           ';scoring_policy=' || octet_length(scoring_policy_canonical) || ':' ||
           scoring_policy_canonical
       AND evaluation_policy_hash =
           recommendation_semantic_tagged_fnv1a64(evaluation_policy_canonical)
$$;


