    CONSTRAINT experiment_recommendation_evalu_recommendations_evaluated_check CHECK ((recommendations_evaluated >= 0)),
    CONSTRAINT experiment_recommendation_evalua_recommendations_eligible_check CHECK ((recommendations_eligible >= 0)),
    CONSTRAINT experiment_recommendation_evalua_scoring_policy_canonical_check CHECK ((btrim(scoring_policy_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluat_recommendations_blocked_check CHECK ((recommendations_blocked >= 0)),
    CONSTRAINT experiment_recommendation_evaluati_evaluation_policy_hash_check CHECK ((btrim(evaluation_policy_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluati_evidence_snapshot_hash_check CHECK ((btrim(evidence_snapshot_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation__scoring_policy_hash_check CHECK ((btrim(scoring_policy_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_r_evaluation_version_check CHECK ((evaluation_version > 0)),
    CONSTRAINT experiment_recommendation_evaluation_ru_evaluation_errors_check CHECK ((evaluation_errors >= 0)),
    CONSTRAINT experiment_recommendation_evaluation_ru_evaluator_version_check CHECK ((evaluator_version > 0)),
    CONSTRAINT experiment_recommendation_evaluation_run_lifecycle_check CHECK ((((status = 'running'::text) AND (completed_at IS NULL) AND (error_message IS NULL)) OR ((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (error_message IS NULL)) OR ((status = 'failed'::text) AND (completed_at IS NOT NULL) AND (error_message IS NOT NULL) AND (btrim(error_message) <> ''::text)))),
    CONSTRAINT experiment_recommendation_evaluation_run_requested_limit_check CHECK (((requested_limit IS NULL) OR (requested_limit > 0))),
    CONSTRAINT experiment_recommendation_evaluation_run_scoring_version_check CHECK ((scoring_version > 0)),
    CONSTRAINT experiment_recommendation_evaluation_run_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text])))
);


--
-- Name: recommendation_evaluation_result_semantics_valid_v1(phase4b_eval_79586.experiment_recommendation_evaluation_result, phase4b_eval_79586.experiment_recommendation_evaluation_run); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_evaluation_result_semantics_valid_v1(evaluation phase4b_eval_79586.experiment_recommendation_evaluation_result, run phase4b_eval_79586.experiment_recommendation_evaluation_run) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT recommendation_evaluation_run_semantics_valid_v1(run)
       AND evaluation.recommendation_evaluation_run_id =
           run.recommendation_evaluation_run_id
       AND evaluation.recommendation_semantic_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.recommendation_semantic_canonical)
       AND evaluation.recommendation_policy_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.recommendation_policy_canonical)
       AND evaluation.evidence_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.evidence_canonical)
       AND evaluation.evaluation_identity_canonical =
           'experiment_recommendation_evaluation_identity_v1;evaluation_policy=' ||
           octet_length(run.evaluation_policy_canonical) || ':' ||
           run.evaluation_policy_canonical || ';recommendation_semantic=' ||
           octet_length(evaluation.recommendation_semantic_canonical) || ':' ||
           evaluation.recommendation_semantic_canonical ||
           ';recommendation_policy=' ||
           octet_length(evaluation.recommendation_policy_canonical) || ':' ||
           evaluation.recommendation_policy_canonical || ';evidence=' ||
           octet_length(evaluation.evidence_canonical) || ':' ||
           evaluation.evidence_canonical
       AND evaluation.evaluation_identity_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.evaluation_identity_canonical)
$$;


--
-- Name: recommendation_evaluation_run_semantics_valid_v1(phase4b_eval_79586.experiment_recommendation_evaluation_run); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_evaluation_run_semantics_valid_v1(run phase4b_eval_79586.experiment_recommendation_evaluation_run) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT recommendation_evaluation_policy_provenance_valid_v1(
        run.evaluation_policy_canonical, run.evaluation_policy_hash,
        run.evaluation_version, run.evaluator_version,
        run.scoring_policy_canonical, run.scoring_policy_hash,
        run.scoring_version)
$$;


--
-- Name: recommendation_evaluation_semantic_canonical_v1(integer, integer, text, integer); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_evaluation_semantic_canonical_v1(evaluation_version integer, evaluator_version integer, scoring_policy_canonical text, scoring_version integer) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT 'experiment_recommendation_evaluation_semantic_v1;semantic_version=1;' ||
        'algorithm=advisory_evaluator_v1;' ||
        'classification=invalid,unsupported,insufficient,stale,pending_duplicate,' ||
        'active_duplicate,completed_duplicate,advisory_ready_v1;' ||
        'eligibility=only_advisory_ready_is_eligible_v1;' ||
        'disposition_precedence=persisted_evidence_then_family_then_missing_then_stale_then_duplicate_then_score_v1;' ||
        'evaluation_version=' || evaluation_version ||
        ';evaluator_version=' || evaluator_version ||
        ';scoring_semantic=' ||
        octet_length(recommendation_scoring_semantic_canonical_v1(
            scoring_policy_canonical, scoring_version)) || ':' ||
        recommendation_scoring_semantic_canonical_v1(
            scoring_policy_canonical, scoring_version)
    WHERE evaluation_version = 1 AND evaluator_version = 1
      AND scoring_version = 1
$$;


--
-- Name: recommendation_ranking_membership_contains(text, text, bigint); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_ranking_membership_contains(membership_canonical text, target_evaluation_identity text, target_evaluation_result_id bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    membership_bytes bytea := convert_to(membership_canonical, 'UTF8');
    target_identity_bytes bytea := convert_to(target_evaluation_identity, 'UTF8');
    header_bytes bytea := convert_to(
        'experiment_recommendation_ranking_membership_v1;count=', 'UTF8');
    delimiter_bytes bytea := convert_to(';', 'UTF8');
    colon_bytes bytea := convert_to(':', 'UTF8');
    cursor_position integer;
    delimiter_offset integer;
    member_count_text text;
    member_count_numeric numeric;
    member_count integer;
    member_ordinal integer;
    member_prefix_bytes bytea;
    identity_length_text text;
    identity_length_numeric numeric;
    identity_length integer;
    member_identity_bytes bytea;
    result_prefix_bytes bytea;
    member_result_id_text text;
    member_result_id_numeric numeric;
    target_found boolean := false;
    total_length integer := octet_length(membership_bytes);
BEGIN
    IF substring(membership_bytes FROM 1 FOR octet_length(header_bytes)) <>
       header_bytes THEN
        RETURN false;
    END IF;
    cursor_position := octet_length(header_bytes) + 1;
    delimiter_offset := position(
        delimiter_bytes IN substring(membership_bytes FROM cursor_position));
    IF delimiter_offset = 0 THEN
        member_count_text := convert_from(
            substring(membership_bytes FROM cursor_position), 'UTF8');
        cursor_position := total_length + 1;
    ELSE
        member_count_text := convert_from(substring(
            membership_bytes FROM cursor_position FOR delimiter_offset - 1),
            'UTF8');
        cursor_position := cursor_position + delimiter_offset - 1;
    END IF;
    IF member_count_text !~ '^(0|[1-9][0-9]*)$'
       OR length(member_count_text) > 4 THEN
        RETURN false;
    END IF;
    member_count_numeric := member_count_text::numeric;
    IF member_count_numeric > 1000 THEN
        RETURN false;
    END IF;
    member_count := member_count_numeric::integer;
    IF member_count = 0 THEN
        RETURN false;
    END IF;
    IF cursor_position > total_length THEN
        RETURN false;
    END IF;

    FOR member_ordinal IN 0..member_count - 1 LOOP
        member_prefix_bytes := convert_to(
            ';member[' || member_ordinal::text || '].evaluation_identity=',
            'UTF8');
        IF substring(membership_bytes FROM cursor_position
                     FOR octet_length(member_prefix_bytes)) <>
           member_prefix_bytes THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + octet_length(member_prefix_bytes);
        delimiter_offset := position(
            colon_bytes IN substring(membership_bytes FROM cursor_position));
        IF delimiter_offset = 0 THEN
            RETURN false;
        END IF;
        identity_length_text := convert_from(substring(
            membership_bytes FROM cursor_position FOR delimiter_offset - 1),
            'UTF8');
        IF identity_length_text !~ '^(0|[1-9][0-9]*)$'
           OR length(identity_length_text) > 10 THEN
            RETURN false;
        END IF;
        identity_length_numeric := identity_length_text::numeric;
        IF identity_length_numeric > total_length THEN
            RETURN false;
        END IF;
        identity_length := identity_length_numeric::integer;
        cursor_position := cursor_position + delimiter_offset;
        member_identity_bytes := substring(
            membership_bytes FROM cursor_position FOR identity_length);
        IF octet_length(member_identity_bytes) <> identity_length THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + identity_length;

        result_prefix_bytes := convert_to(
            ';member[' || member_ordinal::text || '].evaluation_result_id=',
            'UTF8');
        IF substring(membership_bytes FROM cursor_position
                     FOR octet_length(result_prefix_bytes)) <>
           result_prefix_bytes THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + octet_length(result_prefix_bytes);
        IF member_ordinal < member_count - 1 THEN
            delimiter_offset := position(delimiter_bytes IN substring(
                membership_bytes FROM cursor_position));
            IF delimiter_offset = 0 THEN
                RETURN false;
            END IF;
            member_result_id_text := convert_from(substring(
                membership_bytes FROM cursor_position FOR delimiter_offset - 1),
                'UTF8');
            cursor_position := cursor_position + delimiter_offset - 1;
        ELSE
            member_result_id_text := convert_from(
                substring(membership_bytes FROM cursor_position), 'UTF8');
            cursor_position := total_length + 1;
        END IF;
        IF member_result_id_text !~ '^[1-9][0-9]*$'
           OR length(member_result_id_text) > 19 THEN
            RETURN false;
        END IF;
        member_result_id_numeric := member_result_id_text::numeric;
        IF member_result_id_numeric > 9223372036854775807::numeric THEN
            RETURN false;
        END IF;
        IF member_identity_bytes = target_identity_bytes
           AND member_result_id_numeric = target_evaluation_result_id THEN
            target_found := true;
        END IF;
    END LOOP;
    RETURN target_found AND cursor_position = total_length + 1;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range OR
         character_not_in_repertoire THEN
        RETURN false;
END;
$_$;


--
-- Name: recommendation_ranking_membership_count_v1(text); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_ranking_membership_count_v1(membership_canonical text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    matched text[];
    parsed numeric;
BEGIN
    matched := regexp_match(membership_canonical,
        '^experiment_recommendation_ranking_membership_v1;count=(0|[1-9][0-9]*)(;|$)');
    IF matched IS NULL OR length(matched[1]) > 4 THEN RETURN NULL; END IF;
    parsed := matched[1]::numeric;
    IF parsed > 1000 THEN RETURN NULL; END IF;
    IF parsed = 0 AND membership_canonical <>
       'experiment_recommendation_ranking_membership_v1;count=0' THEN
        RETURN NULL;
    END IF;
    RETURN parsed::integer;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN NULL;
END;
$_$;


--
-- Name: recommendation_ranking_tie_break_matches(text, text, double precision); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_ranking_tie_break_matches(tie_break_primary text, evaluation_disposition text, evaluation_final_score double precision) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    parsed_score double precision;
BEGIN
    IF evaluation_final_score IS NOT NULL THEN
        IF left(tie_break_primary, 6) <> 'score:' THEN
            RETURN false;
        END IF;
        parsed_score := substring(tie_break_primary FROM 7)::double precision;
        RETURN parsed_score NOT IN (
                   'NaN'::double precision,
                   'Infinity'::double precision,
                   '-Infinity'::double precision)
               AND parsed_score = evaluation_final_score;
    END IF;
    RETURN tie_break_primary = CASE evaluation_disposition
        WHEN 'blocked_pending_duplicate' THEN 'priority:0'
        WHEN 'blocked_active_duplicate' THEN 'priority:1'
        WHEN 'completed_duplicate' THEN 'priority:2'
        WHEN 'insufficient_evidence' THEN 'priority:0'
        WHEN 'stale_source_evidence' THEN 'priority:1'
        WHEN 'unsupported_recommendation_family' THEN 'priority:2'
        WHEN 'invalid_persisted_evidence' THEN 'priority:3'
        ELSE NULL
    END;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN false;
END;
$$;


--
-- Name: recommendation_scoring_policy_provenance_valid_v1(text, text, integer); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_scoring_policy_provenance_valid_v1(policy_canonical text, policy_hash text, policy_version integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
DECLARE
    parts text[];
    expected_keys constant text[] := ARRAY[
        'scoring_version',
        'leader_score_weight',
        'inference_accuracy_weight',
        'evidence_strength_weight',
        'neutral_balance_weight',
        'structural_distance_weight',
        'parameter_preference_weight',
        'source_rank_weight',
        'horizon_change_penalty_weight',
        'relative_mutation_penalty_weight',
        'minimum_evidence_count',
        'evidence_saturation_count',
        'preferred_neutral_proportion',
        'maximum_neutral_proportion',
        'maximum_relative_mutation',
        'maximum_absolute_structural_distance',
        'allow_missing_neutral_proportion',
        'score_floor',
        'score_ceiling',
        'core_lr_preference',
        'head_lr_preference',
        'label_threshold_preference',
        'prediction_horizon_preference'
    ];
    values_text text[] := ARRAY[]::text[];
    index_value integer;
    separator integer;
    key_text text;
    value_text text;
    canonical_double_pattern constant text :=
        '^(0|[1-9][0-9]*)([.][0-9]*[1-9])?([e][+-][0-9]{2,3})?$';
    weights double precision[];
    minimum_evidence bigint;
    evidence_saturation bigint;
    preferred_neutral double precision;
    maximum_neutral double precision;
    maximum_relative double precision;
    maximum_absolute double precision;
    score_floor_value double precision;
    score_ceiling_value double precision;
    preferences double precision[];
BEGIN
    IF policy_version <> 1 OR
       policy_hash <> recommendation_semantic_tagged_fnv1a64(policy_canonical)
    THEN
        RETURN false;
    END IF;

    parts := string_to_array(policy_canonical, ';');
    IF cardinality(parts) <> cardinality(expected_keys) + 1 OR
       parts[1] <> 'experiment_recommendation_scoring_policy_v1'
    THEN
        RETURN false;
    END IF;

    FOR index_value IN 1..cardinality(expected_keys) LOOP
        separator := strpos(parts[index_value + 1], '=');
        IF separator <= 1 OR
           strpos(substr(parts[index_value + 1], separator + 1), '=') <> 0
        THEN
            RETURN false;
        END IF;

        key_text := substr(parts[index_value + 1], 1, separator - 1);
        value_text := substr(parts[index_value + 1], separator + 1);

        IF key_text <> expected_keys[index_value] OR value_text = '' THEN
            RETURN false;
        END IF;

        values_text := array_append(values_text, value_text);
    END LOOP;

    IF values_text[1] <> '1' THEN
        RETURN false;
    END IF;

    -- C++ v1 emits non-negative finite policy values in a deterministic
    -- decimal/scientific spelling. Reject alternate spellings such as
    -- trailing fractional zeros, uppercase E, leading '+', and negative zero.
    FOREACH index_value IN ARRAY ARRAY[
        2,3,4,5,6,7,8,9,10,13,14,15,16,18,19,20,21,22,23
    ]
    LOOP
        IF values_text[index_value] !~ canonical_double_pattern THEN
            RETURN false;
        END IF;
    END LOOP;

    IF values_text[11] !~ '^[1-9][0-9]*$' OR
       values_text[12] !~ '^(0|[1-9][0-9]*)$' OR
       values_text[17] !~ '^[01]$'
    THEN
        RETURN false;
    END IF;

    BEGIN
        weights := ARRAY[
            values_text[2]::double precision,
            values_text[3]::double precision,
            values_text[4]::double precision,
            values_text[5]::double precision,
            values_text[6]::double precision,
            values_text[7]::double precision,
            values_text[8]::double precision,
            values_text[9]::double precision,
            values_text[10]::double precision
        ];
        minimum_evidence := values_text[11]::bigint;
        evidence_saturation := values_text[12]::bigint;
        preferred_neutral := values_text[13]::double precision;
        maximum_neutral := values_text[14]::double precision;
        maximum_relative := values_text[15]::double precision;
        maximum_absolute := values_text[16]::double precision;
        score_floor_value := values_text[18]::double precision;
        score_ceiling_value := values_text[19]::double precision;
        preferences := ARRAY[
            values_text[20]::double precision,
            values_text[21]::double precision,
            values_text[22]::double precision,
            values_text[23]::double precision
        ];
    EXCEPTION
        WHEN numeric_value_out_of_range OR invalid_text_representation THEN
            RETURN false;
    END;

    -- Mirror ValidateRecommendationScoringPolicy().
    IF EXISTS (
        SELECT 1
        FROM unnest(weights) value
        WHERE value < 0.0)
    THEN
        RETURN false;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM unnest(weights[1:7]) value
        WHERE value > 0.0)
    THEN
        RETURN false;
    END IF;

    IF minimum_evidence <= 0 OR evidence_saturation < minimum_evidence THEN
        RETURN false;
    END IF;

    IF preferred_neutral < 0.0 OR preferred_neutral > 1.0 THEN
        RETURN false;
    END IF;

    IF maximum_neutral < preferred_neutral OR maximum_neutral > 1.0 THEN
        RETURN false;
    END IF;

    IF maximum_relative <= 0.0 OR maximum_absolute <= 0.0 THEN
        RETURN false;
    END IF;

    IF score_floor_value < 0.0 OR score_ceiling_value > 1.0 OR
       score_floor_value >= score_ceiling_value
    THEN
        RETURN false;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(preferences) value
        WHERE value < 0.0 OR value > 1.0)
    THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$_$;


--
-- Name: recommendation_scoring_semantic_canonical_v1(text, integer); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_scoring_semantic_canonical_v1(scoring_policy_canonical text, scoring_version integer) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT 'experiment_recommendation_scoring_semantic_v1;semantic_version=1;' ||
        'algorithm=weighted_component_score_v1;' ||
        'components=leader_quality,inference_accuracy,evidence_strength,neutral_balance,' ||
        'structural_proximity,parameter_preference,source_rank,horizon_change_penalty,' ||
        'relative_mutation_penalty;' ||
        'normalization=component_clamp_unit_and_policy_thresholds_v1;' ||
        'aggregation=positive_weight_normalized_minus_penalty_weight_normalized_then_policy_clamp_v1;' ||
        'missing=neutral_policy_or_ineligible_v1;' ||
        'structural_distance=relative_delta_else_absolute_delta_v1;' ||
        'source_metrics=persisted_leader_accuracy_neutral_evidence_v1;policy=' ||
        octet_length(scoring_policy_canonical) || ':' || scoring_policy_canonical
    WHERE scoring_version = 1
$$;


--
-- Name: recommendation_semantic_tagged_fnv1a64(text); Type: FUNCTION; Schema: phase4b_eval_79586; Owner: -
--

CREATE FUNCTION phase4b_eval_79586.recommendation_semantic_tagged_fnv1a64(canonical_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
DECLARE
    canonical_bytes bytea := convert_to(canonical_value, 'UTF8');
    hash_value numeric := 14695981039346656037;
    byte_index integer;
    low_byte integer;
    high_word bigint;
    low_word bigint;
BEGIN
    IF octet_length(canonical_bytes) > 0 THEN
        FOR byte_index IN 0..octet_length(canonical_bytes) - 1 LOOP
            low_byte := mod(hash_value, 256)::integer #
                get_byte(canonical_bytes, byte_index);
            hash_value := hash_value - mod(hash_value, 256) + low_byte;
            hash_value := mod(
                hash_value * 1099511628211, 18446744073709551616);
        END LOOP;
    END IF;
    high_word := trunc(hash_value / 4294967296)::bigint;
    low_word := mod(hash_value, 4294967296)::bigint;
    RETURN 'fnv1a64:' || lpad(to_hex(high_word), 8, '0') ||
        lpad(to_hex(low_word), 8, '0');
END;
$$;


--
-- Name: enforce_recommendation_evaluation_result_semantics_v1(); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.enforce_recommendation_evaluation_result_semantics_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_run experiment_recommendation_evaluation_run%ROWTYPE;
BEGIN
    SELECT * INTO parent_run
    FROM experiment_recommendation_evaluation_run
    WHERE recommendation_evaluation_run_id =
          NEW.recommendation_evaluation_run_id
    FOR SHARE;
    IF NOT FOUND OR NOT recommendation_evaluation_result_semantics_valid_v1(
            NEW, parent_run) THEN
        RAISE EXCEPTION 'evaluation result semantic provenance differs from run'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_evaluation_result_run_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_evaluation_run_semantics_v1(); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.enforce_recommendation_evaluation_run_semantics_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND
       (OLD.evaluation_policy_canonical, OLD.evaluation_policy_hash,
        OLD.evaluation_version, OLD.evaluator_version,
        OLD.scoring_policy_canonical, OLD.scoring_policy_hash,
        OLD.scoring_version, OLD.evaluation_run_identity_canonical,
        OLD.evaluation_run_identity_hash, OLD.evidence_snapshot_canonical,
        OLD.evidence_snapshot_hash) IS NOT DISTINCT FROM
       (NEW.evaluation_policy_canonical, NEW.evaluation_policy_hash,
        NEW.evaluation_version, NEW.evaluator_version,
        NEW.scoring_policy_canonical, NEW.scoring_policy_hash,
        NEW.scoring_version, NEW.evaluation_run_identity_canonical,
        NEW.evaluation_run_identity_hash, NEW.evidence_snapshot_canonical,
        NEW.evidence_snapshot_hash) THEN
        RETURN NEW;
    END IF;
    IF NOT recommendation_evaluation_run_semantics_valid_v1(NEW)
       OR NEW.evaluation_run_identity_hash <>
          recommendation_semantic_tagged_fnv1a64(
              NEW.evaluation_run_identity_canonical)
       OR NEW.evidence_snapshot_hash <>
          recommendation_semantic_tagged_fnv1a64(
              NEW.evidence_snapshot_canonical) THEN
        RAISE EXCEPTION 'invalid evaluation run semantic provenance'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_evaluation_run_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_member_insert(); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.enforce_recommendation_ranking_member_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'phase4b_eval_80040', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_ranking_snapshot snapshot
    JOIN experiment_recommendation_evaluation_result evaluation
      ON evaluation.recommendation_evaluation_result_id =
         NEW.recommendation_evaluation_result_id
    JOIN experiment_recommendation recommendation
      ON recommendation.recommendation_id = evaluation.recommendation_id
    WHERE snapshot.recommendation_ranking_snapshot_id =
          NEW.recommendation_ranking_snapshot_id
      AND (
          snapshot.status = 'running'
          OR (snapshot.status = 'completed' AND EXISTS (
              SELECT 1
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
                AND existing.recommendation_evaluation_result_id =
                    NEW.recommendation_evaluation_result_id
          ))
      )
      AND evaluation.recommendation_id = NEW.recommendation_id
      AND evaluation.recommendation_semantic_hash =
          NEW.recommendation_semantic_hash
      AND evaluation.evaluation_identity_hash = NEW.evaluation_identity_hash
      AND evaluation.final_score IS NOT DISTINCT FROM NEW.final_score
      AND evaluation.disposition = NEW.disposition
      AND evaluation.recommendation_scan_id = NEW.recommendation_scan_id
      AND evaluation.source_experiment_id = NEW.source_experiment_id
      AND evaluation.source_model_id IS NOT DISTINCT FROM NEW.source_model_id
      AND evaluation.source_analysis_id IS NOT DISTINCT FROM NEW.source_analysis_id
      AND (
          (snapshot.scope_type = 'evaluation_run'
              AND evaluation.recommendation_evaluation_run_id =
                  snapshot.evaluation_run_filter)
          OR (snapshot.scope_type = 'recommendation_scan'
              AND evaluation.recommendation_scan_id =
                  snapshot.recommendation_scan_filter)
          OR (snapshot.scope_type = 'symbol'
              AND recommendation.source_symbol = snapshot.symbol_filter)
          OR (snapshot.scope_type = 'horizon'
              AND recommendation.source_prediction_horizon =
                  snapshot.horizon_filter)
          OR (snapshot.scope_type = 'family'
              AND recommendation.changed_parameter = snapshot.family_filter)
          OR (snapshot.scope_type = 'symbol_horizon'
              AND recommendation.source_symbol = snapshot.symbol_filter
              AND recommendation.source_prediction_horizon =
                  snapshot.horizon_filter)
          OR snapshot.scope_type = 'global'
      )
      AND recommendation_ranking_membership_contains(
          snapshot.source_membership_canonical,
          evaluation.evaluation_identity_canonical,
          evaluation.recommendation_evaluation_result_id)
      AND (
          EXISTS (
              SELECT 1
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
                AND existing.recommendation_evaluation_result_id =
                    NEW.recommendation_evaluation_result_id
          )
          OR (
              SELECT count(*)
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
          ) < snapshot.requested_limit
      )
      AND NEW.bucket_rank <= snapshot.requested_limit
      AND NEW.global_ordinal <= snapshot.requested_limit
      AND recommendation.source_symbol = NEW.symbol
      AND recommendation.source_prediction_horizon = NEW.horizon
      AND recommendation.changed_parameter = NEW.family
      AND recommendation.source_value_canonical = NEW.source_value_canonical
      AND recommendation.proposed_value_canonical = NEW.proposed_value_canonical
      AND NEW.tie_break_semantic_hash = NEW.recommendation_semantic_hash
      AND NEW.tie_break_evaluation_hash = NEW.evaluation_identity_hash
      AND recommendation_ranking_tie_break_matches(
          NEW.tie_break_primary,
          evaluation.disposition,
          evaluation.final_score)
      AND NEW.inclusion_reason = CASE NEW.bucket
          WHEN 'advisory_ready' THEN 'included_advisory_ready'
          ELSE 'included_for_advisory_inspection'
      END
      AND NEW.block_reason IS NOT DISTINCT FROM CASE NEW.bucket
          WHEN 'advisory_ready' THEN NULL::text
          ELSE evaluation.reason_code
      END
      AND NEW.top_positive_component IS NOT DISTINCT FROM (
          SELECT component.component_name
          FROM experiment_recommendation_evaluation_component component
          WHERE component.recommendation_evaluation_result_id =
                evaluation.recommendation_evaluation_result_id
            AND NOT component.is_penalty
          ORDER BY component.weighted_contribution DESC,
                   component.component_name ASC
          LIMIT 1
      )
      AND NEW.top_penalty_component IS NOT DISTINCT FROM (
          SELECT component.component_name
          FROM experiment_recommendation_evaluation_component component
          WHERE component.recommendation_evaluation_result_id =
                evaluation.recommendation_evaluation_result_id
            AND component.is_penalty
          ORDER BY component.weighted_contribution DESC,
                   component.component_name ASC
          LIMIT 1
      )
    FOR UPDATE OF snapshot;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'invalid or terminal recommendation ranking membership'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_member_authority_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_member_semantics_v2(); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.enforce_recommendation_ranking_member_semantics_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_ranking_snapshot snapshot
    JOIN experiment_recommendation_evaluation_result evaluation
      ON evaluation.recommendation_evaluation_result_id =
         NEW.recommendation_evaluation_result_id
    JOIN experiment_recommendation_evaluation_run run
      ON run.recommendation_evaluation_run_id =
         evaluation.recommendation_evaluation_run_id
    WHERE snapshot.recommendation_ranking_snapshot_id =
          NEW.recommendation_ranking_snapshot_id
      AND snapshot.population_semantic_state = 'verified_homogeneous'
      AND recommendation_evaluation_result_semantics_valid_v1(evaluation, run)
      AND snapshot.scoring_semantic_canonical =
          recommendation_scoring_semantic_canonical_v1(
              run.scoring_policy_canonical, run.scoring_version)
      AND snapshot.scoring_semantic_hash =
          recommendation_semantic_tagged_fnv1a64(
              snapshot.scoring_semantic_canonical)
      AND snapshot.evaluation_semantic_canonical =
          recommendation_evaluation_semantic_canonical_v1(
              run.evaluation_version, run.evaluator_version,
              run.scoring_policy_canonical, run.scoring_version)
      AND snapshot.evaluation_semantic_hash =
          recommendation_semantic_tagged_fnv1a64(
              snapshot.evaluation_semantic_canonical);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ranking member semantic identity differs from snapshot'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_member_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_snapshot_semantics_v2(); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.enforce_recommendation_ranking_snapshot_semantics_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    declared_count integer;
    resolved_count integer;
    invalid_count integer;
    scoring_count integer;
    evaluation_count integer;
    expected_identity text;
BEGIN
    IF TG_OP = 'UPDATE' AND
       (OLD.ranking_snapshot_identity_version, OLD.population_semantic_state,
        OLD.scoring_semantic_canonical, OLD.scoring_semantic_hash,
        OLD.scoring_semantic_version, OLD.evaluation_semantic_canonical,
        OLD.evaluation_semantic_hash, OLD.evaluation_semantic_version,
        OLD.distinct_scoring_semantic_count,
        OLD.distinct_evaluation_semantic_count,
        OLD.homogeneity_validation_result) IS NOT DISTINCT FROM
       (NEW.ranking_snapshot_identity_version, NEW.population_semantic_state,
        NEW.scoring_semantic_canonical, NEW.scoring_semantic_hash,
        NEW.scoring_semantic_version, NEW.evaluation_semantic_canonical,
        NEW.evaluation_semantic_hash, NEW.evaluation_semantic_version,
        NEW.distinct_scoring_semantic_count,
        NEW.distinct_evaluation_semantic_count,
        NEW.homogeneity_validation_result) THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'ranking snapshot semantic identity is immutable'
            USING ERRCODE = '55000';
    END IF;
    IF NEW.ranking_snapshot_identity_version <> 2 OR
       NEW.ranking_policy_hash <>
           recommendation_semantic_tagged_fnv1a64(NEW.ranking_policy_canonical) OR
       NEW.scope_hash <>
           recommendation_semantic_tagged_fnv1a64(NEW.scope_canonical) OR
       NEW.source_membership_hash <>
           recommendation_semantic_tagged_fnv1a64(
               NEW.source_membership_canonical) THEN
        RAISE EXCEPTION 'invalid Phase 3B ranking snapshot provenance'
            USING ERRCODE = '23514';
    END IF;
    declared_count := recommendation_ranking_membership_count_v1(
        NEW.source_membership_canonical);
    IF NEW.population_semantic_state = 'empty' THEN
        IF declared_count IS DISTINCT FROM 0 OR
           NEW.homogeneity_validation_result <> 'empty_population' THEN
            RAISE EXCEPTION 'invalid empty ranking semantic state'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.population_semantic_state = 'verified_homogeneous' THEN
        IF declared_count IS NULL OR declared_count <= 0 OR
           NEW.scoring_semantic_hash <>
               recommendation_semantic_tagged_fnv1a64(
                   NEW.scoring_semantic_canonical) OR
           NEW.evaluation_semantic_hash <>
               recommendation_semantic_tagged_fnv1a64(
                   NEW.evaluation_semantic_canonical) THEN
            RAISE EXCEPTION 'invalid homogeneous ranking semantic identity'
                USING ERRCODE = '23514';
        END IF;
        SELECT count(*)::integer,
               count(*) FILTER (WHERE NOT
                   recommendation_evaluation_result_semantics_valid_v1(
                       evaluation, run))::integer,
               count(DISTINCT recommendation_scoring_semantic_canonical_v1(
                   run.scoring_policy_canonical, run.scoring_version))::integer,
               count(DISTINCT recommendation_evaluation_semantic_canonical_v1(
                   run.evaluation_version, run.evaluator_version,
                   run.scoring_policy_canonical, run.scoring_version))::integer
          INTO resolved_count, invalid_count, scoring_count, evaluation_count
        FROM experiment_recommendation_evaluation_result evaluation
        JOIN experiment_recommendation_evaluation_run run
          ON run.recommendation_evaluation_run_id =
             evaluation.recommendation_evaluation_run_id
        WHERE recommendation_ranking_membership_contains(
            NEW.source_membership_canonical,
            evaluation.evaluation_identity_canonical,
            evaluation.recommendation_evaluation_result_id)
          AND recommendation_scoring_semantic_canonical_v1(
              run.scoring_policy_canonical, run.scoring_version) =
              NEW.scoring_semantic_canonical
          AND recommendation_evaluation_semantic_canonical_v1(
              run.evaluation_version, run.evaluator_version,
              run.scoring_policy_canonical, run.scoring_version) =
              NEW.evaluation_semantic_canonical;
        IF resolved_count <> declared_count OR invalid_count <> 0 OR
           scoring_count <> 1 OR evaluation_count <> 1 THEN
            RAISE EXCEPTION 'ranking population is not verified homogeneous'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'new ranking snapshot semantic state is not admissible'
            USING ERRCODE = '23514';
    END IF;
    expected_identity :=
        'experiment_recommendation_ranking_snapshot_identity_v2;policy=' ||
        octet_length(NEW.ranking_policy_canonical) || ':' ||
        NEW.ranking_policy_canonical || ';scope=' ||
        octet_length(NEW.scope_canonical) || ':' || NEW.scope_canonical ||
        ';limit=' || NEW.requested_limit || ';population_state=' ||
        NEW.population_semantic_state || ';scoring_semantic=' ||
        CASE WHEN NEW.population_semantic_state = 'empty' THEN 'NULL'
             ELSE octet_length(NEW.scoring_semantic_canonical) || ':' ||
                  NEW.scoring_semantic_canonical END ||
        ';evaluation_semantic=' ||
        CASE WHEN NEW.population_semantic_state = 'empty' THEN 'NULL'
             ELSE octet_length(NEW.evaluation_semantic_canonical) || ':' ||
                  NEW.evaluation_semantic_canonical END || ';membership=' ||
        octet_length(NEW.source_membership_canonical) || ':' ||
        NEW.source_membership_canonical;
    IF NEW.ranking_snapshot_identity_canonical <> expected_identity OR
       NEW.ranking_snapshot_identity_hash <>
           recommendation_semantic_tagged_fnv1a64(expected_identity) THEN
        RAISE EXCEPTION 'invalid Phase 3B ranking snapshot identity'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_snapshot_transition(); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.enforce_recommendation_ranking_snapshot_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'phase4b_eval_80040', 'pg_temp'
    AS $$
DECLARE
    persisted_member_count integer;
    persisted_advisory_ready_count integer;
    persisted_blocked_count integer;
    persisted_non_actionable_count integer;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'running' THEN
            RAISE EXCEPTION 'recommendation ranking snapshot must start running'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'recommendation_ranking_snapshot_initial_status_check';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status <> 'running' OR NEW.status NOT IN ('completed', 'failed') THEN
        RAISE EXCEPTION 'invalid recommendation ranking snapshot transition'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_snapshot_transition_check';
    END IF;

    SELECT count(*)::integer,
           count(*) FILTER (WHERE bucket = 'advisory_ready')::integer,
           count(*) FILTER (WHERE bucket = 'blocked')::integer,
           count(*) FILTER (WHERE bucket = 'non_actionable')::integer
    INTO persisted_member_count,
         persisted_advisory_ready_count,
         persisted_blocked_count,
         persisted_non_actionable_count
    FROM experiment_recommendation_ranking_member
    WHERE recommendation_ranking_snapshot_id =
          OLD.recommendation_ranking_snapshot_id;

    IF (NEW.status = 'completed' AND (
            NEW.member_count <> persisted_member_count
            OR NEW.advisory_ready_count <> persisted_advisory_ready_count
            OR NEW.blocked_count <> persisted_blocked_count
            OR NEW.non_actionable_count <> persisted_non_actionable_count))
       OR (NEW.status = 'failed' AND persisted_member_count <> 0) THEN
        RAISE EXCEPTION 'recommendation ranking snapshot counts do not match members'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_snapshot_member_count_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: recommendation_evaluation_policy_provenance_valid_v1(text, text, integer, integer, text, text, integer); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_evaluation_policy_provenance_valid_v1(evaluation_policy_canonical text, evaluation_policy_hash text, evaluation_version integer, evaluator_version integer, scoring_policy_canonical text, scoring_policy_hash text, scoring_version integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT recommendation_scoring_policy_provenance_valid_v1(
               scoring_policy_canonical, scoring_policy_hash, scoring_version)
       AND evaluation_version = 1
       AND evaluator_version = 1
       AND evaluation_policy_canonical =
           'experiment_recommendation_evaluation_policy_v1;evaluation_version=' ||
           evaluation_version || ';evaluator_version=' || evaluator_version ||
           ';scoring_policy=' || octet_length(scoring_policy_canonical) || ':' ||
           scoring_policy_canonical
       AND evaluation_policy_hash =
           recommendation_semantic_tagged_fnv1a64(evaluation_policy_canonical)
$$;


--
-- Name: experiment_recommendation_evaluation_result; Type: TABLE; Schema: phase4b_eval_80040; Owner: -
--

CREATE TABLE phase4b_eval_80040.experiment_recommendation_evaluation_result (
    recommendation_evaluation_result_id bigint NOT NULL,
    recommendation_evaluation_run_id bigint NOT NULL,
    recommendation_id bigint NOT NULL,
    evaluation_identity_canonical text NOT NULL,
    evaluation_identity_hash text NOT NULL,
    recommendation_semantic_canonical text NOT NULL,
    recommendation_semantic_hash text NOT NULL,
    recommendation_policy_canonical text NOT NULL,
    recommendation_policy_hash text NOT NULL,
    recommendation_scan_id bigint NOT NULL,
    source_experiment_id bigint NOT NULL,
    source_model_id bigint,
    source_analysis_id bigint,
    evidence_canonical text NOT NULL,
    evidence_hash text NOT NULL,
    eligibility text NOT NULL,
    disposition text NOT NULL,
    reason_code text NOT NULL,
    explanation text NOT NULL,
    final_score double precision,
    raw_positive_score double precision,
    raw_penalty_score double precision,
    raw_total_score double precision,
    component_count integer NOT NULL,
    missing_evidence_count integer NOT NULL,
    ranking_ordinal integer NOT NULL,
    result_status text DEFAULT 'evaluated'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    final_profitability_provenance_version integer,
    source_final_inference_eval_result_id bigint,
    source_final_profitability_observation_id bigint,
    source_final_profitability_unavailable_reason text,
    source_final_profitability_inference_scope text,
    source_final_profitability_inference_start text,
    source_final_profitability_inference_end text,
    source_final_profitability_actionable_count bigint,
    source_final_profitability_aggregate_return double precision,
    source_final_profitability_average_return double precision,
    source_final_profitability_metric_definition_hash text,
    source_final_profitability_source_content_hash text,
    source_final_profitability_observation_identity_hash text,
    profitability_evidence_canonical text,
    profitability_evidence_hash text,
    CONSTRAINT experiment_recommendation_ev_evaluation_identity_canonica_check CHECK ((btrim(evaluation_identity_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_ev_recommendation_policy_canoni_check CHECK ((btrim(recommendation_policy_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_ev_recommendation_semantic_cano_check CHECK ((btrim(recommendation_semantic_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_ev_recommendation_semantic_hash_check CHECK ((btrim(recommendation_semantic_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_eval_recommendation_policy_hash_check CHECK ((btrim(recommendation_policy_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evalua_evaluation_identity_hash_check CHECK ((btrim(evaluation_identity_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluati_missing_evidence_count_check CHECK ((missing_evidence_count >= 0)),
    CONSTRAINT experiment_recommendation_evaluation_r_evidence_canonical_check CHECK ((btrim(evidence_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_resu_component_count_check CHECK ((component_count >= 0)),
    CONSTRAINT experiment_recommendation_evaluation_resu_ranking_ordinal_check CHECK ((ranking_ordinal > 0)),
    CONSTRAINT experiment_recommendation_evaluation_result_disposition_check CHECK ((disposition = ANY (ARRAY['advisory_ready'::text, 'insufficient_evidence'::text, 'blocked_pending_duplicate'::text, 'blocked_active_duplicate'::text, 'completed_duplicate'::text, 'stale_source_evidence'::text, 'unsupported_recommendation_family'::text, 'invalid_persisted_evidence'::text]))),
    CONSTRAINT experiment_recommendation_evaluation_result_eligibility_check CHECK ((eligibility = ANY (ARRAY['eligible'::text, 'ineligible'::text]))),
    CONSTRAINT experiment_recommendation_evaluation_result_evidence_hash_check CHECK ((btrim(evidence_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_result_explanation_check CHECK ((btrim(explanation) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_result_finite_check CHECK ((((final_score IS NULL) OR (final_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))) AND ((raw_positive_score IS NULL) OR (raw_positive_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))) AND ((raw_penalty_score IS NULL) OR (raw_penalty_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))) AND ((raw_total_score IS NULL) OR (raw_total_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))))),
    CONSTRAINT experiment_recommendation_evaluation_result_reason_code_check CHECK ((btrim(reason_code) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_result_result_status_check CHECK ((result_status = 'evaluated'::text)),
    CONSTRAINT experiment_recommendation_evaluation_result_shape_check CHECK ((((eligibility = 'eligible'::text) AND (disposition = 'advisory_ready'::text) AND (final_score IS NOT NULL) AND (final_score >= (0.0)::double precision) AND (final_score <= (1.0)::double precision) AND (raw_positive_score IS NOT NULL) AND (raw_penalty_score IS NOT NULL) AND (raw_total_score IS NOT NULL) AND (component_count > 0)) OR ((eligibility = 'ineligible'::text) AND (disposition <> 'advisory_ready'::text) AND (final_score IS NULL) AND (raw_positive_score IS NULL) AND (raw_penalty_score IS NULL) AND (raw_total_score IS NULL) AND (component_count = 0))))
);


--
-- Name: experiment_recommendation_evaluation_run; Type: TABLE; Schema: phase4b_eval_80040; Owner: -
--

CREATE TABLE phase4b_eval_80040.experiment_recommendation_evaluation_run (
    recommendation_evaluation_run_id bigint NOT NULL,
    status text NOT NULL,
    evaluation_run_identity_canonical text NOT NULL,
    evaluation_run_identity_hash text NOT NULL,
    evaluation_policy_canonical text NOT NULL,
    evaluation_policy_hash text NOT NULL,
    evaluation_version integer NOT NULL,
    evaluator_version integer NOT NULL,
    scoring_policy_canonical text NOT NULL,
    scoring_policy_hash text NOT NULL,
    scoring_version integer NOT NULL,
    recommendation_scan_filter bigint,
    recommendation_id_filter bigint,
    requested_limit integer,
    evidence_snapshot_canonical text NOT NULL,
    evidence_snapshot_hash text NOT NULL,
    recommendations_considered integer DEFAULT 0 NOT NULL,
    recommendations_evaluated integer DEFAULT 0 NOT NULL,
    recommendations_eligible integer DEFAULT 0 NOT NULL,
    recommendations_blocked integer DEFAULT 0 NOT NULL,
    evaluation_errors integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT experiment_recommendation_ev_evaluation_run_identity_cano_check CHECK ((btrim(evaluation_run_identity_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_ev_evaluation_run_identity_hash_check CHECK ((btrim(evaluation_run_identity_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_eva_evaluation_policy_canonical_check CHECK ((btrim(evaluation_policy_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_eva_evidence_snapshot_canonical_check CHECK ((btrim(evidence_snapshot_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_eval_recommendations_considered_check CHECK ((recommendations_considered >= 0)),
    CONSTRAINT experiment_recommendation_evalu_recommendations_evaluated_check CHECK ((recommendations_evaluated >= 0)),
    CONSTRAINT experiment_recommendation_evalua_recommendations_eligible_check CHECK ((recommendations_eligible >= 0)),
    CONSTRAINT experiment_recommendation_evalua_scoring_policy_canonical_check CHECK ((btrim(scoring_policy_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluat_recommendations_blocked_check CHECK ((recommendations_blocked >= 0)),
    CONSTRAINT experiment_recommendation_evaluati_evaluation_policy_hash_check CHECK ((btrim(evaluation_policy_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluati_evidence_snapshot_hash_check CHECK ((btrim(evidence_snapshot_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation__scoring_policy_hash_check CHECK ((btrim(scoring_policy_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_r_evaluation_version_check CHECK ((evaluation_version > 0)),
    CONSTRAINT experiment_recommendation_evaluation_ru_evaluation_errors_check CHECK ((evaluation_errors >= 0)),
    CONSTRAINT experiment_recommendation_evaluation_ru_evaluator_version_check CHECK ((evaluator_version > 0)),
    CONSTRAINT experiment_recommendation_evaluation_run_lifecycle_check CHECK ((((status = 'running'::text) AND (completed_at IS NULL) AND (error_message IS NULL)) OR ((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (error_message IS NULL)) OR ((status = 'failed'::text) AND (completed_at IS NOT NULL) AND (error_message IS NOT NULL) AND (btrim(error_message) <> ''::text)))),
    CONSTRAINT experiment_recommendation_evaluation_run_requested_limit_check CHECK (((requested_limit IS NULL) OR (requested_limit > 0))),
    CONSTRAINT experiment_recommendation_evaluation_run_scoring_version_check CHECK ((scoring_version > 0)),
    CONSTRAINT experiment_recommendation_evaluation_run_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text])))
);


--
-- Name: recommendation_evaluation_result_semantics_valid_v1(phase4b_eval_80040.experiment_recommendation_evaluation_result, phase4b_eval_80040.experiment_recommendation_evaluation_run); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_evaluation_result_semantics_valid_v1(evaluation phase4b_eval_80040.experiment_recommendation_evaluation_result, run phase4b_eval_80040.experiment_recommendation_evaluation_run) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT recommendation_evaluation_run_semantics_valid_v1(run)
       AND evaluation.recommendation_evaluation_run_id =
           run.recommendation_evaluation_run_id
       AND evaluation.recommendation_semantic_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.recommendation_semantic_canonical)
       AND evaluation.recommendation_policy_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.recommendation_policy_canonical)
       AND evaluation.evidence_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.evidence_canonical)
       AND evaluation.evaluation_identity_canonical =
           'experiment_recommendation_evaluation_identity_v1;evaluation_policy=' ||
           octet_length(run.evaluation_policy_canonical) || ':' ||
           run.evaluation_policy_canonical || ';recommendation_semantic=' ||
           octet_length(evaluation.recommendation_semantic_canonical) || ':' ||
           evaluation.recommendation_semantic_canonical ||
           ';recommendation_policy=' ||
           octet_length(evaluation.recommendation_policy_canonical) || ':' ||
           evaluation.recommendation_policy_canonical || ';evidence=' ||
           octet_length(evaluation.evidence_canonical) || ':' ||
           evaluation.evidence_canonical
       AND evaluation.evaluation_identity_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.evaluation_identity_canonical)
$$;


--
-- Name: recommendation_evaluation_run_semantics_valid_v1(phase4b_eval_80040.experiment_recommendation_evaluation_run); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_evaluation_run_semantics_valid_v1(run phase4b_eval_80040.experiment_recommendation_evaluation_run) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT recommendation_evaluation_policy_provenance_valid_v1(
        run.evaluation_policy_canonical, run.evaluation_policy_hash,
        run.evaluation_version, run.evaluator_version,
        run.scoring_policy_canonical, run.scoring_policy_hash,
        run.scoring_version)
$$;


--
-- Name: recommendation_evaluation_semantic_canonical_v1(integer, integer, text, integer); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_evaluation_semantic_canonical_v1(evaluation_version integer, evaluator_version integer, scoring_policy_canonical text, scoring_version integer) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT 'experiment_recommendation_evaluation_semantic_v1;semantic_version=1;' ||
        'algorithm=advisory_evaluator_v1;' ||
        'classification=invalid,unsupported,insufficient,stale,pending_duplicate,' ||
        'active_duplicate,completed_duplicate,advisory_ready_v1;' ||
        'eligibility=only_advisory_ready_is_eligible_v1;' ||
        'disposition_precedence=persisted_evidence_then_family_then_missing_then_stale_then_duplicate_then_score_v1;' ||
        'evaluation_version=' || evaluation_version ||
        ';evaluator_version=' || evaluator_version ||
        ';scoring_semantic=' ||
        octet_length(recommendation_scoring_semantic_canonical_v1(
            scoring_policy_canonical, scoring_version)) || ':' ||
        recommendation_scoring_semantic_canonical_v1(
            scoring_policy_canonical, scoring_version)
    WHERE evaluation_version = 1 AND evaluator_version = 1
      AND scoring_version = 1
$$;


--
-- Name: recommendation_ranking_membership_contains(text, text, bigint); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_ranking_membership_contains(membership_canonical text, target_evaluation_identity text, target_evaluation_result_id bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    membership_bytes bytea := convert_to(membership_canonical, 'UTF8');
    target_identity_bytes bytea := convert_to(target_evaluation_identity, 'UTF8');
    header_bytes bytea := convert_to(
        'experiment_recommendation_ranking_membership_v1;count=', 'UTF8');
    delimiter_bytes bytea := convert_to(';', 'UTF8');
    colon_bytes bytea := convert_to(':', 'UTF8');
    cursor_position integer;
    delimiter_offset integer;
    member_count_text text;
    member_count_numeric numeric;
    member_count integer;
    member_ordinal integer;
    member_prefix_bytes bytea;
    identity_length_text text;
    identity_length_numeric numeric;
    identity_length integer;
    member_identity_bytes bytea;
    result_prefix_bytes bytea;
    member_result_id_text text;
    member_result_id_numeric numeric;
    target_found boolean := false;
    total_length integer := octet_length(membership_bytes);
BEGIN
    IF substring(membership_bytes FROM 1 FOR octet_length(header_bytes)) <>
       header_bytes THEN
        RETURN false;
    END IF;
    cursor_position := octet_length(header_bytes) + 1;
    delimiter_offset := position(
        delimiter_bytes IN substring(membership_bytes FROM cursor_position));
    IF delimiter_offset = 0 THEN
        member_count_text := convert_from(
            substring(membership_bytes FROM cursor_position), 'UTF8');
        cursor_position := total_length + 1;
    ELSE
        member_count_text := convert_from(substring(
            membership_bytes FROM cursor_position FOR delimiter_offset - 1),
            'UTF8');
        cursor_position := cursor_position + delimiter_offset - 1;
    END IF;
    IF member_count_text !~ '^(0|[1-9][0-9]*)$'
       OR length(member_count_text) > 4 THEN
        RETURN false;
    END IF;
    member_count_numeric := member_count_text::numeric;
    IF member_count_numeric > 1000 THEN
        RETURN false;
    END IF;
    member_count := member_count_numeric::integer;
    IF member_count = 0 THEN
        RETURN false;
    END IF;
    IF cursor_position > total_length THEN
        RETURN false;
    END IF;

    FOR member_ordinal IN 0..member_count - 1 LOOP
        member_prefix_bytes := convert_to(
            ';member[' || member_ordinal::text || '].evaluation_identity=',
            'UTF8');
        IF substring(membership_bytes FROM cursor_position
                     FOR octet_length(member_prefix_bytes)) <>
           member_prefix_bytes THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + octet_length(member_prefix_bytes);
        delimiter_offset := position(
            colon_bytes IN substring(membership_bytes FROM cursor_position));
        IF delimiter_offset = 0 THEN
            RETURN false;
        END IF;
        identity_length_text := convert_from(substring(
            membership_bytes FROM cursor_position FOR delimiter_offset - 1),
            'UTF8');
        IF identity_length_text !~ '^(0|[1-9][0-9]*)$'
           OR length(identity_length_text) > 10 THEN
            RETURN false;
        END IF;
        identity_length_numeric := identity_length_text::numeric;
        IF identity_length_numeric > total_length THEN
            RETURN false;
        END IF;
        identity_length := identity_length_numeric::integer;
        cursor_position := cursor_position + delimiter_offset;
        member_identity_bytes := substring(
            membership_bytes FROM cursor_position FOR identity_length);
        IF octet_length(member_identity_bytes) <> identity_length THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + identity_length;

        result_prefix_bytes := convert_to(
            ';member[' || member_ordinal::text || '].evaluation_result_id=',
            'UTF8');
        IF substring(membership_bytes FROM cursor_position
                     FOR octet_length(result_prefix_bytes)) <>
           result_prefix_bytes THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + octet_length(result_prefix_bytes);
        IF member_ordinal < member_count - 1 THEN
            delimiter_offset := position(delimiter_bytes IN substring(
                membership_bytes FROM cursor_position));
            IF delimiter_offset = 0 THEN
                RETURN false;
            END IF;
            member_result_id_text := convert_from(substring(
                membership_bytes FROM cursor_position FOR delimiter_offset - 1),
                'UTF8');
            cursor_position := cursor_position + delimiter_offset - 1;
        ELSE
            member_result_id_text := convert_from(
                substring(membership_bytes FROM cursor_position), 'UTF8');
            cursor_position := total_length + 1;
        END IF;
        IF member_result_id_text !~ '^[1-9][0-9]*$'
           OR length(member_result_id_text) > 19 THEN
            RETURN false;
        END IF;
        member_result_id_numeric := member_result_id_text::numeric;
        IF member_result_id_numeric > 9223372036854775807::numeric THEN
            RETURN false;
        END IF;
        IF member_identity_bytes = target_identity_bytes
           AND member_result_id_numeric = target_evaluation_result_id THEN
            target_found := true;
        END IF;
    END LOOP;
    RETURN target_found AND cursor_position = total_length + 1;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range OR
         character_not_in_repertoire THEN
        RETURN false;
END;
$_$;


--
-- Name: recommendation_ranking_membership_count_v1(text); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_ranking_membership_count_v1(membership_canonical text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    matched text[];
    parsed numeric;
BEGIN
    matched := regexp_match(membership_canonical,
        '^experiment_recommendation_ranking_membership_v1;count=(0|[1-9][0-9]*)(;|$)');
    IF matched IS NULL OR length(matched[1]) > 4 THEN RETURN NULL; END IF;
    parsed := matched[1]::numeric;
    IF parsed > 1000 THEN RETURN NULL; END IF;
    IF parsed = 0 AND membership_canonical <>
       'experiment_recommendation_ranking_membership_v1;count=0' THEN
        RETURN NULL;
    END IF;
    RETURN parsed::integer;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN NULL;
END;
$_$;


--
-- Name: recommendation_ranking_tie_break_matches(text, text, double precision); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_ranking_tie_break_matches(tie_break_primary text, evaluation_disposition text, evaluation_final_score double precision) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    parsed_score double precision;
BEGIN
    IF evaluation_final_score IS NOT NULL THEN
        IF left(tie_break_primary, 6) <> 'score:' THEN
            RETURN false;
        END IF;
        parsed_score := substring(tie_break_primary FROM 7)::double precision;
        RETURN parsed_score NOT IN (
                   'NaN'::double precision,
                   'Infinity'::double precision,
                   '-Infinity'::double precision)
               AND parsed_score = evaluation_final_score;
    END IF;
    RETURN tie_break_primary = CASE evaluation_disposition
        WHEN 'blocked_pending_duplicate' THEN 'priority:0'
        WHEN 'blocked_active_duplicate' THEN 'priority:1'
        WHEN 'completed_duplicate' THEN 'priority:2'
        WHEN 'insufficient_evidence' THEN 'priority:0'
        WHEN 'stale_source_evidence' THEN 'priority:1'
        WHEN 'unsupported_recommendation_family' THEN 'priority:2'
        WHEN 'invalid_persisted_evidence' THEN 'priority:3'
        ELSE NULL
    END;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN false;
END;
$$;


--
-- Name: recommendation_scoring_policy_provenance_valid_v1(text, text, integer); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_scoring_policy_provenance_valid_v1(policy_canonical text, policy_hash text, policy_version integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
DECLARE
    parts text[];
    expected_keys constant text[] := ARRAY[
        'scoring_version',
        'leader_score_weight',
        'inference_accuracy_weight',
        'evidence_strength_weight',
        'neutral_balance_weight',
        'structural_distance_weight',
        'parameter_preference_weight',
        'source_rank_weight',
        'horizon_change_penalty_weight',
        'relative_mutation_penalty_weight',
        'minimum_evidence_count',
        'evidence_saturation_count',
        'preferred_neutral_proportion',
        'maximum_neutral_proportion',
        'maximum_relative_mutation',
        'maximum_absolute_structural_distance',
        'allow_missing_neutral_proportion',
        'score_floor',
        'score_ceiling',
        'core_lr_preference',
        'head_lr_preference',
        'label_threshold_preference',
        'prediction_horizon_preference'
    ];
    values_text text[] := ARRAY[]::text[];
    index_value integer;
    separator integer;
    key_text text;
    value_text text;
    canonical_double_pattern constant text :=
        '^(0|[1-9][0-9]*)([.][0-9]*[1-9])?([e][+-][0-9]{2,3})?$';
    weights double precision[];
    minimum_evidence bigint;
    evidence_saturation bigint;
    preferred_neutral double precision;
    maximum_neutral double precision;
    maximum_relative double precision;
    maximum_absolute double precision;
    score_floor_value double precision;
    score_ceiling_value double precision;
    preferences double precision[];
BEGIN
    IF policy_version <> 1 OR
       policy_hash <> recommendation_semantic_tagged_fnv1a64(policy_canonical)
    THEN
        RETURN false;
    END IF;

    parts := string_to_array(policy_canonical, ';');
    IF cardinality(parts) <> cardinality(expected_keys) + 1 OR
       parts[1] <> 'experiment_recommendation_scoring_policy_v1'
    THEN
        RETURN false;
    END IF;

    FOR index_value IN 1..cardinality(expected_keys) LOOP
        separator := strpos(parts[index_value + 1], '=');
        IF separator <= 1 OR
           strpos(substr(parts[index_value + 1], separator + 1), '=') <> 0
        THEN
            RETURN false;
        END IF;

        key_text := substr(parts[index_value + 1], 1, separator - 1);
        value_text := substr(parts[index_value + 1], separator + 1);

        IF key_text <> expected_keys[index_value] OR value_text = '' THEN
            RETURN false;
        END IF;

        values_text := array_append(values_text, value_text);
    END LOOP;

    IF values_text[1] <> '1' THEN
        RETURN false;
    END IF;

    -- C++ v1 emits non-negative finite policy values in a deterministic
    -- decimal/scientific spelling. Reject alternate spellings such as
    -- trailing fractional zeros, uppercase E, leading '+', and negative zero.
    FOREACH index_value IN ARRAY ARRAY[
        2,3,4,5,6,7,8,9,10,13,14,15,16,18,19,20,21,22,23
    ]
    LOOP
        IF values_text[index_value] !~ canonical_double_pattern THEN
            RETURN false;
        END IF;
    END LOOP;

    IF values_text[11] !~ '^[1-9][0-9]*$' OR
       values_text[12] !~ '^(0|[1-9][0-9]*)$' OR
       values_text[17] !~ '^[01]$'
    THEN
        RETURN false;
    END IF;

    BEGIN
        weights := ARRAY[
            values_text[2]::double precision,
            values_text[3]::double precision,
            values_text[4]::double precision,
            values_text[5]::double precision,
            values_text[6]::double precision,
            values_text[7]::double precision,
            values_text[8]::double precision,
            values_text[9]::double precision,
            values_text[10]::double precision
        ];
        minimum_evidence := values_text[11]::bigint;
        evidence_saturation := values_text[12]::bigint;
        preferred_neutral := values_text[13]::double precision;
        maximum_neutral := values_text[14]::double precision;
        maximum_relative := values_text[15]::double precision;
        maximum_absolute := values_text[16]::double precision;
        score_floor_value := values_text[18]::double precision;
        score_ceiling_value := values_text[19]::double precision;
        preferences := ARRAY[
            values_text[20]::double precision,
            values_text[21]::double precision,
            values_text[22]::double precision,
            values_text[23]::double precision
        ];
    EXCEPTION
        WHEN numeric_value_out_of_range OR invalid_text_representation THEN
            RETURN false;
    END;

    -- Mirror ValidateRecommendationScoringPolicy().
    IF EXISTS (
        SELECT 1
        FROM unnest(weights) value
        WHERE value < 0.0)
    THEN
        RETURN false;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM unnest(weights[1:7]) value
        WHERE value > 0.0)
    THEN
        RETURN false;
    END IF;

    IF minimum_evidence <= 0 OR evidence_saturation < minimum_evidence THEN
        RETURN false;
    END IF;

    IF preferred_neutral < 0.0 OR preferred_neutral > 1.0 THEN
        RETURN false;
    END IF;

    IF maximum_neutral < preferred_neutral OR maximum_neutral > 1.0 THEN
        RETURN false;
    END IF;

    IF maximum_relative <= 0.0 OR maximum_absolute <= 0.0 THEN
        RETURN false;
    END IF;

    IF score_floor_value < 0.0 OR score_ceiling_value > 1.0 OR
       score_floor_value >= score_ceiling_value
    THEN
        RETURN false;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(preferences) value
        WHERE value < 0.0 OR value > 1.0)
    THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$_$;


--
-- Name: recommendation_scoring_semantic_canonical_v1(text, integer); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_scoring_semantic_canonical_v1(scoring_policy_canonical text, scoring_version integer) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT 'experiment_recommendation_scoring_semantic_v1;semantic_version=1;' ||
        'algorithm=weighted_component_score_v1;' ||
        'components=leader_quality,inference_accuracy,evidence_strength,neutral_balance,' ||
        'structural_proximity,parameter_preference,source_rank,horizon_change_penalty,' ||
        'relative_mutation_penalty;' ||
        'normalization=component_clamp_unit_and_policy_thresholds_v1;' ||
        'aggregation=positive_weight_normalized_minus_penalty_weight_normalized_then_policy_clamp_v1;' ||
        'missing=neutral_policy_or_ineligible_v1;' ||
        'structural_distance=relative_delta_else_absolute_delta_v1;' ||
        'source_metrics=persisted_leader_accuracy_neutral_evidence_v1;policy=' ||
        octet_length(scoring_policy_canonical) || ':' || scoring_policy_canonical
    WHERE scoring_version = 1
$$;


--
-- Name: recommendation_semantic_tagged_fnv1a64(text); Type: FUNCTION; Schema: phase4b_eval_80040; Owner: -
--

CREATE FUNCTION phase4b_eval_80040.recommendation_semantic_tagged_fnv1a64(canonical_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
DECLARE
    canonical_bytes bytea := convert_to(canonical_value, 'UTF8');
    hash_value numeric := 14695981039346656037;
    byte_index integer;
    low_byte integer;
    high_word bigint;
    low_word bigint;
BEGIN
    IF octet_length(canonical_bytes) > 0 THEN
        FOR byte_index IN 0..octet_length(canonical_bytes) - 1 LOOP
            low_byte := mod(hash_value, 256)::integer #
                get_byte(canonical_bytes, byte_index);
            hash_value := hash_value - mod(hash_value, 256) + low_byte;
            hash_value := mod(
                hash_value * 1099511628211, 18446744073709551616);
        END LOOP;
    END IF;
    high_word := trunc(hash_value / 4294967296)::bigint;
    low_word := mod(hash_value, 4294967296)::bigint;
    RETURN 'fnv1a64:' || lpad(to_hex(high_word), 8, '0') ||
        lpad(to_hex(low_word), 8, '0');
END;
$$;


--
-- Name: campaign_operations_reconciliation_resolution; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_operations_reconciliation_resolution (
    reconciliation_resolution_id bigint NOT NULL,
    reconciliation_observation_id bigint NOT NULL,
    observation_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    owning_service text NOT NULL COLLATE pg_catalog."C",
    owning_capability text NOT NULL COLLATE pg_catalog."C",
    transition_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    transition_identity_hash text NOT NULL COLLATE pg_catalog."C",
    cancellation_settlement_id bigint,
    dispatch_attempt_outcome_id bigint,
    resolution_disposition text NOT NULL COLLATE pg_catalog."C",
    resolution_contract_version integer NOT NULL,
    resolution_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    resolution_identity_hash text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT campaign_operations_reconcil_reconciliation_resolution_id_check CHECK ((reconciliation_resolution_id > 0)),
    CONSTRAINT campaign_operations_reconcili_resolution_contract_version_check CHECK ((resolution_contract_version = 1)),
    CONSTRAINT campaign_operations_reconciliati_resolution_identity_hash_check CHECK ((resolution_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_reconciliati_transition_identity_hash_check CHECK ((transition_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_reconciliation_reso_owning_capability_check CHECK ((owning_capability = ANY (ARRAY['campaign_operations_recovery'::text, 'campaign_operations_cancellation_coordinator'::text]))),
    CONSTRAINT campaign_operations_reconciliation_resolution_disposition_check CHECK ((resolution_disposition = ANY (ARRAY['request_returned_ready'::text, 'cancellation_settled'::text, 'already_resolved'::text]))),
    CONSTRAINT campaign_operations_resolution_causal_shape_check CHECK ((((owning_capability = 'campaign_operations_cancellation_coordinator'::text) AND (cancellation_settlement_id IS NOT NULL) AND (dispatch_attempt_outcome_id IS NULL) AND (resolution_disposition = 'cancellation_settled'::text)) OR ((owning_capability = 'campaign_operations_recovery'::text) AND (cancellation_settlement_id IS NULL) AND (dispatch_attempt_outcome_id IS NOT NULL) AND (resolution_disposition = ANY (ARRAY['request_returned_ready'::text, 'already_resolved'::text])))))
);


--
-- Name: TABLE campaign_operations_reconciliation_resolution; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.campaign_operations_reconciliation_resolution IS 'Immutable typed edge to PostgreSQL-validated owning-service causal evidence.';


--
-- Name: append_campaign_operations_cancellation_resolution(bigint, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_campaign_operations_cancellation_resolution(target_observation_id bigint, target_transition_canonical text, target_transition_hash text, target_resolution_canonical text, target_resolution_hash text) RETURNS public.campaign_operations_reconciliation_resolution
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    observation campaign_operations_reconciliation_observation%ROWTYPE;
    settlement campaign_operations_cancellation_settlement%ROWTYPE;
    existing campaign_operations_reconciliation_resolution%ROWTYPE;
    result campaign_operations_reconciliation_resolution%ROWTYPE;
BEGIN
    SELECT * INTO STRICT observation
    FROM campaign_operations_reconciliation_observation
    WHERE reconciliation_observation_id = target_observation_id
    FOR UPDATE;

    SELECT * INTO existing
    FROM campaign_operations_reconciliation_resolution
    WHERE reconciliation_observation_id = target_observation_id;
    IF existing.reconciliation_resolution_id IS NOT NULL THEN
        IF existing.cancellation_settlement_id IS NULL OR
           existing.dispatch_attempt_outcome_id IS NOT NULL OR
           existing.transition_identity_canonical <>
               target_transition_canonical OR
           existing.transition_identity_hash <> target_transition_hash OR
           existing.resolution_identity_canonical <>
               target_resolution_canonical OR
           existing.resolution_identity_hash <> target_resolution_hash THEN
            RAISE EXCEPTION
                'campaign operations cancellation resolution conflict'
                USING ERRCODE = '23514';
        END IF;
        RETURN existing;
    END IF;

    IF observation.reason_code <> 'cancellation_settlement_pending' OR
       observation.recommended_service <>
           'campaign_operations_cancellation_coordinator' OR
       observation.recommended_action <> 'replay_cancellation' OR
       observation.diagnostic_code <>
           'cancellation_settlement_pending' THEN
        RAISE EXCEPTION
            'campaign operations cancellation observation is not actionable'
            USING ERRCODE = '23514';
    END IF;

    BEGIN
        SELECT causal_settlement.* INTO STRICT settlement
        FROM campaign_operations_cancellation_settlement causal_settlement
        JOIN campaign_operations_cancellation_request cancellation
          ON cancellation.cancellation_request_id =
             causal_settlement.cancellation_request_id
        WHERE causal_settlement.settlement_identity_canonical =
                  target_transition_canonical
          AND causal_settlement.settlement_identity_hash =
                  target_transition_hash
          AND cancellation.operational_campaign_id =
                  observation.operational_campaign_id
          AND cancellation.operational_request_id =
                  observation.operational_request_id
          AND cancellation.request_identity_canonical =
                  observation.request_identity_canonical
          AND cancellation.expected_request_state =
                  observation.expected_request_state
          AND cancellation.expected_request_version =
                  observation.expected_request_version
          AND EXISTS (
              SELECT 1
              FROM campaign_operations_control_audit_reference_event audit
              WHERE audit.cancellation_request_id =
                        cancellation.cancellation_request_id
                AND audit.cancellation_settlement_id =
                        causal_settlement.cancellation_settlement_id
                AND audit.operational_campaign_id =
                        observation.operational_campaign_id
                AND audit.operational_request_id =
                        observation.operational_request_id
                AND audit.cause_kind = 'cancellation_settled'
                AND audit.capability =
                        'campaign_operations_cancellation_coordinator'
                AND audit.outcome = 'recorded')
        FOR UPDATE OF causal_settlement;
    EXCEPTION WHEN no_data_found OR too_many_rows THEN
        RAISE EXCEPTION
            'campaign operations cancellation causal evidence mismatch'
            USING ERRCODE = '23514';
    END;

    INSERT INTO campaign_operations_reconciliation_resolution(
        reconciliation_observation_id, observation_identity_canonical,
        owning_service, owning_capability, transition_identity_canonical,
        transition_identity_hash, cancellation_settlement_id,
        resolution_disposition, resolution_contract_version,
        resolution_identity_canonical, resolution_identity_hash)
    VALUES(target_observation_id,
        observation.observation_identity_canonical,
        'campaign_operations_cancellation_coordinator',
        'campaign_operations_cancellation_coordinator',
        settlement.settlement_identity_canonical,
        settlement.settlement_identity_hash,
        settlement.cancellation_settlement_id,
        'cancellation_settled', 1,
        target_resolution_canonical, target_resolution_hash)
    RETURNING * INTO result;
    RETURN result;
END;
$$;


--
-- Name: append_campaign_operations_recovery_resolution(bigint, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_campaign_operations_recovery_resolution(target_observation_id bigint, target_transition_canonical text, target_transition_hash text, target_resolution_disposition text, target_resolution_canonical text, target_resolution_hash text) RETURNS public.campaign_operations_reconciliation_resolution
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    observation campaign_operations_reconciliation_observation%ROWTYPE;
    outcome campaign_operations_dispatch_attempt_outcome%ROWTYPE;
    existing campaign_operations_reconciliation_resolution%ROWTYPE;
    derived_disposition text;
    result campaign_operations_reconciliation_resolution%ROWTYPE;
BEGIN
    SELECT * INTO STRICT observation
    FROM campaign_operations_reconciliation_observation
    WHERE reconciliation_observation_id = target_observation_id
    FOR UPDATE;

    SELECT * INTO existing
    FROM campaign_operations_reconciliation_resolution
    WHERE reconciliation_observation_id = target_observation_id;
    IF existing.reconciliation_resolution_id IS NOT NULL THEN
        IF existing.cancellation_settlement_id IS NOT NULL OR
           existing.dispatch_attempt_outcome_id IS NULL OR
           existing.transition_identity_canonical <>
               target_transition_canonical OR
           existing.transition_identity_hash <> target_transition_hash OR
           existing.resolution_disposition <>
               target_resolution_disposition OR
           existing.resolution_identity_canonical <>
               target_resolution_canonical OR
           existing.resolution_identity_hash <> target_resolution_hash THEN
            RAISE EXCEPTION
                'campaign operations recovery resolution conflict'
                USING ERRCODE = '23514';
        END IF;
        RETURN existing;
    END IF;

    IF observation.reason_code <>
           'dispatch_lease_expired_no_downstream_evidence' OR
       observation.recommended_service <>
           'campaign_operations_dispatch_recovery' OR
       observation.recommended_action <> 'clear_stale_dispatch_lease' OR
       observation.diagnostic_code <>
           'dispatch_lease_expired_no_downstream_evidence' THEN
        RAISE EXCEPTION
            'campaign operations recovery observation is not actionable'
            USING ERRCODE = '23514';
    END IF;

    BEGIN
        SELECT causal_outcome.* INTO STRICT outcome
        FROM campaign_operations_dispatch_attempt_outcome causal_outcome
        JOIN campaign_operations_dispatch_attempt attempt
          ON attempt.dispatch_attempt_id =
             causal_outcome.dispatch_attempt_id
        WHERE causal_outcome.outcome_identity_canonical =
                  target_transition_canonical
          AND causal_outcome.outcome_identity_hash =
                  target_transition_hash
          AND attempt.operational_request_id =
                  observation.operational_request_id
          AND causal_outcome.result_classification = 'rejected'
          AND causal_outcome.downstream_evidence_classification =
                  'no_phase5_evidence'
          AND causal_outcome.semantic_conflict_classification = 'none'
          AND causal_outcome.uncertain_commit_recovery_classification =
                  'proven_no_commit'
          AND causal_outcome.diagnostic_code =
                  observation.diagnostic_code
          AND causal_outcome.expected_request_version =
                  observation.expected_request_version
          AND causal_outcome.resulting_request_version =
                  observation.expected_request_version + 1
          AND EXISTS (
              SELECT 1
              FROM campaign_operations_dispatch_audit_reference_event audit
              WHERE audit.dispatch_attempt_id =
                        attempt.dispatch_attempt_id
                AND audit.dispatch_attempt_outcome_id =
                        causal_outcome.dispatch_attempt_outcome_id
                AND audit.operational_campaign_id =
                        observation.operational_campaign_id
                AND audit.operational_request_id =
                        observation.operational_request_id
                AND audit.cause_kind = 'dispatch_lease_recovered'
                AND audit.capability = 'campaign_operations_recovery'
                AND audit.prior_version =
                        observation.expected_request_version
                AND audit.resulting_version =
                        observation.expected_request_version + 1
                AND audit.outcome = 'recorded')
        FOR UPDATE OF causal_outcome;
    EXCEPTION WHEN no_data_found OR too_many_rows THEN
        RAISE EXCEPTION
            'campaign operations recovery causal evidence mismatch'
            USING ERRCODE = '23514';
    END;

    IF EXISTS (
        SELECT 1
        FROM campaign_operations_reconciliation_resolution resolution
        WHERE resolution.dispatch_attempt_outcome_id =
              outcome.dispatch_attempt_outcome_id) THEN
        derived_disposition := 'already_resolved';
    ELSE
        derived_disposition := 'request_returned_ready';
    END IF;
    IF target_resolution_disposition <> derived_disposition THEN
        RAISE EXCEPTION
            'campaign operations recovery disposition mismatch'
            USING ERRCODE = '23514';
    END IF;

    INSERT INTO campaign_operations_reconciliation_resolution(
        reconciliation_observation_id, observation_identity_canonical,
        owning_service, owning_capability, transition_identity_canonical,
        transition_identity_hash, dispatch_attempt_outcome_id,
        resolution_disposition, resolution_contract_version,
        resolution_identity_canonical, resolution_identity_hash)
    VALUES(target_observation_id,
        observation.observation_identity_canonical,
        'campaign_operations_dispatch_recovery',
        'campaign_operations_recovery',
        outcome.outcome_identity_canonical,
        outcome.outcome_identity_hash,
        outcome.dispatch_attempt_outcome_id,
        derived_disposition, 1,
        target_resolution_canonical, target_resolution_hash)
    RETURNING * INTO result;
    RETURN result;
END;
$$;


--
-- Name: experiment_lifecycle_cancellation_event; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.experiment_lifecycle_cancellation_event (
    lifecycle_cancellation_event_id bigint NOT NULL,
    cancellation_request_id bigint NOT NULL,
    cancellation_request_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    downstream_control_owner_id bigint NOT NULL,
    experiment_id bigint NOT NULL,
    expected_status text NOT NULL COLLATE pg_catalog."C",
    expected_phase text NOT NULL COLLATE pg_catalog."C",
    observed_status text NOT NULL COLLATE pg_catalog."C",
    observed_phase text NOT NULL COLLATE pg_catalog."C",
    resulting_status text NOT NULL COLLATE pg_catalog."C",
    disposition text NOT NULL COLLATE pg_catalog."C",
    actor_identity text NOT NULL COLLATE pg_catalog."C",
    event_contract_version integer NOT NULL,
    event_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    event_identity_hash text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT experiment_lifecycle_cancell_lifecycle_cancellation_event_check CHECK ((lifecycle_cancellation_event_id > 0)),
    CONSTRAINT experiment_lifecycle_cancellatio_event_identity_canonical_check CHECK ((event_identity_canonical <> ''::text)),
    CONSTRAINT experiment_lifecycle_cancellation__event_contract_version_check CHECK ((event_contract_version = 1)),
    CONSTRAINT experiment_lifecycle_cancellation_eve_event_identity_hash_check CHECK ((event_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT experiment_lifecycle_cancellation_event_actor_identity_check CHECK ((actor_identity ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text)),
    CONSTRAINT experiment_lifecycle_cancellation_event_disposition_check CHECK ((disposition = ANY (ARRAY['accepted'::text, 'already_terminal'::text, 'running_not_supported'::text]))),
    CONSTRAINT lifecycle_cancellation_result_shape_check CHECK ((((disposition = 'accepted'::text) AND (observed_status = ANY (ARRAY['pending'::text, 'paused'::text])) AND (resulting_status = 'cancelled'::text)) OR ((disposition = 'already_terminal'::text) AND (observed_status = ANY (ARRAY['completed'::text, 'failed'::text, 'cancelled'::text])) AND (resulting_status = observed_status)) OR ((disposition = 'running_not_supported'::text) AND (observed_status = 'running'::text) AND (resulting_status = observed_status))))
);


--
-- Name: apply_experiment_lifecycle_cancellation(bigint, bigint, bigint, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_experiment_lifecycle_cancellation(target_cancellation_request_id bigint, target_control_owner_id bigint, target_experiment_id bigint, expected_status_value text, expected_phase_value text, actor_value text, event_canonical_value text, event_hash_value text) RETURNS public.experiment_lifecycle_cancellation_event
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    target_campaign_id bigint;
    campaign_completed boolean;
    current_experiment experiment%ROWTYPE;
    disposition_value text;
    resulting_status_value text;
    result experiment_lifecycle_cancellation_event%ROWTYPE;
BEGIN
    SELECT cancellation.operational_campaign_id
      INTO STRICT target_campaign_id
    FROM campaign_operations_cancellation_request cancellation
    JOIN campaign_operations_downstream_control_owner control_owner
      ON control_owner.operational_request_id =
         cancellation.operational_request_id
    WHERE cancellation.cancellation_request_id =
              target_cancellation_request_id
      AND cancellation.actor_identity = actor_value
      AND control_owner.downstream_control_owner_id =
              target_control_owner_id
      AND control_owner.experiment_id = target_experiment_id;

    campaign_completed :=
        campaign_operations_lifecycle_cancellation_boundary_completed(
            target_campaign_id);

    SELECT * INTO result
    FROM experiment_lifecycle_cancellation_event
    WHERE cancellation_request_id = target_cancellation_request_id
      AND downstream_control_owner_id = target_control_owner_id;
    IF result.lifecycle_cancellation_event_id IS NOT NULL THEN
        IF result.event_identity_canonical <> event_canonical_value OR
           result.event_identity_hash <> event_hash_value THEN
            RAISE EXCEPTION 'lifecycle cancellation replay conflicts'
                USING ERRCODE = '23514';
        END IF;
        RETURN result;
    END IF;

    IF campaign_completed THEN
        RAISE EXCEPTION
            'campaign operations completed campaign is immutable'
            USING ERRCODE = '23514';
    END IF;

    SELECT * INTO STRICT current_experiment
    FROM experiment WHERE experiment_id = target_experiment_id FOR UPDATE;
    IF current_experiment.status <> expected_status_value OR
       current_experiment.phase <> expected_phase_value THEN
        RAISE EXCEPTION 'experiment lifecycle changed during cancellation'
            USING ERRCODE = '40001';
    END IF;
    IF current_experiment.status IN ('pending', 'paused') THEN
        disposition_value := 'accepted';
        resulting_status_value := 'cancelled';
        UPDATE experiment
           SET status = 'cancelled', completed_at = transaction_timestamp(),
               updated_at = transaction_timestamp()
         WHERE experiment_id = target_experiment_id;
    ELSIF current_experiment.status IN (
            'completed', 'failed', 'cancelled') THEN
        disposition_value := 'already_terminal';
        resulting_status_value := current_experiment.status;
    ELSIF current_experiment.status = 'running' THEN
        disposition_value := 'running_not_supported';
        resulting_status_value := current_experiment.status;
    ELSE
        RAISE EXCEPTION 'unsupported experiment lifecycle state'
            USING ERRCODE = '23514';
    END IF;
    INSERT INTO experiment_lifecycle_cancellation_event(
        cancellation_request_id,
        cancellation_request_identity_canonical,
        downstream_control_owner_id, experiment_id,
        expected_status, expected_phase, observed_status, observed_phase,
        resulting_status, disposition, actor_identity,
        event_contract_version, event_identity_canonical,
        event_identity_hash)
    SELECT target_cancellation_request_id,
           cancellation_identity_canonical,
           target_control_owner_id, target_experiment_id,
           expected_status_value, expected_phase_value,
           current_experiment.status, current_experiment.phase,
           resulting_status_value, disposition_value, actor_value,
           1, event_canonical_value, event_hash_value
    FROM campaign_operations_cancellation_request
    WHERE cancellation_request_id = target_cancellation_request_id
    RETURNING * INTO result;
    RETURN result;
EXCEPTION WHEN unique_violation THEN
    SELECT * INTO STRICT result
    FROM experiment_lifecycle_cancellation_event
    WHERE cancellation_request_id = target_cancellation_request_id
      AND downstream_control_owner_id = target_control_owner_id;
    IF result.event_identity_canonical <> event_canonical_value OR
       result.event_identity_hash <> event_hash_value THEN
        RAISE EXCEPTION 'lifecycle cancellation replay conflicts'
            USING ERRCODE = '23514';
    END IF;
    RETURN result;
END;
$$;


--
-- Name: campaign_operations_completion_blockers(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_completion_blockers(target_campaign_id bigint) RETURNS TABLE(blocker_code text, blocker_detail text, blocker_class text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE scope_count integer;
DECLARE request_total integer;
BEGIN
    SELECT materialization_member_count INTO scope_count
    FROM campaign_operations_campaign
    WHERE operational_campaign_id = target_campaign_id;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'campaign_not_found'::text,
            target_campaign_id::text, 'inconsistent'::text;
        RETURN;
    END IF;

    SELECT count(*)::integer INTO request_total
    FROM campaign_operations_operational_request
    WHERE operational_campaign_id = target_campaign_id;

    RETURN QUERY
    SELECT 'campaign_paused',
           COALESCE(control.control_event_id::text, 'unknown'), 'unsettled'
    FROM LATERAL (
        SELECT control_event_id, event_kind
        FROM campaign_operations_control_event
        WHERE operational_campaign_id = target_campaign_id
        ORDER BY control_version DESC LIMIT 1) control
    WHERE control.event_kind = 'pause'
    UNION ALL
    SELECT 'authorization_missing', target_campaign_id::text, 'inconsistent'
    WHERE NOT EXISTS (
        SELECT 1 FROM campaign_operations_authorization_event
        WHERE operational_campaign_id = target_campaign_id)
    UNION ALL
    SELECT 'active_authorization_unexhausted',
           auth_head.authorization_event_id::text, 'unsettled'
    FROM (
        SELECT DISTINCT ON (
            action_kind, action_contract_version,
            scope_kind, scope_contract_version) *
        FROM campaign_operations_authorization_event
        WHERE operational_campaign_id = target_campaign_id
        ORDER BY action_kind, action_contract_version,
            scope_kind, scope_contract_version,
            chain_version DESC, authorization_event_id DESC) auth_head
    WHERE auth_head.event_kind = 'granted'
      AND auth_head.not_before <= transaction_timestamp()
      AND (auth_head.expires_at IS NULL OR
           auth_head.expires_at > transaction_timestamp())
      AND NOT EXISTS (
          SELECT 1 FROM campaign_operations_operational_request
          WHERE operational_campaign_id = target_campaign_id
            AND request_state IN (
                'bound', 'permanently_failed', 'cancelled'))
    UNION ALL
    SELECT 'budget_missing', target_campaign_id::text, 'inconsistent'
    WHERE NOT EXISTS (
        SELECT 1 FROM campaign_operations_budget_ledger_entry
        WHERE operational_campaign_id = target_campaign_id)
    UNION ALL
    SELECT 'budget_accounting_inconsistent',
           format('total=%s,ever=%s,committed=%s,released=%s,held=%s',
               head.resulting_total, accounting.ever_reserved,
               accounting.committed, accounting.released_or_expired,
               accounting.held),
           'inconsistent'
    FROM LATERAL (
        SELECT * FROM campaign_operations_budget_ledger_entry
        WHERE operational_campaign_id = target_campaign_id
        ORDER BY ledger_version DESC LIMIT 1) head
    CROSS JOIN LATERAL (
        SELECT
            COALESCE(sum(amount), 0)::bigint AS ever_reserved,
            COALESCE(sum(amount) FILTER (
                WHERE reservation_state = 'committed'), 0)::bigint
                AS committed,
            COALESCE(sum(amount) FILTER (
                WHERE reservation_state IN ('released', 'expired')), 0)::
                bigint AS released_or_expired,
            COALESCE(sum(amount) FILTER (
                WHERE reservation_state = 'held'), 0)::bigint AS held
        FROM campaign_operations_reservation
        WHERE operational_campaign_id = target_campaign_id) accounting
    WHERE accounting.ever_reserved <>
              accounting.committed + accounting.released_or_expired +
              accounting.held
       OR accounting.committed + accounting.held > head.resulting_total
       OR head.resulting_total < 0
    UNION ALL
    SELECT 'request_missing', target_campaign_id::text, 'unsettled'
    WHERE request_total = 0
    UNION ALL
    SELECT 'request_cardinality_conflict', request_total::text, 'inconsistent'
    WHERE request_total > 1
    UNION ALL
    SELECT CASE request_state
               WHEN 'ready' THEN 'request_ready'
               WHEN 'dispatching' THEN 'request_dispatching'
               ELSE 'request_reconciliation_required'
           END,
           operational_request_id::text,
           CASE WHEN request_state = 'reconciliation_required'
                THEN 'reconciliation_required' ELSE 'unsettled' END
    FROM campaign_operations_operational_request
    WHERE operational_campaign_id = target_campaign_id
      AND request_state IN ('ready', 'dispatching', 'reconciliation_required')
    UNION ALL
    SELECT 'active_dispatch_lease', operational_request_id::text, 'unsettled'
    FROM campaign_operations_operational_request
    WHERE operational_campaign_id = target_campaign_id
      AND (lease_token_hash IS NOT NULL OR lease_expires_at IS NOT NULL OR
           dispatcher_identity IS NOT NULL)
    UNION ALL
    SELECT 'reservation_request_cardinality_mismatch',
           format('reservations=%s,requests=%s',
               (SELECT count(*) FROM campaign_operations_reservation
                WHERE operational_campaign_id = target_campaign_id),
               request_total), 'inconsistent'
    WHERE (SELECT count(*) FROM campaign_operations_reservation
           WHERE operational_campaign_id = target_campaign_id) <> request_total
    UNION ALL
    SELECT CASE reservation_state
               WHEN 'held' THEN 'reservation_held'
               ELSE 'reservation_reconciliation_required'
           END,
           reservation_id::text,
           CASE WHEN reservation_state = 'reconciliation_required'
                THEN 'reconciliation_required' ELSE 'unsettled' END
    FROM campaign_operations_reservation
    WHERE operational_campaign_id = target_campaign_id
      AND reservation_state IN ('held', 'reconciliation_required')
    UNION ALL
    SELECT 'reservation_request_state_conflict',
           format('reservation=%s,request=%s',
               reservation.reservation_state, request.request_state),
           'inconsistent'
    FROM campaign_operations_reservation reservation
    JOIN campaign_operations_operational_request request
      ON request.reservation_id = reservation.reservation_id
    WHERE reservation.operational_campaign_id = target_campaign_id
      AND NOT (
          (request.request_state = 'bound' AND
           reservation.reservation_state = 'committed') OR
          (request.request_state IN ('permanently_failed', 'cancelled') AND
           reservation.reservation_state IN ('released', 'expired')))
    UNION ALL
    SELECT 'incomplete_dispatch_attempt', attempt.dispatch_attempt_id::text,
           'reconciliation_required'
    FROM campaign_operations_dispatch_attempt attempt
    JOIN campaign_operations_operational_request request
      ON request.operational_request_id = attempt.operational_request_id
    LEFT JOIN campaign_operations_dispatch_attempt_outcome outcome
      ON outcome.dispatch_attempt_id = attempt.dispatch_attempt_id
    WHERE request.operational_campaign_id = target_campaign_id
      AND outcome.dispatch_attempt_outcome_id IS NULL
    UNION ALL
    SELECT 'ambiguous_dispatch_attempt', outcome.dispatch_attempt_id::text,
           'reconciliation_required'
    FROM campaign_operations_dispatch_attempt_outcome outcome
    JOIN campaign_operations_dispatch_attempt attempt
      ON attempt.dispatch_attempt_id = outcome.dispatch_attempt_id
    JOIN campaign_operations_operational_request request
      ON request.operational_request_id = attempt.operational_request_id
    WHERE request.operational_campaign_id = target_campaign_id
      AND (outcome.result_classification = 'reconciliation_required' OR
           outcome.uncertain_commit_recovery_classification =
               'ambiguous_evidence' OR
           outcome.downstream_evidence_classification IN (
               'partial_phase5_evidence', 'progressed_unbound_evidence',
               'causally_ambiguous'))
    UNION ALL
    SELECT 'binding_cardinality_mismatch',
           format('request=%s,bindings=%s,scope=%s',
               request.operational_request_id,
               (SELECT count(*) FROM campaign_operations_request_binding b
                WHERE b.operational_request_id =
                      request.operational_request_id),
               scope_count), 'inconsistent'
    FROM campaign_operations_operational_request request
    WHERE request.operational_campaign_id = target_campaign_id
      AND request.request_state = 'bound'
      AND (SELECT count(*) FROM campaign_operations_request_binding b
           WHERE b.operational_request_id =
                 request.operational_request_id) <> scope_count
    UNION ALL
    SELECT 'control_owner_cardinality_mismatch',
           format('request=%s,owners=%s,scope=%s',
               request.operational_request_id,
               (SELECT count(*)
                FROM campaign_operations_downstream_control_owner owner
                WHERE owner.operational_request_id =
                      request.operational_request_id),
               scope_count), 'inconsistent'
    FROM campaign_operations_operational_request request
    WHERE request.operational_campaign_id = target_campaign_id
      AND request.request_state = 'bound'
      AND (SELECT count(*)
           FROM campaign_operations_downstream_control_owner owner
           WHERE owner.operational_request_id =
                 request.operational_request_id) <> scope_count
    UNION ALL
    SELECT 'unexpected_unbound_binding', request.operational_request_id::text,
           'inconsistent'
    FROM campaign_operations_operational_request request
    WHERE request.operational_campaign_id = target_campaign_id
      AND request.request_state IN ('permanently_failed', 'cancelled')
      AND EXISTS (
          SELECT 1 FROM campaign_operations_request_binding binding
          WHERE binding.operational_request_id =
                request.operational_request_id)
    UNION ALL
    SELECT 'downstream_lifecycle_nonterminal',
           format('experiment=%s,status=%s,phase=%s',
               experiment.experiment_id, experiment.status,
               experiment.phase), 'unsettled'
    FROM campaign_operations_request_binding binding
    JOIN campaign_operations_operational_request request
      ON request.operational_request_id = binding.operational_request_id
    JOIN experiment
      ON experiment.experiment_id = binding.experiment_id
    WHERE request.operational_campaign_id = target_campaign_id
      AND experiment.status NOT IN ('completed', 'failed', 'cancelled')
    UNION ALL
    SELECT 'cancellation_unsettled',
           cancellation.cancellation_request_id::text, 'unsettled'
    FROM campaign_operations_cancellation_request cancellation
    LEFT JOIN campaign_operations_cancellation_settlement settlement
      ON settlement.cancellation_request_id =
         cancellation.cancellation_request_id
    WHERE cancellation.operational_campaign_id = target_campaign_id
      AND settlement.cancellation_settlement_id IS NULL
    UNION ALL
    SELECT 'cancellation_inconsistent',
           cancellation.cancellation_request_id::text, 'inconsistent'
    FROM campaign_operations_cancellation_request cancellation
    JOIN campaign_operations_cancellation_settlement settlement
      ON settlement.cancellation_request_id =
         cancellation.cancellation_request_id
    WHERE cancellation.operational_campaign_id = target_campaign_id
      AND settlement.disposition = 'inconsistent'
    UNION ALL
    SELECT 'blocking_reconciliation_observation',
           format('observation=%s,reason=%s',
               observation.reconciliation_observation_id,
               observation.reason_code), 'reconciliation_required'
    FROM campaign_operations_reconciliation_observation observation
    LEFT JOIN campaign_operations_reconciliation_resolution resolution
      ON resolution.reconciliation_observation_id =
         observation.reconciliation_observation_id
    WHERE observation.operational_campaign_id = target_campaign_id
      AND resolution.reconciliation_resolution_id IS NULL
      AND observation.reason_code NOT IN (
          'terminal_lifecycle_completion_ready',
          'post_completion_lifecycle_changed');
END;
$$;


--
-- Name: campaign_operations_completion_classification(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_completion_classification(target_campaign_id bigint) RETURNS TABLE(administrative_terminal_state text, completion_classification text, scope_member_count integer, completed_member_count integer, failed_member_count integer, cancelled_or_never_dispatched_member_count integer, reservation_count integer, request_count integer, binding_count integer, control_owner_count integer, cancellation_request_count integer, cancellation_settlement_count integer, unresolved_blocking_observation_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE request_state_value text;
DECLARE completed_count integer;
DECLARE failed_count integer;
DECLARE cancelled_count integer;
DECLARE scope_count integer;
DECLARE bound_count integer;
BEGIN
    IF EXISTS (
        SELECT 1 FROM campaign_operations_completion_blockers(
            target_campaign_id)) THEN
        RAISE EXCEPTION 'campaign operations completion remains blocked'
            USING ERRCODE = 'P0001';
    END IF;
    SELECT campaign.materialization_member_count, request.request_state
      INTO STRICT scope_count, request_state_value
    FROM campaign_operations_campaign campaign
    JOIN campaign_operations_operational_request request
      ON request.operational_campaign_id =
         campaign.operational_campaign_id
    WHERE campaign.operational_campaign_id = target_campaign_id;
    SELECT
        count(*) FILTER (WHERE experiment.status = 'completed')::integer,
        count(*) FILTER (WHERE experiment.status = 'failed')::integer,
        count(*) FILTER (WHERE experiment.status = 'cancelled')::integer,
        count(*)::integer
      INTO completed_count, failed_count, cancelled_count, bound_count
    FROM campaign_operations_request_binding binding
    JOIN campaign_operations_operational_request request
      ON request.operational_request_id = binding.operational_request_id
    JOIN experiment ON experiment.experiment_id = binding.experiment_id
    WHERE request.operational_campaign_id = target_campaign_id;
    IF request_state_value = 'permanently_failed' THEN
        completion_classification := 'operational_request_failed';
        administrative_terminal_state := 'terminal_failed';
        completed_count := 0;
        failed_count := 0;
        cancelled_count := scope_count;
    ELSIF request_state_value = 'cancelled' THEN
        completion_classification := 'all_scope_cancelled';
        administrative_terminal_state := 'terminal_cancelled';
        completed_count := 0;
        failed_count := 0;
        cancelled_count := scope_count;
    ELSIF failed_count > 0 AND
          (completed_count > 0 OR cancelled_count > 0) THEN
        completion_classification := 'mixed_terminal_outcomes';
        administrative_terminal_state := 'terminal_failed';
    ELSIF failed_count = scope_count THEN
        completion_classification := 'downstream_failure';
        administrative_terminal_state := 'terminal_failed';
    ELSIF failed_count = 0 AND completed_count > 0 AND
          cancelled_count > 0 THEN
        completion_classification := 'terminal_partial_completion';
        administrative_terminal_state := 'terminal_completed';
    ELSIF cancelled_count = scope_count THEN
        completion_classification := 'all_scope_cancelled';
        administrative_terminal_state := 'terminal_cancelled';
    ELSIF completed_count = scope_count THEN
        completion_classification := 'all_downstream_completed';
        administrative_terminal_state := 'terminal_completed';
    ELSE
        RAISE EXCEPTION 'campaign operations classification is ambiguous'
            USING ERRCODE = 'P0001';
    END IF;
    scope_member_count := scope_count;
    completed_member_count := completed_count;
    failed_member_count := failed_count;
    cancelled_or_never_dispatched_member_count := cancelled_count;
    SELECT count(*)::integer INTO reservation_count
    FROM campaign_operations_reservation
    WHERE operational_campaign_id = target_campaign_id;
    SELECT count(*)::integer INTO request_count
    FROM campaign_operations_operational_request
    WHERE operational_campaign_id = target_campaign_id;
    binding_count := bound_count;
    SELECT count(*)::integer INTO control_owner_count
    FROM campaign_operations_downstream_control_owner owner
    JOIN campaign_operations_operational_request request
      ON request.operational_request_id = owner.operational_request_id
    WHERE request.operational_campaign_id = target_campaign_id;
    SELECT count(*)::integer INTO cancellation_request_count
    FROM campaign_operations_cancellation_request
    WHERE operational_campaign_id = target_campaign_id;
    SELECT count(*)::integer INTO cancellation_settlement_count
    FROM campaign_operations_cancellation_settlement settlement
    JOIN campaign_operations_cancellation_request cancellation
      ON cancellation.cancellation_request_id =
         settlement.cancellation_request_id
    WHERE cancellation.operational_campaign_id = target_campaign_id;
    unresolved_blocking_observation_count := 0;
    RETURN NEXT;
END;
$$;


--
-- Name: campaign_operations_completion_evidence_text(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_completion_evidence_text(target_campaign_id bigint, evidence_kind text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE result text;
BEGIN
    CASE evidence_kind
    WHEN 'authorization' THEN
        SELECT 'authorization_v1;' || COALESCE(string_agg(format(
            'head_id=%s,version=%s,kind=%s,action=%s,scope=%s,'
            'not_before=%s,expires_at=%s,canonical=%s:%s',
            head.authorization_event_id, head.chain_version,
            head.event_kind, head.action_kind, head.scope_kind,
            to_char(head.not_before AT TIME ZONE 'UTC',
                'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            COALESCE(to_char(head.expires_at AT TIME ZONE 'UTC',
                'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'), 'none'),
            octet_length(head.authorization_identity_canonical),
            head.authorization_identity_canonical), ';'
            ORDER BY head.action_kind, head.action_contract_version,
                head.scope_kind, head.scope_contract_version), 'none')
        INTO result
        FROM (
            SELECT DISTINCT ON (
                action_kind, action_contract_version,
                scope_kind, scope_contract_version) *
            FROM campaign_operations_authorization_event
            WHERE operational_campaign_id = target_campaign_id
            ORDER BY action_kind, action_contract_version,
                scope_kind, scope_contract_version,
                chain_version DESC, authorization_event_id DESC) head;
    WHEN 'budget' THEN
        SELECT format(
            'budget_v1;id=%s;version=%s;status=%s;total=%s;'
            'ever_reserved=%s;committed=%s;released_or_expired=%s;'
            'held=%s;unallocated=%s;canonical=%s:%s',
            head.budget_ledger_entry_id, head.ledger_version,
            head.ledger_status, head.resulting_total,
            COALESCE(accounting.ever_reserved, 0),
            COALESCE(accounting.committed, 0),
            COALESCE(accounting.released_or_expired, 0),
            COALESCE(accounting.held, 0),
            head.resulting_total - COALESCE(accounting.committed, 0) -
                COALESCE(accounting.held, 0),
            length(head.budget_identity_canonical),
            head.budget_identity_canonical)
        INTO result
        FROM LATERAL (
            SELECT * FROM campaign_operations_budget_ledger_entry
            WHERE operational_campaign_id = target_campaign_id
            ORDER BY ledger_version DESC LIMIT 1) head
        CROSS JOIN LATERAL (
            SELECT
                COALESCE(sum(amount), 0)::bigint AS ever_reserved,
                COALESCE(sum(amount) FILTER (
                    WHERE reservation_state = 'committed'), 0)::bigint
                    AS committed,
                COALESCE(sum(amount) FILTER (
                    WHERE reservation_state IN ('released', 'expired')), 0)
                    ::bigint AS released_or_expired,
                COALESCE(sum(amount) FILTER (
                    WHERE reservation_state = 'held'), 0)::bigint AS held
            FROM campaign_operations_reservation
            WHERE operational_campaign_id = target_campaign_id) accounting;
    WHEN 'reservation' THEN
        SELECT 'reservations_v1;' || COALESCE(string_agg(format(
            'id=%s,state=%s,version=%s,amount=%s,canonical=%s:%s;events=%s',
            reservation.reservation_id, reservation.reservation_state,
            reservation.state_version, reservation.amount,
            octet_length(reservation.reservation_identity_canonical),
            reservation.reservation_identity_canonical,
            COALESCE((SELECT string_agg(format(
                'event=%s,kind=%s,expected=%s,resulting=%s,canonical=%s:%s',
                event.reservation_event_id, event.transition_kind,
                event.expected_version, event.resulting_version,
                octet_length(event.reservation_event_identity_canonical),
                event.reservation_event_identity_canonical), ','
                ORDER BY event.resulting_version,
                    event.reservation_event_id)
                FROM campaign_operations_reservation_event event
                WHERE event.reservation_id = reservation.reservation_id),
                'none')), ';'
            ORDER BY reservation.reservation_id), 'none')
        INTO result
        FROM campaign_operations_reservation reservation
        WHERE reservation.operational_campaign_id = target_campaign_id;
    WHEN 'request' THEN
        SELECT 'requests_v1;' || COALESCE(string_agg(format(
            'id=%s,state=%s,version=%s,reservation=%s,lease=%s,'
            'canonical=%s:%s;attempts=%s',
            request.operational_request_id, request.request_state,
            request.state_version, request.reservation_id,
            CASE WHEN request.lease_token_hash IS NULL THEN 'none'
                 ELSE 'present' END,
            octet_length(request.request_identity_canonical),
            request.request_identity_canonical,
            COALESCE((SELECT string_agg(format(
                'attempt=%s,ordinal=%s,canonical=%s:%s,outcome=%s',
                attempt.dispatch_attempt_id, attempt.attempt_ordinal,
                octet_length(attempt.attempt_identity_canonical),
                attempt.attempt_identity_canonical,
                CASE WHEN outcome.dispatch_attempt_outcome_id IS NULL
                     THEN 'none'
                     ELSE format('id=%s,result=%s,canonical=%s:%s',
                         outcome.dispatch_attempt_outcome_id,
                         outcome.result_classification,
                         octet_length(outcome.outcome_identity_canonical),
                         outcome.outcome_identity_canonical)
                END), ',' ORDER BY attempt.attempt_ordinal,
                    attempt.dispatch_attempt_id)
                FROM campaign_operations_dispatch_attempt attempt
                LEFT JOIN campaign_operations_dispatch_attempt_outcome outcome
                  ON outcome.dispatch_attempt_id =
                     attempt.dispatch_attempt_id
                WHERE attempt.operational_request_id =
                      request.operational_request_id), 'none')), ';'
            ORDER BY request.operational_request_id), 'none')
        INTO result
        FROM campaign_operations_operational_request request
        WHERE request.operational_campaign_id = target_campaign_id;
    WHEN 'binding' THEN
        SELECT 'bindings_v1;' || COALESCE(string_agg(format(
            'binding=%s,request=%s,member=%s,ordinal=%s,experiment=%s,'
            'canonical=%s:%s,owner=%s',
            binding.request_binding_id, binding.operational_request_id,
            binding.recommendation_campaign_materialization_member_id,
            binding.member_ordinal, binding.experiment_id,
            octet_length(binding.binding_identity_canonical),
            binding.binding_identity_canonical,
            CASE WHEN owner.downstream_control_owner_id IS NULL THEN 'none'
                 ELSE format('id=%s,mode=%s,canonical=%s:%s',
                     owner.downstream_control_owner_id, owner.control_mode,
                     octet_length(owner.owner_identity_canonical),
                     owner.owner_identity_canonical)
            END), ';'
            ORDER BY binding.operational_request_id, binding.member_ordinal),
            'none')
        INTO result
        FROM campaign_operations_request_binding binding
        JOIN campaign_operations_operational_request request
          ON request.operational_request_id =
             binding.operational_request_id
        LEFT JOIN campaign_operations_downstream_control_owner owner
          ON owner.request_binding_id = binding.request_binding_id
        WHERE request.operational_campaign_id = target_campaign_id;
    WHEN 'lifecycle' THEN
        SELECT 'lifecycle_v1;' || COALESCE(string_agg(format(
            'binding=%s,experiment=%s,status=%s,phase=%s,updated=%s',
            binding.request_binding_id, experiment.experiment_id,
            experiment.status, experiment.phase,
            to_char(experiment.updated_at AT TIME ZONE 'UTC',
                'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')), ';'
            ORDER BY binding.member_ordinal), 'none')
        INTO result
        FROM campaign_operations_request_binding binding
        JOIN campaign_operations_operational_request request
          ON request.operational_request_id =
             binding.operational_request_id
        JOIN experiment
          ON experiment.experiment_id = binding.experiment_id
        WHERE request.operational_campaign_id = target_campaign_id;
    WHEN 'cancellation' THEN
        SELECT 'cancellations_v1;' || COALESCE(string_agg(format(
            'request=%s,target=%s,canonical=%s:%s,settlement=%s',
            cancellation.cancellation_request_id,
            COALESCE(cancellation.operational_request_id::text, 'campaign'),
            octet_length(cancellation.cancellation_identity_canonical),
            cancellation.cancellation_identity_canonical,
            CASE WHEN settlement.cancellation_settlement_id IS NULL
                 THEN 'none'
                 ELSE format('id=%s,disposition=%s,canonical=%s:%s',
                     settlement.cancellation_settlement_id,
                     settlement.disposition,
                     octet_length(settlement.settlement_identity_canonical),
                     settlement.settlement_identity_canonical)
            END), ';'
            ORDER BY cancellation.cancellation_request_id), 'none')
        INTO result
        FROM campaign_operations_cancellation_request cancellation
        LEFT JOIN campaign_operations_cancellation_settlement settlement
          ON settlement.cancellation_request_id =
             cancellation.cancellation_request_id
        WHERE cancellation.operational_campaign_id = target_campaign_id;
    WHEN 'reconciliation' THEN
        SELECT 'reconciliation_v1;' || COALESCE(string_agg(format(
            'observation=%s,reason=%s,evidence=%s:%s,canonical=%s:%s,'
            'resolution=%s',
            observation.reconciliation_observation_id,
            observation.reason_code,
            octet_length(observation.evidence_identity_canonical),
            observation.evidence_identity_canonical,
            octet_length(observation.observation_identity_canonical),
            observation.observation_identity_canonical,
            CASE WHEN resolution.reconciliation_resolution_id IS NULL
                 THEN 'none'
                 ELSE format('id=%s,disposition=%s,transition=%s:%s,'
                     'canonical=%s:%s',
                     resolution.reconciliation_resolution_id,
                     resolution.resolution_disposition,
                     octet_length(
                         resolution.transition_identity_canonical),
                     resolution.transition_identity_canonical,
                     octet_length(
                         resolution.resolution_identity_canonical),
                     resolution.resolution_identity_canonical)
            END), ';'
            ORDER BY observation.reconciliation_observation_id), 'none')
        INTO result
        FROM campaign_operations_reconciliation_observation observation
        LEFT JOIN campaign_operations_reconciliation_resolution resolution
          ON resolution.reconciliation_observation_id =
             observation.reconciliation_observation_id
        WHERE observation.operational_campaign_id = target_campaign_id;
    ELSE
        RAISE EXCEPTION 'unknown completion evidence kind'
            USING ERRCODE = '22023';
    END CASE;
    RETURN COALESCE(result, evidence_kind || '_v1;none');
END;
$$;


--
-- Name: campaign_operations_completion_event; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_operations_completion_event (
    completion_event_id bigint NOT NULL,
    operational_campaign_id bigint NOT NULL,
    campaign_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    operation_key text NOT NULL COLLATE pg_catalog."C",
    administrative_terminal_state text NOT NULL COLLATE pg_catalog."C",
    completion_classification text NOT NULL COLLATE pg_catalog."C",
    budget_ledger_entry_id bigint NOT NULL,
    budget_ledger_version integer NOT NULL,
    budget_resulting_total bigint NOT NULL,
    budget_ever_reserved bigint NOT NULL,
    budget_committed bigint NOT NULL,
    budget_released_or_expired bigint NOT NULL,
    budget_held bigint NOT NULL,
    budget_unallocated bigint NOT NULL,
    scope_member_count integer NOT NULL,
    completed_member_count integer NOT NULL,
    failed_member_count integer NOT NULL,
    cancelled_or_never_dispatched_member_count integer NOT NULL,
    reservation_count integer NOT NULL,
    request_count integer NOT NULL,
    binding_count integer NOT NULL,
    control_owner_count integer NOT NULL,
    cancellation_request_count integer NOT NULL,
    cancellation_settlement_count integer NOT NULL,
    unresolved_blocking_observation_count integer NOT NULL,
    authorization_evidence_canonical text NOT NULL COLLATE pg_catalog."C",
    authorization_evidence_hash text NOT NULL COLLATE pg_catalog."C",
    budget_evidence_canonical text NOT NULL COLLATE pg_catalog."C",
    budget_evidence_hash text NOT NULL COLLATE pg_catalog."C",
    reservation_evidence_canonical text NOT NULL COLLATE pg_catalog."C",
    reservation_evidence_hash text NOT NULL COLLATE pg_catalog."C",
    request_evidence_canonical text NOT NULL COLLATE pg_catalog."C",
    request_evidence_hash text NOT NULL COLLATE pg_catalog."C",
    binding_evidence_canonical text NOT NULL COLLATE pg_catalog."C",
    binding_evidence_hash text NOT NULL COLLATE pg_catalog."C",
    lifecycle_evidence_canonical text NOT NULL COLLATE pg_catalog."C",
    lifecycle_evidence_hash text NOT NULL COLLATE pg_catalog."C",
    cancellation_evidence_canonical text NOT NULL COLLATE pg_catalog."C",
    cancellation_evidence_hash text NOT NULL COLLATE pg_catalog."C",
    reconciliation_evidence_canonical text NOT NULL COLLATE pg_catalog."C",
    reconciliation_evidence_hash text NOT NULL COLLATE pg_catalog."C",
    actor_identity text NOT NULL COLLATE pg_catalog."C",
    capability text NOT NULL COLLATE pg_catalog."C",
    reason text NOT NULL COLLATE pg_catalog."C",
    completion_contract_version integer NOT NULL,
    completion_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    completion_identity_hash text NOT NULL COLLATE pg_catalog."C",
    recorded_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT campaign_operations_completi_administrative_terminal_stat_check CHECK ((administrative_terminal_state = ANY (ARRAY['terminal_completed'::text, 'terminal_cancelled'::text, 'terminal_failed'::text]))),
    CONSTRAINT campaign_operations_completi_authorization_evidence_canon_check CHECK ((authorization_evidence_canonical <> ''::text)),
    CONSTRAINT campaign_operations_completi_cancellation_evidence_canoni_check CHECK ((cancellation_evidence_canonical <> ''::text)),
    CONSTRAINT campaign_operations_completi_cancellation_settlement_coun_check CHECK ((cancellation_settlement_count >= 0)),
    CONSTRAINT campaign_operations_completi_cancelled_or_never_dispatche_check CHECK ((cancelled_or_never_dispatched_member_count >= 0)),
    CONSTRAINT campaign_operations_completi_completion_identity_canonica_check CHECK (((completion_identity_canonical <> ''::text) AND (octet_length(completion_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_completi_lifecycle_evidence_canonical_check CHECK ((lifecycle_evidence_canonical <> ''::text)),
    CONSTRAINT campaign_operations_completi_reconciliation_evidence_cano_check CHECK ((reconciliation_evidence_canonical <> ''::text)),
    CONSTRAINT campaign_operations_completi_reconciliation_evidence_hash_check CHECK ((reconciliation_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completi_reservation_evidence_canonic_check CHECK ((reservation_evidence_canonical <> ''::text)),
    CONSTRAINT campaign_operations_completi_unresolved_blocking_observat_check CHECK ((unresolved_blocking_observation_count = 0)),
    CONSTRAINT campaign_operations_completio_authorization_evidence_hash_check CHECK ((authorization_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completio_campaign_identity_canonical_check CHECK (((campaign_identity_canonical <> ''::text) AND (octet_length(campaign_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_completio_completion_contract_version_check CHECK ((completion_contract_version = 1)),
    CONSTRAINT campaign_operations_completion__budget_evidence_canonical_check CHECK ((budget_evidence_canonical <> ''::text)),
    CONSTRAINT campaign_operations_completion__completion_classification_check CHECK ((completion_classification = ANY (ARRAY['operational_request_failed'::text, 'mixed_terminal_outcomes'::text, 'downstream_failure'::text, 'terminal_partial_completion'::text, 'all_scope_cancelled'::text, 'all_downstream_completed'::text]))),
    CONSTRAINT campaign_operations_completion__reservation_evidence_hash_check CHECK ((reservation_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completion_binding_evidence_canonical_check CHECK ((binding_evidence_canonical <> ''::text)),
    CONSTRAINT campaign_operations_completion_budget_equation CHECK (((budget_ever_reserved = ((budget_committed + budget_released_or_expired) + budget_held)) AND (budget_resulting_total = ((budget_committed + budget_held) + budget_unallocated)))),
    CONSTRAINT campaign_operations_completion_budget_released_or_expired_check CHECK ((budget_released_or_expired >= 0)),
    CONSTRAINT campaign_operations_completion_cancellation_evidence_hash_check CHECK ((cancellation_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completion_cancellation_request_count_check CHECK ((cancellation_request_count >= 0)),
    CONSTRAINT campaign_operations_completion_e_completion_identity_hash_check CHECK ((completion_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completion_ev_lifecycle_evidence_hash_check CHECK ((lifecycle_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completion_eve_budget_resulting_total_check CHECK ((budget_resulting_total >= 0)),
    CONSTRAINT campaign_operations_completion_eve_completed_member_count_check CHECK ((completed_member_count >= 0)),
    CONSTRAINT campaign_operations_completion_even_binding_evidence_hash_check CHECK ((binding_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completion_even_budget_ledger_version_check CHECK ((budget_ledger_version > 0)),
    CONSTRAINT campaign_operations_completion_even_request_evidence_hash_check CHECK ((request_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completion_event_actor_identity_check CHECK ((actor_identity ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_completion_event_binding_count_check CHECK ((binding_count >= 0)),
    CONSTRAINT campaign_operations_completion_event_budget_committed_check CHECK ((budget_committed >= 0)),
    CONSTRAINT campaign_operations_completion_event_budget_ever_reserved_check CHECK ((budget_ever_reserved >= 0)),
    CONSTRAINT campaign_operations_completion_event_budget_evidence_hash_check CHECK ((budget_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_completion_event_budget_held_check CHECK ((budget_held = 0)),
    CONSTRAINT campaign_operations_completion_event_budget_unallocated_check CHECK ((budget_unallocated >= 0)),
    CONSTRAINT campaign_operations_completion_event_capability_check CHECK ((capability = 'campaign_operations_completion_writer'::text)),
    CONSTRAINT campaign_operations_completion_event_completion_event_id_check CHECK ((completion_event_id > 0)),
    CONSTRAINT campaign_operations_completion_event_control_owner_count_check CHECK ((control_owner_count >= 0)),
    CONSTRAINT campaign_operations_completion_event_failed_member_count_check CHECK ((failed_member_count >= 0)),
    CONSTRAINT campaign_operations_completion_event_operation_key_check CHECK ((operation_key ~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_completion_event_reason_check CHECK (((reason <> ''::text) AND (octet_length(reason) <= 4096) AND (reason ~ '[^ 	
]'::text) AND (translate(reason, '	
'::text, ''::text) !~ '[[:cntrl:]]'::text))),
    CONSTRAINT campaign_operations_completion_event_request_count_check CHECK ((request_count >= 0)),
    CONSTRAINT campaign_operations_completion_event_reservation_count_check CHECK ((reservation_count >= 0)),
    CONSTRAINT campaign_operations_completion_event_scope_member_count_check CHECK ((scope_member_count > 0)),
    CONSTRAINT campaign_operations_completion_member_equation CHECK ((((completed_member_count + failed_member_count) + cancelled_or_never_dispatched_member_count) = scope_member_count)),
    CONSTRAINT campaign_operations_completion_request_evidence_canonical_check CHECK ((request_evidence_canonical <> ''::text)),
    CONSTRAINT campaign_operations_completion_state_classification CHECK ((((administrative_terminal_state = 'terminal_failed'::text) AND (completion_classification = ANY (ARRAY['operational_request_failed'::text, 'mixed_terminal_outcomes'::text, 'downstream_failure'::text]))) OR ((administrative_terminal_state = 'terminal_cancelled'::text) AND (completion_classification = 'all_scope_cancelled'::text)) OR ((administrative_terminal_state = 'terminal_completed'::text) AND (completion_classification = ANY (ARRAY['terminal_partial_completion'::text, 'all_downstream_completed'::text])))))
);


--
-- Name: campaign_operations_completion_identity_valid(public.campaign_operations_completion_event); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_completion_identity_valid(candidate public.campaign_operations_completion_event) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE expected_canonical text;
BEGIN
    expected_canonical := 'campaign_operations_completion_v1' ||
        ';campaign=' || octet_length(candidate.campaign_identity_canonical) ||
            ':' || candidate.campaign_identity_canonical ||
        ';operation_key=' || octet_length(candidate.operation_key) || ':' ||
            candidate.operation_key ||
        ';terminal_state=' || candidate.administrative_terminal_state ||
        ';classification=' || candidate.completion_classification ||
        ';budget_ledger_entry_id=' || candidate.budget_ledger_entry_id ||
        ';budget_ledger_version=' || candidate.budget_ledger_version ||
        ';budget_resulting_total=' || candidate.budget_resulting_total ||
        ';budget_ever_reserved=' || candidate.budget_ever_reserved ||
        ';budget_committed=' || candidate.budget_committed ||
        ';budget_released_or_expired=' ||
            candidate.budget_released_or_expired ||
        ';budget_held=' || candidate.budget_held ||
        ';budget_unallocated=' || candidate.budget_unallocated ||
        ';scope_member_count=' || candidate.scope_member_count ||
        ';completed_member_count=' || candidate.completed_member_count ||
        ';failed_member_count=' || candidate.failed_member_count ||
        ';cancelled_or_never_dispatched_member_count=' ||
            candidate.cancelled_or_never_dispatched_member_count ||
        ';reservation_count=' || candidate.reservation_count ||
        ';request_count=' || candidate.request_count ||
        ';binding_count=' || candidate.binding_count ||
        ';control_owner_count=' || candidate.control_owner_count ||
        ';cancellation_request_count=' ||
            candidate.cancellation_request_count ||
        ';cancellation_settlement_count=' ||
            candidate.cancellation_settlement_count ||
        ';unresolved_blocking_observation_count=' ||
            candidate.unresolved_blocking_observation_count ||
        ';authorization_evidence=' ||
            octet_length(candidate.authorization_evidence_canonical) || ':' ||
            candidate.authorization_evidence_canonical ||
        ';budget_evidence=' ||
            octet_length(candidate.budget_evidence_canonical) || ':' ||
            candidate.budget_evidence_canonical ||
        ';reservation_evidence=' ||
            octet_length(candidate.reservation_evidence_canonical) || ':' ||
            candidate.reservation_evidence_canonical ||
        ';request_evidence=' ||
            octet_length(candidate.request_evidence_canonical) || ':' ||
            candidate.request_evidence_canonical ||
        ';binding_evidence=' ||
            octet_length(candidate.binding_evidence_canonical) || ':' ||
            candidate.binding_evidence_canonical ||
        ';lifecycle_evidence=' ||
            octet_length(candidate.lifecycle_evidence_canonical) || ':' ||
            candidate.lifecycle_evidence_canonical ||
        ';cancellation_evidence=' ||
            octet_length(candidate.cancellation_evidence_canonical) || ':' ||
            candidate.cancellation_evidence_canonical ||
        ';reconciliation_evidence=' ||
            octet_length(candidate.reconciliation_evidence_canonical) || ':' ||
            candidate.reconciliation_evidence_canonical ||
        ';actor=' || octet_length(candidate.actor_identity) || ':' ||
            candidate.actor_identity ||
        ';capability=campaign_operations_completion_writer' ||
        ';reason=' || octet_length(candidate.reason) || ':' ||
            candidate.reason;

    RETURN candidate.authorization_evidence_hash =
               campaign_operations_tagged_fnv1a64(
                   candidate.authorization_evidence_canonical) AND
           candidate.budget_evidence_hash =
               campaign_operations_tagged_fnv1a64(
                   candidate.budget_evidence_canonical) AND
           candidate.reservation_evidence_hash =
               campaign_operations_tagged_fnv1a64(
                   candidate.reservation_evidence_canonical) AND
           candidate.request_evidence_hash =
               campaign_operations_tagged_fnv1a64(
                   candidate.request_evidence_canonical) AND
           candidate.binding_evidence_hash =
               campaign_operations_tagged_fnv1a64(
                   candidate.binding_evidence_canonical) AND
           candidate.lifecycle_evidence_hash =
               campaign_operations_tagged_fnv1a64(
                   candidate.lifecycle_evidence_canonical) AND
           candidate.cancellation_evidence_hash =
               campaign_operations_tagged_fnv1a64(
                   candidate.cancellation_evidence_canonical) AND
           candidate.reconciliation_evidence_hash =
               campaign_operations_tagged_fnv1a64(
                   candidate.reconciliation_evidence_canonical) AND
           candidate.completion_identity_canonical = expected_canonical AND
           candidate.completion_identity_hash =
               campaign_operations_tagged_fnv1a64(expected_canonical);
END;
$$;


--
-- Name: campaign_operations_dispatch_attempt; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_operations_dispatch_attempt (
    dispatch_attempt_id bigint NOT NULL,
    operational_request_id bigint NOT NULL,
    request_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    attempt_ordinal integer NOT NULL,
    expected_request_version integer NOT NULL,
    resulting_request_version integer NOT NULL,
    lease_token_digest text NOT NULL COLLATE pg_catalog."C",
    lease_expires_at timestamp with time zone NOT NULL,
    dispatcher_identity text NOT NULL COLLATE pg_catalog."C",
    attempt_contract_version integer NOT NULL,
    attempt_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    attempt_identity_hash text NOT NULL COLLATE pg_catalog."C",
    acquired_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    request_production_admission_id bigint,
    request_production_admission_canonical text COLLATE pg_catalog."C",
    request_production_admission_hash text COLLATE pg_catalog."C",
    production_enablement_event_id bigint,
    production_enablement_event_canonical text COLLATE pg_catalog."C",
    production_enablement_event_hash text COLLATE pg_catalog."C",
    operation_key text COLLATE pg_catalog."C",
    requesting_actor text COLLATE pg_catalog."C",
    original_executing_service_principal text COLLATE pg_catalog."C",
    approved_build_contract_canonical text COLLATE pg_catalog."C",
    approved_build_contract_hash text COLLATE pg_catalog."C",
    production_capability text COLLATE pg_catalog."C",
    CONSTRAINT campaign_operations_dispatch_a_attempt_identity_canonical_check CHECK ((attempt_identity_canonical <> ''::text)),
    CONSTRAINT campaign_operations_dispatch_a_request_identity_canonical_check CHECK ((request_identity_canonical <> ''::text)),
    CONSTRAINT campaign_operations_dispatch_att_expected_request_version_check CHECK ((expected_request_version > 0)),
    CONSTRAINT campaign_operations_dispatch_attemp_attempt_identity_hash_check CHECK ((attempt_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_dispatch_attempt_attempt_ordinal_check CHECK ((attempt_ordinal > 0)),
    CONSTRAINT campaign_operations_dispatch_attempt_check CHECK ((resulting_request_version = (expected_request_version + 1))),
    CONSTRAINT campaign_operations_dispatch_attempt_contract_version_check CHECK ((attempt_contract_version = ANY (ARRAY[1, 2]))),
    CONSTRAINT campaign_operations_dispatch_attempt_dispatch_attempt_id_check CHECK ((dispatch_attempt_id > 0)),
    CONSTRAINT campaign_operations_dispatch_attempt_dispatcher_identity_check CHECK ((dispatcher_identity ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_dispatch_attempt_lease_token_digest_check CHECK ((lease_token_digest ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_dispatch_attempt_v1_v2_shape CHECK ((((attempt_contract_version = 1) AND (request_production_admission_id IS NULL) AND (request_production_admission_canonical IS NULL) AND (request_production_admission_hash IS NULL) AND (production_enablement_event_id IS NULL) AND (production_enablement_event_canonical IS NULL) AND (production_enablement_event_hash IS NULL) AND (operation_key IS NULL) AND (requesting_actor IS NULL) AND (original_executing_service_principal IS NULL) AND (approved_build_contract_canonical IS NULL) AND (approved_build_contract_hash IS NULL) AND (production_capability IS NULL)) OR ((attempt_contract_version = 2) AND (request_production_admission_id IS NOT NULL) AND (request_production_admission_canonical IS NOT NULL) AND (request_production_admission_hash IS NOT NULL) AND (request_production_admission_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text) AND (production_enablement_event_id IS NOT NULL) AND (production_enablement_event_canonical IS NOT NULL) AND (production_enablement_event_hash IS NOT NULL) AND (production_enablement_event_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text) AND (operation_key IS NOT NULL) AND (operation_key ~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$'::text) AND (requesting_actor IS NOT NULL) AND (requesting_actor ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text) AND (dispatcher_identity = requesting_actor) AND (original_executing_service_principal IS NOT NULL) AND (original_executing_service_principal ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text) AND (approved_build_contract_canonical IS NOT NULL) AND (approved_build_contract_hash IS NOT NULL) AND (approved_build_contract_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text) AND (production_capability IS NOT NULL) AND (production_capability = 'campaign_operations_production_dispatcher'::text))))
);


--
-- Name: TABLE campaign_operations_dispatch_attempt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.campaign_operations_dispatch_attempt IS 'Immutable lease-acquisition evidence; never current dispatch authority.';


--
-- Name: campaign_operations_dispatch_attempt_v2_canonical(public.campaign_operations_dispatch_attempt); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_dispatch_attempt_v2_canonical(candidate public.campaign_operations_dispatch_attempt) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
SELECT 'campaign_operations_dispatch_attempt_v2' ||
    ';operational_request_id=' || candidate.operational_request_id ||
    ';request_identity_canonical=' ||
        octet_length(candidate.request_identity_canonical) || ':' ||
        candidate.request_identity_canonical ||
    ';request_production_admission_canonical=' ||
        octet_length(candidate.request_production_admission_canonical) || ':' ||
        candidate.request_production_admission_canonical ||
    ';enable_event_id=' || candidate.production_enablement_event_id ||
    ';enable_event_canonical=' ||
        octet_length(candidate.production_enablement_event_canonical) || ':' ||
        candidate.production_enablement_event_canonical ||
    ';operation_key=' || octet_length(candidate.operation_key) || ':' ||
        candidate.operation_key ||
    ';attempt_ordinal=' || candidate.attempt_ordinal ||
    ';expected_request_version=' || candidate.expected_request_version ||
    ';resulting_request_version=' || candidate.resulting_request_version ||
    ';lease_token_digest=' || octet_length(candidate.lease_token_digest) || ':' ||
        candidate.lease_token_digest ||
    ';lease_expires_at=' || octet_length(to_char(
        candidate.lease_expires_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) || ':' || to_char(
        candidate.lease_expires_at AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ||
    ';requesting_actor=' || octet_length(candidate.requesting_actor) || ':' ||
        candidate.requesting_actor ||
    ';original_executing_service_principal=' ||
        octet_length(candidate.original_executing_service_principal) || ':' ||
        candidate.original_executing_service_principal ||
    ';approved_build_contract=' ||
        octet_length(candidate.approved_build_contract_canonical) || ':' ||
        candidate.approved_build_contract_canonical ||
    ';capability=campaign_operations_production_dispatcher' ||
    ';attempt_contract_version=2'
$$;


--
-- Name: campaign_operations_future_actions_allowed(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_future_actions_allowed(target_campaign_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
    SELECT NOT EXISTS(
        SELECT 1 FROM campaign_operations_cancellation_request
        WHERE operational_campaign_id = target_campaign_id)
    AND NOT COALESCE((
        SELECT event_kind = 'pause'
        FROM campaign_operations_control_event
        WHERE operational_campaign_id = target_campaign_id
        ORDER BY control_version DESC
        LIMIT 1), false)
    AND NOT EXISTS(
        SELECT 1 FROM campaign_operations_completion_event
        WHERE operational_campaign_id = target_campaign_id);
$$;


