COMMENT ON TABLE public.campaign_operations_operational_request IS 'Durable accepted V1 full-materialization request/outbox; Phase 2 persists ready requests but cannot dispatch them.';


--
-- Name: campaign_operations_reconciliation_observation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_operations_reconciliation_observation (
    reconciliation_observation_id bigint NOT NULL,
    run_key text NOT NULL COLLATE pg_catalog."C",
    operational_campaign_id bigint NOT NULL,
    operational_request_id bigint NOT NULL,
    request_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    expected_request_state text NOT NULL COLLATE pg_catalog."C",
    expected_request_version integer NOT NULL,
    reason_code text NOT NULL COLLATE pg_catalog."C",
    evidence_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    evidence_identity_hash text NOT NULL COLLATE pg_catalog."C",
    recommended_service text NOT NULL COLLATE pg_catalog."C",
    recommended_action text NOT NULL COLLATE pg_catalog."C",
    diagnostic_code text NOT NULL COLLATE pg_catalog."C",
    observation_contract_version integer NOT NULL,
    observation_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    observation_identity_hash text NOT NULL COLLATE pg_catalog."C",
    observed_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    reconciliation_cursor_event_id bigint NOT NULL,
    CONSTRAINT campaign_operations_reconcil_observation_contract_version_check CHECK ((observation_contract_version = 1)),
    CONSTRAINT campaign_operations_reconcil_reconciliation_observation_i_check CHECK ((reconciliation_observation_id > 0)),
    CONSTRAINT campaign_operations_reconciliat_observation_identity_hash_check CHECK ((observation_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_reconciliati_expected_request_version_check CHECK ((expected_request_version > 0)),
    CONSTRAINT campaign_operations_reconciliation_evidence_identity_hash_check CHECK ((evidence_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_reconciliation_expected_request_state_check CHECK ((expected_request_state = ANY (ARRAY['ready'::text, 'dispatching'::text, 'bound'::text, 'permanently_failed'::text, 'cancelled'::text, 'reconciliation_required'::text]))),
    CONSTRAINT campaign_operations_reconciliation_ob_recommended_service_check CHECK ((recommended_service ~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_reconciliation_obs_recommended_action_check CHECK ((recommended_action ~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_reconciliation_observ_diagnostic_code_check CHECK ((diagnostic_code ~ '^[a-z0-9_]{1,128}$'::text)),
    CONSTRAINT campaign_operations_reconciliation_observatio_reason_code_check CHECK ((reason_code = ANY (ARRAY['ready_request_not_dispatched'::text, 'dispatch_lease_expired_no_downstream_evidence'::text, 'dispatch_outcome_unknown'::text, 'binding_projection_missing'::text, 'reservation_projection_missing_commit'::text, 'held_reservation_terminal_unbound_request'::text, 'reservation_expired_no_downstream_evidence'::text, 'cancellation_settlement_pending'::text, 'terminal_lifecycle_completion_ready'::text, 'progressed_unbound_evidence'::text, 'partial_downstream_evidence'::text, 'binding_cardinality_mismatch'::text, 'control_owner_conflict'::text, 'budget_accounting_mismatch'::text, 'post_completion_lifecycle_changed'::text, 'causality_ambiguous'::text]))),
    CONSTRAINT campaign_operations_reconciliation_observation_run_key_check CHECK ((run_key ~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$'::text))
);


--
-- Name: TABLE campaign_operations_reconciliation_observation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.campaign_operations_reconciliation_observation IS 'Detection-only immutable evidence linked to one exact durable cursor batch; grants no repair authority.';


