-- Name: COLUMN campaign_operations_reconciliation_observation.reconciliation_cursor_event_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.campaign_operations_reconciliation_observation.reconciliation_cursor_event_id IS 'Exact durable batch membership; replay never infers membership from ranges or current state.';


--
-- Name: campaign_operations_request_production_admission; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_operations_request_production_admission (
    request_production_admission_id bigint NOT NULL,
    operational_request_id bigint NOT NULL,
    request_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    expected_request_version integer NOT NULL,
    dispatch_operation_key text NOT NULL COLLATE pg_catalog."C",
    production_enablement_event_id bigint NOT NULL,
    enable_event_canonical text NOT NULL COLLATE pg_catalog."C",
    requesting_actor text NOT NULL COLLATE pg_catalog."C",
    original_executing_service_principal text NOT NULL COLLATE pg_catalog."C",
    approved_build_contract_canonical text NOT NULL COLLATE pg_catalog."C",
    approved_build_contract_hash text NOT NULL COLLATE pg_catalog."C",
    capability text NOT NULL COLLATE pg_catalog."C",
    admission_contract_version integer NOT NULL,
    admission_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    admission_identity_hash text NOT NULL COLLATE pg_catalog."C",
    admitted_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT campaign_operations_request__admission_identity_canonical_check CHECK (((admission_identity_canonical <> ''::text) AND (octet_length(admission_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_request__approved_build_contract_cano_check CHECK ((approved_build_contract_canonical <> ''::text)),
    CONSTRAINT campaign_operations_request__approved_build_contract_hash_check CHECK ((approved_build_contract_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_request__original_executing_service_p_check CHECK ((original_executing_service_principal ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_request__request_production_admission_check CHECK ((request_production_admission_id > 0)),
    CONSTRAINT campaign_operations_request_pr_admission_contract_version_check CHECK ((admission_contract_version = 1)),
    CONSTRAINT campaign_operations_request_pr_request_identity_canonical_check CHECK ((request_identity_canonical <> ''::text)),
    CONSTRAINT campaign_operations_request_prod_expected_request_version_check CHECK ((expected_request_version > 0)),
    CONSTRAINT campaign_operations_request_produ_admission_identity_hash_check CHECK ((admission_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_request_produc_dispatch_operation_key_check CHECK ((dispatch_operation_key ~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_request_produc_enable_event_canonical_check CHECK ((enable_event_canonical <> ''::text)),
    CONSTRAINT campaign_operations_request_production_a_requesting_actor_check CHECK ((requesting_actor ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_request_production_admissi_capability_check CHECK ((capability = 'campaign_operations_production_dispatcher'::text))
);


--
-- Name: experiment_scheduler_protocol; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.experiment_scheduler_protocol (
    singleton boolean DEFAULT true NOT NULL,
    required_generation integer NOT NULL,
    cutover_state text NOT NULL,
    migration_installed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    cutover_completed_at timestamp with time zone,
    cutover_completed_by text,
    cutover_executable_path text,
    cutover_process_evidence text,
    legacy_no_pid_grace_seconds integer DEFAULT 120 NOT NULL,
    failure_diagnostic text,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    scheduler_evidence_contract_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT experiment_scheduler_protoco_scheduler_evidence_contract__check CHECK ((scheduler_evidence_contract_version = 1)),
    CONSTRAINT experiment_scheduler_protocol_check CHECK ((((cutover_state = 'complete'::text) AND (cutover_completed_at IS NOT NULL) AND (cutover_completed_by IS NOT NULL) AND (cutover_executable_path ~~ '/%'::text) AND (cutover_process_evidence IS NOT NULL)) OR ((cutover_state = ANY (ARRAY['pending'::text, 'failed'::text])) AND (cutover_completed_at IS NULL)))),
    CONSTRAINT experiment_scheduler_protocol_cutover_state_check CHECK ((cutover_state = ANY (ARRAY['pending'::text, 'complete'::text, 'failed'::text]))),
    CONSTRAINT experiment_scheduler_protocol_legacy_no_pid_grace_seconds_check CHECK (((legacy_no_pid_grace_seconds >= 30) AND (legacy_no_pid_grace_seconds <= 86400))),
    CONSTRAINT experiment_scheduler_protocol_required_generation_check CHECK ((required_generation > 0)),
    CONSTRAINT experiment_scheduler_protocol_singleton_check CHECK (singleton)
);


