    filename text NOT NULL,
    checksum text NOT NULL,
    applied_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: campaign_operations_production_readiness_v1; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_operations_production_readiness_v1 AS
 WITH head AS (
         SELECT campaign_operations_production_enablement_event.production_enablement_event_id,
            campaign_operations_production_enablement_event.event_kind,
            campaign_operations_production_enablement_event.operation_key,
            campaign_operations_production_enablement_event.predecessor_event_id,
            campaign_operations_production_enablement_event.predecessor_event_canonical,
            campaign_operations_production_enablement_event.expected_prior_version,
            campaign_operations_production_enablement_event.resulting_version,
            campaign_operations_production_enablement_event.scheduler_protocol_evidence_canonical,
            campaign_operations_production_enablement_event.scheduler_protocol_evidence_hash,
            campaign_operations_production_enablement_event.scheduler_required_generation,
            campaign_operations_production_enablement_event.scheduler_cutover_state,
            campaign_operations_production_enablement_event.scheduler_cutover_completed_at,
            campaign_operations_production_enablement_event.scheduler_cutover_completed_by,
            campaign_operations_production_enablement_event.scheduler_cutover_executable_path,
            campaign_operations_production_enablement_event.scheduler_cutover_process_evidence,
            campaign_operations_production_enablement_event.independent_verification_reference,
            campaign_operations_production_enablement_event.actor_identity,
            campaign_operations_production_enablement_event.capability,
            campaign_operations_production_enablement_event.manager_service_contract,
            campaign_operations_production_enablement_event.approved_build_contract_canonical,
            campaign_operations_production_enablement_event.approved_build_contract_hash,
            campaign_operations_production_enablement_event.approved_build_source_commit,
            campaign_operations_production_enablement_event.approved_build_compiler_contract,
            campaign_operations_production_enablement_event.approved_build_executable_sha256,
            campaign_operations_production_enablement_event.reason,
            campaign_operations_production_enablement_event.enablement_contract_version,
            campaign_operations_production_enablement_event.enablement_identity_canonical,
            campaign_operations_production_enablement_event.enablement_identity_hash,
            campaign_operations_production_enablement_event.recorded_at
           FROM public.campaign_operations_production_enablement_event
          ORDER BY campaign_operations_production_enablement_event.resulting_version DESC
         LIMIT 1
        ), scheduler AS (
         SELECT campaign_operations_scheduler_protocol_evidence_snapshot_v1.required_generation,
            campaign_operations_scheduler_protocol_evidence_snapshot_v1.cutover_state,
            campaign_operations_scheduler_protocol_evidence_snapshot_v1.cutover_completed_at,
            campaign_operations_scheduler_protocol_evidence_snapshot_v1.cutover_completed_by,
            campaign_operations_scheduler_protocol_evidence_snapshot_v1.cutover_executable_path,
            campaign_operations_scheduler_protocol_evidence_snapshot_v1.cutover_process_evidence,
            campaign_operations_scheduler_protocol_evidence_snapshot_v1.evidence_complete,
            campaign_operations_scheduler_protocol_evidence_snapshot_v1.evidence_canonical,
            campaign_operations_scheduler_protocol_evidence_snapshot_v1.evidence_hash
           FROM public.campaign_operations_scheduler_protocol_evidence_snapshot_v1() campaign_operations_scheduler_protocol_evidence_snapshot_v1(required_generation, cutover_state, cutover_completed_at, cutover_completed_by, cutover_executable_path, cutover_process_evidence, evidence_complete, evidence_canonical, evidence_hash)
        ), scheduler_contract AS (
         SELECT protocol.scheduler_evidence_contract_version
           FROM public.experiment_scheduler_protocol protocol
          WHERE protocol.singleton
        ), completion_rows AS (
         SELECT string_agg(DISTINCT (completion.completion_contract_version)::text, '|'::text ORDER BY (completion.completion_contract_version)::text) AS observed_version
           FROM public.campaign_operations_completion_event completion
        ), completion_contract AS (
         SELECT "substring"(pg_get_constraintdef(constraint_row.oid), 'completion_contract_version = ([0-9]+)'::text) AS observed_version
           FROM pg_constraint constraint_row
          WHERE ((constraint_row.conrelid = ('public.campaign_operations_completion_event'::regclass)::oid) AND (constraint_row.contype = 'c'::"char") AND (pg_get_constraintdef(constraint_row.oid) ~~ '%completion_contract_version = %'::text))
        ), role_state AS (
         SELECT public.campaign_operations_has_explicit_role_v1(SESSION_USER, 'campaign_operations_production_reader'::name) AS reader_member,
            public.campaign_operations_has_explicit_role_v1(SESSION_USER, 'campaign_operations_production_dispatcher'::name) AS dispatcher_member,
            public.campaign_operations_has_explicit_role_v1(SESSION_USER, 'campaign_operations_production_phase5_transactional'::name) AS phase5_transactional_member,
            public.campaign_operations_has_explicit_role_v1(SESSION_USER, 'campaign_operations_scheduler_protocol_evidence_reader'::name) AS scheduler_evidence_reader_member,
            public.campaign_operations_has_explicit_role_v1(SESSION_USER, 'campaign_operations_production_enabler'::name) AS enabler_member,
            public.campaign_operations_has_explicit_role_v1(SESSION_USER, 'campaign_operations_production_disabler'::name) AS disabler_member,
            public.campaign_operations_has_explicit_role_v1(SESSION_USER, 'campaign_operations_dispatcher'::name) AS prohibited_test_dispatcher_member,
            public.campaign_operations_has_explicit_role_v1(SESSION_USER, 'campaign_operations_phase5_transactional'::name) AS prohibited_test_phase5_member
        )
 SELECT '055'::text AS migration_version,
    ( SELECT schema_migrations.filename
           FROM public.schema_migrations
          WHERE (schema_migrations.version = '055'::text)) AS migration_filename,
    ( SELECT schema_migrations.checksum
           FROM public.schema_migrations
          WHERE (schema_migrations.version = '055'::text)) AS migration_checksum,
    (scheduler_contract.scheduler_evidence_contract_version)::text AS scheduler_evidence_contract_version,
    ( SELECT string_agg(DISTINCT
                CASE
                    WHEN (event.approved_build_contract_canonical ~ ';build_contract_version=[0-9]+$'::text) THEN "substring"(event.approved_build_contract_canonical, ';build_contract_version=([0-9]+)$'::text)
                    ELSE 'invalid'::text
                END, '|'::text ORDER BY
                CASE
                    WHEN (event.approved_build_contract_canonical ~ ';build_contract_version=[0-9]+$'::text) THEN "substring"(event.approved_build_contract_canonical, ';build_contract_version=([0-9]+)$'::text)
                    ELSE 'invalid'::text
                END) AS string_agg
           FROM public.campaign_operations_production_enablement_event event
          WHERE (event.event_kind = 'enable'::text)) AS manager_build_contract_version,
    ( SELECT string_agg(DISTINCT (event.enablement_contract_version)::text, '|'::text ORDER BY (event.enablement_contract_version)::text) AS string_agg
           FROM public.campaign_operations_production_enablement_event event) AS enablement_contract_version,
    ( SELECT string_agg(DISTINCT (admission.admission_contract_version)::text, '|'::text ORDER BY (admission.admission_contract_version)::text) AS string_agg
           FROM public.campaign_operations_request_production_admission admission) AS admission_contract_version,
    ( SELECT string_agg(DISTINCT (attempt.attempt_contract_version)::text, '|'::text ORDER BY (attempt.attempt_contract_version)::text) AS string_agg
           FROM public.campaign_operations_dispatch_attempt attempt
          WHERE ((attempt.request_production_admission_id IS NOT NULL) OR (attempt.production_enablement_event_id IS NOT NULL))) AS production_attempt_contract_version,
    scheduler.required_generation AS scheduler_required_generation,
    scheduler.cutover_state AS scheduler_cutover_state,
    scheduler.evidence_complete AS scheduler_evidence_complete,
    scheduler.evidence_canonical AS scheduler_evidence_canonical,
    scheduler.evidence_hash AS scheduler_evidence_hash,
    head.production_enablement_event_id,
    head.event_kind AS enablement_kind,
    head.resulting_version AS enablement_version,
    head.enablement_identity_canonical AS enablement_canonical,
    head.enablement_identity_hash AS enablement_hash,
    head.independent_verification_reference,
    head.manager_service_contract,
    head.approved_build_contract_canonical,
    (SESSION_USER)::text AS session_principal,
    (CURRENT_USER)::text AS current_principal,
    role_state.reader_member,
    role_state.dispatcher_member,
    role_state.phase5_transactional_member,
    role_state.scheduler_evidence_reader_member,
    role_state.enabler_member,
    role_state.disabler_member,
    role_state.prohibited_test_dispatcher_member,
    role_state.prohibited_test_phase5_member,
    ((head.event_kind = 'enable'::text) AND scheduler.evidence_complete AND (head.scheduler_protocol_evidence_canonical = scheduler.evidence_canonical)) AS enablement_effective,
    ( SELECT count(*) AS count
           FROM public.campaign_operations_operational_request request
          WHERE ((request.request_state = 'ready'::text) AND request.production_dispatch_enabled)) AS ready_admitted_request_count,
    ( SELECT count(*) AS count
           FROM public.campaign_operations_operational_request request
          WHERE ((request.request_state = 'ready'::text) AND (NOT request.production_dispatch_enabled))) AS ready_unadmitted_request_count,
    ( SELECT count(*) AS count
           FROM (public.campaign_operations_dispatch_attempt attempt
             JOIN public.campaign_operations_operational_request request ON (((request.operational_request_id = attempt.operational_request_id) AND (request.request_state = 'dispatching'::text) AND (request.state_version = attempt.resulting_request_version) AND (request.lease_token_hash = attempt.lease_token_digest) AND (request.lease_expires_at = attempt.lease_expires_at))))
          WHERE ((attempt.attempt_contract_version = 2) AND (attempt.lease_expires_at > transaction_timestamp()) AND (NOT (attempt.production_enablement_event_id IS DISTINCT FROM head.production_enablement_event_id)))) AS active_current_event_lease_count,
    ( SELECT count(*) AS count
           FROM (public.campaign_operations_dispatch_attempt attempt
             JOIN public.campaign_operations_operational_request request ON (((request.operational_request_id = attempt.operational_request_id) AND (request.request_state = 'dispatching'::text) AND (request.state_version = attempt.resulting_request_version) AND (request.lease_token_hash = attempt.lease_token_digest) AND (request.lease_expires_at = attempt.lease_expires_at))))
          WHERE ((attempt.attempt_contract_version = 2) AND (attempt.production_enablement_event_id IS DISTINCT FROM head.production_enablement_event_id))) AS old_event_blocked_lease_count,
    ( SELECT count(*) AS count
           FROM public.campaign_operations_reconciliation_observation o
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM public.campaign_operations_reconciliation_resolution r
                  WHERE (r.reconciliation_observation_id = o.reconciliation_observation_id))))) AS reconciliation_required_count,
    COALESCE(completion_rows.observed_version, completion_contract.observed_version) AS completion_nested_v2_proof_version,
    (NOT (EXISTS ( SELECT 1
           FROM (public.campaign_operations_dispatch_attempt attempt
             LEFT JOIN public.campaign_operations_request_production_admission admission ON ((admission.request_production_admission_id = attempt.request_production_admission_id)))
          WHERE ((attempt.attempt_contract_version = 2) AND (admission.request_production_admission_id IS NULL))))) AS completion_nested_v2_proof_valid
   FROM (((((scheduler
     CROSS JOIN role_state)
     LEFT JOIN head ON (true))
     LEFT JOIN scheduler_contract ON (true))
     LEFT JOIN completion_rows ON (true))
     LEFT JOIN completion_contract ON (true));


--
-- Name: campaign_operations_production_readiness_snapshot_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_production_readiness_snapshot_v1() RETURNS SETOF public.campaign_operations_production_readiness_v1
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ SELECT readiness.* FROM public.campaign_operations_production_readiness_v1 readiness; $$;


--
-- Name: campaign_operations_request_production_admission_canonical_v1(public.campaign_operations_request_production_admission); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_request_production_admission_canonical_v1(candidate public.campaign_operations_request_production_admission) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
SELECT 'campaign_operations_request_production_admission_v1' ||
    ';operational_request_id=' || candidate.operational_request_id ||
    ';request_identity_canonical=' ||
        octet_length(candidate.request_identity_canonical) || ':' ||
        candidate.request_identity_canonical ||
    ';expected_request_version=' || candidate.expected_request_version ||
    ';dispatch_operation_key=' ||
        octet_length(candidate.dispatch_operation_key) || ':' ||
        candidate.dispatch_operation_key ||
    ';enable_event_id=' || candidate.production_enablement_event_id ||
    ';enable_event_canonical=' ||
        octet_length(candidate.enable_event_canonical) || ':' ||
        candidate.enable_event_canonical ||
    ';requesting_actor=' || octet_length(candidate.requesting_actor) || ':' ||
        candidate.requesting_actor ||
    ';original_executing_service_principal=' ||
        octet_length(candidate.original_executing_service_principal) || ':' ||
        candidate.original_executing_service_principal ||
    ';approved_build_contract=' ||
        octet_length(candidate.approved_build_contract_canonical) || ':' ||
        candidate.approved_build_contract_canonical ||
    ';capability=campaign_operations_production_dispatcher' ||
    ';admission_contract_version=1'
$$;


--
-- Name: campaign_operations_scheduler_protocol_evidence_canonical_v1(integer, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_scheduler_protocol_evidence_canonical_v1(required_generation_value integer, cutover_state_value text, cutover_completed_at_value timestamp with time zone, cutover_completed_by_value text, cutover_executable_path_value text, cutover_process_evidence_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
DECLARE timestamp_value text;
BEGIN
    IF required_generation_value <> 52 OR
       cutover_state_value <> 'complete' OR
       cutover_completed_by_value = '' OR
       cutover_executable_path_value = '' OR
       cutover_process_evidence_value = '' THEN
        RAISE EXCEPTION 'invalid scheduler generation-52 protocol evidence'
            USING ERRCODE = '22023';
    END IF;
    timestamp_value := to_char(
        cutover_completed_at_value AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
    RETURN 'campaign_operations_scheduler_protocol_evidence_v1' ||
        ';required_generation=52' ||
        ';cutover_state=complete' ||
        ';migration_contract=61:migration-052-scheduler-generation-52-exact-attempt-authority' ||
        ';protocol_contract=50:scheduler-generation-52-exact-attempt-authority-v1' ||
        ';cutover_completed_at=' || octet_length(timestamp_value) || ':' ||
            timestamp_value ||
        ';cutover_completed_by=' ||
            octet_length(cutover_completed_by_value) || ':' ||
            cutover_completed_by_value ||
        ';cutover_executable_path=' ||
            octet_length(cutover_executable_path_value) || ':' ||
            cutover_executable_path_value ||
        ';cutover_process_evidence=' ||
            octet_length(cutover_process_evidence_value) || ':' ||
            cutover_process_evidence_value;
END;
$$;


--
-- Name: campaign_operations_scheduler_protocol_evidence_lock_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_scheduler_protocol_evidence_lock_v1() RETURNS TABLE(required_generation integer, cutover_state text, cutover_completed_at text, cutover_completed_by text, cutover_executable_path text, cutover_process_evidence text, evidence_complete boolean, evidence_canonical text, evidence_hash text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE generation_value integer;
DECLARE state_value text;
DECLARE completed_at_value timestamptz;
DECLARE completed_by_value text;
DECLARE executable_path_value text;
DECLARE process_evidence_value text;
BEGIN
    SELECT protocol.required_generation, protocol.cutover_state,
           protocol.cutover_completed_at, protocol.cutover_completed_by,
           protocol.cutover_executable_path,
           protocol.cutover_process_evidence
      INTO generation_value, state_value, completed_at_value,
           completed_by_value, executable_path_value, process_evidence_value
    FROM public.experiment_scheduler_protocol protocol
    WHERE protocol.singleton FOR SHARE;
    required_generation := generation_value;
    cutover_state := state_value;
    cutover_completed_at := CASE WHEN completed_at_value IS NULL THEN NULL
        ELSE to_char(completed_at_value AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END;
    cutover_completed_by := completed_by_value;
    cutover_executable_path := executable_path_value;
    cutover_process_evidence := process_evidence_value;
    evidence_complete := coalesce(generation_value = 52 AND
        state_value = 'complete' AND completed_at_value IS NOT NULL AND
        completed_by_value IS NOT NULL AND
        executable_path_value IS NOT NULL AND
        process_evidence_value IS NOT NULL, false);
    IF evidence_complete THEN
        evidence_canonical :=
            public.campaign_operations_scheduler_protocol_evidence_canonical_v1(
                generation_value, state_value, completed_at_value,
                completed_by_value, executable_path_value,
                process_evidence_value);
        evidence_hash :=
            public.campaign_operations_tagged_fnv1a64(evidence_canonical);
    END IF;
    RETURN NEXT;
END;
$$;


--
-- Name: campaign_operations_tagged_fnv1a64(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_operations_tagged_fnv1a64(canonical_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE canonical_bytes bytea := convert_to(canonical_value, 'UTF8');
DECLARE hash_value numeric := 14695981039346656037;
DECLARE byte_index integer;
DECLARE low_byte integer;
DECLARE high_word bigint;
DECLARE low_word bigint;
BEGIN
    IF octet_length(canonical_bytes) > 0 THEN
        FOR byte_index IN 0..octet_length(canonical_bytes) - 1 LOOP
            low_byte := mod(hash_value, 256)::integer #
                get_byte(canonical_bytes, byte_index);
            hash_value := hash_value - mod(hash_value, 256) + low_byte;
            hash_value := mod(
                hash_value * 1099511628211, 18446744073709551616);
        END LOOP;
    END IF;
    high_word := trunc(hash_value / 4294967296)::bigint;
    low_word := mod(hash_value, 4294967296)::bigint;
    RETURN 'fnv1a64:' || lpad(to_hex(high_word), 8, '0') ||
        lpad(to_hex(low_word), 8, '0');
END;
$$;


--
-- Name: canonicalize_experiment_current_operation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonicalize_experiment_current_operation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.current_operation :=
        CASE NEW.current_operation
            WHEN 'training' THEN 'train'
            WHEN 'inference' THEN 'infer'
            WHEN 'analysis' THEN 'analyze'
            WHEN 'checkpoint_stopped' THEN
                CASE
                    WHEN NEW.status = 'pending'
                     AND NEW.phase IN ('infer', 'analyze')
                     AND NEW.stopped_at_checkpoint_epoch IS NOT NULL
                     AND NEW.stopped_at_checkpoint_model_id IS NOT NULL
                     AND NEW.last_model_id = NEW.stopped_at_checkpoint_model_id
                    THEN NEW.phase
                    ELSE NEW.current_operation
                END
            WHEN 'cancel_checkpoint_reached' THEN
                CASE
                    WHEN NEW.status = 'cancelled'
                     AND NEW.phase = 'train'
                     AND NEW.cancellation_request_id IS NOT NULL
                     AND NEW.cancellation_completed_at IS NOT NULL
                     AND NEW.stopped_at_checkpoint_epoch IS NOT NULL
                     AND NEW.stopped_at_checkpoint_model_id IS NOT NULL
                     AND NEW.last_model_id = NEW.stopped_at_checkpoint_model_id
                    THEN 'train'
                    ELSE NEW.current_operation
                END
            WHEN 'cancel_checkpoint_restart_pending' THEN
                CASE
                    WHEN NEW.status = 'pending'
                     AND NEW.phase = 'train'
                     AND NEW.cancellation_request_id IS NOT NULL
                     AND NEW.last_model_id IS NOT NULL
                    THEN 'train'
                    ELSE NEW.current_operation
                END
            WHEN 'cancelled_by_global_request' THEN
                CASE
                    WHEN NEW.status = 'cancelled'
                     AND NEW.phase IN ('train', 'infer', 'analyze')
                     AND NEW.cancellation_request_id IS NOT NULL
                     AND NEW.cancellation_completed_at IS NOT NULL
                    THEN NEW.phase
                    ELSE NEW.current_operation
                END
            ELSE NEW.current_operation
        END;
    RETURN NEW;
END;
$$;


--
-- Name: continuation_target_sequence_is_valid(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.continuation_target_sequence_is_valid(sequence integer[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT cardinality(sequence) > 0
       AND NOT EXISTS (
            SELECT 1
            FROM generate_subscripts(sequence, 1) AS position
            WHERE sequence[position] <= 0
               OR (
                    position > array_lower(sequence, 1)
                    AND sequence[position] <= sequence[position - 1]
               )
       );
$$;


--
-- Name: economic_event_first_release_actual_at(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.economic_event_first_release_actual_at(information_cutoff timestamp with time zone) RETURNS TABLE(economic_event_id bigint, event_release_at timestamp with time zone, first_release_actual_value_kind text, first_release_actual_value_low numeric, first_release_actual_value_high numeric, first_release_actual_unit text, first_release_actual_scale numeric, first_release_actual_qualifier text, proven_available_at timestamp with time zone, provenance_state text, selection_reason text, source_name text, source_native_event_id text, source_observation_id text, evidence_key text)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        f.economic_event_id,
        f.event_release_at,
        f.first_release_value_kind,
        f.first_release_value_low,
        f.first_release_value_high,
        f.first_release_unit,
        f.first_release_scale,
        f.first_release_qualifier,
        f.proven_available_at,
        f.provenance_state,
        f.selection_reason,
        f.first_release_source,
        f.first_release_source_native_event_id,
        f.first_release_source_observation_id,
        f.first_release_evidence_key
    FROM public.economic_event_first_release_actual f
    WHERE f.provenance_state = 'proven_first_release'
      AND f.proven_available_at <= information_cutoff
    ORDER BY f.event_release_at, f.economic_event_id
$$;


--
-- Name: FUNCTION economic_event_first_release_actual_at(information_cutoff timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.economic_event_first_release_actual_at(information_cutoff timestamp with time zone) IS 'PIT-safe Phase-2 API: returns only proven first-release actuals whose proven availability is at or before the caller cutoff.';


--
-- Name: enforce_campaign_materialization_pause_ownership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_materialization_pause_ownership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NOT EXISTS (
        SELECT 1
        FROM experiment_campaign_materialization_control_operation operation
        JOIN experiment_campaign_materialization_control_member member
          ON member.campaign_materialization_control_operation_id =
             operation.campaign_materialization_control_operation_id
        JOIN experiment_campaign_materialization_control_outcome outcome
          ON outcome.campaign_materialization_control_member_id =
             member.campaign_materialization_control_member_id
        WHERE operation.campaign_materialization_control_operation_id =
              NEW.pause_operation_id
          AND operation.action = 'pause'
          AND member.campaign_materialization_control_member_id =
              NEW.pause_control_member_id
          AND member.recommendation_campaign_materialization_member_id =
              NEW.recommendation_campaign_materialization_member_id
          AND member.experiment_id = NEW.experiment_id
          AND outcome.outcome_kind = 'changed_by_group_pause'
          AND outcome.changed_by_operation
    ) THEN
        RAISE EXCEPTION 'campaign pause ownership provenance mismatch'
            USING ERRCODE = '23514';
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.ownership_state = 'consumed' AND NOT EXISTS (
        SELECT 1
        FROM experiment_campaign_materialization_control_operation operation
        JOIN experiment_campaign_materialization_control_member member
          ON member.campaign_materialization_control_operation_id =
             operation.campaign_materialization_control_operation_id
        JOIN experiment_campaign_materialization_control_outcome outcome
          ON outcome.campaign_materialization_control_member_id =
             member.campaign_materialization_control_member_id
        WHERE operation.campaign_materialization_control_operation_id =
              NEW.consumed_resume_operation_id
          AND operation.action = 'resume'
          AND member.recommendation_campaign_materialization_member_id =
              NEW.recommendation_campaign_materialization_member_id
          AND member.experiment_id = NEW.experiment_id
          AND member.source_pause_operation_id = NEW.pause_operation_id
          AND outcome.outcome_kind = 'released_by_group_resume'
          AND outcome.changed_by_operation
    ) THEN
        RAISE EXCEPTION 'campaign resume ownership consumption mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: enforce_campaign_operations_authorization_chain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_authorization_chain() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(
        NEW.campaign_identity_canonical ||
        ';action=' || NEW.action_kind ||
        ';scope=' || NEW.scope_kind, 1179402835030003));

    PERFORM 1
    FROM campaign_operations_campaign campaign
    WHERE campaign.operational_campaign_id = NEW.operational_campaign_id
      AND campaign.campaign_identity_canonical =
              NEW.campaign_identity_canonical;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations authorization campaign mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_authorization_campaign_check';
    END IF;

    IF NEW.chain_version > 1 THEN
        PERFORM 1
        FROM campaign_operations_authorization_event predecessor
        WHERE predecessor.authorization_event_id = NEW.previous_event_id
          AND predecessor.operational_campaign_id =
                  NEW.operational_campaign_id
          AND predecessor.action_kind = NEW.action_kind
          AND predecessor.action_contract_version =
                  NEW.action_contract_version
          AND predecessor.scope_kind = NEW.scope_kind
          AND predecessor.scope_contract_version =
                  NEW.scope_contract_version
          AND predecessor.chain_version = NEW.chain_version - 1
          AND predecessor.authorization_identity_canonical =
                  NEW.previous_event_identity_canonical
          AND predecessor.authorization_identity_hash =
                  NEW.previous_event_identity_hash;
        IF NOT FOUND THEN
            RAISE EXCEPTION
                'campaign operations authorization predecessor mismatch'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'campaign_operations_authorization_previous_check';
        END IF;
    END IF;

    IF NEW.governance_provenance_event_id IS NOT NULL THEN
        PERFORM 1
        FROM campaign_operations_governance_provenance_event provenance
        WHERE provenance.governance_provenance_event_id =
                  NEW.governance_provenance_event_id
          AND provenance.operational_campaign_id =
                  NEW.operational_campaign_id
          AND provenance.provenance_identity_canonical =
                  NEW.provenance_identity_canonical
          AND provenance.provenance_identity_hash =
                  NEW.provenance_identity_hash
          AND provenance.prerequisite_policy =
                  NEW.prerequisite_policy;
        IF NOT FOUND THEN
            RAISE EXCEPTION
                'campaign operations authorization provenance mismatch'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'campaign_operations_authorization_provenance_check';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_binding_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_binding_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_operational_request request
    JOIN experiment_recommendation_campaign_materialization materialization
      ON materialization.recommendation_campaign_materialization_id =
         request.recommendation_campaign_materialization_id
    JOIN experiment_recommendation_campaign_materialization_member member
      ON member.recommendation_campaign_materialization_id =
         materialization.recommendation_campaign_materialization_id
    JOIN experiment_recommendation_conversion_execution execution
      ON execution.recommendation_conversion_proposal_id =
         member.recommendation_conversion_proposal_id
    JOIN experiment_recommendation_conversion_activation activation
      ON activation.recommendation_conversion_execution_id =
         execution.recommendation_conversion_execution_id
    JOIN experiment downstream
      ON downstream.experiment_id = execution.experiment_id
    WHERE request.operational_request_id = NEW.operational_request_id
      AND request.request_identity_canonical =
          NEW.request_identity_canonical
      AND request.recommendation_campaign_materialization_id =
          NEW.recommendation_campaign_materialization_id
      AND materialization.materialization_identity_canonical =
          NEW.materialization_identity_canonical
      AND member.recommendation_campaign_materialization_member_id =
          NEW.recommendation_campaign_materialization_member_id
      AND member.member_ordinal = NEW.member_ordinal
      AND member.selected_member_identity_canonical =
          NEW.selected_member_identity_canonical
      AND member.selected_member_identity_hash =
          NEW.selected_member_identity_hash
      AND member.recommendation_conversion_proposal_id =
          NEW.recommendation_conversion_proposal_id
      AND member.proposal_identity_canonical =
          NEW.proposal_identity_canonical
      AND member.proposal_identity_hash = NEW.proposal_identity_hash
      AND execution.recommendation_conversion_review_decision_id =
          NEW.recommendation_conversion_review_decision_id
      AND execution.recommendation_conversion_execution_id =
          NEW.recommendation_conversion_execution_id
      AND execution.execution_identity_canonical =
          NEW.execution_identity_canonical
      AND execution.execution_identity_hash = NEW.execution_identity_hash
      AND activation.recommendation_conversion_activation_id =
          NEW.recommendation_conversion_activation_id
      AND activation.activation_identity_canonical =
          NEW.activation_identity_canonical
      AND activation.activation_identity_hash =
          NEW.activation_identity_hash
      AND activation.experiment_id = NEW.experiment_id
      AND downstream.status = 'pending'
      AND downstream.phase = 'train';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations binding provenance mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_binding_provenance_check';
    END IF;
    IF NEW.binding_disposition = 'adopted_existing_pending' AND
       (NEW.execution_disposition <> 'reused' OR
        NEW.activation_disposition <> 'reused') THEN
        RAISE EXCEPTION 'campaign operations adoption must reuse exact work'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_budget_audit_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_budget_audit_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_audit_reference_event audit
    WHERE audit.budget_ledger_entry_id = NEW.budget_ledger_entry_id
      AND audit.operational_campaign_id = NEW.operational_campaign_id
      AND audit.cause_kind = 'budget_ledger_recorded'
      AND audit.capability =
              'campaign_operations_budget_administrator'
      AND audit.actor_identity = NEW.administrator_identity
      AND audit.reason = NEW.reason
      AND audit.prior_version IS NOT DISTINCT FROM
              CASE WHEN NEW.ledger_version = 1
                   THEN NULL
                   ELSE NEW.ledger_version - 1
              END
      AND audit.resulting_version = NEW.ledger_version
      AND audit.outcome = 'recorded'
      AND audit.replay_disposition = 'recorded';
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'campaign operations budget audit evidence incomplete'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_budget_audit_check';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_budget_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_budget_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    predecessor campaign_operations_budget_ledger_entry%ROWTYPE;
    committed_units bigint;
    held_units bigint;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(
        NEW.campaign_identity_canonical, 1179402835030004));

    PERFORM 1
    FROM campaign_operations_campaign campaign
    WHERE campaign.operational_campaign_id = NEW.operational_campaign_id
      AND campaign.campaign_identity_canonical =
              NEW.campaign_identity_canonical
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations budget campaign mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'campaign_operations_budget_campaign_check';
    END IF;

    SELECT
        coalesce(sum(amount) FILTER (
            WHERE reservation_state = 'committed'), 0),
        coalesce(sum(amount) FILTER (
            WHERE reservation_state IN (
                'held', 'reconciliation_required')), 0)
    INTO committed_units, held_units
    FROM campaign_operations_reservation
    WHERE operational_campaign_id = NEW.operational_campaign_id;

    IF NEW.ledger_version = 1 THEN
        IF NEW.entry_kind <> 'grant' THEN
            RAISE EXCEPTION 'campaign operations initial budget must grant'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'campaign_operations_budget_initial_check';
        END IF;
    ELSE
        SELECT * INTO STRICT predecessor
        FROM campaign_operations_budget_ledger_entry
        WHERE budget_ledger_entry_id = NEW.previous_entry_id
        FOR UPDATE;
        IF predecessor.operational_campaign_id <>
                NEW.operational_campaign_id OR
           predecessor.ledger_version <> NEW.ledger_version - 1 OR
           predecessor.budget_identity_canonical <>
                NEW.previous_entry_identity_canonical OR
           predecessor.budget_identity_hash <>
                NEW.previous_entry_identity_hash OR
           predecessor.resulting_total <> NEW.prior_total OR
           (NEW.entry_kind IN ('amend', 'revoke') AND
                predecessor.ledger_status <> 'active') OR
           (NEW.entry_kind = 'supersede' AND
                predecessor.ledger_status <> 'revoked') THEN
            RAISE EXCEPTION
                'campaign operations budget predecessor mismatch'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'campaign_operations_budget_previous_check';
        END IF;
    END IF;

    IF NEW.resulting_total < committed_units + held_units OR
       (NEW.entry_kind = 'revoke' AND
            NEW.resulting_total <> committed_units + held_units) THEN
        RAISE EXCEPTION 'campaign operations budget below obligations'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_budget_obligation_check';
    END IF;
    RETURN NEW;
EXCEPTION
    WHEN no_data_found THEN
        RAISE EXCEPTION 'campaign operations budget predecessor missing'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_budget_previous_check';
END;
$$;


--
-- Name: enforce_campaign_operations_campaign_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_campaign_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_campaign_materialization materialization
    WHERE materialization.recommendation_campaign_materialization_id =
              NEW.recommendation_campaign_materialization_id
      AND materialization.materialization_contract_version =
              NEW.materialization_contract_version
      AND materialization.materialization_identity_canonical =
              NEW.materialization_identity_canonical
      AND materialization.materialization_identity_hash =
              NEW.materialization_identity_hash
      AND materialization.selected_member_count =
              NEW.materialization_member_count
      AND (SELECT count(*)::integer
           FROM experiment_recommendation_campaign_materialization_member member
           WHERE member.recommendation_campaign_materialization_id =
                 materialization.recommendation_campaign_materialization_id) =
              NEW.materialization_member_count
      AND (SELECT min(member_ordinal)
           FROM experiment_recommendation_campaign_materialization_member member
           WHERE member.recommendation_campaign_materialization_id =
                 materialization.recommendation_campaign_materialization_id) = 1
      AND (SELECT max(member_ordinal)
           FROM experiment_recommendation_campaign_materialization_member member
           WHERE member.recommendation_campaign_materialization_id =
                 materialization.recommendation_campaign_materialization_id) =
              NEW.materialization_member_count;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations materialization mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_campaign_materialization_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_cancellation_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_cancellation_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_campaign
    WHERE operational_campaign_id = NEW.operational_campaign_id
      AND campaign_identity_canonical =
          NEW.campaign_identity_canonical
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'campaign operations cancellation campaign mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.operational_request_id IS NOT NULL THEN
        PERFORM 1
        FROM campaign_operations_operational_request
        WHERE operational_request_id = NEW.operational_request_id
          AND operational_campaign_id = NEW.operational_campaign_id
          AND request_identity_canonical =
              NEW.request_identity_canonical
          AND request_state = NEW.expected_request_state
          AND state_version = NEW.expected_request_version
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION
                'campaign operations cancellation target mismatch'
                USING ERRCODE = '40001';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_complete_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_complete_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE request_row campaign_operations_operational_request%ROWTYPE;
DECLARE reservation_row campaign_operations_reservation%ROWTYPE;
DECLARE binding_count integer;
DECLARE owner_count integer;
DECLARE target_request_id bigint;
BEGIN
    IF TG_TABLE_NAME = 'campaign_operations_reservation' THEN
        SELECT operational_request_id INTO target_request_id
        FROM campaign_operations_operational_request
        WHERE reservation_id = NEW.reservation_id;
    ELSE
        target_request_id := NEW.operational_request_id;
    END IF;
    SELECT * INTO request_row
    FROM campaign_operations_operational_request
    WHERE operational_request_id = target_request_id;
    IF NOT FOUND OR request_row.request_state <> 'bound' THEN
        RETURN NEW;
    END IF;
    SELECT * INTO STRICT reservation_row
    FROM campaign_operations_reservation
    WHERE reservation_id = request_row.reservation_id;
    SELECT count(*) INTO binding_count
    FROM campaign_operations_request_binding
    WHERE operational_request_id = request_row.operational_request_id;
    SELECT count(*) INTO owner_count
    FROM campaign_operations_downstream_control_owner
    WHERE operational_request_id = request_row.operational_request_id;
    IF reservation_row.reservation_state <> 'committed' OR
       binding_count <> request_row.materialization_member_count OR
       owner_count <> request_row.materialization_member_count OR
       NOT EXISTS (
           SELECT 1 FROM campaign_operations_reservation_commitment c
           WHERE c.reservation_id = reservation_row.reservation_id
             AND c.operational_request_id =
                 request_row.operational_request_id) OR
       NOT EXISTS (
           SELECT 1
           FROM campaign_operations_dispatch_attempt attempt
           JOIN campaign_operations_dispatch_attempt_outcome outcome
             ON outcome.dispatch_attempt_id = attempt.dispatch_attempt_id
           WHERE attempt.operational_request_id =
                 request_row.operational_request_id
             AND outcome.result_classification IN (
                 'created_and_bound',
                 'adopted_existing_pending_and_bound',
                 'existing_identical')) THEN
        RAISE EXCEPTION 'campaign operations bound request is incomplete'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_complete_binding_check';
    END IF;
    IF EXISTS (
        SELECT member.member_ordinal
        FROM experiment_recommendation_campaign_materialization_member member
        WHERE member.recommendation_campaign_materialization_id =
              request_row.recommendation_campaign_materialization_id
        EXCEPT
        SELECT binding.member_ordinal
        FROM campaign_operations_request_binding binding
        WHERE binding.operational_request_id =
              request_row.operational_request_id) THEN
        RAISE EXCEPTION 'campaign operations binding ordinals incomplete'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_completion_audit_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_completion_audit_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_campaign campaign
    WHERE campaign.operational_campaign_id = NEW.operational_campaign_id
      AND campaign.completion_boundary_closed;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'campaign operations completion boundary is not closed'
            USING ERRCODE = '23514';
    END IF;
    PERFORM 1
    FROM campaign_operations_completion_audit_reference_event audit
    WHERE audit.operational_campaign_id = NEW.operational_campaign_id
      AND audit.completion_event_id = NEW.completion_event_id
      AND audit.actor_identity = NEW.actor_identity
      AND audit.capability = NEW.capability
      AND audit.reason = NEW.reason
      AND audit.outcome = 'recorded'
      AND audit.replay_disposition = 'recorded'
      AND audit.diagnostic_code =
          'all_completion_prerequisites_proven';
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'campaign operations completion audit reference missing'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_completion_boundary_consistent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_completion_boundary_consistent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE completion_exists boolean;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM campaign_operations_completion_event completion
        WHERE completion.operational_campaign_id =
              NEW.operational_campaign_id)
      INTO completion_exists;
    IF NEW.completion_boundary_closed <> completion_exists THEN
        RAISE EXCEPTION
            'campaign operations completion boundary/event mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_completion_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_completion_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE classified record;
DECLARE budget record;
DECLARE boundary_closed boolean;
BEGIN
    SELECT completion_boundary_closed INTO boundary_closed
    FROM campaign_operations_campaign
    WHERE operational_campaign_id = NEW.operational_campaign_id
      AND campaign_identity_canonical = NEW.campaign_identity_canonical
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations completion campaign mismatch'
            USING ERRCODE = '23514';
    END IF;
    SELECT * INTO STRICT classified
    FROM campaign_operations_completion_classification(
        NEW.operational_campaign_id);
    SELECT
        head.budget_ledger_entry_id, head.ledger_version,
        head.resulting_total,
        COALESCE(sum(reservation.amount), 0)::bigint AS ever_reserved,
        COALESCE(sum(reservation.amount) FILTER (
            WHERE reservation.reservation_state = 'committed'), 0)::bigint
            AS committed,
        COALESCE(sum(reservation.amount) FILTER (
            WHERE reservation.reservation_state IN ('released', 'expired')),
            0)::bigint AS released_or_expired,
        COALESCE(sum(reservation.amount) FILTER (
            WHERE reservation.reservation_state = 'held'), 0)::bigint AS held
      INTO STRICT budget
    FROM LATERAL (
        SELECT * FROM campaign_operations_budget_ledger_entry
        WHERE operational_campaign_id = NEW.operational_campaign_id
        ORDER BY ledger_version DESC LIMIT 1) head
    LEFT JOIN campaign_operations_reservation reservation
      ON reservation.operational_campaign_id =
         NEW.operational_campaign_id
    GROUP BY head.budget_ledger_entry_id, head.ledger_version,
             head.resulting_total;
    IF NEW.administrative_terminal_state <>
            classified.administrative_terminal_state OR
       NEW.completion_classification <>
            classified.completion_classification OR
       NEW.scope_member_count <> classified.scope_member_count OR
       NEW.completed_member_count <>
            classified.completed_member_count OR
       NEW.failed_member_count <> classified.failed_member_count OR
       NEW.cancelled_or_never_dispatched_member_count <>
            classified.cancelled_or_never_dispatched_member_count OR
       NEW.reservation_count <> classified.reservation_count OR
       NEW.request_count <> classified.request_count OR
       NEW.binding_count <> classified.binding_count OR
       NEW.control_owner_count <> classified.control_owner_count OR
       NEW.cancellation_request_count <>
            classified.cancellation_request_count OR
       NEW.cancellation_settlement_count <>
            classified.cancellation_settlement_count OR
       NEW.unresolved_blocking_observation_count <> 0 OR
       NEW.budget_ledger_entry_id <> budget.budget_ledger_entry_id OR
       NEW.budget_ledger_version <> budget.ledger_version OR
       NEW.budget_resulting_total <> budget.resulting_total OR
       NEW.budget_ever_reserved <> budget.ever_reserved OR
       NEW.budget_committed <> budget.committed OR
       NEW.budget_released_or_expired <> budget.released_or_expired OR
       NEW.budget_held <> budget.held OR
       NEW.budget_unallocated <>
            budget.resulting_total - budget.committed - budget.held OR
       NEW.authorization_evidence_canonical <>
            campaign_operations_completion_evidence_text(
                NEW.operational_campaign_id, 'authorization') OR
       NEW.budget_evidence_canonical <>
            campaign_operations_completion_evidence_text(
                NEW.operational_campaign_id, 'budget') OR
       NEW.reservation_evidence_canonical <>
            campaign_operations_completion_evidence_text(
                NEW.operational_campaign_id, 'reservation') OR
       NEW.request_evidence_canonical <>
            campaign_operations_completion_evidence_text(
                NEW.operational_campaign_id, 'request') OR
       NEW.binding_evidence_canonical <>
            campaign_operations_completion_evidence_text(
                NEW.operational_campaign_id, 'binding') OR
       NEW.lifecycle_evidence_canonical <>
            campaign_operations_completion_evidence_text(
                NEW.operational_campaign_id, 'lifecycle') OR
       NEW.cancellation_evidence_canonical <>
            campaign_operations_completion_evidence_text(
                NEW.operational_campaign_id, 'cancellation') OR
       NEW.reconciliation_evidence_canonical <>
            campaign_operations_completion_evidence_text(
                NEW.operational_campaign_id, 'reconciliation') THEN
        RAISE EXCEPTION
            'campaign operations completion evidence changed or mismatched'
            USING ERRCODE = '40001';
    END IF;
    IF NOT campaign_operations_completion_identity_valid(NEW) THEN
        RAISE EXCEPTION
            'campaign operations completion canonical or hash mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF boundary_closed THEN
        RAISE EXCEPTION
            'campaign operations completion already exists'
            USING ERRCODE = '23505';
    END IF;
    UPDATE campaign_operations_campaign
       SET completion_boundary_closed = true
     WHERE operational_campaign_id = NEW.operational_campaign_id;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_control_audit_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_control_audit_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'campaign_operations_control_event' THEN
        PERFORM 1
        FROM campaign_operations_control_audit_reference_event audit
        WHERE audit.control_event_id = NEW.control_event_id
          AND audit.operational_campaign_id =
              NEW.operational_campaign_id
          AND audit.cause_kind =
              CASE WHEN NEW.event_kind = 'pause'
                   THEN 'campaign_paused'
                   ELSE 'campaign_resumed'
              END
          AND audit.actor_identity = NEW.actor_identity
          AND audit.capability = NEW.capability
          AND audit.reason = NEW.reason
          AND audit.prior_version = NEW.control_version - 1
          AND audit.resulting_version = NEW.control_version
          AND audit.outcome = 'recorded';
    ELSIF TG_TABLE_NAME =
            'campaign_operations_cancellation_request' THEN
        PERFORM 1
        FROM campaign_operations_control_audit_reference_event audit
        WHERE audit.cancellation_request_id =
              NEW.cancellation_request_id
          AND audit.operational_campaign_id =
              NEW.operational_campaign_id
          AND audit.operational_request_id IS NOT DISTINCT FROM
              NEW.operational_request_id
          AND audit.cause_kind = 'cancellation_requested'
          AND audit.actor_identity = NEW.actor_identity
          AND audit.capability = NEW.capability
          AND audit.reason = NEW.reason
          AND audit.outcome = 'recorded';
    ELSIF TG_TABLE_NAME =
            'campaign_operations_cancellation_settlement' THEN
        PERFORM 1
        FROM campaign_operations_control_audit_reference_event audit
        JOIN campaign_operations_cancellation_request request
          ON request.cancellation_request_id =
              NEW.cancellation_request_id
        WHERE audit.cancellation_settlement_id =
              NEW.cancellation_settlement_id
          AND audit.cancellation_request_id =
              NEW.cancellation_request_id
          AND audit.operational_campaign_id =
              request.operational_campaign_id
          AND audit.operational_request_id IS NOT DISTINCT FROM
              request.operational_request_id
          AND audit.cause_kind = 'cancellation_settled'
          AND audit.outcome = 'recorded';
    ELSIF TG_TABLE_NAME =
            'campaign_operations_reconciliation_observation' THEN
        PERFORM 1
        FROM campaign_operations_control_audit_reference_event audit
        WHERE audit.reconciliation_observation_id =
              NEW.reconciliation_observation_id
          AND audit.operational_campaign_id =
              NEW.operational_campaign_id
          AND audit.operational_request_id =
              NEW.operational_request_id
          AND audit.cause_kind = 'reconciliation_observed'
          AND audit.outcome = 'recorded';
    ELSIF TG_TABLE_NAME =
            'campaign_operations_reconciliation_resolution' THEN
        PERFORM 1
        FROM campaign_operations_control_audit_reference_event audit
        JOIN campaign_operations_reconciliation_observation observation
          ON observation.reconciliation_observation_id =
              NEW.reconciliation_observation_id
        WHERE audit.reconciliation_resolution_id =
              NEW.reconciliation_resolution_id
          AND audit.reconciliation_observation_id =
              NEW.reconciliation_observation_id
          AND audit.operational_campaign_id =
              observation.operational_campaign_id
          AND audit.operational_request_id =
              observation.operational_request_id
          AND audit.cause_kind = 'reconciliation_resolved'
          AND audit.actor_identity = NEW.owning_capability
          AND audit.capability = NEW.owning_capability
          AND audit.reason = observation.diagnostic_code
          AND audit.diagnostic_code = observation.diagnostic_code
          AND audit.outcome = 'recorded';
    ELSE
        RAISE EXCEPTION
            'unsupported campaign operations control audit source'
            USING ERRCODE = '23514';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'campaign operations control audit evidence incomplete'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_control_audit_complete';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_control_chain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_control_chain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    predecessor campaign_operations_control_event%ROWTYPE;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(
        NEW.campaign_identity_canonical || ';control', 1179402835030005));
    PERFORM 1 FROM campaign_operations_campaign
    WHERE operational_campaign_id = NEW.operational_campaign_id
      AND campaign_identity_canonical = NEW.campaign_identity_canonical
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations control campaign mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.control_version = 1 THEN
        IF NEW.event_kind <> 'pause' THEN
            RAISE EXCEPTION 'first campaign control must pause'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        SELECT * INTO STRICT predecessor
        FROM campaign_operations_control_event
        WHERE control_event_id = NEW.previous_control_event_id
        FOR UPDATE;
        IF predecessor.operational_campaign_id <>
                NEW.operational_campaign_id OR
           predecessor.control_version <> NEW.control_version - 1 OR
           predecessor.control_identity_canonical <>
                NEW.previous_control_event_identity_canonical OR
           predecessor.event_kind = NEW.event_kind THEN
            RAISE EXCEPTION 'campaign operations control chain mismatch'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    IF EXISTS (
        SELECT 1 FROM campaign_operations_cancellation_request
        WHERE operational_campaign_id = NEW.operational_campaign_id) THEN
        RAISE EXCEPTION 'campaign operations control blocked by cancellation'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.event_kind = 'resume' AND EXISTS (
        SELECT 1
        FROM campaign_operations_reconciliation_observation observation
        LEFT JOIN campaign_operations_reconciliation_resolution resolution
          ON resolution.reconciliation_observation_id =
              observation.reconciliation_observation_id
        WHERE observation.operational_campaign_id =
              NEW.operational_campaign_id
          AND resolution.reconciliation_resolution_id IS NULL) THEN
        RAISE EXCEPTION
            'campaign operations resume blocked by unresolved reconciliation'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
EXCEPTION WHEN no_data_found THEN
    RAISE EXCEPTION 'campaign operations control predecessor missing'
        USING ERRCODE = '23514';
END;
$$;


--
-- Name: enforce_campaign_operations_control_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_control_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_request_binding binding
    WHERE binding.request_binding_id = NEW.request_binding_id
      AND binding.operational_request_id = NEW.operational_request_id
      AND binding.binding_identity_canonical =
          NEW.binding_identity_canonical
      AND binding.experiment_id = NEW.experiment_id
      AND ((binding.binding_disposition = 'created' AND
            NEW.control_mode = 'created_control') OR
           (binding.binding_disposition = 'adopted_existing_pending' AND
            NEW.control_mode = 'authorized_adoption_control'));
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations control owner mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_control_owner_binding_check';
    END IF;
    IF NEW.control_mode = 'authorized_adoption_control' THEN
        PERFORM 1
        FROM campaign_operations_authorization_event authz
        WHERE authz.authorization_event_id =
              NEW.adoption_authorization_event_id
          AND authz.authorization_identity_canonical =
              NEW.adoption_authorization_identity_canonical
          AND authz.authorization_identity_hash =
              NEW.adoption_authorization_identity_hash
          AND authz.operational_campaign_id = (
              SELECT operational_campaign_id
              FROM campaign_operations_operational_request
              WHERE operational_request_id = NEW.operational_request_id)
          AND authz.action_kind =
              'adopt_existing_pending_and_control'
          AND authz.event_kind = 'granted'
          AND authz.not_before <= transaction_timestamp()
          AND (authz.expires_at IS NULL OR
               authz.expires_at > transaction_timestamp())
          AND authz.authorization_event_id = (
              SELECT authorization_event_id
              FROM campaign_operations_authorization_event
              WHERE operational_campaign_id =
                    authz.operational_campaign_id
                AND action_kind =
                    'adopt_existing_pending_and_control'
                AND action_contract_version = 1
                AND scope_kind = 'complete_materialization'
                AND scope_contract_version = 1
              ORDER BY chain_version DESC LIMIT 1);
        IF NOT FOUND THEN
            RAISE EXCEPTION
                'campaign operations adoption authorization mismatch'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_dispatch_acquisition_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_dispatch_acquisition_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.request_state <> 'dispatching' THEN RETURN NEW; END IF;
    IF OLD.request_state <> 'ready' OR
       NEW.state_version <> OLD.state_version + 1 OR
       NEW.lease_token_hash IS NULL OR NEW.lease_expires_at IS NULL OR
       NEW.dispatcher_identity IS NULL OR
       NEW.operational_campaign_id <> OLD.operational_campaign_id OR
       NEW.reservation_id <> OLD.reservation_id OR
       NEW.request_identity_canonical <> OLD.request_identity_canonical OR
       NOT EXISTS (
         SELECT 1
         FROM public.campaign_operations_dispatch_attempt attempt
         JOIN public.campaign_operations_dispatch_audit_reference_event audit
           ON audit.dispatch_attempt_id = attempt.dispatch_attempt_id
         LEFT JOIN public.campaign_operations_request_production_admission admission
           ON admission.request_production_admission_id =
              attempt.request_production_admission_id
         WHERE attempt.operational_request_id = NEW.operational_request_id
           AND attempt.request_identity_canonical =
               NEW.request_identity_canonical
           AND attempt.expected_request_version = OLD.state_version
           AND attempt.resulting_request_version = NEW.state_version
           AND attempt.lease_token_digest = NEW.lease_token_hash
           AND attempt.lease_expires_at = NEW.lease_expires_at
           AND attempt.dispatcher_identity = NEW.dispatcher_identity
           AND audit.operational_campaign_id = NEW.operational_campaign_id
           AND audit.operational_request_id = NEW.operational_request_id
           AND audit.cause_kind = 'dispatch_lease_acquired'
           AND audit.actor_identity = NEW.dispatcher_identity
           AND audit.prior_version = OLD.state_version
           AND audit.resulting_version = NEW.state_version
           AND ((NOT NEW.production_dispatch_enabled AND
                 attempt.attempt_contract_version = 1 AND
                 admission.request_production_admission_id IS NULL AND
                 audit.request_production_admission_id IS NULL AND
                 audit.production_enablement_event_id IS NULL) OR
                (NEW.production_dispatch_enabled AND
                 attempt.attempt_contract_version = 2 AND
                 admission.operational_request_id =
                     NEW.operational_request_id AND
                 audit.request_production_admission_id =
                     admission.request_production_admission_id AND
                 audit.production_enablement_event_id =
                     attempt.production_enablement_event_id))) THEN
        RAISE EXCEPTION
          'campaign operations dispatch acquisition evidence incomplete'
          USING ERRCODE = '23514',
                CONSTRAINT =
                  'campaign_operations_dispatch_acquisition_complete';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_future_action_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_future_action_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_campaign
    WHERE operational_campaign_id = NEW.operational_campaign_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations campaign missing'
            USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
        SELECT 1 FROM campaign_operations_control_event
        WHERE operational_campaign_id = NEW.operational_campaign_id
        ORDER BY control_version DESC LIMIT 1
    ) AND (
        SELECT event_kind = 'pause'
        FROM campaign_operations_control_event
        WHERE operational_campaign_id = NEW.operational_campaign_id
        ORDER BY control_version DESC LIMIT 1
    ) THEN
        RAISE EXCEPTION 'campaign operations campaign paused'
            USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
        SELECT 1 FROM campaign_operations_cancellation_request
        WHERE operational_campaign_id = NEW.operational_campaign_id) THEN
        RAISE EXCEPTION 'campaign operations campaign cancellation requested'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_governance_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_governance_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_campaign campaign
    JOIN experiment_recommendation_campaign_follow_up_ratification_event
        ratification
      ON ratification.recommendation_campaign_follow_up_ratification_event_id =
             NEW.recommendation_campaign_follow_up_ratification_event_id
    JOIN experiment_recommendation_campaign_follow_up_proposal proposal
      ON proposal.recommendation_campaign_follow_up_proposal_id =
             NEW.recommendation_campaign_follow_up_proposal_id
    WHERE campaign.operational_campaign_id = NEW.operational_campaign_id
      AND campaign.campaign_identity_canonical =
              NEW.campaign_identity_canonical
      AND ratification.ratification_contract_version =
              NEW.ratification_contract_version
      AND ratification.ratification_identity_canonical =
              NEW.ratification_identity_canonical
      AND ratification.ratification_identity_hash =
              NEW.ratification_identity_hash
      AND ratification.recommendation_campaign_follow_up_proposal_review_event_id =
              NEW.recommendation_campaign_follow_up_proposal_review_event_id
      AND ratification.review_contract_version = NEW.review_contract_version
      AND ratification.review_identity_canonical =
              NEW.review_identity_canonical
      AND ratification.review_identity_hash = NEW.review_identity_hash
      AND ratification.recommendation_campaign_follow_up_proposal_id =
              NEW.recommendation_campaign_follow_up_proposal_id
      AND ratification.proposal_contract_version =
              NEW.proposal_contract_version
      AND ratification.proposal_identity_canonical =
              NEW.proposal_identity_canonical
      AND ratification.proposal_identity_hash = NEW.proposal_identity_hash
      AND proposal.materialization_id =
              campaign.recommendation_campaign_materialization_id
      AND proposal.materialization_contract_version =
              campaign.materialization_contract_version
      AND proposal.materialization_identity_canonical =
              campaign.materialization_identity_canonical
      AND proposal.materialization_identity_hash =
              campaign.materialization_identity_hash
      AND proposal.member_count = campaign.materialization_member_count;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations governance provenance mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_governance_provenance_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_phase4_request_transition_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_phase4_request_transition_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.request_state = 'cancelled' AND
       OLD.request_state IN ('ready', 'dispatching') THEN
        PERFORM 1
        FROM campaign_operations_cancellation_request cancellation
        JOIN campaign_operations_cancellation_settlement settlement
          ON settlement.cancellation_request_id =
             cancellation.cancellation_request_id
        JOIN campaign_operations_reservation_event reservation_event
          ON reservation_event.reservation_event_id =
             settlement.reservation_event_id
         AND reservation_event.cancellation_request_id =
             cancellation.cancellation_request_id
        WHERE cancellation.operational_request_id =
                  NEW.operational_request_id
          AND cancellation.request_identity_canonical =
                  NEW.request_identity_canonical
          AND cancellation.expected_request_state = OLD.request_state
          AND cancellation.expected_request_version = OLD.state_version
          AND settlement.disposition = 'unbound_cancelled'
          AND settlement.resulting_request_version = NEW.state_version
          AND reservation_event.operational_request_id =
                  NEW.operational_request_id
          AND reservation_event.resulting_state = 'released';
        IF NOT FOUND THEN
            RAISE EXCEPTION
                'campaign operations cancellation transition incomplete'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                        'campaign_operations_phase4_request_transition_complete';
        END IF;
    ELSIF OLD.request_state = 'dispatching' AND
          NEW.request_state = 'ready' THEN
        PERFORM 1
        FROM campaign_operations_dispatch_attempt attempt
        JOIN campaign_operations_dispatch_attempt_outcome outcome
          ON outcome.dispatch_attempt_id = attempt.dispatch_attempt_id
        JOIN campaign_operations_dispatch_audit_reference_event audit
          ON audit.dispatch_attempt_outcome_id =
             outcome.dispatch_attempt_outcome_id
         AND audit.dispatch_attempt_id = attempt.dispatch_attempt_id
        JOIN campaign_operations_reconciliation_observation observation
          ON observation.operational_request_id =
             NEW.operational_request_id
         AND observation.expected_request_state = OLD.request_state
         AND observation.expected_request_version = OLD.state_version
         AND observation.reason_code =
             'dispatch_lease_expired_no_downstream_evidence'
        JOIN campaign_operations_reconciliation_resolution resolution
          ON resolution.reconciliation_observation_id =
             observation.reconciliation_observation_id
         AND resolution.transition_identity_canonical =
             outcome.outcome_identity_canonical
         AND resolution.transition_identity_hash =
             outcome.outcome_identity_hash
        WHERE attempt.operational_request_id =
                  NEW.operational_request_id
          AND attempt.attempt_ordinal = (
              SELECT max(latest.attempt_ordinal)
              FROM campaign_operations_dispatch_attempt latest
              WHERE latest.operational_request_id =
                    NEW.operational_request_id)
          AND outcome.expected_request_version = OLD.state_version
          AND outcome.resulting_request_version = NEW.state_version
          AND outcome.diagnostic_code =
              'dispatch_lease_expired_no_downstream_evidence'
          AND audit.cause_kind = 'dispatch_lease_recovered'
          AND audit.capability = 'campaign_operations_recovery'
          AND audit.prior_version = OLD.state_version
          AND audit.resulting_version = NEW.state_version
          AND resolution.owning_capability =
              'campaign_operations_recovery'
          AND resolution.resolution_disposition =
              'request_returned_ready';
        IF NOT FOUND THEN
            RAISE EXCEPTION
                'campaign operations recovery transition incomplete'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                        'campaign_operations_phase4_request_transition_complete';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_phase5_mutation_bound(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_phase5_mutation_bound() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE target_experiment_id bigint;
BEGIN
    IF current_user <> 'campaign_operations_phase5_transactional' THEN
        RETURN NEW;
    END IF;
    target_experiment_id := NEW.experiment_id;
    IF NOT EXISTS (
        SELECT 1
        FROM campaign_operations_request_binding binding
        JOIN campaign_operations_downstream_control_owner owner
          ON owner.request_binding_id = binding.request_binding_id
         AND owner.operational_request_id =
             binding.operational_request_id
         AND owner.experiment_id = binding.experiment_id
        JOIN campaign_operations_operational_request request
          ON request.operational_request_id =
             binding.operational_request_id
        JOIN campaign_operations_reservation reservation
          ON reservation.reservation_id = request.reservation_id
        JOIN campaign_operations_reservation_commitment commitment
          ON commitment.reservation_id = reservation.reservation_id
         AND commitment.operational_request_id =
             request.operational_request_id
        WHERE binding.experiment_id = target_experiment_id
          AND request.request_state = 'bound'
          AND reservation.reservation_state = 'committed') THEN
        RAISE EXCEPTION
            'Campaign Operations Phase 5 mutation lacks atomic binding'
            USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_production_admission_consistent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_production_admission_consistent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE target_request_id bigint;
DECLARE witness_value boolean;
DECLARE admission_count integer;
DECLARE matching_attempt_count integer;
DECLARE matching_audit_count integer;
BEGIN
    target_request_id := CASE TG_TABLE_NAME
        WHEN 'campaign_operations_operational_request' THEN
            NEW.operational_request_id
        WHEN 'campaign_operations_request_production_admission' THEN
            NEW.operational_request_id
        WHEN 'campaign_operations_dispatch_attempt' THEN
            NEW.operational_request_id
        ELSE NEW.operational_request_id END;
    SELECT production_dispatch_enabled INTO STRICT witness_value
    FROM public.campaign_operations_operational_request
    WHERE operational_request_id = target_request_id;
    SELECT count(*)::integer INTO admission_count
    FROM public.campaign_operations_request_production_admission
    WHERE operational_request_id = target_request_id;
    IF witness_value <> (admission_count = 1) THEN
        RAISE EXCEPTION 'production admission witness/evidence mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF admission_count = 1 THEN
        SELECT count(*)::integer INTO matching_attempt_count
        FROM public.campaign_operations_request_production_admission admission
        JOIN public.campaign_operations_dispatch_attempt attempt
          ON attempt.request_production_admission_id =
             admission.request_production_admission_id
         AND attempt.attempt_contract_version = 2
         AND attempt.operational_request_id = admission.operational_request_id
         AND attempt.request_identity_canonical =
             admission.request_identity_canonical
         AND attempt.expected_request_version =
             admission.expected_request_version
         AND attempt.operation_key = admission.dispatch_operation_key
         AND attempt.production_enablement_event_id =
             admission.production_enablement_event_id
         AND attempt.request_production_admission_canonical =
             admission.admission_identity_canonical
        WHERE admission.operational_request_id = target_request_id;
        SELECT count(*)::integer INTO matching_audit_count
        FROM public.campaign_operations_request_production_admission admission
        JOIN public.campaign_operations_dispatch_attempt attempt
          ON attempt.request_production_admission_id =
             admission.request_production_admission_id
         AND attempt.attempt_contract_version = 2
        JOIN public.campaign_operations_dispatch_audit_reference_event audit
          ON audit.dispatch_attempt_id = attempt.dispatch_attempt_id
         AND audit.request_production_admission_id =
             admission.request_production_admission_id
         AND audit.production_enablement_event_id =
             admission.production_enablement_event_id
         AND audit.cause_kind = 'dispatch_lease_acquired'
         AND audit.capability =
             'campaign_operations_production_dispatcher'
         AND audit.actor_identity = admission.requesting_actor
         AND audit.prior_version = admission.expected_request_version
         AND audit.resulting_version =
             admission.expected_request_version + 1
        WHERE admission.operational_request_id = target_request_id;
        IF matching_attempt_count <> 1 OR matching_audit_count <> 1 THEN
            RAISE EXCEPTION 'production admission evidence incomplete'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_production_context_empty_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_production_context_empty_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.campaign_operations_production_transition_context) THEN
        RAISE EXCEPTION
          'production transition context must be empty at transaction end'
          USING ERRCODE = '23514',
                CONSTRAINT =
                  'campaign_operations_production_context_empty_v1';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_reconciliation_cursor_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_reconciliation_cursor_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    cursor_id bigint;
    cursor_row campaign_operations_reconciliation_cursor_event%ROWTYPE;
    observation_count bigint;
    distinct_request_count bigint;
    minimum_request_id bigint;
    maximum_request_id bigint;
    mismatched_run_count bigint;
    out_of_bounds_count bigint;
BEGIN
    cursor_id := CASE
        WHEN TG_TABLE_NAME =
             'campaign_operations_reconciliation_cursor_event'
        THEN NEW.reconciliation_cursor_event_id
        ELSE NEW.reconciliation_cursor_event_id
    END;
    SELECT * INTO STRICT cursor_row
    FROM campaign_operations_reconciliation_cursor_event
    WHERE reconciliation_cursor_event_id = cursor_id;
    SELECT count(*), count(DISTINCT operational_request_id),
           min(operational_request_id), max(operational_request_id),
           count(*) FILTER (WHERE run_key <> cursor_row.run_key),
           count(*) FILTER (
               WHERE operational_request_id <= cursor_row.prior_target_id OR
                     operational_request_id > cursor_row.last_target_id)
      INTO observation_count, distinct_request_count,
           minimum_request_id, maximum_request_id,
           mismatched_run_count, out_of_bounds_count
    FROM campaign_operations_reconciliation_observation
    WHERE reconciliation_cursor_event_id = cursor_id;

    IF observation_count <> cursor_row.selected_count OR
       distinct_request_count <> observation_count OR
       mismatched_run_count <> 0 OR out_of_bounds_count <> 0 OR
       (observation_count = 0 AND
            cursor_row.last_target_id <> cursor_row.prior_target_id) OR
       (observation_count > 0 AND
            (minimum_request_id <= cursor_row.prior_target_id OR
             maximum_request_id <> cursor_row.last_target_id)) THEN
        RAISE EXCEPTION
            'campaign operations reconciliation cursor batch incomplete'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                    'campaign_operations_reconciliation_cursor_complete';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.request_state <> 'ready' OR NEW.state_version <> 1 OR
       NEW.lease_token_hash IS NOT NULL OR
       NEW.lease_expires_at IS NOT NULL OR
       NEW.dispatcher_identity IS NOT NULL OR
       NEW.production_dispatch_enabled THEN
        RAISE EXCEPTION
            'campaign operations request must begin undispatched and ready'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_request_initial_state_check';
    END IF;

    PERFORM 1
    FROM campaign_operations_reservation reservation
    JOIN campaign_operations_authorization_event authz
      ON authz.authorization_event_id =
             reservation.authorization_event_id
    LEFT JOIN campaign_operations_governance_provenance_event provenance
      ON provenance.governance_provenance_event_id =
             authz.governance_provenance_event_id
    WHERE reservation.reservation_id = NEW.reservation_id
      AND reservation.operational_campaign_id =
              NEW.operational_campaign_id
      AND reservation.campaign_identity_canonical =
              NEW.campaign_identity_canonical
      AND reservation.logical_operation_canonical =
              NEW.logical_operation_canonical
      AND reservation.logical_operation_hash =
              NEW.logical_operation_hash
      AND reservation.authorization_event_id =
              NEW.authorization_event_id
      AND reservation.authorization_identity_canonical =
              NEW.authorization_identity_canonical
      AND reservation.authorization_identity_hash =
              NEW.authorization_identity_hash
      AND authz.operational_campaign_id =
              NEW.operational_campaign_id
      AND authz.authorization_identity_canonical =
              NEW.authorization_identity_canonical
      AND authz.authorization_identity_hash =
              NEW.authorization_identity_hash
      AND authz.action_kind = NEW.action_kind
      AND authz.action_contract_version =
              NEW.action_contract_version
      AND authz.scope_kind = reservation.scope_kind
      AND authz.scope_contract_version =
              reservation.scope_contract_version
      AND authz.prerequisite_policy =
              NEW.prerequisite_policy
      AND authz.provenance_identity_canonical IS NOT DISTINCT FROM
              NEW.provenance_identity_canonical
      AND authz.provenance_identity_hash IS NOT DISTINCT FROM
              NEW.provenance_identity_hash
      AND (
          (authz.governance_provenance_event_id IS NULL AND
              provenance.governance_provenance_event_id IS NULL AND
              NEW.provenance_identity_canonical IS NULL AND
              NEW.provenance_identity_hash IS NULL) OR
          (authz.governance_provenance_event_id IS NOT NULL AND
              provenance.governance_provenance_event_id =
                  authz.governance_provenance_event_id AND
              provenance.operational_campaign_id =
                  NEW.operational_campaign_id AND
              provenance.prerequisite_policy =
                  NEW.prerequisite_policy AND
              provenance.provenance_identity_canonical =
                  NEW.provenance_identity_canonical AND
              provenance.provenance_identity_hash =
                  NEW.provenance_identity_hash))
      AND reservation.reservation_identity_canonical =
              NEW.reservation_identity_canonical
      AND reservation.reservation_identity_hash =
              NEW.reservation_identity_hash
      AND reservation.action_kind = NEW.action_kind
      AND reservation.action_contract_version =
              NEW.action_contract_version
      AND reservation.recommendation_campaign_materialization_id =
              NEW.recommendation_campaign_materialization_id
      AND reservation.materialization_contract_version =
              NEW.materialization_contract_version
      AND reservation.materialization_identity_canonical =
              NEW.materialization_identity_canonical
      AND reservation.materialization_identity_hash =
              NEW.materialization_identity_hash
      AND reservation.materialization_member_count =
              NEW.materialization_member_count
      AND reservation.amount = NEW.materialization_member_count
      AND reservation.reservation_state = 'held'
      AND reservation.state_version = 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations request reservation mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_request_reservation_check';
    END IF;
    IF NEW.ordered_scope_digest <> NEW.materialization_identity_hash THEN
        RAISE EXCEPTION 'campaign operations request scope mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_request_scope_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_request_acquisition_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_request_acquisition_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_reservation_event event
    JOIN campaign_operations_reservation reservation
      ON reservation.reservation_id = event.reservation_id
    JOIN campaign_operations_authorization_event authz
      ON authz.authorization_event_id =
             NEW.authorization_event_id
    JOIN campaign_operations_budget_ledger_entry budget
      ON budget.budget_ledger_entry_id =
             reservation.budget_ledger_entry_id
    JOIN campaign_operations_audit_reference_event audit
      ON audit.reservation_event_id = event.reservation_event_id
    WHERE event.reservation_id = NEW.reservation_id
      AND event.operational_request_id = NEW.operational_request_id
      AND event.transition_kind = 'acquired'
      AND event.expected_state IS NULL
      AND event.resulting_state = 'held'
      AND event.expected_version = 0
      AND event.resulting_version = 1
      AND event.request_identity_canonical =
              NEW.request_identity_canonical
      AND reservation.operational_campaign_id =
              NEW.operational_campaign_id
      AND reservation.authorization_event_id =
              NEW.authorization_event_id
      AND reservation.authorization_identity_canonical =
              NEW.authorization_identity_canonical
      AND reservation.authorization_identity_hash =
              NEW.authorization_identity_hash
      AND reservation.reservation_identity_canonical =
              NEW.reservation_identity_canonical
      AND reservation.reservation_identity_hash =
              NEW.reservation_identity_hash
      AND authz.operational_campaign_id =
              NEW.operational_campaign_id
      AND authz.authorization_identity_canonical =
              NEW.authorization_identity_canonical
      AND authz.authorization_identity_hash =
              NEW.authorization_identity_hash
      AND budget.operational_campaign_id =
              NEW.operational_campaign_id
      AND budget.budget_ledger_entry_id =
              reservation.budget_ledger_entry_id
      AND budget.ledger_version = reservation.budget_ledger_version
      AND budget.budget_identity_canonical =
              reservation.budget_identity_canonical
      AND budget.budget_identity_hash =
              reservation.budget_identity_hash
      AND audit.cause_kind = 'reservation_request_accepted'
      AND audit.operational_campaign_id = NEW.operational_campaign_id
      AND audit.authorization_event_id = NEW.authorization_event_id
      AND audit.budget_ledger_entry_id =
              reservation.budget_ledger_entry_id
      AND audit.reservation_id = NEW.reservation_id
      AND audit.reservation_event_id = event.reservation_event_id
      AND audit.operational_request_id = NEW.operational_request_id
      AND audit.actor_identity = NEW.accepting_actor_identity
      AND audit.capability = 'campaign_operations_request_acceptor'
      AND audit.reason = NEW.reason
      AND audit.prior_version IS NULL
      AND audit.resulting_version = NEW.state_version
      AND audit.outcome = 'recorded'
      AND audit.replay_disposition = 'recorded';
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'campaign operations request acquisition evidence incomplete'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_request_acquisition_check';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_reservation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_reservation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    current_budget_id bigint;
    current_budget_total bigint;
    committed_units bigint;
    held_units bigint;
BEGIN
    IF NEW.reservation_state <> 'held' OR NEW.state_version <> 1 THEN
        RAISE EXCEPTION
            'campaign operations reservation must begin held at version one'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_initial_state_check';
    END IF;
    IF NEW.expires_at IS NOT NULL AND
       NEW.expires_at <= transaction_timestamp() THEN
        RAISE EXCEPTION
            'campaign operations reservation expiry must be in the future'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_expiry_check';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(
        NEW.campaign_identity_canonical ||
        ';action=' || NEW.action_kind ||
        ';scope=' || NEW.scope_kind, 1179402835030003));
    PERFORM pg_advisory_xact_lock(hashtextextended(
        NEW.campaign_identity_canonical, 1179402835030004));

    PERFORM 1
    FROM campaign_operations_campaign campaign
    WHERE campaign.operational_campaign_id = NEW.operational_campaign_id
      AND campaign.campaign_identity_canonical =
              NEW.campaign_identity_canonical
      AND campaign.action_kind = NEW.action_kind
      AND campaign.action_contract_version = NEW.action_contract_version
      AND campaign.scope_kind = NEW.scope_kind
      AND campaign.scope_contract_version = NEW.scope_contract_version
      AND campaign.recommendation_campaign_materialization_id =
              NEW.recommendation_campaign_materialization_id
      AND campaign.materialization_contract_version =
              NEW.materialization_contract_version
      AND campaign.materialization_identity_canonical =
              NEW.materialization_identity_canonical
      AND campaign.materialization_identity_hash =
              NEW.materialization_identity_hash
      AND campaign.materialization_member_count =
              NEW.materialization_member_count
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations reservation campaign mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_campaign_check';
    END IF;

    PERFORM 1
    FROM campaign_operations_authorization_event authz
    WHERE authz.authorization_event_id = NEW.authorization_event_id
      AND authz.operational_campaign_id =
              NEW.operational_campaign_id
      AND authz.authorization_identity_canonical =
              NEW.authorization_identity_canonical
      AND authz.authorization_identity_hash =
              NEW.authorization_identity_hash
      AND authz.event_kind = 'granted'
      AND authz.action_kind = NEW.action_kind
      AND authz.action_contract_version =
              NEW.action_contract_version
      AND authz.scope_kind = NEW.scope_kind
      AND authz.scope_contract_version =
              NEW.scope_contract_version
      AND transaction_timestamp() >= authz.not_before
      AND (authz.expires_at IS NULL OR
           transaction_timestamp() < authz.expires_at)
      AND NOT EXISTS (
          SELECT 1
          FROM campaign_operations_authorization_event successor
          WHERE successor.operational_campaign_id =
                    authz.operational_campaign_id
            AND successor.action_kind = authz.action_kind
            AND successor.action_contract_version =
                    authz.action_contract_version
            AND successor.scope_kind = authz.scope_kind
            AND successor.scope_contract_version =
                    authz.scope_contract_version
            AND successor.chain_version > authz.chain_version);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations reservation authorization denied'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_authorization_check';
    END IF;

    SELECT budget_ledger_entry_id, resulting_total
    INTO current_budget_id, current_budget_total
    FROM campaign_operations_budget_ledger_entry
    WHERE operational_campaign_id = NEW.operational_campaign_id
    ORDER BY ledger_version DESC
    LIMIT 1
    FOR UPDATE;
    IF current_budget_id IS NULL OR
       current_budget_id <> NEW.budget_ledger_entry_id OR
       NOT EXISTS (
           SELECT 1
           FROM campaign_operations_budget_ledger_entry budget
           WHERE budget.budget_ledger_entry_id = current_budget_id
             AND budget.ledger_version = NEW.budget_ledger_version
             AND budget.budget_identity_canonical =
                    NEW.budget_identity_canonical
             AND budget.budget_identity_hash =
                    NEW.budget_identity_hash
             AND budget.ledger_status = 'active') THEN
        RAISE EXCEPTION 'campaign operations reservation budget inactive'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_budget_check';
    END IF;

    SELECT
        coalesce(sum(amount) FILTER (
            WHERE reservation_state = 'committed'), 0),
        coalesce(sum(amount) FILTER (
            WHERE reservation_state IN (
                'held', 'reconciliation_required')), 0)
    INTO committed_units, held_units
    FROM campaign_operations_reservation
    WHERE operational_campaign_id = NEW.operational_campaign_id;
    IF NEW.amount > current_budget_total - committed_units - held_units THEN
        RAISE EXCEPTION 'insufficient materialized member dispatch units'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_available_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_reservation_acquisition_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_reservation_acquisition_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_operational_request request
    JOIN campaign_operations_reservation_event event
      ON event.operational_request_id = request.operational_request_id
     AND event.reservation_id = request.reservation_id
    WHERE request.reservation_id = NEW.reservation_id
      AND request.logical_operation_canonical =
              NEW.logical_operation_canonical
      AND event.transition_kind = 'acquired'
      AND event.resulting_state = 'held'
      AND event.resulting_version = 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'campaign operations reservation acquisition evidence incomplete'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_acquisition_check';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_campaign_operations_reservation_commitment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_reservation_commitment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_reservation reservation
    JOIN campaign_operations_operational_request request
      ON request.reservation_id = reservation.reservation_id
    WHERE reservation.reservation_id = NEW.reservation_id
      AND reservation.reservation_identity_canonical =
          NEW.reservation_identity_canonical
      AND reservation.reservation_state = 'committed'
      AND reservation.state_version =
          NEW.resulting_reservation_version
      AND reservation.amount = NEW.amount
      AND request.operational_request_id = NEW.operational_request_id
      AND request.request_identity_canonical =
          NEW.request_identity_canonical
      AND request.request_state = 'bound'
      AND NEW.resulting_reservation_version =
          NEW.expected_reservation_version + 1
      AND (SELECT count(*)
           FROM campaign_operations_request_binding binding
           WHERE binding.operational_request_id =
                 NEW.operational_request_id) =
          request.materialization_member_count;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations commitment mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_commitment_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_operations_reservation_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_operations_reservation_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_reservation reservation
    JOIN campaign_operations_operational_request request
      ON request.operational_request_id = NEW.operational_request_id
    WHERE reservation.reservation_id = NEW.reservation_id
      AND reservation.reservation_identity_canonical =
              NEW.reservation_identity_canonical
      AND request.reservation_id = reservation.reservation_id
      AND request.request_identity_canonical =
              NEW.request_identity_canonical
      AND reservation.amount = NEW.amount
      AND reservation.reservation_state = NEW.resulting_state
      AND reservation.state_version = NEW.resulting_version;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations reservation event mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'campaign_operations_reservation_event_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_campaign_ops_enablement_audit_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_campaign_ops_enablement_audit_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE target_event_id bigint;
BEGIN
    target_event_id := CASE TG_TABLE_NAME
        WHEN 'campaign_operations_production_enablement_event' THEN
            NEW.production_enablement_event_id
        ELSE NEW.production_enablement_event_id END;
    IF NOT EXISTS (
        SELECT 1
        FROM public.campaign_operations_production_enablement_event event
        JOIN public.campaign_operations_production_enablement_audit_reference_event audit
          ON audit.production_enablement_event_id =
             event.production_enablement_event_id
         AND audit.operation_key = event.operation_key
         AND audit.event_kind = event.event_kind
         AND audit.actor_identity = event.actor_identity
         AND audit.capability = event.capability
         AND audit.reason = event.reason
        WHERE event.production_enablement_event_id = target_event_id) THEN
        RAISE EXCEPTION 'production enablement audit incomplete'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: enforce_economic_calendar_snapshot_content_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_economic_calendar_snapshot_content_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_state text;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'economic calendar snapshot content is immutable';
    END IF;
    SELECT snapshot_state INTO parent_state
      FROM economic_calendar_snapshot
     WHERE economic_calendar_snapshot_id =
           NEW.economic_calendar_snapshot_id
     -- FOR SHARE conflicts with the non-key UPDATE used to finalize the
     -- parent.  It therefore prevents a child INSERT that has observed the
     -- 'creating' state from committing after finalization.
     FOR SHARE;
    IF parent_state IS DISTINCT FROM 'creating' THEN
        RAISE EXCEPTION
            'economic calendar snapshot content requires creating snapshot';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_economic_calendar_snapshot_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_economic_calendar_snapshot_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'economic calendar snapshots are immutable';
    END IF;
    IF OLD.snapshot_state = 'creating' AND NEW.snapshot_state = 'finalized' AND
       NEW.economic_calendar_snapshot_id = OLD.economic_calendar_snapshot_id AND
       NEW.created_at = OLD.created_at AND
       NEW.hash_contract_version = OLD.hash_contract_version AND
       NEW.content_hash = OLD.content_hash AND
       NEW.created_by = OLD.created_by AND
       NEW.creation_note IS NOT DISTINCT FROM OLD.creation_note
    THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'economic calendar snapshots are immutable after creation';
END;
$$;


--
-- Name: enforce_experiment_economic_calendar_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_experiment_economic_calendar_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    persisted_hash text;
    persisted_state text;
BEGIN
    IF TG_OP = 'UPDATE' AND
       (OLD.economic_calendar_snapshot_id IS NOT NULL OR
        OLD.economic_calendar_snapshot_hash IS NOT NULL) AND
       (NEW.economic_calendar_snapshot_id IS DISTINCT FROM
            OLD.economic_calendar_snapshot_id OR
        NEW.economic_calendar_snapshot_hash IS DISTINCT FROM
            OLD.economic_calendar_snapshot_hash)
    THEN
        RAISE EXCEPTION
            'experiment economic calendar snapshot binding is immutable';
    END IF;
    IF TG_OP = 'UPDATE' AND
       OLD.economic_calendar_snapshot_id IS NULL AND
       NEW.economic_calendar_snapshot_id IS NOT NULL AND
       (OLD.status <> 'pending' OR OLD.phase <> 'train' OR
        OLD.started_at IS NOT NULL OR OLD.last_model_id IS NOT NULL OR
        EXISTS (SELECT 1 FROM model
                 WHERE experiment_id = OLD.experiment_id))
    THEN
        RAISE EXCEPTION
            'scientifically active experiment cannot acquire a snapshot';
    END IF;
    IF NEW.economic_calendar_snapshot_id IS NOT NULL THEN
        SELECT content_hash, snapshot_state
          INTO persisted_hash, persisted_state
          FROM economic_calendar_snapshot
         WHERE economic_calendar_snapshot_id =
               NEW.economic_calendar_snapshot_id;
        IF NOT FOUND OR persisted_state <> 'finalized' OR
           persisted_hash IS DISTINCT FROM
               NEW.economic_calendar_snapshot_hash
        THEN
            RAISE EXCEPTION
                'experiment economic calendar snapshot identity invalid';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_experiment_model_input_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_experiment_model_input_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND
       (NEW.model_input_width IS NULL OR
        NEW.model_input_semantic_layout_version IS NULL)
    THEN
        RAISE EXCEPTION 'new experiment requires complete model input identity';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF OLD.model_input_width IS DISTINCT FROM NEW.model_input_width OR
           OLD.model_input_semantic_layout_version IS DISTINCT FROM
               NEW.model_input_semantic_layout_version
        THEN
            RAISE EXCEPTION 'experiment model input identity is immutable';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_experiment_recommendation_source_rank(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_experiment_recommendation_source_rank() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF OLD.recommendation_scan_id IS NOT NULL AND
           NEW.recommendation_scan_id IS NULL THEN
            RAISE EXCEPTION 'experiment_recommendation_scan_detachment_invalid'
                USING ERRCODE = '23514';
        END IF;

        IF OLD.source_rank > 0 AND
           (NEW.source_rank IS NULL OR NEW.source_rank <= 0) THEN
            RAISE EXCEPTION 'experiment_recommendation_source_rank_invalid'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.recommendation_scan_id IS NOT NULL AND
       (NEW.source_rank IS NULL OR NEW.source_rank <= 0) THEN
        RAISE EXCEPTION 'experiment_recommendation_source_rank_invalid'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: enforce_follow_up_ratification_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_follow_up_ratification_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_campaign_follow_up_proposal_review_event
        review
    JOIN experiment_recommendation_campaign_follow_up_proposal proposal
      ON proposal.recommendation_campaign_follow_up_proposal_id =
             review.recommendation_campaign_follow_up_proposal_id
    WHERE review.recommendation_campaign_follow_up_proposal_review_event_id =
              NEW.recommendation_campaign_follow_up_proposal_review_event_id
      AND review.review_contract_version = NEW.review_contract_version
      AND review.review_identity_canonical = NEW.review_identity_canonical
      AND review.review_identity_hash = NEW.review_identity_hash
      AND review.review_decision = 'approved'
      AND NEW.review_decision = review.review_decision
      AND review.reviewer_identity = NEW.reviewer_identity
      AND NEW.ratifier_identity <> review.reviewer_identity
      AND review.recommendation_campaign_follow_up_proposal_id =
              NEW.recommendation_campaign_follow_up_proposal_id
      AND review.proposal_contract_version = NEW.proposal_contract_version
      AND review.proposal_identity_canonical =
              NEW.proposal_identity_canonical
      AND review.proposal_identity_hash = NEW.proposal_identity_hash
      AND proposal.proposal_contract_version = NEW.proposal_contract_version
      AND proposal.proposal_identity_canonical =
              NEW.proposal_identity_canonical
      AND proposal.proposal_identity_hash = NEW.proposal_identity_hash;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'follow-up proposal ratification provenance mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'follow_up_ratification_provenance_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_historical_consensus_availability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_historical_consensus_availability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    canonical_family text;
    canonical_release timestamptz;
BEGIN
    IF NEW.candidate_classification <>
        'myfxbook_weekly_claims_pre_release_snapshot' THEN
        RETURN NEW;
    END IF;

    SELECT event_family, event_timestamp_utc
      INTO canonical_family, canonical_release
      FROM economic_event
     WHERE economic_event_id = NEW.economic_event_id;

    IF canonical_family IS DISTINCT FROM 'WEEKLY_CLAIMS' THEN
        RAISE EXCEPTION
            'historical Weekly Claims consensus mapped to non-Weekly-Claims event';
    END IF;
    IF NEW.forecast_available_at >= canonical_release THEN
        RAISE EXCEPTION
            'historical consensus was not archived before canonical release';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_historical_consensus_availability(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_historical_consensus_availability() IS 'Fails closed unless a Phase-8 Weekly Claims snapshot was archived strictly before the canonical release.';


--
-- Name: enforce_model_economic_calendar_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_model_economic_calendar_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    experiment_snapshot_id bigint;
    experiment_snapshot_hash text;
BEGIN
    IF TG_OP = 'UPDATE' AND
       (OLD.economic_calendar_snapshot_id IS NOT NULL OR
        OLD.economic_calendar_snapshot_hash IS NOT NULL) AND
       (NEW.economic_calendar_snapshot_id IS DISTINCT FROM
            OLD.economic_calendar_snapshot_id OR
        NEW.economic_calendar_snapshot_hash IS DISTINCT FROM
            OLD.economic_calendar_snapshot_hash)
    THEN
        RAISE EXCEPTION 'model economic calendar snapshot identity is immutable';
    END IF;
    IF NEW.experiment_id IS NOT NULL THEN
        SELECT economic_calendar_snapshot_id,
               economic_calendar_snapshot_hash
          INTO experiment_snapshot_id, experiment_snapshot_hash
          FROM experiment WHERE experiment_id = NEW.experiment_id
          -- Serialize model inheritance with a concurrent first binding of an
          -- otherwise untouched legacy experiment.
          FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'model references missing experiment';
        END IF;
        IF NEW.economic_calendar_snapshot_id IS NULL AND
           NEW.economic_calendar_snapshot_hash IS NULL
        THEN
            NEW.economic_calendar_snapshot_id := experiment_snapshot_id;
            NEW.economic_calendar_snapshot_hash := experiment_snapshot_hash;
        ELSIF NEW.economic_calendar_snapshot_id IS DISTINCT FROM
                  experiment_snapshot_id OR
              NEW.economic_calendar_snapshot_hash IS DISTINCT FROM
                  experiment_snapshot_hash
        THEN
            RAISE EXCEPTION
                'model and experiment economic calendar snapshot mismatch';
        END IF;
    ELSIF NEW.economic_calendar_snapshot_id IS NOT NULL THEN
        RAISE EXCEPTION
            'unlinked model cannot carry economic calendar snapshot identity';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_model_experiment_lineage_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_model_experiment_lineage_immutable() RETURNS trigger
    LANGUAGE plpgsql
