--
-- Name: enforce_recommendation_campaign_materialization_manifest_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_recommendation_campaign_materialization_manifest_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_campaign_approval approval
    WHERE approval.recommendation_campaign_approval_id =
              NEW.recommendation_campaign_approval_id
      AND approval.decision = 'approved'
      AND NEW.approval_decision = approval.decision
      AND NEW.approval_identity_canonical =
              approval.approval_identity_canonical
      AND NEW.approval_identity_hash = approval.approval_identity_hash
      AND NEW.recommendation_ranking_snapshot_id =
              approval.recommendation_ranking_snapshot_id
      AND NEW.ranking_snapshot_identity_canonical =
              approval.ranking_snapshot_identity_canonical
      AND NEW.ranking_snapshot_identity_hash =
              approval.ranking_snapshot_identity_hash
      AND NEW.planning_policy_canonical = approval.planning_policy_canonical
      AND NEW.planning_policy_hash = approval.planning_policy_hash
      AND NEW.planning_scope_canonical = approval.planning_scope_canonical
      AND NEW.campaign_plan_identity_canonical =
              approval.campaign_plan_identity_canonical
      AND NEW.campaign_plan_identity_hash =
              approval.campaign_plan_identity_hash
      AND NEW.campaign_review_identity_canonical =
              approval.campaign_review_identity_canonical
      AND NEW.campaign_review_identity_hash =
              approval.campaign_review_identity_hash
      AND NEW.approval_reviewer_identity = approval.reviewer_identity
      AND NEW.approval_reason_text = approval.reason_text
      AND NEW.selected_member_count = approval.selected_count;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign materialization approval provenance mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'recommendation_campaign_materialization_authority_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_campaign_materialization_member_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_recommendation_campaign_materialization_member_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_campaign_materialization materialization
    JOIN experiment_recommendation_ranking_member ranking_member
      ON ranking_member.recommendation_ranking_member_id =
             NEW.recommendation_ranking_member_id
     AND ranking_member.recommendation_ranking_snapshot_id =
             materialization.recommendation_ranking_snapshot_id
     AND ranking_member.recommendation_id = NEW.recommendation_id
     AND ranking_member.source_experiment_id = NEW.source_experiment_id
     AND ranking_member.global_ordinal = NEW.ranking_position
    JOIN experiment_recommendation_conversion_proposal proposal
      ON proposal.recommendation_conversion_proposal_id =
             NEW.recommendation_conversion_proposal_id
     AND proposal.recommendation_id = NEW.recommendation_id
     AND proposal.source_experiment_id = NEW.source_experiment_id
     AND proposal.conversion_identity_canonical =
             NEW.proposal_identity_canonical
     AND proposal.conversion_identity_hash = NEW.proposal_identity_hash
    WHERE materialization.recommendation_campaign_materialization_id =
              NEW.recommendation_campaign_materialization_id
      AND NEW.member_ordinal <= materialization.selected_member_count;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign materialization member provenance mismatch'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'recommendation_campaign_materialization_member_authority_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_evaluation_result_semantics_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_recommendation_evaluation_result_semantics_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_run experiment_recommendation_evaluation_run%ROWTYPE;
BEGIN
    SELECT * INTO parent_run
    FROM experiment_recommendation_evaluation_run
    WHERE recommendation_evaluation_run_id =
          NEW.recommendation_evaluation_run_id
    FOR SHARE;
    IF NOT FOUND OR NOT recommendation_evaluation_result_semantics_valid_v1(
            NEW, parent_run) THEN
        RAISE EXCEPTION 'evaluation result semantic provenance differs from run'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_evaluation_result_run_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_evaluation_run_semantics_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_recommendation_evaluation_run_semantics_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND
       (OLD.evaluation_policy_canonical, OLD.evaluation_policy_hash,
        OLD.evaluation_version, OLD.evaluator_version,
        OLD.scoring_policy_canonical, OLD.scoring_policy_hash,
        OLD.scoring_version, OLD.evaluation_run_identity_canonical,
        OLD.evaluation_run_identity_hash, OLD.evidence_snapshot_canonical,
        OLD.evidence_snapshot_hash) IS NOT DISTINCT FROM
       (NEW.evaluation_policy_canonical, NEW.evaluation_policy_hash,
        NEW.evaluation_version, NEW.evaluator_version,
        NEW.scoring_policy_canonical, NEW.scoring_policy_hash,
        NEW.scoring_version, NEW.evaluation_run_identity_canonical,
        NEW.evaluation_run_identity_hash, NEW.evidence_snapshot_canonical,
        NEW.evidence_snapshot_hash) THEN
        RETURN NEW;
    END IF;
    IF NOT recommendation_evaluation_run_semantics_valid_v1(NEW)
       OR NEW.evaluation_run_identity_hash <>
          recommendation_semantic_tagged_fnv1a64(
              NEW.evaluation_run_identity_canonical)
       OR NEW.evidence_snapshot_hash <>
          recommendation_semantic_tagged_fnv1a64(
              NEW.evidence_snapshot_canonical) THEN
        RAISE EXCEPTION 'invalid evaluation run semantic provenance'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_evaluation_run_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_member_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_recommendation_ranking_member_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_ranking_snapshot snapshot
    JOIN experiment_recommendation_evaluation_result evaluation
      ON evaluation.recommendation_evaluation_result_id =
         NEW.recommendation_evaluation_result_id
    JOIN experiment_recommendation recommendation
      ON recommendation.recommendation_id = evaluation.recommendation_id
    WHERE snapshot.recommendation_ranking_snapshot_id =
          NEW.recommendation_ranking_snapshot_id
      AND (
          snapshot.status = 'running'
          OR (snapshot.status = 'completed' AND EXISTS (
              SELECT 1
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
                AND existing.recommendation_evaluation_result_id =
                    NEW.recommendation_evaluation_result_id
          ))
      )
      AND evaluation.recommendation_id = NEW.recommendation_id
      AND evaluation.recommendation_semantic_hash =
          NEW.recommendation_semantic_hash
      AND evaluation.evaluation_identity_hash = NEW.evaluation_identity_hash
      AND evaluation.final_score IS NOT DISTINCT FROM NEW.final_score
      AND evaluation.disposition = NEW.disposition
      AND evaluation.recommendation_scan_id = NEW.recommendation_scan_id
      AND evaluation.source_experiment_id = NEW.source_experiment_id
      AND evaluation.source_model_id IS NOT DISTINCT FROM NEW.source_model_id
      AND evaluation.source_analysis_id IS NOT DISTINCT FROM NEW.source_analysis_id
      AND (
          (snapshot.scope_type = 'evaluation_run'
              AND evaluation.recommendation_evaluation_run_id =
                  snapshot.evaluation_run_filter)
          OR (snapshot.scope_type = 'recommendation_scan'
              AND evaluation.recommendation_scan_id =
                  snapshot.recommendation_scan_filter)
          OR (snapshot.scope_type = 'symbol'
              AND recommendation.source_symbol = snapshot.symbol_filter)
          OR (snapshot.scope_type = 'horizon'
              AND recommendation.source_prediction_horizon =
                  snapshot.horizon_filter)
          OR (snapshot.scope_type = 'family'
              AND recommendation.changed_parameter = snapshot.family_filter)
          OR (snapshot.scope_type = 'symbol_horizon'
              AND recommendation.source_symbol = snapshot.symbol_filter
              AND recommendation.source_prediction_horizon =
                  snapshot.horizon_filter)
          OR snapshot.scope_type = 'global'
      )
      AND recommendation_ranking_membership_contains(
          snapshot.source_membership_canonical,
          evaluation.evaluation_identity_canonical,
          evaluation.recommendation_evaluation_result_id)
      AND (
          EXISTS (
              SELECT 1
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
                AND existing.recommendation_evaluation_result_id =
                    NEW.recommendation_evaluation_result_id
          )
          OR (
              SELECT count(*)
              FROM experiment_recommendation_ranking_member existing
              WHERE existing.recommendation_ranking_snapshot_id =
                    NEW.recommendation_ranking_snapshot_id
          ) < snapshot.requested_limit
      )
      AND NEW.bucket_rank <= snapshot.requested_limit
      AND NEW.global_ordinal <= snapshot.requested_limit
      AND recommendation.source_symbol = NEW.symbol
      AND recommendation.source_prediction_horizon = NEW.horizon
      AND recommendation.changed_parameter = NEW.family
      AND recommendation.source_value_canonical = NEW.source_value_canonical
      AND recommendation.proposed_value_canonical = NEW.proposed_value_canonical
      AND NEW.tie_break_semantic_hash = NEW.recommendation_semantic_hash
      AND NEW.tie_break_evaluation_hash = NEW.evaluation_identity_hash
      AND recommendation_ranking_tie_break_matches(
          NEW.tie_break_primary,
          evaluation.disposition,
          evaluation.final_score)
      AND NEW.inclusion_reason = CASE NEW.bucket
          WHEN 'advisory_ready' THEN 'included_advisory_ready'
          ELSE 'included_for_advisory_inspection'
      END
      AND NEW.block_reason IS NOT DISTINCT FROM CASE NEW.bucket
          WHEN 'advisory_ready' THEN NULL::text
          ELSE evaluation.reason_code
      END
      AND NEW.top_positive_component IS NOT DISTINCT FROM (
          SELECT component.component_name
          FROM experiment_recommendation_evaluation_component component
          WHERE component.recommendation_evaluation_result_id =
                evaluation.recommendation_evaluation_result_id
            AND NOT component.is_penalty
          ORDER BY component.weighted_contribution DESC,
                   component.component_name ASC
          LIMIT 1
      )
      AND NEW.top_penalty_component IS NOT DISTINCT FROM (
          SELECT component.component_name
          FROM experiment_recommendation_evaluation_component component
          WHERE component.recommendation_evaluation_result_id =
                evaluation.recommendation_evaluation_result_id
            AND component.is_penalty
          ORDER BY component.weighted_contribution DESC,
                   component.component_name ASC
          LIMIT 1
      )
    FOR UPDATE OF snapshot;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'invalid or terminal recommendation ranking membership'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_member_authority_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_member_semantics_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_recommendation_ranking_member_semantics_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM experiment_recommendation_ranking_snapshot snapshot
    JOIN experiment_recommendation_evaluation_result evaluation
      ON evaluation.recommendation_evaluation_result_id =
         NEW.recommendation_evaluation_result_id
    JOIN experiment_recommendation_evaluation_run run
      ON run.recommendation_evaluation_run_id =
         evaluation.recommendation_evaluation_run_id
    WHERE snapshot.recommendation_ranking_snapshot_id =
          NEW.recommendation_ranking_snapshot_id
      AND snapshot.population_semantic_state = 'verified_homogeneous'
      AND recommendation_evaluation_result_semantics_valid_v1(evaluation, run)
      AND snapshot.scoring_semantic_canonical =
          recommendation_scoring_semantic_canonical_v1(
              run.scoring_policy_canonical, run.scoring_version)
      AND snapshot.scoring_semantic_hash =
          recommendation_semantic_tagged_fnv1a64(
              snapshot.scoring_semantic_canonical)
      AND snapshot.evaluation_semantic_canonical =
          recommendation_evaluation_semantic_canonical_v1(
              run.evaluation_version, run.evaluator_version,
              run.scoring_policy_canonical, run.scoring_version)
      AND snapshot.evaluation_semantic_hash =
          recommendation_semantic_tagged_fnv1a64(
              snapshot.evaluation_semantic_canonical);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ranking member semantic identity differs from snapshot'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_member_semantics_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_snapshot_semantics_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_recommendation_ranking_snapshot_semantics_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    declared_count integer;
    resolved_count integer;
    invalid_count integer;
    scoring_count integer;
    evaluation_count integer;
    expected_identity text;
BEGIN
    IF TG_OP = 'UPDATE' AND
       (OLD.ranking_snapshot_identity_version, OLD.population_semantic_state,
        OLD.scoring_semantic_canonical, OLD.scoring_semantic_hash,
        OLD.scoring_semantic_version, OLD.evaluation_semantic_canonical,
        OLD.evaluation_semantic_hash, OLD.evaluation_semantic_version,
        OLD.distinct_scoring_semantic_count,
        OLD.distinct_evaluation_semantic_count,
        OLD.homogeneity_validation_result) IS NOT DISTINCT FROM
       (NEW.ranking_snapshot_identity_version, NEW.population_semantic_state,
        NEW.scoring_semantic_canonical, NEW.scoring_semantic_hash,
        NEW.scoring_semantic_version, NEW.evaluation_semantic_canonical,
        NEW.evaluation_semantic_hash, NEW.evaluation_semantic_version,
        NEW.distinct_scoring_semantic_count,
        NEW.distinct_evaluation_semantic_count,
        NEW.homogeneity_validation_result) THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'ranking snapshot semantic identity is immutable'
            USING ERRCODE = '55000';
    END IF;
    IF NEW.ranking_snapshot_identity_version <> 2 OR
       NEW.ranking_policy_hash <>
           recommendation_semantic_tagged_fnv1a64(NEW.ranking_policy_canonical) OR
       NEW.scope_hash <>
           recommendation_semantic_tagged_fnv1a64(NEW.scope_canonical) OR
       NEW.source_membership_hash <>
           recommendation_semantic_tagged_fnv1a64(
               NEW.source_membership_canonical) THEN
        RAISE EXCEPTION 'invalid Phase 3B ranking snapshot provenance'
            USING ERRCODE = '23514';
    END IF;
    declared_count := recommendation_ranking_membership_count_v1(
        NEW.source_membership_canonical);
    IF NEW.population_semantic_state = 'empty' THEN
        IF declared_count IS DISTINCT FROM 0 OR
           NEW.homogeneity_validation_result <> 'empty_population' THEN
            RAISE EXCEPTION 'invalid empty ranking semantic state'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.population_semantic_state = 'verified_homogeneous' THEN
        IF declared_count IS NULL OR declared_count <= 0 OR
           NEW.scoring_semantic_hash <>
               recommendation_semantic_tagged_fnv1a64(
                   NEW.scoring_semantic_canonical) OR
           NEW.evaluation_semantic_hash <>
               recommendation_semantic_tagged_fnv1a64(
                   NEW.evaluation_semantic_canonical) THEN
            RAISE EXCEPTION 'invalid homogeneous ranking semantic identity'
                USING ERRCODE = '23514';
        END IF;
        SELECT count(*)::integer,
               count(*) FILTER (WHERE NOT
                   recommendation_evaluation_result_semantics_valid_v1(
                       evaluation, run))::integer,
               count(DISTINCT recommendation_scoring_semantic_canonical_v1(
                   run.scoring_policy_canonical, run.scoring_version))::integer,
               count(DISTINCT recommendation_evaluation_semantic_canonical_v1(
                   run.evaluation_version, run.evaluator_version,
                   run.scoring_policy_canonical, run.scoring_version))::integer
          INTO resolved_count, invalid_count, scoring_count, evaluation_count
        FROM experiment_recommendation_evaluation_result evaluation
        JOIN experiment_recommendation_evaluation_run run
          ON run.recommendation_evaluation_run_id =
             evaluation.recommendation_evaluation_run_id
        WHERE recommendation_ranking_membership_contains(
            NEW.source_membership_canonical,
            evaluation.evaluation_identity_canonical,
            evaluation.recommendation_evaluation_result_id)
          AND recommendation_scoring_semantic_canonical_v1(
              run.scoring_policy_canonical, run.scoring_version) =
              NEW.scoring_semantic_canonical
          AND recommendation_evaluation_semantic_canonical_v1(
              run.evaluation_version, run.evaluator_version,
              run.scoring_policy_canonical, run.scoring_version) =
              NEW.evaluation_semantic_canonical;
        IF resolved_count <> declared_count OR invalid_count <> 0 OR
           scoring_count <> 1 OR evaluation_count <> 1 THEN
            RAISE EXCEPTION 'ranking population is not verified homogeneous'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'new ranking snapshot semantic state is not admissible'
            USING ERRCODE = '23514';
    END IF;
    expected_identity :=
        'experiment_recommendation_ranking_snapshot_identity_v2;policy=' ||
        octet_length(NEW.ranking_policy_canonical) || ':' ||
        NEW.ranking_policy_canonical || ';scope=' ||
        octet_length(NEW.scope_canonical) || ':' || NEW.scope_canonical ||
        ';limit=' || NEW.requested_limit || ';population_state=' ||
        NEW.population_semantic_state || ';scoring_semantic=' ||
        CASE WHEN NEW.population_semantic_state = 'empty' THEN 'NULL'
             ELSE octet_length(NEW.scoring_semantic_canonical) || ':' ||
                  NEW.scoring_semantic_canonical END ||
        ';evaluation_semantic=' ||
        CASE WHEN NEW.population_semantic_state = 'empty' THEN 'NULL'
             ELSE octet_length(NEW.evaluation_semantic_canonical) || ':' ||
                  NEW.evaluation_semantic_canonical END || ';membership=' ||
        octet_length(NEW.source_membership_canonical) || ':' ||
        NEW.source_membership_canonical;
    IF NEW.ranking_snapshot_identity_canonical <> expected_identity OR
       NEW.ranking_snapshot_identity_hash <>
           recommendation_semantic_tagged_fnv1a64(expected_identity) THEN
        RAISE EXCEPTION 'invalid Phase 3B ranking snapshot identity'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_recommendation_ranking_snapshot_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_recommendation_ranking_snapshot_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    persisted_member_count integer;
    persisted_advisory_ready_count integer;
    persisted_blocked_count integer;
    persisted_non_actionable_count integer;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'running' THEN
            RAISE EXCEPTION 'recommendation ranking snapshot must start running'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'recommendation_ranking_snapshot_initial_status_check';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status <> 'running' OR NEW.status NOT IN ('completed', 'failed') THEN
        RAISE EXCEPTION 'invalid recommendation ranking snapshot transition'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_snapshot_transition_check';
    END IF;

    SELECT count(*)::integer,
           count(*) FILTER (WHERE bucket = 'advisory_ready')::integer,
           count(*) FILTER (WHERE bucket = 'blocked')::integer,
           count(*) FILTER (WHERE bucket = 'non_actionable')::integer
    INTO persisted_member_count,
         persisted_advisory_ready_count,
         persisted_blocked_count,
         persisted_non_actionable_count
    FROM experiment_recommendation_ranking_member
    WHERE recommendation_ranking_snapshot_id =
          OLD.recommendation_ranking_snapshot_id;

    IF (NEW.status = 'completed' AND (
            NEW.member_count <> persisted_member_count
            OR NEW.advisory_ready_count <> persisted_advisory_ready_count
            OR NEW.blocked_count <> persisted_blocked_count
            OR NEW.non_actionable_count <> persisted_non_actionable_count))
       OR (NEW.status = 'failed' AND persisted_member_count <> 0) THEN
        RAISE EXCEPTION 'recommendation ranking snapshot counts do not match members'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'recommendation_ranking_snapshot_member_count_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: expertadvisor_guard_checkpoint_decision_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expertadvisor_guard_checkpoint_decision_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.checkpoint_eval_id IS DISTINCT FROM NEW.checkpoint_eval_id
       OR OLD.parent_experiment_id IS DISTINCT FROM NEW.parent_experiment_id
       OR OLD.checkpoint_epoch IS DISTINCT FROM NEW.checkpoint_epoch
       OR OLD.checkpoint_model_id IS DISTINCT FROM NEW.checkpoint_model_id
       OR OLD.analysis_id IS DISTINCT FROM NEW.analysis_id
       OR OLD.inference_eval_result_id IS DISTINCT FROM NEW.inference_eval_result_id
       OR OLD.policy_revision IS DISTINCT FROM NEW.policy_revision
       OR OLD.policy_hash IS DISTINCT FROM NEW.policy_hash
       OR OLD.evidence_watermark IS DISTINCT FROM NEW.evidence_watermark
       OR OLD.decision IS DISTINCT FROM NEW.decision
       OR OLD.reason IS DISTINCT FROM NEW.reason
       OR OLD.leader_score IS DISTINCT FROM NEW.leader_score
       OR OLD.infer_accuracy IS DISTINCT FROM NEW.infer_accuracy
       OR OLD.rank_value IS DISTINCT FROM NEW.rank_value
       OR OLD.rank_scope IS DISTINCT FROM NEW.rank_scope
       OR OLD.rank_population_watermark IS DISTINCT FROM NEW.rank_population_watermark
       OR OLD.requested_stop_epoch IS DISTINCT FROM NEW.requested_stop_epoch
       OR OLD.created_at IS DISTINCT FROM NEW.created_at
    THEN
        RAISE EXCEPTION 'checkpoint policy decision meaning is immutable'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.identity_status = 'active'
       AND NEW.identity_status NOT IN ('active', 'superseded', 'action_applied')
    THEN
        RAISE EXCEPTION 'invalid checkpoint policy decision lifecycle transition'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.identity_status IN ('legacy', 'superseded', 'action_applied')
       AND NEW IS DISTINCT FROM OLD
    THEN
        RAISE EXCEPTION 'terminal checkpoint policy decision is immutable'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.stop_request_applied AND NOT NEW.stop_request_applied THEN
        RAISE EXCEPTION 'checkpoint policy stop attribution is terminal'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.identity_status = 'action_applied'
       AND NEW.identity_status <> 'action_applied'
    THEN
        RAISE EXCEPTION 'applied checkpoint policy stop is terminal'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: expertadvisor_require_scheduler_protocol_generation_52(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expertadvisor_require_scheduler_protocol_generation_52() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    configured_generation text;
    protocol_ready boolean;
    dispatch_claim boolean;
BEGIN
    dispatch_claim :=
        NEW.status = 'running'
        AND (
            OLD.status IS DISTINCT FROM NEW.status
            OR OLD.phase IS DISTINCT FROM NEW.phase
            OR OLD.active_scheduler_worker_attempt_id
               IS DISTINCT FROM NEW.active_scheduler_worker_attempt_id
        );
    IF NOT dispatch_claim THEN
        RETURN NEW;
    END IF;

    configured_generation :=
        current_setting(
            'expertadvisor.scheduler_protocol_generation',
            true
        );
    SELECT EXISTS (
        SELECT 1
        FROM experiment_scheduler_protocol
        WHERE singleton
          AND required_generation = 52
          AND cutover_state = 'complete'
    )
    INTO protocol_ready;

    IF configured_generation IS DISTINCT FROM '52'
       OR NOT protocol_ready
       OR NEW.active_scheduler_worker_attempt_id IS NULL
    THEN
        RAISE EXCEPTION
            'scheduler protocol generation 52 dispatch barrier rejected claim: configured_generation=%, protocol_ready=%, active_attempt_present=%, old_status=%, new_status=%, old_phase=%, new_phase=%',
            COALESCE(configured_generation, 'NULL'),
            protocol_ready,
            NEW.active_scheduler_worker_attempt_id IS NOT NULL,
            OLD.status,
            NEW.status,
            OLD.phase,
            NEW.phase
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: expertadvisor_validate_checkpoint_active_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expertadvisor_validate_checkpoint_active_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    bound_phase text := NEW.phase;
BEGIN
    IF NEW.active_scheduler_worker_attempt_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE'
       AND OLD.active_scheduler_worker_attempt_id =
           NEW.active_scheduler_worker_attempt_id
    THEN
        bound_phase := OLD.phase;
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM experiment_scheduler_worker_attempt a
        WHERE a.worker_attempt_id =
              NEW.active_scheduler_worker_attempt_id
          AND a.experiment_id =
              COALESCE(NEW.parent_experiment_id, NEW.experiment_id)
          AND a.checkpoint_eval_id = NEW.checkpoint_eval_id
          AND (
              (bound_phase = 'infer'
               AND a.worker_kind = 'checkpoint_infer'
               AND a.lifecycle_phase = 'infer'
               AND a.capacity_class = 'infer')
              OR
              (bound_phase = 'analyze'
               AND a.worker_kind = 'checkpoint_analyze'
               AND a.lifecycle_phase = 'analyze'
               AND a.capacity_class = 'analyze')
          )
          AND a.lifecycle_state IN (
              'reserved', 'spawned', 'running', 'observed',
              'identity_ambiguous'
          )
    ) THEN
        RAISE EXCEPTION
            'checkpoint active worker attempt identity mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: expertadvisor_validate_experiment_active_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expertadvisor_validate_experiment_active_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    bound_phase text := NEW.phase;
BEGIN
    IF NEW.active_scheduler_worker_attempt_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE'
       AND OLD.active_scheduler_worker_attempt_id =
           NEW.active_scheduler_worker_attempt_id
    THEN
        bound_phase := OLD.phase;
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM experiment_scheduler_worker_attempt a
        WHERE a.worker_attempt_id =
              NEW.active_scheduler_worker_attempt_id
          AND a.worker_kind = 'experiment'
          AND a.experiment_id = NEW.experiment_id
          AND a.checkpoint_eval_id IS NULL
          AND a.lifecycle_phase = bound_phase
          AND a.capacity_class = bound_phase
          AND a.lifecycle_state IN (
              'reserved', 'spawned', 'running', 'observed', 'stopped',
              'identity_ambiguous'
          )
    ) THEN
        RAISE EXCEPTION
            'experiment active worker attempt identity mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: expertadvisor_validate_inference_producer_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expertadvisor_validate_inference_producer_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE a experiment_scheduler_worker_attempt%ROWTYPE;
        producer_exists boolean;
        owner_experiment bigint;
        owner_exists boolean;
BEGIN
  IF NEW.producer_worker_attempt_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO a FROM experiment_scheduler_worker_attempt
   WHERE worker_attempt_id=NEW.producer_worker_attempt_id;
  producer_exists := FOUND;
  SELECT experiment_id INTO owner_experiment FROM model WHERE model_id=NEW.model_id;
  owner_exists := FOUND;
  IF NOT producer_exists OR NOT owner_exists OR owner_experiment IS NULL
     OR a.experiment_id IS DISTINCT FROM owner_experiment
     OR a.lifecycle_phase <> 'infer' OR a.capacity_class <> 'infer'
     OR (NEW.inference_scope = 'final' AND
         (a.worker_kind <> 'experiment' OR a.checkpoint_eval_id IS NOT NULL))
     OR (NEW.inference_scope = 'checkpoint' AND
         (a.worker_kind <> 'checkpoint_infer' OR NEW.checkpoint_eval_id IS NULL
          OR a.checkpoint_eval_id IS DISTINCT FROM NEW.checkpoint_eval_id))
     OR NEW.inference_scope NOT IN ('final','checkpoint') THEN
    RAISE EXCEPTION 'invalid inference producer worker attempt';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: expertadvisor_validate_scientific_producer_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expertadvisor_validate_scientific_producer_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE a experiment_scheduler_worker_attempt%ROWTYPE;
BEGIN
  IF NEW.producer_worker_attempt_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO a FROM experiment_scheduler_worker_attempt
   WHERE worker_attempt_id=NEW.producer_worker_attempt_id;
  IF NOT FOUND OR a.experiment_id IS DISTINCT FROM NEW.experiment_id
     OR a.worker_kind <> 'experiment' OR a.lifecycle_phase <> 'train'
     OR a.capacity_class <> 'train' THEN
    RAISE EXCEPTION 'invalid model producer worker attempt';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_campaign_operations_attempt_v1_isolation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_attempt_v1_isolation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF NEW.attempt_contract_version = 1 AND (
       NOT public.campaign_operations_isolated_v1_authority_valid() OR
       NOT EXISTS (
         SELECT 1
         FROM public.campaign_operations_operational_request request
         WHERE request.operational_request_id = NEW.operational_request_id
           AND request.production_dispatch_enabled = false)) THEN
        RAISE EXCEPTION
          'campaign operations Attempt V1 isolated authority required'
          USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_campaign_operations_completed_campaign(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_completed_campaign() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE target_campaign_id bigint;
DECLARE target_campaign_closed boolean;
BEGIN
    CASE TG_TABLE_NAME
    WHEN 'campaign_operations_reservation_event' THEN
        SELECT reservation.operational_campaign_id
          INTO STRICT target_campaign_id
        FROM campaign_operations_reservation reservation
        WHERE reservation.reservation_id = NEW.reservation_id;
    WHEN 'campaign_operations_dispatch_attempt' THEN
        SELECT request.operational_campaign_id INTO STRICT target_campaign_id
        FROM campaign_operations_operational_request request
        WHERE request.operational_request_id =
              NEW.operational_request_id;
    WHEN 'campaign_operations_dispatch_attempt_outcome' THEN
        SELECT request.operational_campaign_id
          INTO STRICT target_campaign_id
        FROM campaign_operations_dispatch_attempt attempt
        JOIN campaign_operations_operational_request request
          ON request.operational_request_id =
             attempt.operational_request_id
        WHERE attempt.dispatch_attempt_id = NEW.dispatch_attempt_id;
    WHEN 'campaign_operations_request_binding' THEN
        SELECT request.operational_campaign_id INTO STRICT target_campaign_id
        FROM campaign_operations_operational_request request
        WHERE request.operational_request_id =
              NEW.operational_request_id;
    WHEN 'campaign_operations_downstream_control_owner' THEN
        SELECT request.operational_campaign_id INTO STRICT target_campaign_id
        FROM campaign_operations_operational_request request
        WHERE request.operational_request_id =
              NEW.operational_request_id;
    WHEN 'campaign_operations_reservation_commitment' THEN
        SELECT reservation.operational_campaign_id
          INTO STRICT target_campaign_id
        FROM campaign_operations_reservation reservation
        WHERE reservation.reservation_id = NEW.reservation_id;
    WHEN 'campaign_operations_cancellation_settlement' THEN
        SELECT cancellation.operational_campaign_id
          INTO STRICT target_campaign_id
        FROM campaign_operations_cancellation_request cancellation
        WHERE cancellation.cancellation_request_id =
              NEW.cancellation_request_id;
    WHEN 'campaign_operations_reconciliation_resolution' THEN
        SELECT observation.operational_campaign_id
          INTO STRICT target_campaign_id
        FROM campaign_operations_reconciliation_observation observation
        WHERE observation.reconciliation_observation_id =
              NEW.reconciliation_observation_id;
    WHEN 'experiment_lifecycle_cancellation_event' THEN
        SELECT cancellation.operational_campaign_id
          INTO STRICT target_campaign_id
        FROM campaign_operations_cancellation_request cancellation
        WHERE cancellation.cancellation_request_id =
              NEW.cancellation_request_id;
    ELSE
        target_campaign_id := NEW.operational_campaign_id;
    END CASE;
    -- Serialize the terminal boundary itself.  A check without this lock can
    -- miss an uncommitted completion and allow a child insert to resume after
    -- the completion commits.  Owning workflows already take this campaign
    -- lock before reservation/request locks; the reconciliation observation
    -- repository follows the same order after Phase G.
    SELECT completion_boundary_closed INTO target_campaign_closed
    FROM campaign_operations_campaign
    WHERE operational_campaign_id = target_campaign_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations completion campaign missing'
            USING ERRCODE = '23503';
    END IF;
    IF target_campaign_closed THEN
        RAISE EXCEPTION
            'campaign operations completed campaign is immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_campaign_operations_completion_boundary_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_completion_boundary_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP = 'TRUNCATE' THEN
        IF EXISTS (
            SELECT 1 FROM campaign_operations_campaign
            WHERE completion_boundary_closed) THEN
            RAISE EXCEPTION
                'campaign operations completion boundary is immutable'
                USING ERRCODE = '55000';
        END IF;
        RETURN NULL;
    END IF;
    IF TG_OP = 'DELETE' THEN
        IF OLD.completion_boundary_closed THEN
            RAISE EXCEPTION
                'campaign operations completion boundary is immutable'
                USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.completion_boundary_closed IS NOT DISTINCT FROM
            NEW.completion_boundary_closed THEN
        RETURN NEW;
    END IF;
    IF OLD.completion_boundary_closed OR
       NOT NEW.completion_boundary_closed OR
       pg_trigger_depth() <> 2 THEN
        RAISE EXCEPTION
            'campaign operations completion boundary is immutable'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_campaign_operations_completion_v2_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_completion_v2_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM public.campaign_operations_operational_request request
        JOIN public.campaign_operations_dispatch_attempt attempt
          ON attempt.operational_request_id = request.operational_request_id
         AND attempt.attempt_contract_version = 2
        LEFT JOIN public.campaign_operations_request_production_admission admission
          ON admission.request_production_admission_id =
             attempt.request_production_admission_id
        LEFT JOIN public.campaign_operations_dispatch_audit_reference_event audit
          ON audit.dispatch_attempt_id = attempt.dispatch_attempt_id
         AND audit.cause_kind = 'dispatch_lease_acquired'
        WHERE request.operational_campaign_id = NEW.operational_campaign_id
          AND (NOT request.production_dispatch_enabled OR
               admission.request_production_admission_id IS NULL OR
               audit.dispatch_audit_reference_event_id IS NULL)) THEN
        RAISE EXCEPTION 'completion V1 nested Attempt V2 evidence incomplete'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_campaign_operations_dispatch_control(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_dispatch_control() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE latest_control text;
BEGIN
    IF NEW.request_state NOT IN ('dispatching', 'bound') OR
       NEW.request_state = OLD.request_state THEN
        RETURN NEW;
    END IF;
    PERFORM 1
    FROM campaign_operations_campaign
    WHERE operational_campaign_id = NEW.operational_campaign_id
    FOR UPDATE;
    SELECT event_kind INTO latest_control
    FROM campaign_operations_control_event
    WHERE operational_campaign_id = NEW.operational_campaign_id
    ORDER BY control_version DESC
    LIMIT 1;
    IF latest_control = 'pause' THEN
        RAISE EXCEPTION 'campaign operations dispatch blocked by pause'
            USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
        SELECT 1 FROM campaign_operations_cancellation_request
        WHERE operational_campaign_id = NEW.operational_campaign_id) THEN
        RAISE EXCEPTION
            'campaign operations dispatch blocked by cancellation'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_campaign_operations_phase5_experiment_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_phase5_experiment_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
    IF current_user = 'campaign_operations_phase5_transactional' AND (
       OLD.status <> 'paused' OR OLD.phase <> 'train' OR
       NEW.status <> 'pending' OR NEW.phase <> 'train' OR
       NEW.updated_at <> transaction_timestamp() OR
       (to_jsonb(NEW) - ARRAY['status','phase','updated_at']) <>
       (to_jsonb(OLD) - ARRAY['status','phase','updated_at']) OR
       NOT EXISTS (
           SELECT 1
           FROM experiment_recommendation_conversion_activation activation
           WHERE activation.experiment_id = NEW.experiment_id
             AND activation.previous_status = 'paused'
             AND activation.previous_phase = 'train'
             AND activation.resulting_status = 'pending'
             AND activation.resulting_phase = 'train'
             AND activation.xmin =
                 pg_current_xact_id()::text::xid)) THEN
        RAISE EXCEPTION
            'Campaign Operations Phase 5 experiment update denied'
            USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_campaign_operations_production_admission_witness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_production_admission_witness() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP = 'TRUNCATE' THEN
        IF EXISTS (SELECT 1 FROM public.campaign_operations_operational_request
                   WHERE production_dispatch_enabled) THEN
            RAISE EXCEPTION 'production admission witness is immutable'
                USING ERRCODE = '55000';
        END IF;
        RETURN NULL;
    END IF;
    IF TG_OP = 'DELETE' THEN
        IF OLD.production_dispatch_enabled THEN
            RAISE EXCEPTION 'production admission witness is immutable'
                USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.production_dispatch_enabled IS NOT DISTINCT FROM
       NEW.production_dispatch_enabled THEN RETURN NEW; END IF;
    IF OLD.production_dispatch_enabled OR
       NOT NEW.production_dispatch_enabled OR
       NOT public.campaign_operations_production_context_valid_v1(
           'dispatch_v2', NEW.operational_request_id,
           NULL) THEN
        RAISE EXCEPTION 'production admission witness is immutable'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_campaign_operations_production_attempt_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_production_attempt_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP = 'TRUNCATE' THEN
        IF EXISTS (
          SELECT 1 FROM public.campaign_operations_dispatch_attempt
          WHERE attempt_contract_version = 2) THEN
            RAISE EXCEPTION
              'Campaign Operations production attempt evidence is immutable'
              USING ERRCODE = '55000';
        END IF;
        RETURN NULL;
    END IF;
    IF OLD.attempt_contract_version = 2 OR
       (TG_OP = 'UPDATE' AND NEW.attempt_contract_version = 2) THEN
        RAISE EXCEPTION
          'Campaign Operations production attempt evidence is immutable'
          USING ERRCODE = '55000';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: guard_campaign_operations_production_dispatch_audit_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_production_dispatch_audit_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE operation_key_value text;
BEGIN
    IF NEW.request_production_admission_id IS NULL THEN RETURN NEW; END IF;
    SELECT attempt.operation_key INTO STRICT operation_key_value
    FROM public.campaign_operations_dispatch_attempt attempt
    WHERE attempt.dispatch_attempt_id = NEW.dispatch_attempt_id
      AND attempt.operational_request_id = NEW.operational_request_id
      AND attempt.request_production_admission_id =
          NEW.request_production_admission_id
      AND attempt.production_enablement_event_id =
          NEW.production_enablement_event_id
      AND attempt.attempt_contract_version = 2;
    IF NOT public.campaign_operations_production_context_valid_v1(
         'dispatch_v2', NEW.operational_request_id, operation_key_value) THEN
        RAISE EXCEPTION
          'fixed production acquisition transition context required'
          USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_campaign_operations_production_dispatch_audit_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_production_dispatch_audit_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    IF TG_OP = 'TRUNCATE' THEN
        IF EXISTS (
          SELECT 1
          FROM public.campaign_operations_dispatch_audit_reference_event
          WHERE request_production_admission_id IS NOT NULL) THEN
            RAISE EXCEPTION
              'Campaign Operations production dispatch audit is immutable'
              USING ERRCODE = '55000';
        END IF;
        RETURN NULL;
    END IF;
    IF OLD.request_production_admission_id IS NOT NULL OR
       (TG_OP = 'UPDATE' AND
        NEW.request_production_admission_id IS NOT NULL) THEN
        RAISE EXCEPTION
          'Campaign Operations production dispatch audit is immutable'
          USING ERRCODE = '55000';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: guard_campaign_operations_production_post_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_campaign_operations_production_post_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE target_request_id bigint;
DECLARE target_campaign_id bigint;
DECLARE boundary_closed boolean;
BEGIN
    target_request_id := CASE TG_TABLE_NAME
        WHEN 'campaign_operations_request_production_admission' THEN
            NEW.operational_request_id
        WHEN 'campaign_operations_dispatch_attempt' THEN
            NEW.operational_request_id
        ELSE NEW.operational_request_id END;
    SELECT request.operational_campaign_id, campaign.completion_boundary_closed
      INTO STRICT target_campaign_id, boundary_closed
    FROM public.campaign_operations_operational_request request
    JOIN public.campaign_operations_campaign campaign
      ON campaign.operational_campaign_id = request.operational_campaign_id
    WHERE request.operational_request_id = target_request_id
    FOR UPDATE OF campaign;
    IF boundary_closed THEN
        RAISE EXCEPTION 'completed campaign rejects production evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: campaign_operations_authorization_event; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_operations_authorization_event (
    authorization_event_id bigint NOT NULL,
    operational_campaign_id bigint NOT NULL,
    campaign_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    previous_event_id bigint,
    previous_event_identity_canonical text COLLATE pg_catalog."C",
    previous_event_identity_hash text COLLATE pg_catalog."C",
    chain_version integer NOT NULL,
    event_kind text NOT NULL COLLATE pg_catalog."C",
    action_kind text NOT NULL COLLATE pg_catalog."C",
    action_contract_version integer NOT NULL,
    scope_kind text NOT NULL COLLATE pg_catalog."C",
    scope_contract_version integer NOT NULL,
    prerequisite_policy text NOT NULL COLLATE pg_catalog."C",
    governance_provenance_event_id bigint,
    provenance_identity_canonical text COLLATE pg_catalog."C",
    provenance_identity_hash text COLLATE pg_catalog."C",
    authorization_role text NOT NULL COLLATE pg_catalog."C",
    actor_identity text NOT NULL COLLATE pg_catalog."C",
    reason text NOT NULL COLLATE pg_catalog."C",
    not_before timestamp with time zone NOT NULL,
    expires_at timestamp with time zone,
    authorization_contract_version integer NOT NULL,
    authorization_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    authorization_identity_hash text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT campaign_operations_authoriz_authorization_contract_versi_check CHECK ((authorization_contract_version = 1)),
    CONSTRAINT campaign_operations_authoriz_authorization_identity_canon_check CHECK (((authorization_identity_canonical <> ''::text) AND (octet_length(authorization_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_authoriza_authorization_identity_hash_check CHECK ((authorization_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_authoriza_campaign_identity_canonical_check CHECK (((campaign_identity_canonical <> ''::text) AND (octet_length(campaign_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_authorization__authorization_event_id_check CHECK ((authorization_event_id > 0)),
    CONSTRAINT campaign_operations_authorization__scope_contract_version_check CHECK ((scope_contract_version = 1)),
    CONSTRAINT campaign_operations_authorization_action_contract_version_check CHECK ((action_contract_version = 1)),
    CONSTRAINT campaign_operations_authorization_eve_prerequisite_policy_check CHECK ((prerequisite_policy = ANY (ARRAY['phase4d_materialization_only_v1'::text, 'phase4d_materialization_plus_exact_phase6d_ratification_v1'::text]))),
    CONSTRAINT campaign_operations_authorization_even_authorization_role_check CHECK ((authorization_role = 'campaign_operations_authorizer'::text)),
    CONSTRAINT campaign_operations_authorization_event_action_kind_check CHECK ((action_kind = ANY (ARRAY['dispatch_full_materialization'::text, 'adopt_existing_pending_and_control'::text]))),
    CONSTRAINT campaign_operations_authorization_event_actor_identity_check CHECK ((actor_identity ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_authorization_event_chain_version_check CHECK ((chain_version > 0)),
    CONSTRAINT campaign_operations_authorization_event_event_kind_check CHECK ((event_kind = ANY (ARRAY['granted'::text, 'revoked'::text, 'expiry_observed'::text]))),
    CONSTRAINT campaign_operations_authorization_event_reason_check CHECK (((reason <> ''::text) AND (octet_length(reason) <= 4096) AND (reason ~ '[^ 	
]'::text) AND (translate(reason, '	
'::text, ''::text) !~ '[[:cntrl:]]'::text))),
    CONSTRAINT campaign_operations_authorization_event_scope_kind_check CHECK ((scope_kind = 'complete_materialization'::text)),
    CONSTRAINT campaign_operations_authorization_initial_kind_check CHECK (((chain_version > 1) OR (event_kind = 'granted'::text))),
    CONSTRAINT campaign_operations_authorization_previous_shape_check CHECK ((((chain_version = 1) AND (previous_event_id IS NULL) AND (previous_event_identity_canonical IS NULL) AND (previous_event_identity_hash IS NULL)) OR ((chain_version > 1) AND (previous_event_id IS NOT NULL) AND (previous_event_identity_canonical IS NOT NULL) AND (previous_event_identity_canonical <> ''::text) AND (previous_event_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)))),
    CONSTRAINT campaign_operations_authorization_provenance_shape_check CHECK ((((governance_provenance_event_id IS NULL) AND (provenance_identity_canonical IS NULL) AND (provenance_identity_hash IS NULL) AND (prerequisite_policy = 'phase4d_materialization_only_v1'::text)) OR ((governance_provenance_event_id IS NOT NULL) AND (provenance_identity_canonical IS NOT NULL) AND (provenance_identity_canonical <> ''::text) AND (provenance_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)))),
    CONSTRAINT campaign_operations_authorization_validity_check CHECK (((expires_at IS NULL) OR (expires_at > not_before)))
);


--
-- Name: TABLE campaign_operations_authorization_event; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.campaign_operations_authorization_event IS 'Immutable serialized operational-authorization chain; persisted kinds are granted, revoked, and expiry_observed only.';


--
-- Name: lock_campaign_operations_authorization_head(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_campaign_operations_authorization_head(target_campaign_id bigint, target_action_kind text) RETURNS public.campaign_operations_authorization_event
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE locked_row campaign_operations_authorization_event%ROWTYPE;
BEGIN
    SELECT * INTO locked_row
    FROM campaign_operations_authorization_event
    WHERE operational_campaign_id = target_campaign_id
      AND action_kind = target_action_kind
      AND action_contract_version = 1
      AND scope_kind = 'complete_materialization'
      AND scope_contract_version = 1
    ORDER BY chain_version DESC LIMIT 1
    FOR UPDATE;
    RETURN locked_row;
END;
$$;


--
-- Name: campaign_operations_budget_ledger_entry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_operations_budget_ledger_entry (
    budget_ledger_entry_id bigint NOT NULL,
    operational_campaign_id bigint NOT NULL,
    campaign_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    previous_entry_id bigint,
    previous_entry_identity_canonical text COLLATE pg_catalog."C",
    previous_entry_identity_hash text COLLATE pg_catalog."C",
    ledger_version integer NOT NULL,
    entry_kind text NOT NULL COLLATE pg_catalog."C",
    ledger_status text NOT NULL COLLATE pg_catalog."C",
    budget_unit text NOT NULL COLLATE pg_catalog."C",
    delta bigint NOT NULL,
    prior_total bigint NOT NULL,
    resulting_total bigint NOT NULL,
    administrator_identity text NOT NULL COLLATE pg_catalog."C",
    reason text NOT NULL COLLATE pg_catalog."C",
    budget_contract_version integer NOT NULL,
    budget_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    budget_identity_hash text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT campaign_operations_budget_arithmetic_check CHECK (((prior_total + delta) = resulting_total)),
    CONSTRAINT campaign_operations_budget_kind_shape_check CHECK ((((entry_kind = 'grant'::text) AND (ledger_version = 1) AND (prior_total = 0) AND (delta > 0) AND (ledger_status = 'active'::text)) OR ((entry_kind = 'amend'::text) AND (ledger_version > 1) AND (delta <> 0) AND (ledger_status = 'active'::text)) OR ((entry_kind = 'revoke'::text) AND (ledger_version > 1) AND (ledger_status = 'revoked'::text)) OR ((entry_kind = 'supersede'::text) AND (ledger_version > 1) AND (ledger_status = 'active'::text)))),
    CONSTRAINT campaign_operations_budget_le_campaign_identity_canonical_check CHECK (((campaign_identity_canonical <> ''::text) AND (octet_length(campaign_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_budget_ledg_budget_identity_canonical_check CHECK (((budget_identity_canonical <> ''::text) AND (octet_length(budget_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_budget_ledger__administrator_identity_check CHECK ((administrator_identity ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_budget_ledger__budget_ledger_entry_id_check CHECK ((budget_ledger_entry_id > 0)),
    CONSTRAINT campaign_operations_budget_ledger_budget_contract_version_check CHECK ((budget_contract_version = 1)),
    CONSTRAINT campaign_operations_budget_ledger_en_budget_identity_hash_check CHECK ((budget_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_budget_ledger_entry_budget_unit_check CHECK ((budget_unit = 'materialized_member_dispatch'::text)),
    CONSTRAINT campaign_operations_budget_ledger_entry_entry_kind_check CHECK ((entry_kind = ANY (ARRAY['grant'::text, 'amend'::text, 'revoke'::text, 'supersede'::text]))),
    CONSTRAINT campaign_operations_budget_ledger_entry_ledger_status_check CHECK ((ledger_status = ANY (ARRAY['active'::text, 'revoked'::text]))),
    CONSTRAINT campaign_operations_budget_ledger_entry_ledger_version_check CHECK ((ledger_version > 0)),
    CONSTRAINT campaign_operations_budget_ledger_entry_prior_total_check CHECK ((prior_total >= 0)),
    CONSTRAINT campaign_operations_budget_ledger_entry_reason_check CHECK (((reason <> ''::text) AND (octet_length(reason) <= 4096) AND (reason ~ '[^ 	
]'::text) AND (translate(reason, '	
'::text, ''::text) !~ '[[:cntrl:]]'::text))),
    CONSTRAINT campaign_operations_budget_ledger_entry_resulting_total_check CHECK ((resulting_total >= 0)),
    CONSTRAINT campaign_operations_budget_previous_shape_check CHECK ((((ledger_version = 1) AND (previous_entry_id IS NULL) AND (previous_entry_identity_canonical IS NULL) AND (previous_entry_identity_hash IS NULL)) OR ((ledger_version > 1) AND (previous_entry_id IS NOT NULL) AND (previous_entry_identity_canonical IS NOT NULL) AND (previous_entry_identity_canonical <> ''::text) AND (previous_entry_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text))))
);


--
-- Name: TABLE campaign_operations_budget_ledger_entry; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.campaign_operations_budget_ledger_entry IS 'Append-only V1 materialized-member budget authority; balances derive from this head and reservation evidence.';


--
-- Name: lock_campaign_operations_budget_head(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_campaign_operations_budget_head(target_campaign_id bigint) RETURNS public.campaign_operations_budget_ledger_entry
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE locked_row campaign_operations_budget_ledger_entry%ROWTYPE;
BEGIN
    SELECT * INTO locked_row
    FROM campaign_operations_budget_ledger_entry
    WHERE operational_campaign_id = target_campaign_id
    ORDER BY ledger_version DESC LIMIT 1
    FOR UPDATE;
    RETURN locked_row;
END;
$$;


--
-- Name: lock_campaign_operations_campaign(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_campaign_operations_campaign(target_operational_campaign_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    PERFORM 1
    FROM campaign_operations_campaign
    WHERE operational_campaign_id = target_operational_campaign_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations campaign not found'
            USING ERRCODE = 'P0002';
    END IF;
END;
$$;


--
-- Name: lock_campaign_operations_request(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_campaign_operations_request(target_request_id bigint) RETURNS public.campaign_operations_operational_request
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE locked_row campaign_operations_operational_request%ROWTYPE;
BEGIN
    SELECT * INTO STRICT locked_row
    FROM campaign_operations_operational_request
    WHERE operational_request_id = target_request_id
    FOR UPDATE;
    RETURN locked_row;
END;
$$;


