--
-- Name: minutes_between(time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.minutes_between(start_time time without time zone, end_time time without time zone) RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT (
        EXTRACT(EPOCH FROM (end_time - start_time)) / 60
        + CASE
            WHEN end_time < start_time THEN 1440
            ELSE 0
          END
    )::INTEGER;
$$;


--
-- Name: minutes_until(time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.minutes_until(target_time time without time zone) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
    SELECT minutes_between(
        LOCALTIME::TIME,
        target_time
    );
$$;


--
-- Name: recommendation_evaluation_policy_provenance_valid_v1(text, text, integer, integer, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_evaluation_policy_provenance_valid_v1(evaluation_policy_canonical text, evaluation_policy_hash text, evaluation_version integer, evaluator_version integer, scoring_policy_canonical text, scoring_policy_hash text, scoring_version integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT recommendation_scoring_policy_provenance_valid_v1(
               scoring_policy_canonical, scoring_policy_hash, scoring_version)
       AND evaluation_version = 1
       AND evaluator_version = 1
       AND evaluation_policy_canonical =
           'experiment_recommendation_evaluation_policy_v1;evaluation_version=' ||
           evaluation_version || ';evaluator_version=' || evaluator_version ||
           ';scoring_policy=' || octet_length(scoring_policy_canonical) || ':' ||
           scoring_policy_canonical
       AND evaluation_policy_hash =
           recommendation_semantic_tagged_fnv1a64(evaluation_policy_canonical)
$$;


