    source_final_profitability_source_content_hash text,
    source_final_profitability_observation_identity_hash text,
    profitability_evidence_canonical text,
    profitability_evidence_hash text,
    CONSTRAINT evaluation_final_profitability_shape_check CHECK ((((profitability_evidence_canonical IS NULL) = (profitability_evidence_hash IS NULL)) AND ((profitability_evidence_hash IS NULL) OR (profitability_evidence_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)) AND (((final_profitability_provenance_version IS NULL) AND (source_final_inference_eval_result_id IS NULL) AND (source_final_profitability_observation_id IS NULL) AND (source_final_profitability_unavailable_reason IS NULL) AND (source_final_profitability_inference_scope IS NULL) AND (source_final_profitability_inference_start IS NULL) AND (source_final_profitability_inference_end IS NULL) AND (source_final_profitability_actionable_count IS NULL) AND (source_final_profitability_aggregate_return IS NULL) AND (source_final_profitability_average_return IS NULL) AND (source_final_profitability_metric_definition_hash IS NULL) AND (source_final_profitability_source_content_hash IS NULL) AND (source_final_profitability_observation_identity_hash IS NULL)) OR ((final_profitability_provenance_version = 1) AND (source_final_profitability_inference_scope = 'final'::text) AND (source_final_profitability_observation_id IS NULL) AND (btrim(source_final_profitability_unavailable_reason) <> ''::text) AND (source_final_profitability_inference_start IS NULL) AND (source_final_profitability_inference_end IS NULL) AND (source_final_profitability_actionable_count IS NULL) AND (source_final_profitability_aggregate_return IS NULL) AND (source_final_profitability_average_return IS NULL) AND (source_final_profitability_metric_definition_hash IS NULL) AND (source_final_profitability_source_content_hash IS NULL) AND (source_final_profitability_observation_identity_hash IS NULL)) OR ((final_profitability_provenance_version = 1) AND (source_final_inference_eval_result_id IS NOT NULL) AND (source_final_profitability_observation_id IS NOT NULL) AND (source_final_profitability_unavailable_reason IS NULL) AND (source_final_profitability_inference_scope = 'final'::text) AND (btrim(source_final_profitability_inference_start) <> ''::text) AND (btrim(source_final_profitability_inference_end) <> ''::text) AND (source_final_profitability_actionable_count >= 0) AND (source_final_profitability_aggregate_return <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision])) AND (((source_final_profitability_actionable_count = 0) AND (source_final_profitability_average_return IS NULL)) OR ((source_final_profitability_actionable_count > 0) AND (source_final_profitability_average_return IS NOT NULL) AND (source_final_profitability_average_return <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision])))) AND (source_final_profitability_metric_definition_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text) AND (source_final_profitability_source_content_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text) AND (source_final_profitability_observation_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text))))),
    CONSTRAINT experiment_recommendation_ev_evaluation_identity_canonica_check CHECK ((btrim(evaluation_identity_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_ev_recommendation_policy_canoni_check CHECK ((btrim(recommendation_policy_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_ev_recommendation_semantic_cano_check CHECK ((btrim(recommendation_semantic_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_ev_recommendation_semantic_hash_check CHECK ((btrim(recommendation_semantic_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_eval_recommendation_policy_hash_check CHECK ((btrim(recommendation_policy_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evalua_evaluation_identity_hash_check CHECK ((btrim(evaluation_identity_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluati_missing_evidence_count_check CHECK ((missing_evidence_count >= 0)),
    CONSTRAINT experiment_recommendation_evaluation_r_evidence_canonical_check CHECK ((btrim(evidence_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_resu_component_count_check CHECK ((component_count >= 0)),
    CONSTRAINT experiment_recommendation_evaluation_resu_ranking_ordinal_check CHECK ((ranking_ordinal > 0)),
    CONSTRAINT experiment_recommendation_evaluation_result_disposition_check CHECK ((disposition = ANY (ARRAY['advisory_ready'::text, 'insufficient_evidence'::text, 'blocked_pending_duplicate'::text, 'blocked_active_duplicate'::text, 'completed_duplicate'::text, 'stale_source_evidence'::text, 'unsupported_recommendation_family'::text, 'invalid_persisted_evidence'::text]))),
    CONSTRAINT experiment_recommendation_evaluation_result_eligibility_check CHECK ((eligibility = ANY (ARRAY['eligible'::text, 'ineligible'::text]))),
    CONSTRAINT experiment_recommendation_evaluation_result_evidence_hash_check CHECK ((btrim(evidence_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_result_explanation_check CHECK ((btrim(explanation) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_result_finite_check CHECK ((((final_score IS NULL) OR (final_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))) AND ((raw_positive_score IS NULL) OR (raw_positive_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))) AND ((raw_penalty_score IS NULL) OR (raw_penalty_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))) AND ((raw_total_score IS NULL) OR (raw_total_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))))),
    CONSTRAINT experiment_recommendation_evaluation_result_hash_size_check CHECK ((octet_length(evaluation_identity_hash) <= 128)),
    CONSTRAINT experiment_recommendation_evaluation_result_reason_code_check CHECK ((btrim(reason_code) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_result_result_status_check CHECK ((result_status = 'evaluated'::text)),
    CONSTRAINT experiment_recommendation_evaluation_result_shape_check CHECK ((((eligibility = 'eligible'::text) AND (disposition = 'advisory_ready'::text) AND (final_score IS NOT NULL) AND (final_score >= (0.0)::double precision) AND (final_score <= (1.0)::double precision) AND (raw_positive_score IS NOT NULL) AND (raw_penalty_score IS NOT NULL) AND (raw_total_score IS NOT NULL) AND (component_count > 0)) OR ((eligibility = 'ineligible'::text) AND (disposition <> 'advisory_ready'::text) AND (final_score IS NULL) AND (raw_positive_score IS NULL) AND (raw_penalty_score IS NULL) AND (raw_total_score IS NULL) AND (component_count = 0))))
);


