    CONSTRAINT experiment_recommendation_evaluation_run_hash_size_check CHECK ((octet_length(evaluation_run_identity_hash) <= 128)),
    CONSTRAINT experiment_recommendation_evaluation_run_lifecycle_check CHECK ((((status = 'running'::text) AND (completed_at IS NULL) AND (error_message IS NULL)) OR ((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (error_message IS NULL)) OR ((status = 'failed'::text) AND (completed_at IS NOT NULL) AND (error_message IS NOT NULL) AND (btrim(error_message) <> ''::text)))),
    CONSTRAINT experiment_recommendation_evaluation_run_requested_limit_check CHECK (((requested_limit IS NULL) OR (requested_limit > 0))),
    CONSTRAINT experiment_recommendation_evaluation_run_scoring_version_check CHECK ((scoring_version > 0)),
    CONSTRAINT experiment_recommendation_evaluation_run_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text])))
);


