COMMENT ON COLUMN public.experiment_recommendation_evaluation_run.evaluation_run_identity_canonical IS 'Authoritative complete identity. Hash lookup plus exact canonical comparison is collision-safe.';


--
-- Name: recommendation_evaluation_result_semantics_valid_v1(public.experiment_recommendation_evaluation_result, public.experiment_recommendation_evaluation_run); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_evaluation_result_semantics_valid_v1(evaluation public.experiment_recommendation_evaluation_result, run public.experiment_recommendation_evaluation_run) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT recommendation_evaluation_run_semantics_valid_v1(run)
       AND evaluation.recommendation_evaluation_run_id =
           run.recommendation_evaluation_run_id
       AND evaluation.recommendation_semantic_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.recommendation_semantic_canonical)
       AND evaluation.recommendation_policy_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.recommendation_policy_canonical)
       AND evaluation.evidence_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.evidence_canonical)
       AND evaluation.evaluation_identity_canonical =
           'experiment_recommendation_evaluation_identity_v1;evaluation_policy=' ||
           octet_length(run.evaluation_policy_canonical) || ':' ||
           run.evaluation_policy_canonical || ';recommendation_semantic=' ||
           octet_length(evaluation.recommendation_semantic_canonical) || ':' ||
           evaluation.recommendation_semantic_canonical ||
           ';recommendation_policy=' ||
           octet_length(evaluation.recommendation_policy_canonical) || ':' ||
           evaluation.recommendation_policy_canonical || ';evidence=' ||
           octet_length(evaluation.evidence_canonical) || ':' ||
           evaluation.evidence_canonical
       AND evaluation.evaluation_identity_hash =
           recommendation_semantic_tagged_fnv1a64(
               evaluation.evaluation_identity_canonical)
$$;


--
-- Name: recommendation_evaluation_run_semantics_valid_v1(public.experiment_recommendation_evaluation_run); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_evaluation_run_semantics_valid_v1(run public.experiment_recommendation_evaluation_run) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT recommendation_evaluation_policy_provenance_valid_v1(
        run.evaluation_policy_canonical, run.evaluation_policy_hash,
        run.evaluation_version, run.evaluator_version,
        run.scoring_policy_canonical, run.scoring_policy_hash,
        run.scoring_version)
$$;


--
-- Name: recommendation_evaluation_semantic_canonical_v1(integer, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_evaluation_semantic_canonical_v1(evaluation_version integer, evaluator_version integer, scoring_policy_canonical text, scoring_version integer) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT 'experiment_recommendation_evaluation_semantic_v1;semantic_version=1;' ||
        'algorithm=advisory_evaluator_v1;' ||
        'classification=invalid,unsupported,insufficient,stale,pending_duplicate,' ||
        'active_duplicate,completed_duplicate,advisory_ready_v1;' ||
        'eligibility=only_advisory_ready_is_eligible_v1;' ||
        'disposition_precedence=persisted_evidence_then_family_then_missing_then_stale_then_duplicate_then_score_v1;' ||
        'evaluation_version=' || evaluation_version ||
        ';evaluator_version=' || evaluator_version ||
        ';scoring_semantic=' ||
        octet_length(recommendation_scoring_semantic_canonical_v1(
            scoring_policy_canonical, scoring_version)) || ':' ||
        recommendation_scoring_semantic_canonical_v1(
            scoring_policy_canonical, scoring_version)
    WHERE evaluation_version = 1 AND evaluator_version = 1
      AND scoring_version = 1
$$;


--
-- Name: recommendation_ranking_membership_contains(text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_ranking_membership_contains(membership_canonical text, target_evaluation_identity text, target_evaluation_result_id bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    membership_bytes bytea := convert_to(membership_canonical, 'UTF8');
    target_identity_bytes bytea := convert_to(target_evaluation_identity, 'UTF8');
    header_bytes bytea := convert_to(
        'experiment_recommendation_ranking_membership_v1;count=', 'UTF8');
    delimiter_bytes bytea := convert_to(';', 'UTF8');
    colon_bytes bytea := convert_to(':', 'UTF8');
    cursor_position integer;
    delimiter_offset integer;
    member_count_text text;
    member_count_numeric numeric;
    member_count integer;
    member_ordinal integer;
    member_prefix_bytes bytea;
    identity_length_text text;
    identity_length_numeric numeric;
    identity_length integer;
    member_identity_bytes bytea;
    result_prefix_bytes bytea;
    member_result_id_text text;
    member_result_id_numeric numeric;
    target_found boolean := false;
    total_length integer := octet_length(membership_bytes);
BEGIN
    IF substring(membership_bytes FROM 1 FOR octet_length(header_bytes)) <>
       header_bytes THEN
        RETURN false;
    END IF;
    cursor_position := octet_length(header_bytes) + 1;
    delimiter_offset := position(
        delimiter_bytes IN substring(membership_bytes FROM cursor_position));
    IF delimiter_offset = 0 THEN
        member_count_text := convert_from(
            substring(membership_bytes FROM cursor_position), 'UTF8');
        cursor_position := total_length + 1;
    ELSE
        member_count_text := convert_from(substring(
            membership_bytes FROM cursor_position FOR delimiter_offset - 1),
            'UTF8');
        cursor_position := cursor_position + delimiter_offset - 1;
    END IF;
    IF member_count_text !~ '^(0|[1-9][0-9]*)$'
       OR length(member_count_text) > 4 THEN
        RETURN false;
    END IF;
    member_count_numeric := member_count_text::numeric;
    IF member_count_numeric > 1000 THEN
        RETURN false;
    END IF;
    member_count := member_count_numeric::integer;
    IF member_count = 0 THEN
        RETURN false;
    END IF;
    IF cursor_position > total_length THEN
        RETURN false;
    END IF;

    FOR member_ordinal IN 0..member_count - 1 LOOP
        member_prefix_bytes := convert_to(
            ';member[' || member_ordinal::text || '].evaluation_identity=',
            'UTF8');
        IF substring(membership_bytes FROM cursor_position
                     FOR octet_length(member_prefix_bytes)) <>
           member_prefix_bytes THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + octet_length(member_prefix_bytes);
        delimiter_offset := position(
            colon_bytes IN substring(membership_bytes FROM cursor_position));
        IF delimiter_offset = 0 THEN
            RETURN false;
        END IF;
        identity_length_text := convert_from(substring(
            membership_bytes FROM cursor_position FOR delimiter_offset - 1),
            'UTF8');
        IF identity_length_text !~ '^(0|[1-9][0-9]*)$'
           OR length(identity_length_text) > 10 THEN
            RETURN false;
        END IF;
        identity_length_numeric := identity_length_text::numeric;
        IF identity_length_numeric > total_length THEN
            RETURN false;
        END IF;
        identity_length := identity_length_numeric::integer;
        cursor_position := cursor_position + delimiter_offset;
        member_identity_bytes := substring(
            membership_bytes FROM cursor_position FOR identity_length);
        IF octet_length(member_identity_bytes) <> identity_length THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + identity_length;

        result_prefix_bytes := convert_to(
            ';member[' || member_ordinal::text || '].evaluation_result_id=',
            'UTF8');
        IF substring(membership_bytes FROM cursor_position
                     FOR octet_length(result_prefix_bytes)) <>
           result_prefix_bytes THEN
            RETURN false;
        END IF;
        cursor_position := cursor_position + octet_length(result_prefix_bytes);
        IF member_ordinal < member_count - 1 THEN
            delimiter_offset := position(delimiter_bytes IN substring(
                membership_bytes FROM cursor_position));
            IF delimiter_offset = 0 THEN
                RETURN false;
            END IF;
            member_result_id_text := convert_from(substring(
                membership_bytes FROM cursor_position FOR delimiter_offset - 1),
                'UTF8');
            cursor_position := cursor_position + delimiter_offset - 1;
        ELSE
            member_result_id_text := convert_from(
                substring(membership_bytes FROM cursor_position), 'UTF8');
            cursor_position := total_length + 1;
        END IF;
        IF member_result_id_text !~ '^[1-9][0-9]*$'
           OR length(member_result_id_text) > 19 THEN
            RETURN false;
        END IF;
        member_result_id_numeric := member_result_id_text::numeric;
        IF member_result_id_numeric > 9223372036854775807::numeric THEN
            RETURN false;
        END IF;
        IF member_identity_bytes = target_identity_bytes
           AND member_result_id_numeric = target_evaluation_result_id THEN
            target_found := true;
        END IF;
    END LOOP;
    RETURN target_found AND cursor_position = total_length + 1;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range OR
         character_not_in_repertoire THEN
        RETURN false;
END;
$_$;


--
-- Name: recommendation_ranking_membership_count_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_ranking_membership_count_v1(membership_canonical text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    matched text[];
    parsed numeric;
BEGIN
    matched := regexp_match(membership_canonical,
        '^experiment_recommendation_ranking_membership_v1;count=(0|[1-9][0-9]*)(;|$)');
    IF matched IS NULL OR length(matched[1]) > 4 THEN RETURN NULL; END IF;
    parsed := matched[1]::numeric;
    IF parsed > 1000 THEN RETURN NULL; END IF;
    IF parsed = 0 AND membership_canonical <>
       'experiment_recommendation_ranking_membership_v1;count=0' THEN
        RETURN NULL;
    END IF;
    RETURN parsed::integer;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN NULL;
END;
$_$;


--
-- Name: recommendation_ranking_tie_break_matches(text, text, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_ranking_tie_break_matches(tie_break_primary text, evaluation_disposition text, evaluation_final_score double precision) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    parsed_score double precision;
BEGIN
    IF evaluation_final_score IS NOT NULL THEN
        IF left(tie_break_primary, 6) <> 'score:' THEN
            RETURN false;
        END IF;
        parsed_score := substring(tie_break_primary FROM 7)::double precision;
        RETURN parsed_score NOT IN (
                   'NaN'::double precision,
                   'Infinity'::double precision,
                   '-Infinity'::double precision)
               AND parsed_score = evaluation_final_score;
    END IF;
    RETURN tie_break_primary = CASE evaluation_disposition
        WHEN 'blocked_pending_duplicate' THEN 'priority:0'
        WHEN 'blocked_active_duplicate' THEN 'priority:1'
        WHEN 'completed_duplicate' THEN 'priority:2'
        WHEN 'insufficient_evidence' THEN 'priority:0'
        WHEN 'stale_source_evidence' THEN 'priority:1'
        WHEN 'unsupported_recommendation_family' THEN 'priority:2'
        WHEN 'invalid_persisted_evidence' THEN 'priority:3'
        ELSE NULL
    END;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN false;
END;
$$;


--
-- Name: recommendation_scoring_policy_provenance_valid_v1(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_scoring_policy_provenance_valid_v1(policy_canonical text, policy_hash text, policy_version integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
DECLARE
    parts text[];
    expected_keys constant text[] := ARRAY[
        'scoring_version',
        'leader_score_weight',
        'inference_accuracy_weight',
        'evidence_strength_weight',
        'neutral_balance_weight',
        'structural_distance_weight',
        'parameter_preference_weight',
        'source_rank_weight',
        'horizon_change_penalty_weight',
        'relative_mutation_penalty_weight',
        'minimum_evidence_count',
        'evidence_saturation_count',
        'preferred_neutral_proportion',
        'maximum_neutral_proportion',
        'maximum_relative_mutation',
        'maximum_absolute_structural_distance',
        'allow_missing_neutral_proportion',
        'score_floor',
        'score_ceiling',
        'core_lr_preference',
        'head_lr_preference',
        'label_threshold_preference',
        'prediction_horizon_preference'
    ];
    values_text text[] := ARRAY[]::text[];
    index_value integer;
    separator integer;
    key_text text;
    value_text text;
    canonical_double_pattern constant text :=
        '^(0|[1-9][0-9]*)([.][0-9]*[1-9])?([e][+-][0-9]{2,3})?$';
    weights double precision[];
    minimum_evidence bigint;
    evidence_saturation bigint;
    preferred_neutral double precision;
    maximum_neutral double precision;
    maximum_relative double precision;
    maximum_absolute double precision;
    score_floor_value double precision;
    score_ceiling_value double precision;
    preferences double precision[];
BEGIN
    IF policy_version <> 1 OR
       policy_hash <> recommendation_semantic_tagged_fnv1a64(policy_canonical)
    THEN
        RETURN false;
    END IF;

    parts := string_to_array(policy_canonical, ';');
    IF cardinality(parts) <> cardinality(expected_keys) + 1 OR
       parts[1] <> 'experiment_recommendation_scoring_policy_v1'
    THEN
        RETURN false;
    END IF;

    FOR index_value IN 1..cardinality(expected_keys) LOOP
        separator := strpos(parts[index_value + 1], '=');
        IF separator <= 1 OR
           strpos(substr(parts[index_value + 1], separator + 1), '=') <> 0
        THEN
            RETURN false;
        END IF;

        key_text := substr(parts[index_value + 1], 1, separator - 1);
        value_text := substr(parts[index_value + 1], separator + 1);

        IF key_text <> expected_keys[index_value] OR value_text = '' THEN
            RETURN false;
        END IF;

        values_text := array_append(values_text, value_text);
    END LOOP;

    IF values_text[1] <> '1' THEN
        RETURN false;
    END IF;

    -- C++ v1 emits non-negative finite policy values in a deterministic
    -- decimal/scientific spelling. Reject alternate spellings such as
    -- trailing fractional zeros, uppercase E, leading '+', and negative zero.
    FOREACH index_value IN ARRAY ARRAY[
        2,3,4,5,6,7,8,9,10,13,14,15,16,18,19,20,21,22,23
    ]
    LOOP
        IF values_text[index_value] !~ canonical_double_pattern THEN
            RETURN false;
        END IF;
    END LOOP;

    IF values_text[11] !~ '^[1-9][0-9]*$' OR
       values_text[12] !~ '^(0|[1-9][0-9]*)$' OR
       values_text[17] !~ '^[01]$'
    THEN
        RETURN false;
    END IF;

    BEGIN
        weights := ARRAY[
            values_text[2]::double precision,
            values_text[3]::double precision,
            values_text[4]::double precision,
            values_text[5]::double precision,
            values_text[6]::double precision,
            values_text[7]::double precision,
            values_text[8]::double precision,
            values_text[9]::double precision,
            values_text[10]::double precision
        ];
        minimum_evidence := values_text[11]::bigint;
        evidence_saturation := values_text[12]::bigint;
        preferred_neutral := values_text[13]::double precision;
        maximum_neutral := values_text[14]::double precision;
        maximum_relative := values_text[15]::double precision;
        maximum_absolute := values_text[16]::double precision;
        score_floor_value := values_text[18]::double precision;
        score_ceiling_value := values_text[19]::double precision;
        preferences := ARRAY[
            values_text[20]::double precision,
            values_text[21]::double precision,
            values_text[22]::double precision,
            values_text[23]::double precision
        ];
    EXCEPTION
        WHEN numeric_value_out_of_range OR invalid_text_representation THEN
            RETURN false;
    END;

    -- Mirror ValidateRecommendationScoringPolicy().
    IF EXISTS (
        SELECT 1
        FROM unnest(weights) value
        WHERE value < 0.0)
    THEN
        RETURN false;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM unnest(weights[1:7]) value
        WHERE value > 0.0)
    THEN
        RETURN false;
    END IF;

    IF minimum_evidence <= 0 OR evidence_saturation < minimum_evidence THEN
        RETURN false;
    END IF;

    IF preferred_neutral < 0.0 OR preferred_neutral > 1.0 THEN
        RETURN false;
    END IF;

    IF maximum_neutral < preferred_neutral OR maximum_neutral > 1.0 THEN
        RETURN false;
    END IF;

    IF maximum_relative <= 0.0 OR maximum_absolute <= 0.0 THEN
        RETURN false;
    END IF;

    IF score_floor_value < 0.0 OR score_ceiling_value > 1.0 OR
       score_floor_value >= score_ceiling_value
    THEN
        RETURN false;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(preferences) value
        WHERE value < 0.0 OR value > 1.0)
    THEN
        RETURN false;
    END IF;

    RETURN true;
END;
$_$;


--
-- Name: recommendation_scoring_semantic_canonical_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_scoring_semantic_canonical_v1(scoring_policy_canonical text, scoring_version integer) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT 'experiment_recommendation_scoring_semantic_v1;semantic_version=1;' ||
        'algorithm=weighted_component_score_v1;' ||
        'components=leader_quality,inference_accuracy,evidence_strength,neutral_balance,' ||
        'structural_proximity,parameter_preference,source_rank,horizon_change_penalty,' ||
        'relative_mutation_penalty;' ||
        'normalization=component_clamp_unit_and_policy_thresholds_v1;' ||
        'aggregation=positive_weight_normalized_minus_penalty_weight_normalized_then_policy_clamp_v1;' ||
        'missing=neutral_policy_or_ineligible_v1;' ||
        'structural_distance=relative_delta_else_absolute_delta_v1;' ||
        'source_metrics=persisted_leader_accuracy_neutral_evidence_v1;policy=' ||
        octet_length(scoring_policy_canonical) || ':' || scoring_policy_canonical
    WHERE scoring_version = 1
$$;


--
-- Name: recommendation_semantic_tagged_fnv1a64(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recommendation_semantic_tagged_fnv1a64(canonical_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
DECLARE
    canonical_bytes bytea := convert_to(canonical_value, 'UTF8');
    hash_value numeric := 14695981039346656037;
    byte_index integer;
    low_byte integer;
    high_word bigint;
    low_word bigint;
BEGIN
    IF octet_length(canonical_bytes) > 0 THEN
        FOR byte_index IN 0..octet_length(canonical_bytes) - 1 LOOP
            low_byte := mod(hash_value, 256)::integer #
                get_byte(canonical_bytes, byte_index);
            hash_value := hash_value - mod(hash_value, 256) + low_byte;
            hash_value := mod(
                hash_value * 1099511628211, 18446744073709551616);
        END LOOP;
    END IF;
    high_word := trunc(hash_value / 4294967296)::bigint;
    low_word := mod(hash_value, 4294967296)::bigint;
    RETURN 'fnv1a64:' || lpad(to_hex(high_word), 8, '0') ||
        lpad(to_hex(low_word), 8, '0');
END;
$$;


--
-- Name: record_campaign_operations_production_disable_v1(text, bigint, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_campaign_operations_production_disable_v1(operation_key_value text, predecessor_event_id_value bigint, predecessor_event_canonical_value text, expected_prior_version_value integer, disabling_actor_value text, reason_value text) RETURNS public.campaign_operations_production_enablement_event
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE predecessor
    public.campaign_operations_production_enablement_event%ROWTYPE;
DECLARE event public.campaign_operations_production_enablement_event%ROWTYPE;
BEGIN
    IF operation_key_value IS NULL OR octet_length(operation_key_value) > 128 OR
       operation_key_value !~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$' THEN
        RAISE EXCEPTION 'invalid production operation key'
            USING ERRCODE = '22023';
    END IF;
    SELECT candidate.* INTO event
    FROM public.campaign_operations_production_disable_replay_v1(
        operation_key_value, predecessor_event_id_value,
        predecessor_event_canonical_value, expected_prior_version_value,
        disabling_actor_value, reason_value) candidate;
    IF FOUND THEN RETURN event; END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(19055, 1);
    SELECT candidate.* INTO event
    FROM public.campaign_operations_production_disable_replay_v1(
        operation_key_value, predecessor_event_id_value,
        predecessor_event_canonical_value, expected_prior_version_value,
        disabling_actor_value, reason_value) candidate;
    IF FOUND THEN RETURN event; END IF;
    SELECT * INTO STRICT predecessor
    FROM public.campaign_operations_production_enablement_event candidate
    ORDER BY candidate.resulting_version DESC LIMIT 1;
    IF predecessor.production_enablement_event_id <>
           predecessor_event_id_value OR
       predecessor.enablement_identity_canonical <>
           predecessor_event_canonical_value OR
       predecessor.resulting_version <> expected_prior_version_value OR
       predecessor.event_kind <> 'enable' THEN
        RAISE EXCEPTION 'production disable predecessor mismatch'
            USING ERRCODE = '40001';
    END IF;
    INSERT INTO public.campaign_operations_production_transition_context(
        backend_pid, transaction_id, transition_kind,
        operational_request_id, operation_key)
    VALUES(pg_catalog.pg_backend_pid(), pg_catalog.txid_current(), 'disable',
           NULL, operation_key_value);
    event.production_enablement_event_id := pg_catalog.nextval(
        pg_catalog.pg_get_serial_sequence(
          'public.campaign_operations_production_enablement_event',
          'production_enablement_event_id'));
    event.event_kind := 'disable';
    event.operation_key := operation_key_value;
    event.predecessor_event_id := predecessor_event_id_value;
    event.predecessor_event_canonical := predecessor_event_canonical_value;
    event.expected_prior_version := expected_prior_version_value;
    event.resulting_version := expected_prior_version_value + 1;
    event.actor_identity := disabling_actor_value;
    event.capability := 'campaign_operations_production_disabler';
    event.reason := reason_value;
    event.enablement_contract_version := 1;
    event.recorded_at := pg_catalog.transaction_timestamp();
    event.enablement_identity_canonical :=
        public.campaign_operations_production_enablement_canonical_v1(event);
    event.enablement_identity_hash :=
        public.campaign_operations_tagged_fnv1a64(
            event.enablement_identity_canonical);
    INSERT INTO public.campaign_operations_production_enablement_event
        SELECT event.*;
    INSERT INTO
      public.campaign_operations_production_enablement_audit_reference_event(
        production_enablement_event_id, operation_key, event_kind,
        actor_identity, capability, reason, outcome, replay_disposition,
        diagnostic_code)
    VALUES(event.production_enablement_event_id, event.operation_key,
        event.event_kind, event.actor_identity, event.capability, event.reason,
        'recorded', 'new_operation', 'immutable_enablement_event_recorded');
    DELETE FROM public.campaign_operations_production_transition_context context
    WHERE context.backend_pid = pg_catalog.pg_backend_pid()
      AND context.transaction_id = pg_catalog.txid_current();
    RETURN event;
END;
$_$;


--
-- Name: record_campaign_operations_production_enable_v1(text, integer, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_campaign_operations_production_enable_v1(operation_key_value text, expected_prior_version_value integer, scheduler_evidence_canonical_value text, independent_verification_reference_value text, authorizing_actor_value text, manager_service_contract_value text, approved_build_contract_canonical_value text, approved_build_source_commit_value text, approved_build_compiler_contract_value text, approved_build_executable_sha256_value text, reason_value text) RETURNS public.campaign_operations_production_enablement_event
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE scheduler_record record;
DECLARE predecessor
    public.campaign_operations_production_enablement_event%ROWTYPE;
DECLARE event public.campaign_operations_production_enablement_event%ROWTYPE;
DECLARE build_canonical_value text;
BEGIN
    IF operation_key_value IS NULL OR octet_length(operation_key_value) > 128 OR
       operation_key_value !~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$' THEN
        RAISE EXCEPTION 'invalid production operation key'
            USING ERRCODE = '22023';
    END IF;
    build_canonical_value :=
        public.campaign_operations_manager_build_canonical_v1(
            manager_service_contract_value,
            approved_build_source_commit_value,
            approved_build_compiler_contract_value,
            approved_build_executable_sha256_value);
    IF build_canonical_value <> approved_build_contract_canonical_value THEN
        RAISE EXCEPTION 'production enable approved build mismatch'
            USING ERRCODE = '23514';
    END IF;
    SELECT candidate.* INTO event
    FROM public.campaign_operations_production_enable_replay_v1(
        operation_key_value, expected_prior_version_value,
        scheduler_evidence_canonical_value,
        independent_verification_reference_value,
        authorizing_actor_value, manager_service_contract_value,
        approved_build_contract_canonical_value,
        approved_build_source_commit_value,
        approved_build_compiler_contract_value,
        approved_build_executable_sha256_value, reason_value) candidate;
    IF FOUND THEN RETURN event; END IF;
    SELECT * INTO STRICT scheduler_record
    FROM public.campaign_operations_scheduler_protocol_evidence_lock_v1();
    IF NOT scheduler_record.evidence_complete OR
       scheduler_record.evidence_canonical <>
           scheduler_evidence_canonical_value THEN
        RAISE EXCEPTION 'production enable scheduler evidence mismatch'
            USING ERRCODE = '23514';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(19055, 1);
    SELECT candidate.* INTO event
    FROM public.campaign_operations_production_enable_replay_v1(
        operation_key_value, expected_prior_version_value,
        scheduler_evidence_canonical_value,
        independent_verification_reference_value,
        authorizing_actor_value, manager_service_contract_value,
        approved_build_contract_canonical_value,
        approved_build_source_commit_value,
        approved_build_compiler_contract_value,
        approved_build_executable_sha256_value, reason_value) candidate;
    IF FOUND THEN RETURN event; END IF;
    SELECT * INTO predecessor
    FROM public.campaign_operations_production_enablement_event candidate
    ORDER BY candidate.resulting_version DESC LIMIT 1;
    IF expected_prior_version_value = 0 THEN
        IF predecessor.production_enablement_event_id IS NOT NULL THEN
            RAISE EXCEPTION 'production enable predecessor mismatch'
                USING ERRCODE = '40001';
        END IF;
    ELSIF predecessor.production_enablement_event_id IS NULL OR
          predecessor.resulting_version <> expected_prior_version_value OR
          predecessor.event_kind <> 'disable' THEN
        RAISE EXCEPTION 'production enable predecessor mismatch'
            USING ERRCODE = '40001';
    END IF;
    INSERT INTO public.campaign_operations_production_transition_context(
        backend_pid, transaction_id, transition_kind,
        operational_request_id, operation_key)
    VALUES(pg_catalog.pg_backend_pid(), pg_catalog.txid_current(), 'enable',
           NULL, operation_key_value);

    event.production_enablement_event_id := pg_catalog.nextval(
        pg_catalog.pg_get_serial_sequence(
          'public.campaign_operations_production_enablement_event',
          'production_enablement_event_id'));
    event.event_kind := 'enable';
    event.operation_key := operation_key_value;
    event.predecessor_event_id := predecessor.production_enablement_event_id;
    event.predecessor_event_canonical := coalesce(
        predecessor.enablement_identity_canonical, '');
    event.expected_prior_version := expected_prior_version_value;
    event.resulting_version := expected_prior_version_value + 1;
    event.scheduler_protocol_evidence_canonical :=
        scheduler_record.evidence_canonical;
    event.scheduler_protocol_evidence_hash := scheduler_record.evidence_hash;
    event.scheduler_required_generation := scheduler_record.required_generation;
    event.scheduler_cutover_state := scheduler_record.cutover_state;
    event.scheduler_cutover_completed_at :=
        scheduler_record.cutover_completed_at::timestamptz;
    event.scheduler_cutover_completed_by :=
        scheduler_record.cutover_completed_by;
    event.scheduler_cutover_executable_path :=
        scheduler_record.cutover_executable_path;
    event.scheduler_cutover_process_evidence :=
        scheduler_record.cutover_process_evidence;
    event.independent_verification_reference :=
        independent_verification_reference_value;
    event.actor_identity := authorizing_actor_value;
    event.capability := 'campaign_operations_production_enabler';
    event.manager_service_contract := manager_service_contract_value;
    event.approved_build_contract_canonical := build_canonical_value;
    event.approved_build_contract_hash :=
        public.campaign_operations_tagged_fnv1a64(build_canonical_value);
    event.approved_build_source_commit := approved_build_source_commit_value;
    event.approved_build_compiler_contract :=
        approved_build_compiler_contract_value;
    event.approved_build_executable_sha256 :=
        approved_build_executable_sha256_value;
    event.reason := reason_value;
    event.enablement_contract_version := 1;
    event.recorded_at := pg_catalog.transaction_timestamp();
    event.enablement_identity_canonical :=
        public.campaign_operations_production_enablement_canonical_v1(event);
    event.enablement_identity_hash :=
        public.campaign_operations_tagged_fnv1a64(
            event.enablement_identity_canonical);
    INSERT INTO public.campaign_operations_production_enablement_event
        SELECT event.*;
    INSERT INTO
      public.campaign_operations_production_enablement_audit_reference_event(
        production_enablement_event_id, operation_key, event_kind,
        actor_identity, capability, reason, outcome, replay_disposition,
        diagnostic_code)
    VALUES(event.production_enablement_event_id, event.operation_key,
        event.event_kind, event.actor_identity, event.capability, event.reason,
        'recorded', 'new_operation', 'immutable_enablement_event_recorded');
    DELETE FROM public.campaign_operations_production_transition_context context
    WHERE context.backend_pid = pg_catalog.pg_backend_pid()
      AND context.transaction_id = pg_catalog.txid_current();
    RETURN event;
END;
$_$;


