--
-- Name: reject_recommendation_profitability_snapshot_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_recommendation_profitability_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.final_profitability_provenance_version IS DISTINCT FROM
           NEW.final_profitability_provenance_version
       OR OLD.source_final_inference_eval_result_id IS DISTINCT FROM
           NEW.source_final_inference_eval_result_id
       OR OLD.source_final_profitability_observation_id IS DISTINCT FROM
           NEW.source_final_profitability_observation_id
       OR OLD.source_final_profitability_unavailable_reason IS DISTINCT FROM
           NEW.source_final_profitability_unavailable_reason
       OR OLD.source_final_profitability_inference_scope IS DISTINCT FROM
           NEW.source_final_profitability_inference_scope
       OR OLD.source_final_profitability_inference_start IS DISTINCT FROM
           NEW.source_final_profitability_inference_start
       OR OLD.source_final_profitability_inference_end IS DISTINCT FROM
           NEW.source_final_profitability_inference_end
       OR OLD.source_final_profitability_actionable_count IS DISTINCT FROM
           NEW.source_final_profitability_actionable_count
       OR OLD.source_final_profitability_aggregate_return IS DISTINCT FROM
           NEW.source_final_profitability_aggregate_return
       OR OLD.source_final_profitability_average_return IS DISTINCT FROM
           NEW.source_final_profitability_average_return
       OR OLD.source_final_profitability_metric_definition_hash IS DISTINCT FROM
           NEW.source_final_profitability_metric_definition_hash
       OR OLD.source_final_profitability_source_content_hash IS DISTINCT FROM
           NEW.source_final_profitability_source_content_hash
       OR OLD.source_final_profitability_observation_identity_hash IS DISTINCT FROM
           NEW.source_final_profitability_observation_identity_hash
    THEN
        RAISE EXCEPTION
            'recommendation profitability snapshot is immutable'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: replace_parameter(bigint, text, integer, integer, double precision[]); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.replace_parameter(IN p_model_id bigint, IN p_param_name text, IN p_n_rows integer, IN p_n_cols integer, IN p_values double precision[])
    LANGUAGE plpgsql
    AS $$
DECLARE
    total INT := p_n_rows * p_n_cols;
    idx   INT;
    r     INT;
    c     INT;
BEGIN
    IF array_length(p_values, 1) IS DISTINCT FROM total THEN
        RAISE EXCEPTION 'replace_parameter: length of p_values (%) does not match n_rows*n_cols (%)',
            array_length(p_values, 1), total;
    END IF;

    -- Clear existing entries for this parameter
    DELETE FROM matrix WHERE model_id = p_model_id AND param_name = p_param_name;

    -- Insert new entries
    idx := 1;
    FOR r IN 0..(p_n_rows - 1) LOOP
        FOR c IN 0..(p_n_cols - 1) LOOP
            INSERT INTO matrix (model_id, param_name, n_rows, n_cols, row_idx, col_idx, value)
            VALUES (p_model_id, p_param_name, p_n_rows, p_n_cols, r, c, p_values[idx]);
            idx := idx + 1;
        END LOOP;
    END LOOP;
END;
$$;


--
-- Name: training_objective_tagged_fnv1a64(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.training_objective_tagged_fnv1a64(canonical_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
DECLARE
    canonical_bytes bytea := convert_to(canonical_value, 'UTF8');
    hash_value numeric := 14695981039346656037;
    byte_index integer;
    low_byte integer;
    high_word bigint;
    low_word bigint;
BEGIN
    IF octet_length(canonical_bytes) > 0 THEN
        FOR byte_index IN 0..octet_length(canonical_bytes) - 1 LOOP
            low_byte := mod(hash_value, 256)::integer #
                get_byte(canonical_bytes, byte_index);
            hash_value := hash_value - mod(hash_value, 256) + low_byte;
            hash_value := mod(
                hash_value * 1099511628211, 18446744073709551616);
        END LOOP;
    END IF;
    high_word := trunc(hash_value / 4294967296)::bigint;
    low_word := mod(hash_value, 4294967296)::bigint;
    RETURN 'fnv1a64:' || lpad(to_hex(high_word), 8, '0') ||
        lpad(to_hex(low_word), 8, '0');
END;
$$;


--
-- Name: transition_campaign_operations_request_bound(bigint, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_operations_request_bound(target_request_id bigint, expected_version_value integer, lease_digest_value text) RETURNS public.campaign_operations_operational_request
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE changed campaign_operations_operational_request%ROWTYPE;
BEGIN
    UPDATE campaign_operations_operational_request
       SET request_state = 'bound',
           state_version = state_version + 1,
           lease_token_hash = NULL,
           lease_expires_at = NULL,
           dispatcher_identity = NULL,
           updated_at = transaction_timestamp()
     WHERE operational_request_id = target_request_id
       AND request_state = 'dispatching'
       AND state_version = expected_version_value
       AND lease_token_hash = lease_digest_value
       AND lease_expires_at > transaction_timestamp()
       AND production_dispatch_enabled = false
     RETURNING * INTO changed;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations bind compare-and-set lost'
            USING ERRCODE = 'P0001';
    END IF;
    RETURN changed;
END;
$$;


--
-- Name: transition_campaign_operations_request_bound_production_v2(bigint, integer, text, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_operations_request_bound_production_v2(target_request_id bigint, expected_version_value integer, lease_digest_value text, dispatch_attempt_id_value bigint, operation_key_value text, approved_build_contract_canonical_value text) RETURNS public.campaign_operations_operational_request
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE request_row public.campaign_operations_operational_request%ROWTYPE;
DECLARE attempt_row public.campaign_operations_dispatch_attempt%ROWTYPE;
DECLARE admission_row public.campaign_operations_request_production_admission%ROWTYPE;
DECLARE first_attempt_row public.campaign_operations_dispatch_attempt%ROWTYPE;
DECLARE enablement_row public.campaign_operations_production_enablement_event%ROWTYPE;
DECLARE current_enablement_row public.campaign_operations_production_enablement_event%ROWTYPE;
DECLARE changed public.campaign_operations_operational_request%ROWTYPE;
DECLARE outcome_count integer;
BEGIN
    SELECT candidate.* INTO STRICT request_row
    FROM public.campaign_operations_operational_request candidate
    WHERE candidate.operational_request_id = target_request_id
    FOR UPDATE;

    SELECT candidate.* INTO STRICT attempt_row
    FROM public.campaign_operations_dispatch_attempt candidate
    WHERE candidate.dispatch_attempt_id = dispatch_attempt_id_value;

    SELECT candidate.* INTO STRICT admission_row
    FROM public.campaign_operations_request_production_admission candidate
    WHERE candidate.operational_request_id = target_request_id;

    -- The immutable admission records the first acquisition key.  Recovery
    -- may produce a later Attempt V2 under a new caller key; bind ownership
    -- is therefore the exact producing attempt, while this relationship
    -- proves the admission still belongs to its original first attempt.
    SELECT candidate.* INTO STRICT first_attempt_row
    FROM public.campaign_operations_dispatch_attempt candidate
    WHERE candidate.request_production_admission_id =
          admission_row.request_production_admission_id
      AND candidate.attempt_contract_version = 2
      AND candidate.attempt_ordinal = 1;

    SELECT candidate.* INTO STRICT enablement_row
    FROM public.campaign_operations_production_enablement_event candidate
    WHERE candidate.production_enablement_event_id =
          attempt_row.production_enablement_event_id;

    SELECT candidate.* INTO STRICT current_enablement_row
    FROM public.campaign_operations_production_enablement_event candidate
    ORDER BY candidate.resulting_version DESC
    LIMIT 1;

    SELECT count(*)::integer INTO outcome_count
    FROM public.campaign_operations_dispatch_attempt_outcome outcome
    WHERE outcome.dispatch_attempt_id = dispatch_attempt_id_value;

    -- This is the exact H1-produced predecessor.  The mutable Boolean is
    -- checked as a one-way admission/Attempt V2 witness, while all durable
    -- production identities are re-read from their authoritative rows.
    IF request_row.request_state <> 'dispatching' OR
       request_row.state_version <> expected_version_value OR
       request_row.production_dispatch_enabled IS DISTINCT FROM true OR
       request_row.lease_token_hash IS DISTINCT FROM lease_digest_value OR
       request_row.lease_expires_at <= pg_catalog.transaction_timestamp() OR
       attempt_row.attempt_contract_version <> 2 OR
       attempt_row.operational_request_id <> target_request_id OR
       attempt_row.request_identity_canonical <>
           request_row.request_identity_canonical OR
       attempt_row.expected_request_version <> expected_version_value - 1 OR
       attempt_row.resulting_request_version <> expected_version_value OR
       attempt_row.lease_token_digest <> lease_digest_value OR
       attempt_row.lease_expires_at <> request_row.lease_expires_at OR
       attempt_row.dispatcher_identity <> request_row.dispatcher_identity OR
       attempt_row.operation_key IS DISTINCT FROM operation_key_value OR
       attempt_row.approved_build_contract_canonical IS DISTINCT FROM
           approved_build_contract_canonical_value OR
       admission_row.operational_request_id <> target_request_id OR
       admission_row.request_identity_canonical <>
           request_row.request_identity_canonical OR
       admission_row.expected_request_version <>
           first_attempt_row.expected_request_version OR
       first_attempt_row.operational_request_id <> target_request_id OR
       first_attempt_row.request_production_admission_id <>
           admission_row.request_production_admission_id OR
       first_attempt_row.operation_key IS DISTINCT FROM
           admission_row.dispatch_operation_key OR
       admission_row.request_production_admission_id <>
           attempt_row.request_production_admission_id OR
       attempt_row.production_enablement_event_id <>
           admission_row.production_enablement_event_id OR
       attempt_row.request_production_admission_canonical <>
           admission_row.admission_identity_canonical OR
       attempt_row.request_production_admission_hash <>
           admission_row.admission_identity_hash OR
       attempt_row.production_enablement_event_canonical <>
           enablement_row.enablement_identity_canonical OR
       attempt_row.production_enablement_event_hash <>
           enablement_row.enablement_identity_hash OR
       enablement_row.event_kind <> 'enable' OR
       enablement_row.production_enablement_event_id <>
           current_enablement_row.production_enablement_event_id OR
       current_enablement_row.event_kind <> 'enable' OR
       current_enablement_row.approved_build_contract_canonical IS DISTINCT FROM
           approved_build_contract_canonical_value OR
       enablement_row.approved_build_contract_canonical IS DISTINCT FROM
           approved_build_contract_canonical_value OR
       admission_row.approved_build_contract_canonical IS DISTINCT FROM
           approved_build_contract_canonical_value OR
       outcome_count <> 0 THEN
        RAISE EXCEPTION
            'campaign operations production bind predecessor invalid'
            USING ERRCODE = '40001';
    END IF;

    UPDATE public.campaign_operations_operational_request candidate
       SET request_state = 'bound',
           state_version = candidate.state_version + 1,
           lease_token_hash = NULL,
           lease_expires_at = NULL,
           dispatcher_identity = NULL,
           updated_at = pg_catalog.transaction_timestamp()
     WHERE candidate.operational_request_id = target_request_id
       AND candidate.request_state = 'dispatching'
       AND candidate.state_version = expected_version_value
       AND candidate.lease_token_hash = lease_digest_value
       AND candidate.lease_expires_at > pg_catalog.transaction_timestamp()
       AND candidate.production_dispatch_enabled = true
     RETURNING candidate.* INTO changed;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'campaign operations production bind compare-and-set lost'
            USING ERRCODE = 'P0001';
    END IF;
    RETURN changed;
END;
$$;


--
-- Name: transition_campaign_operations_request_cancelled(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_operations_request_cancelled(target_request_id bigint, expected_version integer) RETURNS public.campaign_operations_operational_request
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE changed campaign_operations_operational_request%ROWTYPE;
BEGIN
    UPDATE campaign_operations_operational_request
       SET request_state = 'cancelled',
           state_version = state_version + 1,
           lease_token_hash = NULL,
           lease_expires_at = NULL,
           dispatcher_identity = NULL,
           updated_at = transaction_timestamp()
     WHERE operational_request_id = target_request_id
       AND state_version = expected_version
       AND request_state IN ('ready', 'dispatching')
       AND NOT EXISTS (
           SELECT 1 FROM campaign_operations_request_binding
           WHERE operational_request_id = target_request_id)
       AND NOT EXISTS (
           SELECT 1
           FROM campaign_operations_operational_request request
           JOIN experiment_recommendation_campaign_materialization_member
               member
             ON member.recommendation_campaign_materialization_id =
                request.recommendation_campaign_materialization_id
           JOIN experiment_recommendation_conversion_execution execution
             ON execution.recommendation_conversion_proposal_id =
                member.recommendation_conversion_proposal_id
           WHERE request.operational_request_id = target_request_id)
       AND (
           request_state = 'ready' OR NOT EXISTS (
               SELECT 1
               FROM campaign_operations_dispatch_attempt attempt
               JOIN campaign_operations_dispatch_attempt_outcome outcome
                 ON outcome.dispatch_attempt_id =
                    attempt.dispatch_attempt_id
               WHERE attempt.operational_request_id =
                    target_request_id
                 AND attempt.attempt_ordinal = (
                     SELECT max(latest.attempt_ordinal)
                     FROM campaign_operations_dispatch_attempt latest
                     WHERE latest.operational_request_id =
                         target_request_id)))
    RETURNING * INTO changed;
    IF changed.operational_request_id IS NULL THEN
        RAISE EXCEPTION 'campaign operations request cancellation conflict'
            USING ERRCODE = '40001';
    END IF;
    RETURN changed;
END;
$$;


--
-- Name: transition_campaign_operations_request_dispatch_production_v2(bigint, integer, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_operations_request_dispatch_production_v2(target_request_id bigint, expected_version_value integer, lease_digest_value text, lease_expires_at_value timestamp with time zone, operation_key_value text, requesting_actor_value text, approved_build_contract_canonical_value text) RETURNS public.campaign_operations_dispatch_attempt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE scheduler_record record;
DECLARE head public.campaign_operations_production_enablement_event%ROWTYPE;
DECLARE request_candidate
    public.campaign_operations_operational_request%ROWTYPE;
DECLARE request public.campaign_operations_operational_request%ROWTYPE;
DECLARE admission
    public.campaign_operations_request_production_admission%ROWTYPE;
DECLARE attempt public.campaign_operations_dispatch_attempt%ROWTYPE;
DECLARE next_ordinal integer;
BEGIN
    IF operation_key_value IS NULL OR octet_length(operation_key_value) > 128 OR
       operation_key_value !~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$' THEN
        RAISE EXCEPTION 'invalid production operation key'
            USING ERRCODE = '22023';
    END IF;
    SELECT candidate.* INTO attempt
    FROM public.campaign_operations_production_acquire_replay_v2(
        target_request_id, expected_version_value, lease_digest_value,
        lease_expires_at_value, operation_key_value, requesting_actor_value,
        approved_build_contract_canonical_value) candidate;
    IF FOUND THEN RETURN attempt; END IF;
    SELECT * INTO STRICT scheduler_record
    FROM public.campaign_operations_scheduler_protocol_evidence_lock_v1();
    IF NOT scheduler_record.evidence_complete THEN
        RAISE EXCEPTION 'production dispatch scheduler evidence incomplete'
            USING ERRCODE = '23514';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock_shared(19055, 1);
    SELECT * INTO STRICT head
    FROM public.campaign_operations_production_enablement_event candidate
    ORDER BY candidate.resulting_version DESC LIMIT 1;
    IF head.event_kind <> 'enable' OR
       head.scheduler_protocol_evidence_canonical <>
           scheduler_record.evidence_canonical OR
       head.approved_build_contract_canonical <>
           approved_build_contract_canonical_value THEN
        RAISE EXCEPTION 'production dispatch enablement is ineffective'
            USING ERRCODE = '23514';
    END IF;
    -- Optimistic identity read only; no tuple lock is taken before the
    -- authorization, budget, and campaign/completion boundaries.
    SELECT * INTO STRICT request_candidate
    FROM public.campaign_operations_operational_request candidate
    WHERE candidate.operational_request_id = target_request_id;

    PERFORM public.lock_campaign_operations_authorization_head(
        request_candidate.operational_campaign_id,
        request_candidate.action_kind);
    PERFORM public.lock_campaign_operations_budget_head(
        request_candidate.operational_campaign_id);
    PERFORM public.lock_campaign_operations_campaign(
        request_candidate.operational_campaign_id);
    PERFORM public.lock_campaign_operations_reservation(
        request_candidate.reservation_id);
    SELECT locked.* INTO STRICT request
    FROM public.lock_campaign_operations_request(target_request_id) locked;
    IF request.operational_campaign_id <>
           request_candidate.operational_campaign_id OR
       request.reservation_id <> request_candidate.reservation_id OR
       request.action_kind <> request_candidate.action_kind THEN
        RAISE EXCEPTION 'production dispatch request identity changed'
            USING ERRCODE = '40001';
    END IF;

    SELECT candidate.* INTO attempt
    FROM public.campaign_operations_production_acquire_replay_v2(
        target_request_id, expected_version_value, lease_digest_value,
        lease_expires_at_value, operation_key_value, requesting_actor_value,
        approved_build_contract_canonical_value) candidate;
    IF FOUND THEN RETURN attempt; END IF;
    IF request.request_state <> 'ready' OR
       request.state_version <> expected_version_value OR
       request.lease_token_hash IS NOT NULL OR
       request.lease_expires_at IS NOT NULL OR
       request.dispatcher_identity IS NOT NULL OR
       lease_expires_at_value <= pg_catalog.transaction_timestamp() OR
       request.production_dispatch_enabled IS DISTINCT FROM EXISTS (
         SELECT 1
         FROM public.campaign_operations_request_production_admission existing
         WHERE existing.operational_request_id = target_request_id) THEN
        RAISE EXCEPTION 'production dispatch request compare-and-set lost'
            USING ERRCODE = '40001';
    END IF;
    SELECT coalesce(max(existing.attempt_ordinal), 0) + 1
      INTO next_ordinal
    FROM public.campaign_operations_dispatch_attempt existing
    WHERE existing.operational_request_id = target_request_id;
    INSERT INTO public.campaign_operations_production_transition_context(
        backend_pid, transaction_id, transition_kind,
        operational_request_id, operation_key)
    VALUES(pg_catalog.pg_backend_pid(), pg_catalog.txid_current(),
           'dispatch_v2', target_request_id, operation_key_value);

    SELECT existing.* INTO admission
    FROM public.campaign_operations_request_production_admission existing
    WHERE existing.operational_request_id = target_request_id;
    IF NOT FOUND THEN
        admission.request_production_admission_id := pg_catalog.nextval(
            pg_catalog.pg_get_serial_sequence(
              'public.campaign_operations_request_production_admission',
              'request_production_admission_id'));
        admission.operational_request_id := target_request_id;
        admission.request_identity_canonical :=
            request.request_identity_canonical;
        admission.expected_request_version := expected_version_value;
        admission.dispatch_operation_key := operation_key_value;
        admission.production_enablement_event_id :=
            head.production_enablement_event_id;
        admission.enable_event_canonical := head.enablement_identity_canonical;
        admission.requesting_actor := requesting_actor_value;
        admission.original_executing_service_principal := session_user::text;
        admission.approved_build_contract_canonical :=
            approved_build_contract_canonical_value;
        admission.approved_build_contract_hash :=
            head.approved_build_contract_hash;
        admission.capability := 'campaign_operations_production_dispatcher';
        admission.admission_contract_version := 1;
        admission.admitted_at := pg_catalog.transaction_timestamp();
        admission.admission_identity_canonical :=
            public.campaign_operations_request_production_admission_canonical_v1(
                admission);
        admission.admission_identity_hash :=
            public.campaign_operations_tagged_fnv1a64(
                admission.admission_identity_canonical);
        INSERT INTO public.campaign_operations_request_production_admission
            SELECT admission.*;
    ELSIF admission.request_identity_canonical <>
              request.request_identity_canonical OR
          admission.admission_identity_canonical <>
              public.campaign_operations_request_production_admission_canonical_v1(
                  admission) OR
          admission.admission_identity_hash <>
              public.campaign_operations_tagged_fnv1a64(
                  admission.admission_identity_canonical) THEN
        RAISE EXCEPTION 'request production admission evidence corrupt'
            USING ERRCODE = '23514';
    END IF;

    UPDATE public.campaign_operations_operational_request candidate
       SET request_state = 'dispatching',
           state_version = candidate.state_version + 1,
           lease_token_hash = lease_digest_value,
           lease_expires_at = lease_expires_at_value,
           dispatcher_identity = requesting_actor_value,
           production_dispatch_enabled = true,
           updated_at = pg_catalog.transaction_timestamp()
     WHERE candidate.operational_request_id = target_request_id
       AND candidate.request_state = 'ready'
       AND candidate.state_version = expected_version_value;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'production dispatch request compare-and-set lost'
            USING ERRCODE = '40001';
    END IF;

    attempt.dispatch_attempt_id := pg_catalog.nextval(
        pg_catalog.pg_get_serial_sequence(
          'public.campaign_operations_dispatch_attempt',
          'dispatch_attempt_id'));
    attempt.operational_request_id := target_request_id;
    attempt.request_identity_canonical := request.request_identity_canonical;
    attempt.attempt_ordinal := next_ordinal;
    attempt.expected_request_version := expected_version_value;
    attempt.resulting_request_version := expected_version_value + 1;
    attempt.lease_token_digest := lease_digest_value;
    attempt.lease_expires_at := lease_expires_at_value;
    attempt.dispatcher_identity := requesting_actor_value;
    attempt.attempt_contract_version := 2;
    attempt.acquired_at := pg_catalog.transaction_timestamp();
    attempt.request_production_admission_id :=
        admission.request_production_admission_id;
    attempt.request_production_admission_canonical :=
        admission.admission_identity_canonical;
    attempt.request_production_admission_hash :=
        admission.admission_identity_hash;
    attempt.production_enablement_event_id :=
        head.production_enablement_event_id;
    attempt.production_enablement_event_canonical :=
        head.enablement_identity_canonical;
    attempt.production_enablement_event_hash := head.enablement_identity_hash;
    attempt.operation_key := operation_key_value;
    attempt.requesting_actor := requesting_actor_value;
    attempt.original_executing_service_principal := session_user::text;
    attempt.approved_build_contract_canonical :=
        approved_build_contract_canonical_value;
    attempt.approved_build_contract_hash := head.approved_build_contract_hash;
    attempt.production_capability :=
        'campaign_operations_production_dispatcher';
    attempt.attempt_identity_canonical :=
        public.campaign_operations_dispatch_attempt_v2_canonical(attempt);
    attempt.attempt_identity_hash :=
        public.campaign_operations_tagged_fnv1a64(
            attempt.attempt_identity_canonical);
    INSERT INTO public.campaign_operations_dispatch_attempt SELECT attempt.*;
    INSERT INTO public.campaign_operations_dispatch_audit_reference_event(
        operational_campaign_id, operational_request_id, dispatch_attempt_id,
        dispatch_attempt_outcome_id, cause_kind, actor_identity, capability,
        prior_version, resulting_version, outcome, replay_disposition,
        diagnostic_code, request_production_admission_id,
        production_enablement_event_id)
    VALUES(request.operational_campaign_id, target_request_id,
        attempt.dispatch_attempt_id, NULL, 'dispatch_lease_acquired',
        requesting_actor_value, 'campaign_operations_production_dispatcher',
        expected_version_value, expected_version_value + 1, 'recorded',
        'new_operation', 'dispatch_lease_acquired',
        admission.request_production_admission_id,
        head.production_enablement_event_id);
    DELETE FROM public.campaign_operations_production_transition_context context
    WHERE context.backend_pid = pg_catalog.pg_backend_pid()
      AND context.transaction_id = pg_catalog.txid_current();
    RETURN attempt;
END;
$_$;


--
-- Name: transition_campaign_operations_request_dispatching(bigint, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_operations_request_dispatching(target_request_id bigint, expected_version_value integer, lease_digest_value text, dispatcher_value text) RETURNS public.campaign_operations_operational_request
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE changed public.campaign_operations_operational_request%ROWTYPE;
BEGIN
    IF NOT public.campaign_operations_isolated_v1_authority_valid() THEN
        RAISE EXCEPTION
          'campaign operations Attempt V1 isolated authority required'
          USING ERRCODE = '42501';
    END IF;
    UPDATE public.campaign_operations_operational_request
       SET request_state = 'dispatching',
           state_version = state_version + 1,
           lease_token_hash = lease_digest_value,
           lease_expires_at = transaction_timestamp() + interval '5 minutes',
           dispatcher_identity = dispatcher_value,
           updated_at = transaction_timestamp()
     WHERE operational_request_id = target_request_id
       AND request_state = 'ready'
       AND state_version = expected_version_value
       AND lease_token_hash IS NULL
       AND lease_expires_at IS NULL
       AND dispatcher_identity IS NULL
       AND production_dispatch_enabled = false
       AND NOT EXISTS (
         SELECT 1
         FROM public.campaign_operations_production_enablement_event)
     RETURNING * INTO changed;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations lease compare-and-set lost'
            USING ERRCODE = 'P0001';
    END IF;
    RETURN changed;
END;
$$;


--
-- Name: transition_campaign_operations_request_ready_recovered(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_operations_request_ready_recovered(target_request_id bigint, expected_version integer) RETURNS public.campaign_operations_operational_request
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE changed campaign_operations_operational_request%ROWTYPE;
BEGIN
    UPDATE campaign_operations_operational_request
       SET request_state = 'ready',
           state_version = state_version + 1,
           lease_token_hash = NULL,
           lease_expires_at = NULL,
           dispatcher_identity = NULL,
           updated_at = transaction_timestamp()
     WHERE operational_request_id = target_request_id
       AND state_version = expected_version
       AND request_state = 'dispatching'
       AND lease_expires_at <= transaction_timestamp()
       AND NOT EXISTS (
           SELECT 1 FROM campaign_operations_request_binding
           WHERE operational_request_id = target_request_id)
       AND NOT EXISTS (
           SELECT 1
           FROM campaign_operations_operational_request request
           JOIN experiment_recommendation_campaign_materialization_member
               member
             ON member.recommendation_campaign_materialization_id =
                request.recommendation_campaign_materialization_id
           JOIN experiment_recommendation_conversion_execution execution
             ON execution.recommendation_conversion_proposal_id =
                member.recommendation_conversion_proposal_id
           WHERE request.operational_request_id = target_request_id)
       AND NOT EXISTS (
           SELECT 1
           FROM campaign_operations_dispatch_attempt attempt
           JOIN campaign_operations_dispatch_attempt_outcome outcome
             ON outcome.dispatch_attempt_id = attempt.dispatch_attempt_id
           WHERE attempt.operational_request_id = target_request_id
             AND attempt.attempt_ordinal = (
                 SELECT max(latest.attempt_ordinal)
                 FROM campaign_operations_dispatch_attempt latest
                 WHERE latest.operational_request_id =
                     target_request_id))
    RETURNING * INTO changed;
    IF changed.operational_request_id IS NULL THEN
        RAISE EXCEPTION 'campaign operations lease recovery conflict'
            USING ERRCODE = '40001';
    END IF;
    RETURN changed;
END;
$$;


--
-- Name: transition_campaign_operations_reservation_committed(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_operations_reservation_committed(target_reservation_id bigint, expected_version_value integer) RETURNS public.campaign_operations_reservation
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE changed campaign_operations_reservation%ROWTYPE;
BEGIN
    UPDATE campaign_operations_reservation
       SET reservation_state = 'committed',
           state_version = state_version + 1,
           updated_at = transaction_timestamp()
     WHERE reservation_id = target_reservation_id
       AND reservation_state = 'held'
       AND state_version = expected_version_value
       AND (expires_at IS NULL OR expires_at > transaction_timestamp())
     RETURNING * INTO changed;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign operations reservation compare-and-set lost'
            USING ERRCODE = 'P0001';
    END IF;
    RETURN changed;
END;
$$;


--
-- Name: transition_campaign_operations_reservation_released(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_campaign_operations_reservation_released(target_reservation_id bigint, expected_version integer) RETURNS public.campaign_operations_reservation
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE changed campaign_operations_reservation%ROWTYPE;
BEGIN
    UPDATE campaign_operations_reservation
       SET reservation_state = 'released',
           state_version = state_version + 1,
           updated_at = transaction_timestamp()
     WHERE reservation_id = target_reservation_id
       AND state_version = expected_version
       AND reservation_state = 'held'
    RETURNING * INTO changed;
    IF changed.reservation_id IS NULL THEN
        RAISE EXCEPTION 'campaign operations reservation release conflict'
            USING ERRCODE = '40001';
    END IF;
    RETURN changed;
END;
$$;


--
-- Name: upsert_matrix_element(bigint, text, integer, integer, integer, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_matrix_element(p_model_id bigint, p_param_name text, p_n_rows integer, p_n_cols integer, p_row_idx integer, p_col_idx integer, p_value double precision) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO matrix (model_id, param_name, n_rows, n_cols, row_idx, col_idx, value)
    VALUES (p_model_id, p_param_name, p_n_rows, p_n_cols, p_row_idx, p_col_idx, p_value)
    ON CONFLICT (model_id, param_name, row_idx, col_idx) DO UPDATE
      SET value = EXCLUDED.value,
          n_rows = EXCLUDED.n_rows,
          n_cols = EXCLUDED.n_cols;
END;
$$;


--
-- Name: validate_campaign_operations_dispatch_attempt_v2_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_campaign_operations_dispatch_attempt_v2_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected_canonical text;
BEGIN
    IF NEW.attempt_contract_version = 1 THEN RETURN NEW; END IF;
    IF NOT public.campaign_operations_production_context_valid_v1(
         'dispatch_v2', NEW.operational_request_id, NEW.operation_key) THEN
        RAISE EXCEPTION
          'fixed production acquisition transition context required'
          USING ERRCODE = '42501';
    END IF;
    expected_canonical :=
        public.campaign_operations_dispatch_attempt_v2_canonical(NEW);
    IF NEW.attempt_identity_canonical <> expected_canonical OR
       NEW.attempt_identity_hash <>
           public.campaign_operations_tagged_fnv1a64(expected_canonical) OR
       NEW.request_production_admission_hash <>
           public.campaign_operations_tagged_fnv1a64(
               NEW.request_production_admission_canonical) OR
       NEW.production_enablement_event_hash <>
           public.campaign_operations_tagged_fnv1a64(
               NEW.production_enablement_event_canonical) OR
       NEW.approved_build_contract_hash <>
           public.campaign_operations_tagged_fnv1a64(
               NEW.approved_build_contract_canonical) OR
       NOT EXISTS (
           SELECT 1
           FROM public.campaign_operations_request_production_admission admission
           WHERE admission.request_production_admission_id =
                 NEW.request_production_admission_id
             AND admission.operational_request_id =
                 NEW.operational_request_id
             AND admission.request_identity_canonical =
                 NEW.request_identity_canonical
             AND admission.admission_identity_canonical =
                 NEW.request_production_admission_canonical
             AND admission.admission_identity_hash =
                 NEW.request_production_admission_hash) THEN
        RAISE EXCEPTION 'production dispatch Attempt V2 canonical mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_campaign_operations_manager_attempt_completeness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_campaign_operations_manager_attempt_completeness() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE attempt public.campaign_operations_dispatch_attempt%ROWTYPE;
DECLARE evidence public.campaign_operations_dispatch_manager_operation%ROWTYPE;
DECLARE evidence_count integer;
DECLARE expected_source text;
BEGIN
    SELECT candidate.* INTO attempt
    FROM public.campaign_operations_dispatch_attempt candidate
    WHERE candidate.dispatch_attempt_id = NEW.dispatch_attempt_id;
    IF NOT FOUND OR attempt.attempt_contract_version <> 2 OR
       attempt.operation_key NOT LIKE 'mgr-v1:%' THEN
        RETURN NEW;
    END IF;

    -- The source relation is Manager-only.  Treat a caller which merely
    -- borrows the reserved key namespace as corrupt rather than permitting a
    -- source row for a non-Manager Attempt V2.
    IF attempt.dispatcher_identity <> 'campaign_operations_manager' OR
       attempt.requesting_actor <> 'campaign_operations_manager' OR
       attempt.operation_key !~ '^mgr-v1:fnv1a64:[0-9a-f]{16}:[1-9][0-9]*$' THEN
        RAISE EXCEPTION 'H3 Manager Attempt V2 identity is invalid'
            USING ERRCODE = '23514';
    END IF;

    SELECT count(*)::integer INTO evidence_count
    FROM public.campaign_operations_dispatch_manager_operation candidate
    WHERE candidate.dispatch_attempt_id = attempt.dispatch_attempt_id;
    IF evidence_count <> 1 THEN
        RAISE EXCEPTION 'H3 Manager Attempt V2 source evidence incomplete'
            USING ERRCODE = '23514';
    END IF;

    SELECT candidate.* INTO STRICT evidence
    FROM public.campaign_operations_dispatch_manager_operation candidate
    WHERE candidate.dispatch_attempt_id = attempt.dispatch_attempt_id;
    expected_source := 'campaign_operations_manager_request_operation_v1' ||
        ';request_identity_canonical=' ||
        octet_length(attempt.request_identity_canonical)::text || ':' ||
        attempt.request_identity_canonical ||
        ';expected_request_version=' || attempt.expected_request_version::text;
    IF evidence.operational_request_id <> attempt.operational_request_id OR
       evidence.operation_key <> attempt.operation_key OR
       evidence.request_identity_canonical <> attempt.request_identity_canonical OR
       evidence.expected_request_version <> attempt.expected_request_version OR
       evidence.source_canonical <> expected_source OR
       evidence.source_hash <> public.campaign_operations_tagged_fnv1a64(
           evidence.source_canonical) OR
       evidence.operation_key <> 'mgr-v1:' || evidence.source_hash || ':' ||
           evidence.expected_request_version::text OR
       evidence.contract_version <> 1 THEN
        RAISE EXCEPTION 'H3 Manager Attempt V2 source evidence mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: validate_campaign_operations_manager_operation_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_campaign_operations_manager_operation_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE expected_source text;
DECLARE expected_request_identity text;
BEGIN
    IF NEW.contract_version <> 1 OR
       NEW.operation_key !~ '^mgr-v1:fnv1a64:[0-9a-f]{16}:[1-9][0-9]*$' OR
       NEW.expected_request_version <= 0 THEN
        RAISE EXCEPTION 'H3 manager operation typed evidence invalid'
            USING ERRCODE = '23514';
    END IF;
    SELECT 'campaign_operations_manager_request_operation_v1' ||
           ';request_identity_canonical=' ||
           octet_length(attempt.request_identity_canonical)::text || ':' ||
           attempt.request_identity_canonical ||
           ';expected_request_version=' ||
           attempt.expected_request_version::text,
           attempt.request_identity_canonical
      INTO expected_source, expected_request_identity
    FROM public.campaign_operations_dispatch_attempt attempt
    WHERE attempt.dispatch_attempt_id = NEW.dispatch_attempt_id
      AND attempt.attempt_contract_version = 2
      AND attempt.operational_request_id = NEW.operational_request_id
      AND attempt.operation_key = NEW.operation_key
      AND attempt.expected_request_version = NEW.expected_request_version
      AND attempt.dispatcher_identity = 'campaign_operations_manager'
      AND attempt.requesting_actor = 'campaign_operations_manager';
    IF NOT FOUND OR NEW.request_identity_canonical <> expected_request_identity OR
       NEW.source_canonical <> expected_source OR
       NEW.source_hash <> public.campaign_operations_tagged_fnv1a64(
           NEW.source_canonical) OR
       NEW.operation_key <> 'mgr-v1:' || NEW.source_hash || ':' ||
           NEW.expected_request_version::text THEN
        RAISE EXCEPTION 'H3 manager operation source evidence mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: validate_campaign_operations_production_enablement_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_campaign_operations_production_enablement_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE predecessor
    public.campaign_operations_production_enablement_event%ROWTYPE;
DECLARE expected_canonical text;
BEGIN
    IF NOT public.campaign_operations_production_context_valid_v1(
         NEW.event_kind, NULL, NEW.operation_key) THEN
        RAISE EXCEPTION
          'fixed production enablement transition context required'
          USING ERRCODE = '42501';
    END IF;
    expected_canonical :=
        public.campaign_operations_production_enablement_canonical_v1(NEW);
    IF NEW.enablement_identity_canonical <> expected_canonical OR
       NEW.enablement_identity_hash <>
               public.campaign_operations_tagged_fnv1a64(expected_canonical) OR
       (NEW.event_kind = 'enable' AND (
           NEW.scheduler_protocol_evidence_hash <>
               public.campaign_operations_tagged_fnv1a64(
                   NEW.scheduler_protocol_evidence_canonical) OR
           NEW.scheduler_protocol_evidence_canonical <>
               public.campaign_operations_scheduler_protocol_evidence_canonical_v1(
                   NEW.scheduler_required_generation,
                   NEW.scheduler_cutover_state,
                   NEW.scheduler_cutover_completed_at,
                   NEW.scheduler_cutover_completed_by,
                   NEW.scheduler_cutover_executable_path,
                   NEW.scheduler_cutover_process_evidence) OR
           NEW.approved_build_contract_hash <>
               public.campaign_operations_tagged_fnv1a64(
                   NEW.approved_build_contract_canonical) OR
           NEW.approved_build_contract_canonical <>
               public.campaign_operations_manager_build_canonical_v1(
                   NEW.manager_service_contract,
                   NEW.approved_build_source_commit,
                   NEW.approved_build_compiler_contract,
                   NEW.approved_build_executable_sha256))) THEN
        RAISE EXCEPTION 'production enablement canonical mismatch'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.predecessor_event_id IS NULL THEN
        IF NEW.event_kind <> 'enable' OR NEW.expected_prior_version <> 0 OR
           NEW.resulting_version <> 1 OR
           NEW.predecessor_event_canonical <> '' OR
           EXISTS (SELECT 1 FROM
               public.campaign_operations_production_enablement_event) THEN
            RAISE EXCEPTION 'production enablement genesis mismatch'
                USING ERRCODE = '23514';
        END IF;
    ELSE
        SELECT * INTO STRICT predecessor
        FROM public.campaign_operations_production_enablement_event
        WHERE production_enablement_event_id = NEW.predecessor_event_id;
        IF predecessor.enablement_identity_canonical <>
               NEW.predecessor_event_canonical OR
           predecessor.resulting_version <> NEW.expected_prior_version OR
           predecessor.event_kind = NEW.event_kind OR
           EXISTS (SELECT 1
                   FROM public.campaign_operations_production_enablement_event later
                   WHERE later.resulting_version >
                         predecessor.resulting_version) THEN
            RAISE EXCEPTION 'production enablement predecessor mismatch'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_campaign_ops_production_admission_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_campaign_ops_production_admission_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected_canonical text;
BEGIN
    IF NOT public.campaign_operations_production_context_valid_v1(
         'dispatch_v2', NEW.operational_request_id,
         NEW.dispatch_operation_key) THEN
        RAISE EXCEPTION
          'fixed production acquisition transition context required'
          USING ERRCODE = '42501';
    END IF;
    expected_canonical :=
        public.campaign_operations_request_production_admission_canonical_v1(
            NEW);
    IF NEW.admission_identity_canonical <> expected_canonical OR
       NEW.admission_identity_hash <>
           public.campaign_operations_tagged_fnv1a64(expected_canonical) OR
       NEW.approved_build_contract_hash <>
           public.campaign_operations_tagged_fnv1a64(
               NEW.approved_build_contract_canonical) OR
       NOT EXISTS (
           SELECT 1
           FROM public.campaign_operations_operational_request request
           JOIN public.campaign_operations_production_enablement_event enablement
             ON enablement.production_enablement_event_id =
                NEW.production_enablement_event_id
           WHERE request.operational_request_id = NEW.operational_request_id
             AND request.request_identity_canonical =
                 NEW.request_identity_canonical
             AND request.state_version = NEW.expected_request_version
             AND NOT request.production_dispatch_enabled
             AND enablement.event_kind = 'enable'
             AND enablement.enablement_identity_canonical =
                 NEW.enable_event_canonical
             AND enablement.approved_build_contract_canonical =
                 NEW.approved_build_contract_canonical) THEN
        RAISE EXCEPTION 'request production admission canonical mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_campaign_profitability_prospective_outcome_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_campaign_profitability_prospective_outcome_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM experiment_recommendation_ranking_snapshot snapshot
        JOIN experiment_recommendation_ranking_member member
          ON member.recommendation_ranking_snapshot_id =
             snapshot.recommendation_ranking_snapshot_id
        JOIN experiment experiment_row
          ON experiment_row.experiment_id = NEW.source_experiment_id
        JOIN model source_model
          ON source_model.model_id = NEW.source_model_id
        WHERE snapshot.recommendation_ranking_snapshot_id =
                  NEW.ranking_snapshot_id
          AND snapshot.status = 'completed'
          AND snapshot.evaluation_run_filter = NEW.source_evaluation_run_id
          AND member.source_experiment_id = NEW.source_experiment_id
          AND member.source_model_id = NEW.source_model_id
          AND source_model.experiment_id = NEW.source_experiment_id
          AND experiment_row.last_model_id = NEW.source_model_id
          AND experiment_row.symbol = NEW.symbol
          AND experiment_row.prediction_horizon = NEW.prediction_horizon
          AND abs(experiment_row.c_next_threshold - NEW.threshold_logret) <=
              0.0000001
          AND experiment_row.infer_end::date < NEW.outcome_start
    ) THEN
        RAISE EXCEPTION
            'prospective outcome provenance does not match an exact frozen final source model';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_economic_event_actual_observation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_economic_event_actual_observation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_source_name text;
    event_release_at timestamptz;
    observation_available_at timestamptz;
BEGIN
    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            'economic_event_actual_observation:' ||
            NEW.economic_event_id::text,
            0));

    SELECT source_agency, event_timestamp_utc
    INTO event_source_name, event_release_at
    FROM public.economic_event
    WHERE economic_event_id = NEW.economic_event_id
    FOR KEY SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'economic event actual observation references missing event'
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF NEW.source_role = 'authoritative' AND
       NEW.source_name <> event_source_name
    THEN
        RAISE EXCEPTION 'authoritative actual observation source mismatch'
            USING ERRCODE = 'check_violation';
    END IF;

    -- Generated columns are populated after BEFORE triggers.  Derive the
    -- candidate boundary from the submitted evidence instead of reading
    -- NEW.proven_available_at before PostgreSQL has computed it.
    observation_available_at := CASE NEW.availability_proof
        WHEN 'source_publication' THEN NEW.source_publication_at
        WHEN 'system_observation' THEN NEW.observed_at
    END;

    IF observation_available_at < event_release_at THEN
        RAISE EXCEPTION 'economic event actual observation predates release event'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_economic_event_release_actual(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_economic_event_release_actual() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    official_source_agency text;
    official_event_timestamp timestamptz;
BEGIN
    -- Serialize observations for one authoritative event so concurrent
    -- inserts cannot evade revision-order validation.
    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            'economic_event_release_actual:' || NEW.economic_event_id::text,
            0));

    SELECT source_agency, event_timestamp_utc
    INTO official_source_agency, official_event_timestamp
    FROM economic_event
    WHERE economic_event_id = NEW.economic_event_id
    FOR KEY SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'economic event release actual references missing event'
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    IF NEW.source_agency <> official_source_agency THEN
        RAISE EXCEPTION 'economic event release actual source agency mismatch'
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.available_at < official_event_timestamp THEN
        RAISE EXCEPTION 'economic event release actual predates release event'
            USING ERRCODE = 'check_violation';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM economic_event_release_actual existing
        WHERE existing.economic_event_id = NEW.economic_event_id
          AND (
              (existing.revision_sequence < NEW.revision_sequence AND
               existing.available_at > NEW.available_at) OR
              (existing.revision_sequence > NEW.revision_sequence AND
               existing.available_at < NEW.available_at)
          )
    ) THEN
        RAISE EXCEPTION 'economic event release actual revision order conflict'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_inference_profitability_observation_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_inference_profitability_observation_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM inference_eval_result ier
        JOIN model m ON m.model_id = NEW.model_id
        WHERE ier.id = NEW.inference_eval_result_id
          AND ier.model_id = NEW.model_id
          AND ier.status = 'completed'
          AND ier.inference_scope = NEW.inference_scope
          AND ier.checkpoint_eval_id IS NOT DISTINCT FROM NEW.checkpoint_eval_id
          AND ier.from_date = NEW.inference_start
          AND ier.to_date = NEW.inference_end
          AND (
              (NEW.inference_scope = 'final' AND
               m.experiment_id IS NOT DISTINCT FROM NEW.experiment_id AND
               ier.parent_experiment_id IS NULL) OR
              (NEW.inference_scope = 'checkpoint' AND
               ier.parent_experiment_id = NEW.experiment_id)
          )
    ) THEN
        RAISE EXCEPTION
            'inference profitability provenance does not match completed inference evidence';
    END IF;

    IF NEW.inference_scope = 'checkpoint' AND NOT EXISTS (
        SELECT 1
        FROM experiment_checkpoint_eval ce
        WHERE ce.checkpoint_eval_id = NEW.checkpoint_eval_id
          AND ce.parent_experiment_id = NEW.experiment_id
          AND ce.checkpoint_model_id = NEW.model_id
    ) THEN
        RAISE EXCEPTION
            'checkpoint profitability provenance does not match checkpoint evaluation';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_recommendation_final_profitability_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_recommendation_final_profitability_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.final_profitability_provenance_version IS NULL THEN
        RETURN NEW;
    END IF;

    -- Mirror ResolveExactFinalInferenceResult(): the result reference is valid
    -- on its own, including when no profitability observation is available.
    IF NEW.source_final_inference_eval_result_id IS NOT NULL AND NOT EXISTS (
        WITH model_config AS (
            SELECT model_id,
                round(max(value) FILTER (WHERE col_idx = 1))::bigint AS
                    prediction_horizon,
                max(value) FILTER (WHERE col_idx = 2) AS threshold_logret,
                round(max(value) FILTER (WHERE col_idx = 3))::bigint AS
                    window_size,
                round(max(value) FILTER (WHERE col_idx = 4))::integer AS
                    label_rule_id,
                round(max(value) FILTER (WHERE col_idx = 10))::bigint AS
                    completed_epochs
            FROM matrix
            WHERE param_name = 'train_config_meta'
              AND row_idx = 0
              AND model_id = NEW.source_model_id
            GROUP BY model_id
            HAVING count(DISTINCT col_idx) FILTER (
                WHERE col_idx BETWEEN 0 AND 13) >= 14
        ), target_config AS (
            SELECT model_id,
                round(max(value) FILTER (WHERE col_idx = 0))::integer AS
                    target_type
            FROM matrix
            WHERE param_name = 'target_meta'
              AND row_idx = 0
              AND model_id = NEW.source_model_id
            GROUP BY model_id
        ), source_context AS (
            SELECT experiment.experiment_id,
                model.model_id,
                experiment.symbol,
                model_config.prediction_horizon,
                model_config.threshold_logret,
                model_config.window_size,
                model_config.label_rule_id,
                COALESCE(target_config.target_type, 1) AS target_type,
                experiment.infer_start::date::text AS inference_start,
                experiment.infer_end::date::text AS inference_end,
                model_config.completed_epochs
            FROM experiment
            JOIN model
              ON model.model_id = experiment.last_model_id
             AND model.experiment_id = experiment.experiment_id
            JOIN model_config ON model_config.model_id = model.model_id
            LEFT JOIN target_config ON target_config.model_id = model.model_id
            WHERE experiment.experiment_id = NEW.source_experiment_id
              AND experiment.last_model_id = NEW.source_model_id
              AND experiment.infer_start IS NOT NULL
              AND experiment.infer_end IS NOT NULL
              AND model_config.prediction_horizon =
                    experiment.prediction_horizon
              AND abs(model_config.threshold_logret -
                      experiment.c_next_threshold) <= 1e-7
        ), exact_result AS (
            SELECT result.id
            FROM source_context
            JOIN inference_eval_result result
              ON result.model_id = source_context.model_id
             AND result.symbol = source_context.symbol
             AND result.prediction_horizon =
                    source_context.prediction_horizon
             AND result.threshold_logret = source_context.threshold_logret
             AND result.window_size = source_context.window_size
             AND result.label_rule_id = source_context.label_rule_id
             AND result.target_type = source_context.target_type
             AND result.from_date = source_context.inference_start
             AND result.to_date = source_context.inference_end
             AND result.completed_epochs = source_context.completed_epochs
             AND result.status = 'completed'
             AND result.inference_scope = 'final'
             AND result.checkpoint_eval_id IS NULL
             AND result.parent_experiment_id IS NULL
        )
        SELECT 1
        FROM exact_result
        WHERE exact_result.id = NEW.source_final_inference_eval_result_id
          AND (SELECT count(*) FROM exact_result) = 1
    ) THEN
        RAISE EXCEPTION
            'recommendation FINAL inference provenance mismatch'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.source_final_profitability_observation_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM inference_profitability_observation observation
        WHERE observation.profitability_observation_id =
                  NEW.source_final_profitability_observation_id
          AND observation.experiment_id = NEW.source_experiment_id
          AND observation.model_id = NEW.source_model_id
          AND observation.inference_eval_result_id =
                  NEW.source_final_inference_eval_result_id
          AND observation.inference_scope = 'final'
          AND observation.checkpoint_eval_id IS NULL
          AND observation.inference_start =
                  NEW.source_final_profitability_inference_start
          AND observation.inference_end =
                  NEW.source_final_profitability_inference_end
          AND observation.actionable_count =
                  NEW.source_final_profitability_actionable_count
          AND observation.aggregate_terminal_horizon_log_return_sum =
                  NEW.source_final_profitability_aggregate_return
          AND observation.average_terminal_horizon_log_return_per_actionable_prediction
                  IS NOT DISTINCT FROM
                  NEW.source_final_profitability_average_return
          AND observation.metric_definition_hash =
                  NEW.source_final_profitability_metric_definition_hash
          AND observation.source_content_hash =
                  NEW.source_final_profitability_source_content_hash
          AND observation.observation_identity_hash =
                  NEW.source_final_profitability_observation_identity_hash
    ) THEN
        RAISE EXCEPTION
            'recommendation FINAL profitability observation provenance mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


