    CONSTRAINT experiment_recommendation_evaluatio_weighted_contribution_check CHECK (((weighted_contribution >= (0.0)::double precision) AND (weighted_contribution <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision])))),
    CONSTRAINT experiment_recommendation_evaluation_co_component_ordinal_check CHECK ((component_ordinal > 0)),
    CONSTRAINT experiment_recommendation_evaluation_com_normalized_value_check CHECK (((normalized_value >= (0.0)::double precision) AND (normalized_value <= (1.0)::double precision))),
    CONSTRAINT experiment_recommendation_evaluation_compo_component_name_check CHECK ((component_name = ANY (ARRAY['leader_quality'::text, 'inference_accuracy'::text, 'evidence_strength'::text, 'neutral_balance'::text, 'structural_proximity'::text, 'parameter_preference'::text, 'source_rank'::text, 'horizon_change_penalty'::text, 'relative_mutation_penalty'::text]))),
    CONSTRAINT experiment_recommendation_evaluation_componen_explanation_check CHECK ((btrim(explanation) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_componen_reason_code_check CHECK ((btrim(reason_code) <> ''::text)),
    CONSTRAINT experiment_recommendation_evaluation_component_weight_check CHECK (((weight >= (0.0)::double precision) AND (weight <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))))
);


