    CONSTRAINT experiment_recommendation_ranking__source_membership_hash_check CHECK ((btrim(source_membership_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_ranking_sn_advisory_ready_count_check CHECK ((advisory_ready_count >= 0)),
    CONSTRAINT experiment_recommendation_ranking_sn_non_actionable_count_check CHECK ((non_actionable_count >= 0)),
