    CONSTRAINT experiment_recommendation_ranking_snapsho_ranking_version_check CHECK ((ranking_version > 0)),
    CONSTRAINT experiment_recommendation_ranking_snapsho_requested_limit_check CHECK (((requested_limit > 0) AND (requested_limit <= 1000))),
    CONSTRAINT experiment_recommendation_ranking_snapsho_scope_canonical_check CHECK ((btrim(scope_canonical) <> ''::text)),
    CONSTRAINT experiment_recommendation_ranking_snapshot_blocked_count_check CHECK ((blocked_count >= 0)),
    CONSTRAINT experiment_recommendation_ranking_snapshot_horizon_filter_check CHECK (((horizon_filter IS NULL) OR (horizon_filter > 0))),
    CONSTRAINT experiment_recommendation_ranking_snapshot_member_count_check CHECK ((member_count >= 0)),
    CONSTRAINT experiment_recommendation_ranking_snapshot_scope_hash_check CHECK ((btrim(scope_hash) <> ''::text)),
    CONSTRAINT experiment_recommendation_ranking_snapshot_scope_type_check CHECK ((scope_type = ANY (ARRAY['evaluation_run'::text, 'recommendation_scan'::text, 'symbol'::text, 'horizon'::text, 'family'::text, 'symbol_horizon'::text, 'global'::text]))),
    CONSTRAINT experiment_recommendation_ranking_snapshot_status_check CHECK ((status = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text]))),
    CONSTRAINT recommendation_ranking_population_semantics_shape_check CHECK (((ranking_snapshot_identity_version = ANY (ARRAY[1, 2])) AND (population_semantic_state = ANY (ARRAY['verified_homogeneous'::text, 'empty'::text, 'legacy_heterogeneous'::text, 'legacy_unverified'::text])) AND (distinct_scoring_semantic_count >= 0) AND (distinct_evaluation_semantic_count >= 0) AND (((population_semantic_state = 'verified_homogeneous'::text) AND (scoring_semantic_canonical IS NOT NULL) AND (scoring_semantic_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text) AND (scoring_semantic_version = 1) AND (evaluation_semantic_canonical IS NOT NULL) AND (evaluation_semantic_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text) AND (evaluation_semantic_version = 1) AND (distinct_scoring_semantic_count = 1) AND (distinct_evaluation_semantic_count = 1) AND (homogeneity_validation_result = 'verified_homogeneous'::text)) OR ((population_semantic_state = 'empty'::text) AND (scoring_semantic_canonical IS NULL) AND (scoring_semantic_hash IS NULL) AND (scoring_semantic_version IS NULL) AND (evaluation_semantic_canonical IS NULL) AND (evaluation_semantic_hash IS NULL) AND (evaluation_semantic_version IS NULL) AND (distinct_scoring_semantic_count = 0) AND (distinct_evaluation_semantic_count = 0) AND (homogeneity_validation_result = 'empty_population'::text)) OR ((population_semantic_state = ANY (ARRAY['legacy_heterogeneous'::text, 'legacy_unverified'::text])) AND (scoring_semantic_canonical IS NULL) AND (scoring_semantic_hash IS NULL) AND (scoring_semantic_version IS NULL) AND (evaluation_semantic_canonical IS NULL) AND (evaluation_semantic_hash IS NULL) AND (evaluation_semantic_version IS NULL))))),
    CONSTRAINT recommendation_ranking_snapshot_lifecycle_check CHECK ((((status = 'running'::text) AND (completed_at IS NULL) AND (error_message IS NULL) AND (member_count = 0) AND (advisory_ready_count = 0) AND (blocked_count = 0) AND (non_actionable_count = 0)) OR ((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (error_message IS NULL) AND (member_count = ((advisory_ready_count + blocked_count) + non_actionable_count))) OR ((status = 'failed'::text) AND (completed_at IS NOT NULL) AND (error_message IS NOT NULL) AND (btrim(error_message) <> ''::text) AND (member_count = 0) AND (advisory_ready_count = 0) AND (blocked_count = 0) AND (non_actionable_count = 0)))),
    CONSTRAINT recommendation_ranking_snapshot_scope_shape_check CHECK ((((scope_type = 'evaluation_run'::text) AND (evaluation_run_filter IS NOT NULL) AND (recommendation_scan_filter IS NULL) AND (symbol_filter IS NULL) AND (horizon_filter IS NULL) AND (family_filter IS NULL)) OR ((scope_type = 'recommendation_scan'::text) AND (evaluation_run_filter IS NULL) AND (recommendation_scan_filter IS NOT NULL) AND (symbol_filter IS NULL) AND (horizon_filter IS NULL) AND (family_filter IS NULL)) OR ((scope_type = 'symbol'::text) AND (evaluation_run_filter IS NULL) AND (recommendation_scan_filter IS NULL) AND (symbol_filter IS NOT NULL) AND (btrim(symbol_filter) <> ''::text) AND (horizon_filter IS NULL) AND (family_filter IS NULL)) OR ((scope_type = 'horizon'::text) AND (evaluation_run_filter IS NULL) AND (recommendation_scan_filter IS NULL) AND (symbol_filter IS NULL) AND (horizon_filter IS NOT NULL) AND (family_filter IS NULL)) OR ((scope_type = 'family'::text) AND (evaluation_run_filter IS NULL) AND (recommendation_scan_filter IS NULL) AND (symbol_filter IS NULL) AND (horizon_filter IS NULL) AND (family_filter IS NOT NULL) AND (btrim(family_filter) <> ''::text)) OR ((scope_type = 'symbol_horizon'::text) AND (evaluation_run_filter IS NULL) AND (recommendation_scan_filter IS NULL) AND (symbol_filter IS NOT NULL) AND (btrim(symbol_filter) <> ''::text) AND (horizon_filter IS NOT NULL) AND (family_filter IS NULL)) OR ((scope_type = 'global'::text) AND (evaluation_run_filter IS NULL) AND (recommendation_scan_filter IS NULL) AND (symbol_filter IS NULL) AND (horizon_filter IS NULL) AND (family_filter IS NULL))))
);


