    CONSTRAINT experiment_recommendation_ranking_membe_tie_break_primary_check CHECK ((btrim(tie_break_primary) <> ''::text)),
    CONSTRAINT experiment_recommendation_ranking_member_bucket_check CHECK ((bucket = ANY (ARRAY['advisory_ready'::text, 'blocked'::text, 'non_actionable'::text]))),
    CONSTRAINT experiment_recommendation_ranking_member_bucket_rank_check CHECK ((bucket_rank > 0)),
    CONSTRAINT experiment_recommendation_ranking_member_disposition_check CHECK ((disposition = ANY (ARRAY['advisory_ready'::text, 'insufficient_evidence'::text, 'blocked_pending_duplicate'::text, 'blocked_active_duplicate'::text, 'completed_duplicate'::text, 'stale_source_evidence'::text, 'unsupported_recommendation_family'::text, 'invalid_persisted_evidence'::text]))),
    CONSTRAINT experiment_recommendation_ranking_member_family_check CHECK ((btrim(family) <> ''::text)),
    CONSTRAINT experiment_recommendation_ranking_member_global_ordinal_check CHECK ((global_ordinal > 0)),
    CONSTRAINT experiment_recommendation_ranking_member_horizon_check CHECK ((horizon > 0)),
    CONSTRAINT experiment_recommendation_ranking_member_inclusion_reason_check CHECK ((btrim(inclusion_reason) <> ''::text)),
    CONSTRAINT experiment_recommendation_ranking_member_symbol_check CHECK ((btrim(symbol) <> ''::text)),
    CONSTRAINT experiment_recommendation_ranking_tie_break_semantic_hash_check CHECK ((btrim(tie_break_semantic_hash) <> ''::text)),
    CONSTRAINT recommendation_ranking_member_finite_check CHECK (((final_score IS NULL) OR (final_score <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision])))),
    CONSTRAINT recommendation_ranking_member_shape_check CHECK ((((bucket = 'advisory_ready'::text) AND (disposition = 'advisory_ready'::text) AND (final_score IS NOT NULL) AND (final_score >= (0.0)::double precision) AND (final_score <= (1.0)::double precision) AND (block_reason IS NULL)) OR ((bucket = 'blocked'::text) AND (disposition = ANY (ARRAY['blocked_pending_duplicate'::text, 'blocked_active_duplicate'::text, 'completed_duplicate'::text])) AND (final_score IS NULL) AND (block_reason IS NOT NULL) AND (btrim(block_reason) <> ''::text)) OR ((bucket = 'non_actionable'::text) AND (disposition = ANY (ARRAY['insufficient_evidence'::text, 'stale_source_evidence'::text, 'unsupported_recommendation_family'::text, 'invalid_persisted_evidence'::text])) AND (final_score IS NULL) AND (block_reason IS NOT NULL) AND (btrim(block_reason) <> ''::text))))
);


