CREATE TABLE public.campaign_operations_campaign (
    operational_campaign_id bigint NOT NULL,
    recommendation_campaign_materialization_id bigint NOT NULL,
    materialization_contract_version integer NOT NULL,
    materialization_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    materialization_identity_hash text NOT NULL COLLATE pg_catalog."C",
    materialization_member_count integer NOT NULL,
    origin_kind text NOT NULL COLLATE pg_catalog."C",
    action_kind text NOT NULL COLLATE pg_catalog."C",
    action_contract_version integer NOT NULL,
    scope_kind text NOT NULL COLLATE pg_catalog."C",
    scope_contract_version integer NOT NULL,
    campaign_contract_version integer NOT NULL,
    campaign_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    campaign_identity_hash text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    completion_boundary_closed boolean DEFAULT false NOT NULL,
    CONSTRAINT campaign_operations_campaign_action_contract_version_check CHECK ((action_contract_version = 1)),
    CONSTRAINT campaign_operations_campaign_action_kind_check CHECK ((action_kind = 'dispatch_full_materialization'::text)),
    CONSTRAINT campaign_operations_campaign_campaign_contract_version_check CHECK ((campaign_contract_version = 1)),
    CONSTRAINT campaign_operations_campaign_campaign_identity_canonical_check CHECK (((campaign_identity_canonical <> ''::text) AND (octet_length(campaign_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_campaign_campaign_identity_hash_check CHECK ((campaign_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_campaign_materialization_contract_ver_check CHECK ((materialization_contract_version = 1)),
    CONSTRAINT campaign_operations_campaign_materialization_identity_can_check CHECK (((materialization_identity_canonical <> ''::text) AND (octet_length(materialization_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_campaign_materialization_identity_has_check CHECK ((materialization_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_campaign_materialization_member_count_check CHECK ((materialization_member_count > 0)),
    CONSTRAINT campaign_operations_campaign_operational_campaign_id_check CHECK ((operational_campaign_id > 0)),
    CONSTRAINT campaign_operations_campaign_origin_kind_check CHECK ((origin_kind = 'phase4d_materialization_v1'::text)),
    CONSTRAINT campaign_operations_campaign_scope_contract_version_check CHECK ((scope_contract_version = 1)),
    CONSTRAINT campaign_operations_campaign_scope_kind_check CHECK ((scope_kind = 'complete_materialization'::text))
);


