--

CREATE TABLE public.campaign_operations_reservation_event (
    reservation_event_id bigint NOT NULL,
    reservation_id bigint NOT NULL,
    reservation_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    transition_kind text NOT NULL COLLATE pg_catalog."C",
    expected_state text COLLATE pg_catalog."C",
    resulting_state text NOT NULL COLLATE pg_catalog."C",
    expected_version integer NOT NULL,
    resulting_version integer NOT NULL,
    operational_request_id bigint NOT NULL,
    request_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    amount bigint NOT NULL,
    reservation_event_contract_version integer NOT NULL,
    reservation_event_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    reservation_event_identity_hash text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    cancellation_request_id bigint,
    reconciliation_observation_id bigint,
    CONSTRAINT campaign_operations_reservat_reservation_event_contract_v_check CHECK ((reservation_event_contract_version = 1)),
    CONSTRAINT campaign_operations_reservat_reservation_event_identity_c_check CHECK (((reservation_event_identity_canonical <> ''::text) AND (octet_length(reservation_event_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_reservat_reservation_event_identity_h_check CHECK ((reservation_event_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_reservat_reservation_identity_canoni_check1 CHECK (((reservation_identity_canonical <> ''::text) AND (octet_length(reservation_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_reservatio_request_identity_canonical_check CHECK (((request_identity_canonical <> ''::text) AND (octet_length(request_identity_canonical) <= 134217728))),
    CONSTRAINT campaign_operations_reservation_even_reservation_event_id_check CHECK ((reservation_event_id > 0)),
    CONSTRAINT campaign_operations_reservation_event_acquisition_check CHECK (((transition_kind <> 'acquired'::text) OR ((expected_state IS NULL) AND (resulting_state = 'held'::text) AND (expected_version = 0) AND (resulting_version = 1)))),
    CONSTRAINT campaign_operations_reservation_event_amount_check CHECK ((amount > 0)),
    CONSTRAINT campaign_operations_reservation_event_expected_state_check CHECK ((expected_state = ANY (ARRAY['held'::text, 'committed'::text, 'released'::text, 'expired'::text, 'reconciliation_required'::text]))),
    CONSTRAINT campaign_operations_reservation_event_expected_version_check CHECK ((expected_version >= 0)),
    CONSTRAINT campaign_operations_reservation_event_resulting_state_check CHECK ((resulting_state = ANY (ARRAY['held'::text, 'committed'::text, 'released'::text, 'expired'::text, 'reconciliation_required'::text]))),
    CONSTRAINT campaign_operations_reservation_event_resulting_version_check CHECK ((resulting_version > 0)),
    CONSTRAINT campaign_operations_reservation_event_transition_kind_check CHECK ((transition_kind = ANY (ARRAY['acquired'::text, 'committed'::text, 'released'::text, 'expired'::text, 'reconciliation_required'::text]))),
    CONSTRAINT campaign_operations_reservation_event_version_check CHECK ((resulting_version = (expected_version + 1)))
);


