--
-- Name: campaign_operations_budget_status_v1; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_operations_budget_status_v1 AS
 WITH reservation_totals AS (
         SELECT campaign_operations_reservation.operational_campaign_id,
            (COALESCE(sum(campaign_operations_reservation.amount), (0)::numeric))::bigint AS ever_reserved,
            (COALESCE(sum(campaign_operations_reservation.amount) FILTER (WHERE (campaign_operations_reservation.reservation_state = 'committed'::text)), (0)::numeric))::bigint AS committed,
            (COALESCE(sum(campaign_operations_reservation.amount) FILTER (WHERE (campaign_operations_reservation.reservation_state = ANY (ARRAY['released'::text, 'expired'::text]))), (0)::numeric))::bigint AS released_or_expired,
            count(*) AS reservation_count,
            count(*) FILTER (WHERE (EXISTS ( SELECT 1
                   FROM public.campaign_operations_operational_request request
                  WHERE (request.reservation_id = campaign_operations_reservation.reservation_id)))) AS request_count,
            count(*) FILTER (WHERE (EXISTS ( SELECT 1
                   FROM public.campaign_operations_reservation_event event
                  WHERE ((event.reservation_id = campaign_operations_reservation.reservation_id) AND (event.transition_kind = 'acquired'::text))))) AS acquisition_count
           FROM public.campaign_operations_reservation
          GROUP BY campaign_operations_reservation.operational_campaign_id
        ), budget_head AS (
         SELECT DISTINCT ON (campaign_operations_budget_ledger_entry.operational_campaign_id) campaign_operations_budget_ledger_entry.operational_campaign_id,
            campaign_operations_budget_ledger_entry.budget_ledger_entry_id,
            campaign_operations_budget_ledger_entry.ledger_version,
            campaign_operations_budget_ledger_entry.ledger_status,
            campaign_operations_budget_ledger_entry.resulting_total,
            campaign_operations_budget_ledger_entry.budget_identity_hash
           FROM public.campaign_operations_budget_ledger_entry
          ORDER BY campaign_operations_budget_ledger_entry.operational_campaign_id, campaign_operations_budget_ledger_entry.ledger_version DESC
        )
 SELECT campaign.operational_campaign_id,
    head.budget_ledger_entry_id,
    head.ledger_version,
    head.ledger_status,
    head.resulting_total AS granted,
    COALESCE(totals.ever_reserved, (0)::bigint) AS ever_reserved,
    COALESCE(totals.committed, (0)::bigint) AS committed,
    COALESCE(totals.released_or_expired, (0)::bigint) AS released_or_expired,
    ((COALESCE(totals.ever_reserved, (0)::bigint) - COALESCE(totals.committed, (0)::bigint)) - COALESCE(totals.released_or_expired, (0)::bigint)) AS held,
    ((COALESCE(head.resulting_total, (0)::bigint) - COALESCE(totals.ever_reserved, (0)::bigint)) + COALESCE(totals.released_or_expired, (0)::bigint)) AS unallocated,
        CASE
            WHEN (head.ledger_status = 'active'::text) THEN ((head.resulting_total - COALESCE(totals.ever_reserved, (0)::bigint)) + COALESCE(totals.released_or_expired, (0)::bigint))
            ELSE (0)::bigint
        END AS reservable,
    head.budget_identity_hash,
    ((COALESCE(totals.ever_reserved, (0)::bigint) >= (COALESCE(totals.committed, (0)::bigint) + COALESCE(totals.released_or_expired, (0)::bigint))) AND (COALESCE(head.resulting_total, (0)::bigint) >= (COALESCE(totals.ever_reserved, (0)::bigint) - COALESCE(totals.released_or_expired, (0)::bigint))) AND (COALESCE(totals.reservation_count, (0)::bigint) = COALESCE(totals.request_count, (0)::bigint)) AND (COALESCE(totals.reservation_count, (0)::bigint) = COALESCE(totals.acquisition_count, (0)::bigint))) AS accounting_consistent
   FROM ((public.campaign_operations_campaign campaign
     LEFT JOIN budget_head head USING (operational_campaign_id))
     LEFT JOIN reservation_totals totals USING (operational_campaign_id));


