CREATE TABLE public.campaign_operations_cancellation_settlement (
    cancellation_settlement_id bigint NOT NULL,
    cancellation_request_id bigint NOT NULL,
    cancellation_request_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    disposition text NOT NULL COLLATE pg_catalog."C",
    reservation_event_id bigint,
    reservation_event_identity_canonical text COLLATE pg_catalog."C",
    resulting_request_version integer,
    lifecycle_evidence_identity_canonical text COLLATE pg_catalog."C",
    lifecycle_evidence_identity_hash text COLLATE pg_catalog."C",
    settlement_contract_version integer NOT NULL,
    settlement_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    settlement_identity_hash text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT campaign_operations_cancella_settlement_identity_canonica_check CHECK ((settlement_identity_canonical <> ''::text)),
    CONSTRAINT campaign_operations_cancellat_settlement_contract_version_check CHECK ((settlement_contract_version = 1)),
    CONSTRAINT campaign_operations_cancellati_cancellation_settlement_id_check CHECK ((cancellation_settlement_id > 0)),
    CONSTRAINT campaign_operations_cancellatio_resulting_request_version_check CHECK ((resulting_request_version > 0)),
    CONSTRAINT campaign_operations_cancellation_settlement_disposition_check CHECK ((disposition = ANY (ARRAY['unbound_cancelled'::text, 'lifecycle_request_accepted'::text, 'already_terminal'::text, 'running_cancellation_not_supported'::text, 'inconsistent'::text]))),
    CONSTRAINT campaign_operations_cancellation_settlement_identity_hash_check CHECK ((settlement_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_settlement_shape_check CHECK ((((disposition = 'unbound_cancelled'::text) AND (reservation_event_id IS NOT NULL) AND (reservation_event_identity_canonical IS NOT NULL) AND (resulting_request_version IS NOT NULL) AND (lifecycle_evidence_identity_canonical IS NULL) AND (lifecycle_evidence_identity_hash IS NULL)) OR ((disposition <> 'unbound_cancelled'::text) AND (reservation_event_id IS NULL) AND (reservation_event_identity_canonical IS NULL) AND (lifecycle_evidence_identity_canonical IS NOT NULL) AND (lifecycle_evidence_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text))))
);


