    request_identity_canonical text COLLATE pg_catalog."C",
    expected_request_state text COLLATE pg_catalog."C",
    expected_request_version integer,
    cancellation_scope text NOT NULL COLLATE pg_catalog."C",
    operation_key text NOT NULL COLLATE pg_catalog."C",
    actor_identity text NOT NULL COLLATE pg_catalog."C",
    capability text NOT NULL COLLATE pg_catalog."C",
    reason text NOT NULL COLLATE pg_catalog."C",
    cancellation_contract_version integer NOT NULL,
    cancellation_identity_canonical text NOT NULL COLLATE pg_catalog."C",
    cancellation_identity_hash text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT campaign_operations_cancella_cancellation_contract_versio_check CHECK ((cancellation_contract_version = 1)),
    CONSTRAINT campaign_operations_cancella_cancellation_identity_canoni_check CHECK ((cancellation_identity_canonical <> ''::text)),
    CONSTRAINT campaign_operations_cancellat_campaign_identity_canonical_check CHECK ((campaign_identity_canonical <> ''::text)),
    CONSTRAINT campaign_operations_cancellati_cancellation_identity_hash_check CHECK ((cancellation_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_cancellation__cancellation_request_id_check CHECK ((cancellation_request_id > 0)),
    CONSTRAINT campaign_operations_cancellation_expected_request_version_check CHECK ((expected_request_version > 0)),
    CONSTRAINT campaign_operations_cancellation_r_expected_request_state_check CHECK ((expected_request_state = ANY (ARRAY['ready'::text, 'dispatching'::text, 'bound'::text, 'permanently_failed'::text, 'cancelled'::text, 'reconciliation_required'::text]))),
    CONSTRAINT campaign_operations_cancellation_reque_cancellation_scope_check CHECK ((cancellation_scope = 'complete_materialization'::text)),
    CONSTRAINT campaign_operations_cancellation_request_actor_identity_check CHECK ((actor_identity ~ '^[A-Za-z0-9][A-Za-z0-9._@:/+\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_cancellation_request_capability_check CHECK ((capability = 'campaign_operations_cancellation_coordinator'::text)),
    CONSTRAINT campaign_operations_cancellation_request_operation_key_check CHECK ((operation_key ~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_cancellation_request_reason_check CHECK (((reason <> ''::text) AND (octet_length(reason) <= 4096))),
    CONSTRAINT campaign_operations_cancellation_target_shape_check CHECK ((((operational_request_id IS NULL) AND (request_identity_canonical IS NULL) AND (expected_request_state IS NULL) AND (expected_request_version IS NULL)) OR ((operational_request_id IS NOT NULL) AND (request_identity_canonical IS NOT NULL) AND (expected_request_state IS NOT NULL) AND (expected_request_version IS NOT NULL))))
);


