--
-- Name: campaign_operations_completion_status_v1; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_operations_completion_status_v1 AS
 SELECT campaign.operational_campaign_id,
    (completion.completion_event_id IS NOT NULL) AS completion_recorded,
    (completion.completion_event_id IS NOT NULL) AS logically_archived,
    completion.completion_event_id,
    completion.recorded_at,
    completion.administrative_terminal_state AS recorded_terminal_state,
    completion.completion_classification,
    completion.completion_identity_hash,
    completion.lifecycle_evidence_canonical AS recorded_lifecycle_evidence,
    public.campaign_operations_completion_evidence_text(campaign.operational_campaign_id, 'lifecycle'::text) AS current_lifecycle_evidence,
    ((completion.completion_event_id IS NOT NULL) AND (completion.lifecycle_evidence_canonical <> public.campaign_operations_completion_evidence_text(campaign.operational_campaign_id, 'lifecycle'::text))) AS post_completion_lifecycle_changed,
    ( SELECT count(*) AS count
           FROM public.campaign_operations_cancellation_request request
          WHERE (request.operational_campaign_id = campaign.operational_campaign_id)) AS cancellation_request_count,
    ( SELECT count(*) AS count
           FROM (public.campaign_operations_reconciliation_observation observation
             LEFT JOIN public.campaign_operations_reconciliation_resolution resolution ON ((resolution.reconciliation_observation_id = observation.reconciliation_observation_id)))
          WHERE ((observation.operational_campaign_id = campaign.operational_campaign_id) AND (resolution.reconciliation_resolution_id IS NULL) AND (observation.reason_code <> ALL (ARRAY['terminal_lifecycle_completion_ready'::text, 'post_completion_lifecycle_changed'::text])))) AS unresolved_blocking_observation_count
   FROM (public.campaign_operations_campaign campaign
     LEFT JOIN public.campaign_operations_completion_event completion ON ((completion.operational_campaign_id = campaign.operational_campaign_id)));


