    CONSTRAINT campaign_operations_control_audit_reference_event_outcome_check CHECK ((outcome = ANY (ARRAY['recorded'::text, 'existing_identical'::text, 'waiting_for_lease_expiry'::text, 'reconciliation_required'::text])))
);


