    CONSTRAINT campaign_operations_dispatch_audit_production_shape CHECK ((((request_production_admission_id IS NULL) AND (production_enablement_event_id IS NULL) AND (capability = ANY (ARRAY['campaign_operations_dispatcher'::text, 'campaign_operations_phase5_transactional'::text, 'campaign_operations_cancellation_coordinator'::text, 'campaign_operations_recovery'::text]))) OR ((request_production_admission_id IS NOT NULL) AND (production_enablement_event_id IS NOT NULL) AND (capability = ANY (ARRAY['campaign_operations_production_dispatcher'::text, 'campaign_operations_production_phase5_transactional'::text]))))),
