    CONSTRAINT campaign_operations_dispatch_audit_reference_even_outcome_check CHECK ((outcome = ANY (ARRAY['recorded'::text, 'rejected'::text, 'reconciliation_required'::text]))),
    CONSTRAINT campaign_operations_dispatch_audit_reference_event_check CHECK ((resulting_version >= prior_version)),
    CONSTRAINT campaign_operations_dispatch_dispatch_audit_reference_eve_check CHECK ((dispatch_audit_reference_event_id > 0)),
    CONSTRAINT campaign_ops_dispatch_audit_cause_check CHECK ((cause_kind = ANY (ARRAY['dispatch_lease_acquired'::text, 'dispatch_handoff_completed'::text, 'dispatch_handoff_failed'::text, 'dispatch_lease_recovered'::text])))
);


