    CONSTRAINT campaign_operations_request_bindin_proposal_identity_hash_check CHECK ((proposal_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_request_binding_binding_disposition_check CHECK ((binding_disposition = ANY (ARRAY['created'::text, 'adopted_existing_pending'::text]))),
    CONSTRAINT campaign_operations_request_binding_binding_identity_hash_check CHECK ((binding_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT campaign_operations_request_binding_disposition_check CHECK ((((binding_disposition = 'created'::text) AND (execution_disposition = 'created'::text) AND (activation_disposition = 'created'::text)) OR ((binding_disposition = 'adopted_existing_pending'::text) AND (execution_disposition = 'reused'::text) AND (activation_disposition = 'reused'::text)))),
    CONSTRAINT campaign_operations_request_binding_execution_disposition_check CHECK ((execution_disposition = ANY (ARRAY['created'::text, 'reused'::text]))),
