--
-- Name: campaign_operations_production_status_v1; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_operations_production_status_v1 AS
 SELECT request.operational_request_id,
    request.operational_campaign_id,
    request.request_state,
    request.state_version,
    request.production_dispatch_enabled,
    admission.request_production_admission_id,
    admission.admission_identity_canonical,
    admission.admission_identity_hash,
    attempt.dispatch_attempt_id,
    attempt.operation_key,
    attempt.attempt_ordinal,
    attempt.production_enablement_event_id,
    attempt.lease_expires_at,
    (attempt.lease_expires_at <= transaction_timestamp()) AS lease_expired,
    ((request.request_state = 'dispatching'::text) AND (request.lease_expires_at <= transaction_timestamp()) AND (NOT (EXISTS ( SELECT 1
           FROM public.campaign_operations_request_binding binding
          WHERE (binding.operational_request_id = request.operational_request_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM (public.experiment_recommendation_campaign_materialization_member member
             JOIN public.experiment_recommendation_conversion_execution execution ON ((execution.recommendation_conversion_proposal_id = member.recommendation_conversion_proposal_id)))
          WHERE (member.recommendation_campaign_materialization_id = request.recommendation_campaign_materialization_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM (public.campaign_operations_dispatch_attempt recovery_attempt
             JOIN public.campaign_operations_dispatch_attempt_outcome outcome ON ((outcome.dispatch_attempt_id = recovery_attempt.dispatch_attempt_id)))
          WHERE ((recovery_attempt.operational_request_id = request.operational_request_id) AND (recovery_attempt.attempt_ordinal = ( SELECT max(latest.attempt_ordinal) AS max
                   FROM public.campaign_operations_dispatch_attempt latest
                  WHERE (latest.operational_request_id = request.operational_request_id)))))))) AS phase_f_recovery_eligible,
    (observation.reconciliation_observation_id IS NOT NULL) AS reconciliation_required
   FROM (((public.campaign_operations_operational_request request
     LEFT JOIN public.campaign_operations_request_production_admission admission ON ((admission.operational_request_id = request.operational_request_id)))
     LEFT JOIN LATERAL ( SELECT candidate.dispatch_attempt_id,
            candidate.operational_request_id,
            candidate.request_identity_canonical,
            candidate.attempt_ordinal,
            candidate.expected_request_version,
            candidate.resulting_request_version,
            candidate.lease_token_digest,
            candidate.lease_expires_at,
            candidate.dispatcher_identity,
            candidate.attempt_contract_version,
            candidate.attempt_identity_canonical,
            candidate.attempt_identity_hash,
            candidate.acquired_at,
            candidate.request_production_admission_id,
            candidate.request_production_admission_canonical,
            candidate.request_production_admission_hash,
            candidate.production_enablement_event_id,
            candidate.production_enablement_event_canonical,
            candidate.production_enablement_event_hash,
            candidate.operation_key,
            candidate.requesting_actor,
            candidate.original_executing_service_principal,
            candidate.approved_build_contract_canonical,
            candidate.approved_build_contract_hash,
            candidate.production_capability
           FROM public.campaign_operations_dispatch_attempt candidate
          WHERE ((candidate.operational_request_id = request.operational_request_id) AND (candidate.attempt_contract_version = 2))
          ORDER BY candidate.attempt_ordinal DESC, candidate.dispatch_attempt_id DESC
         LIMIT 1) attempt ON (true))
     LEFT JOIN LATERAL ( SELECT candidate.reconciliation_observation_id
           FROM public.campaign_operations_reconciliation_observation candidate
          WHERE ((candidate.operational_request_id = request.operational_request_id) AND (NOT (EXISTS ( SELECT 1
                   FROM public.campaign_operations_reconciliation_resolution resolution
                  WHERE (resolution.reconciliation_observation_id = candidate.reconciliation_observation_id)))))
          ORDER BY candidate.reconciliation_observation_id DESC
         LIMIT 1) observation ON (true));


