    CONSTRAINT campaign_operations_reconciliation_cursor_event_check CHECK ((last_target_id >= prior_target_id)),
    CONSTRAINT campaign_operations_reconciliation_cursor_event_check1 CHECK (((selected_count >= 0) AND (selected_count <= requested_limit))),
    CONSTRAINT campaign_operations_reconciliation_cursor_event_run_key_check CHECK ((run_key ~ '^[A-Za-z0-9][A-Za-z0-9._:/\-]{0,127}$'::text)),
    CONSTRAINT campaign_operations_reconciliation_cursor_prior_target_id_check CHECK ((prior_target_id >= 0)),
