--
-- Name: campaign_operations_request_status_v1; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.campaign_operations_request_status_v1 AS
 SELECT request.operational_request_id,
    request.operational_campaign_id,
    request.request_state,
    request.state_version AS request_state_version,
    request.request_identity_hash,
    request.production_dispatch_enabled,
    reservation.reservation_id,
    reservation.reservation_state,
    reservation.state_version AS reservation_state_version,
    reservation.amount,
    reservation.budget_unit,
    reservation.expires_at,
    reservation.reservation_identity_hash,
    request.authorization_event_id,
    reservation.budget_ledger_entry_id,
    reservation.budget_ledger_version,
    request.created_at,
    COALESCE(((reservation.operational_campaign_id = request.operational_campaign_id) AND (reservation.campaign_identity_canonical = request.campaign_identity_canonical) AND (reservation.logical_operation_contract_version = request.logical_operation_contract_version) AND (reservation.logical_operation_canonical = request.logical_operation_canonical) AND (reservation.logical_operation_hash = request.logical_operation_hash) AND (reservation.authorization_event_id = request.authorization_event_id) AND (reservation.authorization_identity_canonical = request.authorization_identity_canonical) AND (reservation.authorization_identity_hash = request.authorization_identity_hash) AND (reservation.reservation_identity_canonical = request.reservation_identity_canonical) AND (reservation.reservation_identity_hash = request.reservation_identity_hash) AND (reservation.action_kind = request.action_kind) AND (reservation.action_contract_version = request.action_contract_version) AND (reservation.recommendation_campaign_materialization_id = request.recommendation_campaign_materialization_id) AND (reservation.materialization_contract_version = request.materialization_contract_version) AND (reservation.materialization_identity_canonical = request.materialization_identity_canonical) AND (reservation.materialization_identity_hash = request.materialization_identity_hash) AND (reservation.materialization_member_count = request.materialization_member_count) AND (reservation.amount = request.materialization_member_count) AND (request.ordered_scope_digest = request.materialization_identity_hash) AND (authz.operational_campaign_id = request.operational_campaign_id) AND (authz.campaign_identity_canonical = request.campaign_identity_canonical) AND (authz.authorization_identity_canonical = request.authorization_identity_canonical) AND (authz.authorization_identity_hash = request.authorization_identity_hash) AND (authz.event_kind = 'granted'::text) AND (authz.action_kind = request.action_kind) AND (authz.action_contract_version = request.action_contract_version) AND (authz.scope_kind = reservation.scope_kind) AND (authz.scope_contract_version = reservation.scope_contract_version) AND (authz.prerequisite_policy = request.prerequisite_policy) AND (NOT (authz.provenance_identity_canonical IS DISTINCT FROM request.provenance_identity_canonical)) AND (NOT (authz.provenance_identity_hash IS DISTINCT FROM request.provenance_identity_hash)) AND (((authz.governance_provenance_event_id IS NULL) AND (provenance.governance_provenance_event_id IS NULL) AND (request.provenance_identity_canonical IS NULL) AND (request.provenance_identity_hash IS NULL)) OR ((authz.governance_provenance_event_id IS NOT NULL) AND (provenance.governance_provenance_event_id = authz.governance_provenance_event_id) AND (provenance.operational_campaign_id = request.operational_campaign_id) AND (provenance.prerequisite_policy = request.prerequisite_policy) AND (provenance.provenance_identity_canonical = request.provenance_identity_canonical) AND (provenance.provenance_identity_hash = request.provenance_identity_hash))) AND (budget.operational_campaign_id = request.operational_campaign_id) AND (budget.ledger_version = reservation.budget_ledger_version) AND (budget.budget_identity_canonical = reservation.budget_identity_canonical) AND (budget.budget_identity_hash = reservation.budget_identity_hash) AND (EXISTS ( SELECT 1
           FROM public.campaign_operations_reservation_event event
          WHERE ((event.reservation_id = reservation.reservation_id) AND (event.operational_request_id = request.operational_request_id) AND (event.reservation_identity_canonical = reservation.reservation_identity_canonical) AND (event.request_identity_canonical = request.request_identity_canonical) AND (event.transition_kind = 'acquired'::text) AND (event.expected_state IS NULL) AND (event.resulting_state = 'held'::text) AND (event.expected_version = 0) AND (event.resulting_version = 1) AND (event.amount = reservation.amount)))) AND (EXISTS ( SELECT 1
           FROM public.campaign_operations_audit_reference_event audit
          WHERE ((audit.reservation_id = reservation.reservation_id) AND (audit.operational_request_id = request.operational_request_id) AND (audit.operational_campaign_id = request.operational_campaign_id) AND (audit.authorization_event_id = request.authorization_event_id) AND (audit.budget_ledger_entry_id = reservation.budget_ledger_entry_id) AND (audit.reservation_event_id = ( SELECT event.reservation_event_id
                   FROM public.campaign_operations_reservation_event event
                  WHERE ((event.reservation_id = reservation.reservation_id) AND (event.operational_request_id = request.operational_request_id) AND (event.transition_kind = 'acquired'::text) AND (event.resulting_version = 1)))) AND (audit.cause_kind = 'reservation_request_accepted'::text) AND (audit.actor_identity = request.accepting_actor_identity) AND (audit.capability = 'campaign_operations_request_acceptor'::text) AND (audit.reason = request.reason) AND (audit.prior_version IS NULL) AND (audit.resulting_version = 1) AND (audit.outcome = 'recorded'::text) AND (audit.replay_disposition = 'recorded'::text))))), false) AS evidence_consistent
   FROM ((((public.campaign_operations_operational_request request
     JOIN public.campaign_operations_reservation reservation ON ((reservation.reservation_id = request.reservation_id)))
     LEFT JOIN public.campaign_operations_authorization_event authz ON ((authz.authorization_event_id = request.authorization_event_id)))
     LEFT JOIN public.campaign_operations_governance_provenance_event provenance ON ((provenance.governance_provenance_event_id = authz.governance_provenance_event_id)))
     LEFT JOIN public.campaign_operations_budget_ledger_entry budget ON ((budget.budget_ledger_entry_id = reservation.budget_ledger_entry_id)));


