CASE availability_proof
    WHEN 'source_publication'::text THEN source_publication_at
    WHEN 'system_observation'::text THEN observed_at
    ELSE NULL::timestamp with time zone
END) STORED,
    source_url text,
    source_artifact_path text NOT NULL,
    source_artifact_sha256 text,
    semantic_contract text NOT NULL,
