    CONSTRAINT economic_event_actual_observation_actual_raw_check CHECK ((actual_raw <> ''::text)),
    CONSTRAINT economic_event_actual_observation_actual_scale_check CHECK ((actual_scale > (0)::numeric)),
    CONSTRAINT economic_event_actual_observation_actual_unit_check CHECK ((actual_unit <> ''::text)),
    CONSTRAINT economic_event_actual_observation_actual_value_kind_check CHECK ((actual_value_kind = ANY (ARRAY['scalar'::text, 'range'::text]))),
    CONSTRAINT economic_event_actual_observation_availability_proof_check CHECK ((availability_proof = ANY (ARRAY['source_publication'::text, 'system_observation'::text]))),
    CONSTRAINT economic_event_actual_observation_chronology_ck CHECK (((observed_at <= ingested_at) AND ((source_publication_at IS NULL) OR (source_publication_at <= observed_at)))),
    CONSTRAINT economic_event_actual_observation_evidence_key_check CHECK ((evidence_key <> ''::text)),
    CONSTRAINT economic_event_actual_observation_observation_kind_check CHECK ((observation_kind = ANY (ARRAY['initial'::text, 'revision'::text, 'correction'::text, 'alternate_observation'::text, 'unclassified'::text]))),
    CONSTRAINT economic_event_actual_observation_revision_sequence_check CHECK ((revision_sequence >= 0)),
    CONSTRAINT economic_event_actual_observation_semantic_contract_check CHECK ((semantic_contract <> ''::text)),
    CONSTRAINT economic_event_actual_observation_sequence_ck CHECK ((((observation_kind = 'initial'::text) AND (revision_sequence = 0)) OR ((observation_kind = 'revision'::text) AND (revision_sequence > 0)) OR ((observation_kind = ANY (ARRAY['correction'::text, 'alternate_observation'::text, 'unclassified'::text])) AND (revision_sequence IS NULL)))),
    CONSTRAINT economic_event_actual_observation_source_artifact_path_check CHECK ((source_artifact_path <> ''::text)),
    CONSTRAINT economic_event_actual_observation_source_artifact_sha256_check CHECK (((source_artifact_sha256 IS NULL) OR (source_artifact_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT economic_event_actual_observation_source_name_check CHECK ((source_name <> ''::text)),
    CONSTRAINT economic_event_actual_observation_source_observation_id_check CHECK ((source_observation_id <> ''::text)),
    CONSTRAINT economic_event_actual_observation_source_provenance_check CHECK (((jsonb_typeof(source_provenance) = 'object'::text) AND (source_provenance <> '{}'::jsonb))),
    CONSTRAINT economic_event_actual_observation_source_role_check CHECK ((source_role = ANY (ARRAY['authoritative'::text, 'secondary'::text]))),
    CONSTRAINT economic_event_actual_observation_source_time_ck CHECK ((((source_publication_time_status = 'exact'::text) AND (source_publication_at IS NOT NULL) AND (availability_proof = 'source_publication'::text)) OR ((source_publication_time_status = 'unavailable'::text) AND (source_publication_at IS NULL) AND (availability_proof = 'system_observation'::text)))),
    CONSTRAINT economic_event_actual_observation_source_url_check CHECK (((source_url IS NULL) OR (source_url ~ '^https://'::text))),
    CONSTRAINT economic_event_actual_observation_value_shape_ck CHECK ((((actual_value_kind = 'scalar'::text) AND (actual_value_high IS NULL) AND (actual_canonical_value_high IS NULL) AND (actual_canonical_value_low = (actual_value_low * actual_scale))) OR ((actual_value_kind = 'range'::text) AND (actual_value_high IS NOT NULL) AND (actual_canonical_value_high IS NOT NULL) AND (actual_value_low <= actual_value_high) AND (actual_canonical_value_low <= actual_canonical_value_high) AND (actual_canonical_value_low = (actual_value_low * actual_scale)) AND (actual_canonical_value_high = (actual_value_high * actual_scale)))))
);


