--
-- Name: economic_event_canonical_actual; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.economic_event_canonical_actual AS
 SELECT DISTINCT ON (economic_event_id) economic_event_actual_observation_id,
    economic_event_id,
    actual_value_kind,
    actual_canonical_value_low,
    actual_canonical_value_high,
    actual_unit,
    actual_scale,
    actual_qualifier,
    proven_available_at,
    source_name,
    source_native_event_id,
    source_observation_id,
    observation_kind,
    revision_sequence
   FROM public.economic_event_actual_observation o
  WHERE ((source_role = 'authoritative'::text) AND (observation_kind = ANY (ARRAY['initial'::text, 'revision'::text, 'correction'::text])))
  ORDER BY economic_event_id, proven_available_at DESC, revision_sequence DESC NULLS LAST, economic_event_actual_observation_id DESC;


--
-- Name: VIEW economic_event_canonical_actual; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.economic_event_canonical_actual IS 'Latest proven authoritative value for read-only audit; existing feature consumers are not redirected to this view.';


