    forecast_availability_proof text,
    CONSTRAINT economic_event_consensus_actual_parse_status_check CHECK ((actual_parse_status = ANY (ARRAY['missing'::text, 'parsed'::text]))),
    CONSTRAINT economic_event_consensus_actual_semantics_ck CHECK ((((actual_parse_status = 'missing'::text) AND (actual_raw IS NULL) AND (actual_value_kind IS NULL) AND (actual_value_low IS NULL) AND (actual_value_high IS NULL) AND (actual_canonical_value_low IS NULL) AND (actual_canonical_value_high IS NULL) AND (actual_unit IS NULL) AND (actual_scale IS NULL) AND (actual_qualifier IS NULL)) OR ((actual_parse_status = 'parsed'::text) AND (actual_raw IS NOT NULL) AND (actual_raw <> ''::text) AND (actual_value_kind IS NOT NULL) AND (actual_value_low IS NOT NULL) AND (actual_canonical_value_low IS NOT NULL) AND (actual_unit IS NOT NULL) AND (actual_unit <> ''::text) AND (actual_scale IS NOT NULL) AND (actual_scale > (0)::numeric) AND (((actual_value_kind = 'scalar'::text) AND (actual_value_high IS NULL) AND (actual_canonical_value_high IS NULL)) OR ((actual_value_kind = 'range'::text) AND (actual_value_high IS NOT NULL) AND (actual_canonical_value_high IS NOT NULL) AND (actual_value_low <= actual_value_high) AND (actual_canonical_value_low <= actual_canonical_value_high)))))),
    CONSTRAINT economic_event_consensus_actual_value_kind_check CHECK ((actual_value_kind = ANY (ARRAY['scalar'::text, 'range'::text]))),
    CONSTRAINT economic_event_consensus_candidate_classification_ck CHECK ((candidate_classification = ANY (ARRAY['oanda_populated_initial'::text, 'oanda_matched_blank'::text, 'myfxbook_oanda_blank_fill'::text, 'myfxbook_jolts_gap_fill'::text, 'myfxbook_weekly_claims_pre_release_snapshot'::text]))),
    CONSTRAINT economic_event_consensus_consensus_source_check CHECK ((consensus_source <> ''::text)),
    CONSTRAINT economic_event_consensus_forecast_availability_shape_ck CHECK ((((provider_observed_at IS NULL) AND (forecast_available_at IS NULL) AND (source_retrieved_at IS NULL) AND (forecast_availability_proof IS NULL)) OR ((provider_observed_at IS NOT NULL) AND (forecast_available_at IS NOT NULL) AND (source_retrieved_at IS NOT NULL) AND (forecast_availability_proof <> ''::text) AND (provider_observed_at <= forecast_available_at) AND (forecast_available_at <= source_retrieved_at)))),
    CONSTRAINT economic_event_consensus_forecast_parse_status_check CHECK ((forecast_parse_status = ANY (ARRAY['missing'::text, 'parsed'::text]))),
    CONSTRAINT economic_event_consensus_forecast_semantics_ck CHECK ((((forecast_parse_status = 'missing'::text) AND (forecast_raw IS NULL) AND (forecast_value_kind IS NULL) AND (forecast_value_low IS NULL) AND (forecast_value_high IS NULL) AND (forecast_canonical_value_low IS NULL) AND (forecast_canonical_value_high IS NULL) AND (forecast_unit IS NULL) AND (forecast_scale IS NULL) AND (forecast_qualifier IS NULL)) OR ((forecast_parse_status = 'parsed'::text) AND (forecast_raw IS NOT NULL) AND (forecast_raw <> ''::text) AND (forecast_value_kind IS NOT NULL) AND (forecast_value_low IS NOT NULL) AND (forecast_canonical_value_low IS NOT NULL) AND (forecast_unit IS NOT NULL) AND (forecast_unit <> ''::text) AND (forecast_scale IS NOT NULL) AND (forecast_scale > (0)::numeric) AND (((forecast_value_kind = 'scalar'::text) AND (forecast_value_high IS NULL) AND (forecast_canonical_value_high IS NULL)) OR ((forecast_value_kind = 'range'::text) AND (forecast_value_high IS NOT NULL) AND (forecast_canonical_value_high IS NOT NULL) AND (forecast_value_low <= forecast_value_high) AND (forecast_canonical_value_low <= forecast_canonical_value_high)))))),
    CONSTRAINT economic_event_consensus_forecast_value_kind_check CHECK ((forecast_value_kind = ANY (ARRAY['scalar'::text, 'range'::text]))),
    CONSTRAINT economic_event_consensus_match_rule_check CHECK ((match_rule <> ''::text)),
    CONSTRAINT economic_event_consensus_previous_parse_status_check CHECK ((previous_parse_status = ANY (ARRAY['missing'::text, 'parsed'::text]))),
    CONSTRAINT economic_event_consensus_previous_semantics_ck CHECK ((((previous_parse_status = 'missing'::text) AND (previous_raw IS NULL) AND (previous_value_kind IS NULL) AND (previous_value_low IS NULL) AND (previous_value_high IS NULL) AND (previous_canonical_value_low IS NULL) AND (previous_canonical_value_high IS NULL) AND (previous_unit IS NULL) AND (previous_scale IS NULL) AND (previous_qualifier IS NULL)) OR ((previous_parse_status = 'parsed'::text) AND (previous_raw IS NOT NULL) AND (previous_raw <> ''::text) AND (previous_value_kind IS NOT NULL) AND (previous_value_low IS NOT NULL) AND (previous_canonical_value_low IS NOT NULL) AND (previous_unit IS NOT NULL) AND (previous_unit <> ''::text) AND (previous_scale IS NOT NULL) AND (previous_scale > (0)::numeric) AND (((previous_value_kind = 'scalar'::text) AND (previous_value_high IS NULL) AND (previous_canonical_value_high IS NULL)) OR ((previous_value_kind = 'range'::text) AND (previous_value_high IS NOT NULL) AND (previous_canonical_value_high IS NOT NULL) AND (previous_value_low <= previous_value_high) AND (previous_canonical_value_low <= previous_canonical_value_high)))))),
    CONSTRAINT economic_event_consensus_previous_value_kind_check CHECK ((previous_value_kind = ANY (ARRAY['scalar'::text, 'range'::text]))),
    CONSTRAINT economic_event_consensus_provider_contract_ck CHECK ((((consensus_source = 'OANDA'::text) AND (source_report_id IS NOT NULL) AND (source_event_id > 0) AND (source_period IS NOT NULL) AND (source_priority IS NOT NULL) AND (source_timestamp_epoch IS NOT NULL) AND (source_date IS NOT NULL) AND (candidate_classification = ANY (ARRAY['oanda_populated_initial'::text, 'oanda_matched_blank'::text])) AND (provider_observed_at IS NULL) AND (forecast_available_at IS NULL) AND (source_retrieved_at IS NULL) AND (forecast_availability_proof IS NULL)) OR ((consensus_source = 'MYFXBOOK'::text) AND (source_report_id IS NULL) AND (source_event_id <> 0) AND (source_period IS NULL) AND (source_priority IS NULL) AND (source_timestamp_epoch IS NULL) AND (source_date IS NULL) AND (forecast_parse_status = 'parsed'::text) AND (previous_parse_status = 'missing'::text) AND (actual_parse_status = 'missing'::text) AND (source_artifact_sha256 IS NOT NULL) AND (candidate_classification = ANY (ARRAY['myfxbook_oanda_blank_fill'::text, 'myfxbook_jolts_gap_fill'::text])) AND (provider_observed_at IS NULL) AND (forecast_available_at IS NULL) AND (source_retrieved_at IS NULL) AND (forecast_availability_proof IS NULL)) OR ((consensus_source = 'MYFXBOOK'::text) AND (source_report_id IS NULL) AND (source_event_id > 0) AND (source_period IS NULL) AND (source_priority IS NULL) AND (source_timestamp_epoch IS NULL) AND (source_date IS NULL) AND (forecast_parse_status = 'parsed'::text) AND (previous_parse_status = 'missing'::text) AND (actual_parse_status = 'missing'::text) AND (source_artifact_sha256 IS NOT NULL) AND (candidate_classification = 'myfxbook_weekly_claims_pre_release_snapshot'::text) AND (semantic_contract = 'myfxbook_weekly_claims_pre_release_snapshot_v1'::text) AND (provider_observed_at IS NOT NULL) AND (forecast_available_at IS NOT NULL) AND (source_retrieved_at IS NOT NULL) AND (forecast_availability_proof = 'internet_archive_pre_release_capture'::text)))),
    CONSTRAINT economic_event_consensus_semantic_contract_check CHECK ((semantic_contract <> ''::text)),
    CONSTRAINT economic_event_consensus_source_artifact_path_check CHECK ((source_artifact_path <> ''::text)),
    CONSTRAINT economic_event_consensus_source_artifact_sha256_ck CHECK (((source_artifact_sha256 IS NULL) OR (source_artifact_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT economic_event_consensus_source_event_id_ck CHECK ((source_event_id <> 0)),
