    CONSTRAINT economic_event_consensus_source_observation_id_ck CHECK ((source_observation_id <> ''::text)),
    CONSTRAINT economic_event_consensus_source_period_ck CHECK (((source_period IS NULL) OR (source_period <> ''::text))),
    CONSTRAINT economic_event_consensus_source_priority_ck CHECK (((source_priority IS NULL) OR ((source_priority >= 1) AND (source_priority <= 3)))),
    CONSTRAINT economic_event_consensus_source_report_id_ck CHECK (((source_report_id IS NULL) OR (source_report_id > 0))),
    CONSTRAINT economic_event_consensus_source_timestamp_epoch_ck CHECK (((source_timestamp_epoch IS NULL) OR (source_timestamp_epoch > 0)))
);


