--
-- Name: economic_event_release_actual; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.economic_event_release_actual (
    economic_event_release_actual_id bigint NOT NULL,
    economic_event_id bigint NOT NULL,
    source_agency text NOT NULL,
    source_observation_id text NOT NULL,
    publication_state text NOT NULL,
    revision_sequence integer NOT NULL,
    available_at timestamp with time zone NOT NULL,
    retrieved_at timestamp with time zone NOT NULL,
    source_url text NOT NULL,
    source_artifact_path text NOT NULL,
    source_artifact_sha256 text NOT NULL,
    semantic_contract text NOT NULL,
    source_provenance jsonb NOT NULL,
    actual_raw text NOT NULL,
    actual_value_kind text NOT NULL,
    actual_value_low numeric NOT NULL,
    actual_value_high numeric,
    actual_canonical_value_low numeric NOT NULL,
    actual_canonical_value_high numeric,
    actual_unit text NOT NULL,
    actual_scale numeric NOT NULL,
    actual_qualifier text,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT economic_event_release_actual_actual_raw_check CHECK ((actual_raw <> ''::text)),
    CONSTRAINT economic_event_release_actual_actual_scale_check CHECK ((actual_scale > (0)::numeric)),
    CONSTRAINT economic_event_release_actual_actual_unit_check CHECK ((actual_unit <> ''::text)),
    CONSTRAINT economic_event_release_actual_actual_value_kind_check CHECK ((actual_value_kind = ANY (ARRAY['scalar'::text, 'range'::text]))),
    CONSTRAINT economic_event_release_actual_publication_state_check CHECK ((publication_state = ANY (ARRAY['initial'::text, 'revision'::text]))),
    CONSTRAINT economic_event_release_actual_publication_state_ck CHECK ((((publication_state = 'initial'::text) AND (revision_sequence = 0)) OR ((publication_state = 'revision'::text) AND (revision_sequence > 0)))),
    CONSTRAINT economic_event_release_actual_retrieval_ck CHECK ((retrieved_at >= available_at)),
    CONSTRAINT economic_event_release_actual_revision_sequence_check CHECK ((revision_sequence >= 0)),
    CONSTRAINT economic_event_release_actual_semantic_contract_check CHECK ((semantic_contract <> ''::text)),
    CONSTRAINT economic_event_release_actual_source_agency_check CHECK ((source_agency <> ''::text)),
    CONSTRAINT economic_event_release_actual_source_artifact_path_check CHECK ((source_artifact_path <> ''::text)),
    CONSTRAINT economic_event_release_actual_source_artifact_sha256_check CHECK ((source_artifact_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT economic_event_release_actual_source_observation_id_check CHECK ((source_observation_id <> ''::text)),
    CONSTRAINT economic_event_release_actual_source_provenance_check CHECK (((jsonb_typeof(source_provenance) = 'object'::text) AND (source_provenance <> '{}'::jsonb))),
    CONSTRAINT economic_event_release_actual_source_url_check CHECK ((source_url ~ '^https://'::text)),
    CONSTRAINT economic_event_release_actual_value_shape_ck CHECK ((((actual_value_kind = 'scalar'::text) AND (actual_value_high IS NULL) AND (actual_canonical_value_high IS NULL) AND (actual_canonical_value_low = (actual_value_low * actual_scale))) OR ((actual_value_kind = 'range'::text) AND (actual_value_high IS NOT NULL) AND (actual_canonical_value_high IS NOT NULL) AND (actual_value_low <= actual_value_high) AND (actual_canonical_value_low <= actual_canonical_value_high) AND (actual_canonical_value_low = (actual_value_low * actual_scale)) AND (actual_canonical_value_high = (actual_value_high * actual_scale)))))
);


--
-- Name: TABLE economic_event_release_actual; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.economic_event_release_actual IS 'Immutable authoritative initial and revised actual observations with explicit point-in-time availability and source provenance.';


