--

COMMENT ON COLUMN public.economic_event_release_actual.retrieved_at IS 'Time the immutable source artifact was retrieved, distinct from causal availability and database import time.';


--
-- Name: economic_event_feature_release_actual; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.economic_event_feature_release_actual AS
 SELECT economic_event_release_actual_id,
    economic_event_id,
    available_at,
    actual_value_kind,
    actual_canonical_value_low,
    actual_canonical_value_high,
    actual_unit,
    actual_scale,
    actual_qualifier,
    source_agency,
    source_observation_id,
    source_artifact_path,
    source_artifact_sha256,
    semantic_contract,
    source_provenance
   FROM public.economic_event_release_actual a
  WHERE ((publication_state = 'initial'::text) AND (revision_sequence = 0));


--
-- Name: VIEW economic_event_feature_release_actual; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.economic_event_feature_release_actual IS 'The unique provenance-certified initial actual eligible for release-surprise features; later revisions are deliberately excluded.';


--
-- Name: economic_event_first_release_actual; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.economic_event_first_release_actual AS
 WITH eligible AS (
         SELECT o.economic_event_actual_observation_id,
            o.economic_event_id,
            o.source_name,
            o.source_role,
            o.source_native_event_id,
            o.source_observation_id,
            o.evidence_key,
            o.observation_kind,
            o.revision_sequence,
            o.source_publication_at,
            o.source_publication_time_status,
            o.observed_at,
            o.ingested_at,
            o.availability_proof,
            o.proven_available_at,
            o.source_url,
            o.source_artifact_path,
            o.source_artifact_sha256,
            o.semantic_contract,
            o.source_provenance,
            o.actual_raw,
            o.actual_value_kind,
            o.actual_value_low,
            o.actual_value_high,
            o.actual_canonical_value_low,
            o.actual_canonical_value_high,
            o.actual_unit,
            o.actual_scale,
            o.actual_qualifier,
            o.legacy_release_actual_id,
            o.legacy_consensus_id
           FROM (public.economic_event_actual_observation o
             JOIN public.economic_event e_1 USING (economic_event_id))
          WHERE ((o.source_role = 'authoritative'::text) AND (o.source_name = e_1.source_agency) AND (o.observation_kind = 'initial'::text) AND (o.revision_sequence = 0) AND (o.source_publication_time_status = 'exact'::text) AND (o.availability_proof = 'source_publication'::text))
        ), earliest AS (
         SELECT eligible.economic_event_id,
            min(eligible.source_publication_at) AS first_at
           FROM eligible
          GROUP BY eligible.economic_event_id
        ), earliest_assessment AS (
         SELECT q.economic_event_id,
            q.first_at,
            count(*) AS earliest_candidate_count,
            count(DISTINCT jsonb_build_array(q.actual_value_kind, q.actual_canonical_value_low, q.actual_canonical_value_high, q.actual_unit, q.actual_scale, q.actual_qualifier)) AS earliest_semantic_value_count
           FROM ( SELECT e_1.economic_event_actual_observation_id,
                    e_1.economic_event_id,
                    e_1.source_name,
                    e_1.source_role,
                    e_1.source_native_event_id,
                    e_1.source_observation_id,
                    e_1.evidence_key,
                    e_1.observation_kind,
                    e_1.revision_sequence,
                    e_1.source_publication_at,
                    e_1.source_publication_time_status,
                    e_1.observed_at,
                    e_1.ingested_at,
                    e_1.availability_proof,
                    e_1.proven_available_at,
                    e_1.source_url,
                    e_1.source_artifact_path,
                    e_1.source_artifact_sha256,
                    e_1.semantic_contract,
                    e_1.source_provenance,
                    e_1.actual_raw,
                    e_1.actual_value_kind,
                    e_1.actual_value_low,
                    e_1.actual_value_high,
                    e_1.actual_canonical_value_low,
                    e_1.actual_canonical_value_high,
                    e_1.actual_unit,
                    e_1.actual_scale,
                    e_1.actual_qualifier,
                    e_1.legacy_release_actual_id,
                    e_1.legacy_consensus_id,
                    x.first_at
                   FROM (eligible e_1
                     JOIN earliest x USING (economic_event_id))
                  WHERE (e_1.source_publication_at = x.first_at)) q
          GROUP BY q.economic_event_id, q.first_at
        ), selected AS (
         SELECT DISTINCT ON (o.economic_event_id) o.economic_event_actual_observation_id,
            o.economic_event_id,
            o.source_name,
            o.source_role,
            o.source_native_event_id,
            o.source_observation_id,
            o.evidence_key,
            o.observation_kind,
            o.revision_sequence,
            o.source_publication_at,
            o.source_publication_time_status,
            o.observed_at,
            o.ingested_at,
            o.availability_proof,
            o.proven_available_at,
            o.source_url,
            o.source_artifact_path,
            o.source_artifact_sha256,
            o.semantic_contract,
            o.source_provenance,
            o.actual_raw,
            o.actual_value_kind,
            o.actual_value_low,
            o.actual_value_high,
            o.actual_canonical_value_low,
            o.actual_canonical_value_high,
            o.actual_unit,
            o.actual_scale,
            o.actual_qualifier,
            o.legacy_release_actual_id,
            o.legacy_consensus_id
           FROM (eligible o
             JOIN earliest e_1 USING (economic_event_id))
          WHERE (o.source_publication_at = e_1.first_at)
          ORDER BY o.economic_event_id, o.source_name, o.source_observation_id, o.evidence_key, o.economic_event_actual_observation_id
        ), possible_first_claims AS (
         SELECT s_1.economic_event_id,
            s_1.actual_value_kind,
            s_1.actual_canonical_value_low,
            s_1.actual_canonical_value_high,
            s_1.actual_unit,
            s_1.actual_scale,
            s_1.actual_qualifier
           FROM selected s_1
        UNION ALL
         SELECT o.economic_event_id,
            o.actual_value_kind,
            o.actual_canonical_value_low,
            o.actual_canonical_value_high,
            o.actual_unit,
            o.actual_scale,
            o.actual_qualifier
           FROM (public.economic_event_actual_observation o
             JOIN public.economic_event e_1 USING (economic_event_id))
          WHERE ((o.source_role = 'authoritative'::text) AND (o.source_name = e_1.source_agency) AND ((o.observation_kind = 'unclassified'::text) OR ((o.observation_kind = 'initial'::text) AND (o.source_publication_time_status = 'unavailable'::text))))
        ), possible_first_assessment AS (
         SELECT possible_first_claims.economic_event_id,
            count(DISTINCT jsonb_build_array(possible_first_claims.actual_value_kind, possible_first_claims.actual_canonical_value_low, possible_first_claims.actual_canonical_value_high, possible_first_claims.actual_unit, possible_first_claims.actual_scale, possible_first_claims.actual_qualifier)) AS possible_semantic_value_count
           FROM possible_first_claims
          GROUP BY possible_first_claims.economic_event_id
        ), observation_counts AS (
         SELECT economic_event_actual_observation.economic_event_id,
            count(*) AS observation_count,
            count(DISTINCT jsonb_build_array(economic_event_actual_observation.actual_value_kind, economic_event_actual_observation.actual_canonical_value_low, economic_event_actual_observation.actual_canonical_value_high, economic_event_actual_observation.actual_unit, economic_event_actual_observation.actual_scale, economic_event_actual_observation.actual_qualifier)) AS observed_semantic_value_count
           FROM public.economic_event_actual_observation
          GROUP BY economic_event_actual_observation.economic_event_id
        )
 SELECT e.economic_event_id,
    e.currency,
    e.event_family,
    e.event_timestamp_utc AS event_release_at,
    e.source_agency AS canonical_source_agency,
    e.source_event_id AS canonical_source_event_id,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN 'proven_first_release'::text
            WHEN ((COALESCE(a.earliest_semantic_value_count, (0)::bigint) > 1) OR (COALESCE(p.possible_semantic_value_count, (0)::bigint) > 1)) THEN 'ambiguous'::text
            ELSE 'provenance_unavailable'::text
        END AS provenance_state,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1) AND (a.earliest_candidate_count = 1)) THEN 'unique_authoritative_initial_at_earliest_source_publication'::text
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1) AND (a.earliest_candidate_count > 1)) THEN 'corroborated_authoritative_initial_at_earliest_source_publication'::text
            WHEN (a.earliest_semantic_value_count > 1) THEN 'conflicting_authoritative_initials_at_same_earliest_publication'::text
            WHEN (COALESCE(p.possible_semantic_value_count, (0)::bigint) > 1) THEN 'unresolved_authoritative_possible_first_value_conflict'::text
            WHEN (COALESCE(c.observation_count, (0)::bigint) = 0) THEN 'no_actual_observation'::text
            ELSE 'no_authoritative_initial_with_exact_source_publication'::text
        END AS selection_reason,
    COALESCE(c.observation_count, (0)::bigint) AS observation_count,
    COALESCE(c.observed_semantic_value_count, (0)::bigint) AS observed_semantic_value_count,
    COALESCE(a.earliest_candidate_count, (0)::bigint) AS earliest_candidate_count,
    COALESCE(p.possible_semantic_value_count, (0)::bigint) AS possible_first_semantic_value_count,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.economic_event_actual_observation_id
            ELSE NULL::bigint
        END AS first_release_observation_id,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.actual_value_kind
            ELSE NULL::text
        END AS first_release_value_kind,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.actual_canonical_value_low
            ELSE NULL::numeric
        END AS first_release_value_low,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.actual_canonical_value_high
            ELSE NULL::numeric
        END AS first_release_value_high,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.actual_unit
            ELSE NULL::text
        END AS first_release_unit,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.actual_scale
            ELSE NULL::numeric
        END AS first_release_scale,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.actual_qualifier
            ELSE NULL::text
        END AS first_release_qualifier,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.source_publication_at
            ELSE NULL::timestamp with time zone
        END AS proven_available_at,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.source_name
            ELSE NULL::text
        END AS first_release_source,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.source_native_event_id
            ELSE NULL::text
        END AS first_release_source_native_event_id,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.source_observation_id
            ELSE NULL::text
        END AS first_release_source_observation_id,
        CASE
            WHEN ((a.earliest_semantic_value_count = 1) AND (COALESCE(p.possible_semantic_value_count, (1)::bigint) = 1)) THEN s.evidence_key
            ELSE NULL::text
        END AS first_release_evidence_key,
    ca.economic_event_actual_observation_id AS canonical_observation_id,
    ca.actual_value_kind AS canonical_value_kind,
    ca.actual_canonical_value_low AS canonical_value_low,
    ca.actual_canonical_value_high AS canonical_value_high,
    ca.actual_unit AS canonical_unit,
    ca.actual_qualifier AS canonical_qualifier,
    ca.proven_available_at AS canonical_available_at,
        CASE
            WHEN ((a.earliest_semantic_value_count IS DISTINCT FROM 1) OR (COALESCE(p.possible_semantic_value_count, (1)::bigint) <> 1) OR (ca.economic_event_actual_observation_id IS NULL)) THEN NULL::boolean
            ELSE (jsonb_build_array(s.actual_value_kind, s.actual_canonical_value_low, s.actual_canonical_value_high, s.actual_unit, s.actual_scale, s.actual_qualifier) IS DISTINCT FROM jsonb_build_array(ca.actual_value_kind, ca.actual_canonical_value_low, ca.actual_canonical_value_high, ca.actual_unit, ca.actual_scale, ca.actual_qualifier))
        END AS canonical_differs_from_first_release
   FROM (((((public.economic_event e
     LEFT JOIN observation_counts c USING (economic_event_id))
     LEFT JOIN earliest_assessment a USING (economic_event_id))
     LEFT JOIN possible_first_assessment p USING (economic_event_id))
     LEFT JOIN selected s USING (economic_event_id))
     LEFT JOIN public.economic_event_canonical_actual ca USING (economic_event_id));


--
-- Name: VIEW economic_event_first_release_actual; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.economic_event_first_release_actual IS 'One deterministic provenance assessment per logical event. Conflicting earliest authoritative initial values fail closed as ambiguous.';


--
-- Name: economic_event_release_actual_economic_event_release_actual_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.economic_event_release_actual_economic_event_release_actual_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
