--

ALTER SEQUENCE public.economic_event_release_actual_economic_event_release_actual_seq OWNED BY public.economic_event_release_actual.economic_event_release_actual_id;


--
-- Name: economic_event_selected_consensus; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.economic_event_selected_consensus AS
 SELECT economic_event_consensus_id,
    economic_event_id,
    forecast_canonical_value_low AS consensus_value_low,
    forecast_canonical_value_high AS consensus_value_high,
    forecast_value_kind AS consensus_value_kind,
    forecast_unit AS consensus_unit,
    forecast_scale AS consensus_scale,
    forecast_qualifier AS consensus_qualifier,
    consensus_source,
    source_report_id,
    source_event_id,
    source_observation_id,
    source_release_date,
    source_artifact_path,
    source_artifact_sha256,
    candidate_classification,
    match_rule,
    semantic_contract,
    provider_provenance,
    imported_at,
    provider_observed_at,
    forecast_available_at,
    source_retrieved_at,
    forecast_availability_proof
   FROM public.economic_event_consensus c
  WHERE (forecast_parse_status = 'parsed'::text);


--
-- Name: VIEW economic_event_selected_consensus; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.economic_event_selected_consensus IS 'The sole populated consensus observation for each authoritative economic event; provider identity and provenance remain explicit.';


