    worker_process_start_identity text,
    worker_control_state text DEFAULT 'running'::text NOT NULL,
    cancellation_request_id bigint,
    cancel_after_checkpoint_epoch integer,
    last_checkpoint_stop_decision_epoch integer,
    cancel_infer_before boolean DEFAULT false NOT NULL,
    cancellation_completed_at timestamp with time zone,
    worker_global_pause_request_id bigint,
    active_scheduler_worker_attempt_id bigint,
    donchian20_mode text DEFAULT 'enabled'::text NOT NULL,
    feature_warmup_scope text DEFAULT 'legacy_cold_boundary'::text NOT NULL,
    donchian_lookback integer DEFAULT 20 NOT NULL,
    feature_ablation_mask text DEFAULT ''::text NOT NULL,
    resume_expand_input_width boolean DEFAULT false NOT NULL,
    continuation_policy_min_profit_actionable_count bigint,
    continuation_policy_min_profit_aggregate_log_return_sum double precision,
    continuation_policy_min_profit_average_log_return double precision,
    checkpoint_policy_revision bigint DEFAULT 1 NOT NULL,
    checkpoint_policy_hash text,
    checkpoint_policy_last_decision_id bigint,
    checkpoint_policy_stop_decision_id bigint,
    operator_forced_final_inference_rerun_requested boolean DEFAULT false NOT NULL,
    training_objective_id text DEFAULT 'legacy_first_hit_weighted_ce_v1'::text NOT NULL,
    training_objective_version integer DEFAULT 1 NOT NULL,
    loss_definition_version integer DEFAULT 1 NOT NULL,
    training_objective_canonical text DEFAULT 'training_objective_configuration_v1;schema_version=1;objective_id=legacy_first_hit_weighted_ce_v1;objective_family=up_neutral_down_first_hit_classification;objective_version=1;loss_definition_version=1;mode=legacy_first_hit_classification;classification_loss=true_class_weighted_softmax_cross_entropy_v1;classification_target=up_neutral_down_return_high_low_first_hit_strict_threshold_up_tie_v1;class_index_order=down_0_neutral_1_up_2;class_weight_semantics=true_class_weight_multiplies_loss_and_all_logit_components_v1;class_weight_down=1;class_weight_neutral=1;class_weight_up=1;softmax_loss_probability_floor=1e-12;classification_logit_gradient_scale=0.1;shared_core_classification_gradient_scale=4;internal_loss_normalization=weighted_loss_sum_divided_by_true_class_weight_sum_v1;calculate_batch_return_normalization=weighted_loss_sum_divided_by_example_count_v1;gradient_normalization=all_calculate_batch_gradients_divided_by_true_class_weight_sum_v1;batch_window_boundary=overlapping_windows_do_not_cross_outer_tensor_batch_v1;optimizer_family=sgd;optimizer_update=parameter_minus_learning_rate_times_gradient_v1;learning_rate_contract=base_rate_and_parameter_group_multipliers_persisted_in_training_config_v1;gradient_clipping_mode=componentwise_after_normalization_before_update;gradient_clip_threshold=10;nonfinite_gradient_policy=skip_parameter_update_v1;weight_decay=none;gradient_accumulation_precision=core_gradient_accumulation_double_head_gradient_accumulation_float_loss_accumulation_double_v1;auxiliary_loss_mode=disabled;auxiliary_loss_coefficient=0;regression_target_definition=NULL;regression_normalization_identity=NULL;robust_loss_definition=NULL;robust_loss_delta=NULL;target_clipping_definition=none;shared_gradient_combination=classification_only_v1;'::text NOT NULL,
    training_objective_hash text DEFAULT 'fnv1a64:65818f2e1fa1a324'::text NOT NULL,
    auxiliary_loss_mode text DEFAULT 'disabled'::text NOT NULL,
    auxiliary_loss_coefficient double precision DEFAULT 0.0 NOT NULL,
    regression_target_definition text,
    regression_normalization_identity text,
    robust_loss_definition text,
    robust_loss_delta double precision,
    target_clipping_definition text DEFAULT 'none'::text NOT NULL,
    objective_normalization_identity text DEFAULT 'weighted_loss_sum_by_weight_sum_gradients__calculate_batch_return_by_example_count_v1'::text NOT NULL,
    scheduler_priority text DEFAULT 'normal'::text NOT NULL,
    resume_requested boolean DEFAULT false NOT NULL,
    model_input_width integer,
    model_input_semantic_layout_version integer,
    economic_calendar_snapshot_id bigint,
    economic_calendar_snapshot_hash text,
    scheduler_resume_origin text DEFAULT 'none'::text NOT NULL,
    fresh_initialization_seed bigint DEFAULT 42 NOT NULL,
    CONSTRAINT experiment_cancel_checkpoint_shape_check CHECK (((cancel_after_checkpoint_epoch IS NULL) OR ((cancel_after_checkpoint_epoch > 0) AND (cancellation_request_id IS NOT NULL)))),
    CONSTRAINT experiment_checkpoint_policy_enabled_rules_check CHECK (((NOT checkpoint_policy_enabled) OR (checkpoint_policy_min_leader_score IS NOT NULL) OR (checkpoint_policy_min_infer_accuracy IS NOT NULL) OR (checkpoint_policy_top_n IS NOT NULL))),
