--
-- Name: experiment_admin_request; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.experiment_admin_request (
    request_id bigint NOT NULL,
    action text NOT NULL,
    cancellation_mode text,
    infer_before_cancel boolean DEFAULT false NOT NULL,
    invocation_identity text NOT NULL,
    requester_identity text,
    application_owner text,
    application_lease_until timestamp with time zone,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    status text DEFAULT 'applying'::text NOT NULL,
    previous_global_state text NOT NULL,
    resulting_global_state text NOT NULL,
    scheduler_running_observed boolean,
    target_count integer DEFAULT 0 NOT NULL,
    successful_count integer DEFAULT 0 NOT NULL,
    already_satisfied_count integer DEFAULT 0 NOT NULL,
    missing_count integer DEFAULT 0 NOT NULL,
    rejected_count integer DEFAULT 0 NOT NULL,
    failed_count integer DEFAULT 0 NOT NULL,
    result_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_details text,
    target_experiment_id bigint,
    CONSTRAINT experiment_admin_request_action_check CHECK ((action = ANY (ARRAY['pause_all'::text, 'resume_all'::text, 'cancel_all'::text, 'resume_experiment'::text]))),
    CONSTRAINT experiment_admin_request_already_satisfied_count_check CHECK ((already_satisfied_count >= 0)),
    CONSTRAINT experiment_admin_request_cancellation_mode_check CHECK (((cancellation_mode IS NULL) OR (cancellation_mode = ANY (ARRAY['immediate'::text, 'after_next_checkpoint'::text])))),
    CONSTRAINT experiment_admin_request_check CHECK ((((action = 'cancel_all'::text) AND (cancellation_mode IS NOT NULL)) OR ((action <> 'cancel_all'::text) AND (cancellation_mode IS NULL) AND (NOT infer_before_cancel)))),
    CONSTRAINT experiment_admin_request_failed_count_check CHECK ((failed_count >= 0)),
    CONSTRAINT experiment_admin_request_missing_count_check CHECK ((missing_count >= 0)),
    CONSTRAINT experiment_admin_request_previous_global_state_check CHECK ((previous_global_state = ANY (ARRAY['running'::text, 'paused'::text]))),
    CONSTRAINT experiment_admin_request_rejected_count_check CHECK ((rejected_count >= 0)),
    CONSTRAINT experiment_admin_request_resulting_global_state_check CHECK ((resulting_global_state = ANY (ARRAY['running'::text, 'paused'::text]))),
    CONSTRAINT experiment_admin_request_status_check CHECK ((status = ANY (ARRAY['applying'::text, 'pending'::text, 'completed'::text, 'partial'::text, 'failed'::text]))),
    CONSTRAINT experiment_admin_request_successful_count_check CHECK ((successful_count >= 0)),
    CONSTRAINT experiment_admin_request_target_count_check CHECK ((target_count >= 0)),
    CONSTRAINT experiment_admin_request_target_shape_check CHECK ((((action = 'resume_experiment'::text) AND (target_experiment_id IS NOT NULL) AND (cancellation_mode IS NULL) AND (NOT infer_before_cancel)) OR ((action <> 'resume_experiment'::text) AND (target_experiment_id IS NULL))))
);


--
-- Name: experiment_admin_request_request_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.experiment_admin_request_request_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: experiment_admin_request_request_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.experiment_admin_request_request_id_seq OWNED BY public.experiment_admin_request.request_id;


