--

CREATE TABLE public.experiment_admin_worker_outcome (
    request_id bigint NOT NULL,
    worker_identity text NOT NULL,
    experiment_id bigint NOT NULL,
    checkpoint_eval_id bigint,
    worker_kind text DEFAULT 'experiment'::text NOT NULL,
    phase text NOT NULL,
    lifecycle_status text NOT NULL,
    worker_pid integer,
    worker_process_group_id integer,
    worker_process_start_identity text,
    identity_result text DEFAULT 'not_checked'::text NOT NULL,
    requested_signal text,
    signal_result text DEFAULT 'not_attempted'::text NOT NULL,
    cancellation_checkpoint_epoch integer,
    cancellation_checkpoint_model_id bigint,
    inference_action text DEFAULT 'none'::text NOT NULL,
    outcome_status text DEFAULT 'planned'::text NOT NULL,
    detail text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    worker_executable text,
    worker_command_line text,
    source_pause_request_id bigint,
    worker_attempt_id bigint,
    CONSTRAINT experiment_admin_worker_outcome_identity_result_check CHECK ((identity_result = ANY (ARRAY['not_checked'::text, 'validated'::text, 'process_missing'::text, 'stale_pid'::text, 'identity_validation_failed'::text, 'unsafe_process_group'::text, 'permission_denied'::text, 'inspection_failed'::text]))),
    CONSTRAINT experiment_admin_worker_outcome_inference_action_check CHECK ((inference_action = ANY (ARRAY['none'::text, 'already_completed'::text, 'queued'::text, 'running'::text, 'completed'::text, 'failed'::text, 'no_checkpoint'::text, 'identity_ambiguous'::text]))),
    CONSTRAINT experiment_admin_worker_outcome_outcome_status_check CHECK ((outcome_status = ANY (ARRAY['planned'::text, 'pending_checkpoint'::text, 'awaiting_inference'::text, 'completed'::text, 'partial'::text, 'failed'::text]))),
    CONSTRAINT experiment_admin_worker_outcome_signal_result_check CHECK ((signal_result = ANY (ARRAY['not_attempted'::text, 'signaled'::text, 'already_requested_state'::text, 'process_missing'::text, 'stale_pid'::text, 'identity_validation_failed'::text, 'permission_failure'::text, 'signaling_failure'::text, 'escalated'::text]))),
    CONSTRAINT experiment_admin_worker_outcome_worker_kind_check CHECK ((worker_kind = ANY (ARRAY['experiment'::text, 'checkpoint_infer'::text])))
);


--
