-- Name: experiment_checkpoint_decision; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.experiment_checkpoint_decision (
    checkpoint_decision_id bigint NOT NULL,
    checkpoint_eval_id bigint NOT NULL,
    parent_experiment_id bigint NOT NULL,
    checkpoint_epoch integer NOT NULL,
    checkpoint_model_id bigint NOT NULL,
    decision text NOT NULL,
    reason text NOT NULL,
    leader_score double precision,
    infer_accuracy double precision,
    rank_value integer,
    rank_scope text,
    requested_stop_epoch integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    analysis_id bigint,
    inference_eval_result_id bigint,
    policy_revision bigint,
    policy_hash text,
    evidence_watermark text,
    rank_population_watermark text,
    identity_status text DEFAULT 'legacy'::text NOT NULL,
    superseded_at timestamp with time zone,
    superseded_reason text,
    superseded_by_decision_id bigint,
    stop_request_applied boolean DEFAULT false NOT NULL,
    stop_request_applied_at timestamp with time zone,
    stop_action_worker_attempt_id bigint,
    CONSTRAINT checkpoint_decision_stop_action_shape_check CHECK (((stop_request_applied AND (identity_status = 'action_applied'::text) AND (decision = 'stop_requested'::text) AND (requested_stop_epoch IS NOT NULL) AND (stop_request_applied_at IS NOT NULL) AND (stop_action_worker_attempt_id IS NOT NULL)) OR ((NOT stop_request_applied) AND (stop_request_applied_at IS NULL) AND (stop_action_worker_attempt_id IS NULL)))),
    CONSTRAINT checkpoint_decision_supersession_shape_check CHECK ((((identity_status = 'superseded'::text) AND (superseded_at IS NOT NULL) AND (superseded_reason IS NOT NULL)) OR ((identity_status <> 'superseded'::text) AND (superseded_at IS NULL) AND (superseded_reason IS NULL) AND (superseded_by_decision_id IS NULL)))),
    CONSTRAINT checkpoint_decision_versioned_identity_check CHECK ((((identity_status = 'legacy'::text) AND (policy_revision IS NULL) AND (policy_hash IS NULL) AND (evidence_watermark IS NULL)) OR ((identity_status = ANY (ARRAY['active'::text, 'superseded'::text, 'action_applied'::text])) AND (policy_revision > 0) AND (length(policy_hash) = 16) AND (length(evidence_watermark) = 16) AND (analysis_id IS NOT NULL) AND (inference_eval_result_id IS NOT NULL)))),
    CONSTRAINT experiment_checkpoint_decision_rank_scope_check CHECK (((rank_scope IS NULL) OR (rank_scope = ANY (ARRAY['symbol_horizon'::text, 'horizon'::text, 'global'::text])))),
    CONSTRAINT experiment_checkpoint_decision_value_check CHECK ((decision = ANY (ARRAY['continue'::text, 'continue_grace'::text, 'stop_requested'::text, 'skipped'::text])))
);


