    continuation_decision_id bigint NOT NULL,
    source_experiment_id bigint NOT NULL,
    source_model_id bigint NOT NULL,
    source_analysis_id bigint NOT NULL,
    source_checkpoint_eval_id bigint,
    source_epoch integer NOT NULL,
    target_epochs integer NOT NULL,
    decision text NOT NULL,
    reason text NOT NULL,
    leader_score double precision,
    infer_accuracy double precision,
    rank_value integer,
    rank_scope text,
    observed_eval_count integer NOT NULL,
    patience_window integer NOT NULL,
    trend_metric text,
    trend_value double precision,
    policy_revision bigint NOT NULL,
    policy_hash text NOT NULL,
    evidence_watermark text NOT NULL,
    queued_experiment_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT experiment_continuation_decision_value_check CHECK ((decision = ANY (ARRAY['eligible'::text, 'insufficient_evidence'::text, 'rejected_threshold'::text, 'rejected_rank'::text, 'rejected_trend'::text, 'rejected_profitability'::text, 'already_continued'::text, 'continuation_queued'::text, 'skipped'::text, 'error'::text]))),
    CONSTRAINT experiment_continuation_decision_values_check CHECK (((source_epoch > 0) AND (target_epochs > source_epoch) AND (observed_eval_count > 0) AND (patience_window > 0) AND (policy_revision > 0) AND (policy_hash <> ''::text) AND (evidence_watermark <> ''::text) AND ((rank_value IS NULL) OR (rank_value > 0)) AND ((rank_scope IS NULL) OR (rank_scope = ANY (ARRAY['symbol_horizon'::text, 'horizon'::text, 'global'::text]))) AND ((trend_metric IS NULL) OR (trend_metric = ANY (ARRAY['leader_score'::text, 'infer_accuracy'::text]))) AND ((trend_value IS NULL) OR (abs(trend_value) < 'Infinity'::double precision)) AND ((queued_experiment_id IS NULL) OR (queued_experiment_id <> source_experiment_id))))
);


