    accept_model boolean
);


--
-- Name: inference_profitability_observation; Type: TABLE; Schema: recommendation_phase3a_source_28279; Owner: -
--

CREATE TABLE recommendation_phase3a_source_28279.inference_profitability_observation (
    profitability_observation_id bigint NOT NULL,
    experiment_id bigint,
    model_id bigint NOT NULL,
    inference_eval_result_id bigint NOT NULL,
    inference_scope text NOT NULL,
    checkpoint_eval_id bigint,
    inference_start text NOT NULL,
    inference_end text NOT NULL,
    prediction_count bigint NOT NULL,
    actionable_count bigint NOT NULL,
    winning_actionable_count bigint NOT NULL,
    losing_actionable_count bigint NOT NULL,
    gross_positive_terminal_horizon_log_return_sum double precision NOT NULL,
    gross_negative_terminal_horizon_log_return_sum double precision NOT NULL,
    aggregate_terminal_horizon_log_return_sum double precision NOT NULL,
    average_terminal_horizon_log_return_per_actionable_prediction double precision,
    metric_definition_canonical text NOT NULL,
    metric_definition_hash text NOT NULL,
    source_content_hash text NOT NULL,
    observation_identity_canonical text NOT NULL,
    observation_identity_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inference_profitability_average_presence_check CHECK ((((actionable_count = 0) AND (average_terminal_horizon_log_return_per_actionable_prediction IS NULL)) OR ((actionable_count > 0) AND (average_terminal_horizon_log_return_per_actionable_prediction IS NOT NULL)))),
    CONSTRAINT inference_profitability_finite_returns_check CHECK (((gross_positive_terminal_horizon_log_return_sum <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision])) AND (gross_negative_terminal_horizon_log_return_sum <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision])) AND (aggregate_terminal_horizon_log_return_sum <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision])) AND ((average_terminal_horizon_log_return_per_actionable_prediction IS NULL) OR (average_terminal_horizon_log_return_per_actionable_prediction <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))))),
    CONSTRAINT inference_profitability_obse_gross_negative_terminal_hori_check CHECK ((gross_negative_terminal_horizon_log_return_sum <= (0)::double precision)),
    CONSTRAINT inference_profitability_obse_gross_positive_terminal_hori_check CHECK ((gross_positive_terminal_horizon_log_return_sum >= (0)::double precision)),
    CONSTRAINT inference_profitability_obse_observation_identity_canonic_check CHECK ((observation_identity_canonical <> ''::text)),
    CONSTRAINT inference_profitability_obser_metric_definition_canonical_check CHECK ((metric_definition_canonical <> ''::text)),
    CONSTRAINT inference_profitability_observa_observation_identity_hash_check CHECK ((observation_identity_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT inference_profitability_observatio_metric_definition_hash_check CHECK ((metric_definition_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT inference_profitability_observation_check CHECK (((actionable_count >= 0) AND (actionable_count <= prediction_count))),
    CONSTRAINT inference_profitability_observation_check1 CHECK (((winning_actionable_count >= 0) AND (winning_actionable_count <= actionable_count))),
    CONSTRAINT inference_profitability_observation_check2 CHECK (((losing_actionable_count >= 0) AND (losing_actionable_count <= actionable_count))),
    CONSTRAINT inference_profitability_observation_inference_end_check CHECK ((inference_end <> ''::text)),
    CONSTRAINT inference_profitability_observation_inference_scope_check CHECK ((inference_scope = ANY (ARRAY['final'::text, 'checkpoint'::text]))),
    CONSTRAINT inference_profitability_observation_inference_start_check CHECK ((inference_start <> ''::text)),
    CONSTRAINT inference_profitability_observation_prediction_count_check CHECK ((prediction_count >= 0)),
    CONSTRAINT inference_profitability_observation_source_content_hash_check CHECK ((source_content_hash ~ '^fnv1a64:[0-9a-f]{16}$'::text)),
    CONSTRAINT inference_profitability_scope_identity_check CHECK ((((inference_scope = 'final'::text) AND (checkpoint_eval_id IS NULL)) OR ((inference_scope = 'checkpoint'::text) AND (checkpoint_eval_id IS NOT NULL) AND (experiment_id IS NOT NULL)))),
    CONSTRAINT inference_profitability_win_loss_count_check CHECK (((winning_actionable_count + losing_actionable_count) <= actionable_count))
);


--
-- Name: TABLE inference_profitability_observation; Type: COMMENT; Schema: recommendation_phase3a_source_28279; Owner: -
--

COMMENT ON TABLE recommendation_phase3a_source_28279.inference_profitability_observation IS 'Immutable terminal-horizon directional log-return observations produced by completed inference; not portfolio P&L.';


--
-- Name: COLUMN inference_profitability_observation.average_terminal_horizon_log_return_per_actionable_prediction; Type: COMMENT; Schema: recommendation_phase3a_source_28279; Owner: -
--

COMMENT ON COLUMN recommendation_phase3a_source_28279.inference_profitability_observation.average_terminal_horizon_log_return_per_actionable_prediction IS 'NULL when actionable_count is zero; otherwise aggregate return divided by actionable_count.';


--
-- Name: COLUMN inference_profitability_observation.metric_definition_canonical; Type: COMMENT; Schema: recommendation_phase3a_source_28279; Owner: -
--

COMMENT ON COLUMN recommendation_phase3a_source_28279.inference_profitability_observation.metric_definition_canonical IS 'Versioned executable metric semantics, including explicit absent cost, sizing, leverage, and overlap models.';


--
-- Name: COLUMN inference_profitability_observation.source_content_hash; Type: COMMENT; Schema: recommendation_phase3a_source_28279; Owner: -
--

COMMENT ON COLUMN recommendation_phase3a_source_28279.inference_profitability_observation.source_content_hash IS 'FNV-1a identity of the ordered predicted-class and terminal-price inputs consumed by the metric calculation.';


