    ADD CONSTRAINT experiment_recommendation_step3_shape_check CHECK (((recommendation_scan_id IS NULL) OR ((source_analysis_id IS NOT NULL) AND (source_evidence_count > 0) AND (changed_parameter = ANY (ARRAY['core_lr_mult'::text, 'head_lr_mult'::text, 'label_threshold'::text, 'prediction_horizon'::text])) AND (source_value_canonical IS NOT NULL) AND (proposed_value_canonical IS NOT NULL) AND (absolute_delta >= (0)::double precision) AND (semantic_configuration_canonical IS NOT NULL) AND (semantic_hash IS NOT NULL) AND (invocation_configuration_canonical IS NOT NULL) AND (invocation_hash IS NOT NULL) AND (policy_canonical IS NOT NULL) AND (policy_hash IS NOT NULL) AND (generation_ordinal > 0) AND (structural_rank > 0) AND (duplicate_type = ANY (ARRAY['no_duplicate'::text, 'existing_experiment'::text, 'excluded_terminal_experiment'::text, 'active_recommendation'::text, 'historical_recommendation'::text]))))) NOT VALID;


